R_UNIVERSAL = 8.314462618

# ---------------- NASA THERMO ----------------

class NASASpecies:
    def __init__(self, name, low, high, t_switch=1000.0):
        self.name = name
        self.low = low
        self.high = high
        self.t_switch = t_switch

    def coeffs(self, T):
        return self.low if T <= self.t_switch else self.high

    def cp(self, T):
        a = self.coeffs(T)
        return R_UNIVERSAL * (
            a[0]
            + a[1]*T
            + a[2]*T**2
            + a[3]*T**3
            + a[4]*T**4
        )

    def h(self, T):
        a = self.coeffs(T)
        return R_UNIVERSAL * T * (
            a[0]
            + a[1]*T/2
            + a[2]*T**2/3
            + a[3]*T**3/4
            + a[4]*T**4/5
            + a[5]/T
        )

    def s(self, T):
        a = self.coeffs(T)
        return R_UNIVERSAL * (
            a[0]*np.log(T)
            + a[1]*T
            + a[2]*T**2/2
            + a[3]*T**3/3
            + a[4]*T**4/4
            + a[6]
        )

# ---------------- TRANSPORT ----------------

class IndustrialTransport:
    def viscosity_gas(self, T, MW):
        return 1e-5 * (T / 300.0)**0.7

    def conductivity_gas(self, T):
        return 0.02 * (T / 300.0)**0.8

    def diffusivity(self, T, P):
        return 1e-5 * (T / 300.0)**1.75 * (101325.0 / max(P,1.0))

# ---------------- COKE MODEL ----------------

class DynamicCokeModel:
    def __init__(self):
        self.thickness = 0.0

    def growth_rate(self, T_wall, hc_factor):
        base = 1e-9 * np.exp((T_wall - 900.0) / 200.0)
        return base * max(hc_factor, 0.01)

    def update(self, dt, T_wall, hc_factor):
        rate = self.growth_rate(T_wall, hc_factor)
        self.thickness += rate * dt
        return self.thickness

# ---------------- RADIATION ----------------

class RadiantBoxModel:
    SIGMA = 5.670374419e-8

    def radiant_flux(self, T_flame, emissivity=0.85):
        return emissivity * self.SIGMA * T_flame**4

# ---------------- TLE ----------------

class TransferLineExchanger:
    def quench_temperature(self, T_in, duty_kW):
        return max(300.0, T_in - duty_kW / 1000.0)

# ---------------- INDUSTRIAL UTILITIES ----------------

def industrial_reynolds(rho, vel, dia, mu):
    return rho * vel * dia / max(mu, 1e-12)

def industrial_prandtl(cp, mu, k):
    return cp * mu / max(k, 1e-12)

def industrial_nusselt(Re, Pr):
    if Re < 2300:
        return 3.66
    return 0.023 * (Re**0.8) * (Pr**0.4)

class RealGasEOS:
    """Compact real-gas utilities for furnace/tube calculations."""

    @staticmethod
    def peng_robinson_z(T, P, Tc, Pc, omega=0.30):
        Tr = max(T / max(Tc, 1e-9), 0.2)
        Pr = max(P / max(Pc, 1e-9), 0.0)
        kappa = 0.37464 + 1.54226 * omega - 0.26992 * omega**2
        alpha = (1.0 + kappa * (1.0 - np.sqrt(Tr)))**2
        A = 0.45724 * alpha * Pr / max(Tr**2, 1e-12)
        B = 0.07780 * Pr / max(Tr, 1e-12)
        # Cubic: Z³ + a2·Z² + a1·Z + a0 = 0
        a2 = -(1.0 - B)
        a1 = A - 3.0*B**2 - 2.0*B
        a0 = -(A*B - B**2 - B**3)
        # Rev-70: analytical Cardano solution (avoids slow np.roots eigenvalue call)
        # Depressed cubic: t³ + p·t + q = 0  via Z = t - a2/3
        p = a1 - a2*a2/3.0
        q = 2.0*a2*a2*a2/27.0 - a2*a1/3.0 + a0
        disc = (q*q)/4.0 + (p*p*p)/27.0
        shift = a2/3.0
        if disc > 0:
            # One real root
            sq = np.sqrt(disc)
            u = np.cbrt(-q/2.0 + sq)
            v = np.cbrt(-q/2.0 - sq)
            zr = u + v - shift
            return float(np.clip(zr, 0.20, 2.50))
        else:
            # Three real roots — take the largest (vapor root)
            if abs(p) < 1e-30:
                zr = -shift
                return float(np.clip(zr, 0.20, 2.50))
            m = 2.0*np.sqrt(-p/3.0)
            arg = np.clip(3.0*q/(p*m), -1.0, 1.0)
            theta = np.arccos(arg) / 3.0
            roots = [m*np.cos(theta) - shift,
                     m*np.cos(theta - 2.0*np.pi/3.0) - shift,
                     m*np.cos(theta - 4.0*np.pi/3.0) - shift]
            return float(np.clip(max(roots), 0.20, 2.50))

