def _app_base_dir():
    if getattr(sys, 'frozen', False):
        return os.path.dirname(os.path.abspath(sys.executable))
    if '__file__' in globals():
        return os.path.dirname(os.path.abspath(__file__))
    return os.getcwd()

_LOG_PATH = os.path.join(_app_base_dir(), f'{_APP_NAME}.log')
_LOGGER = logging.getLogger(_APP_NAME)

def _configure_logging():
    """Initialize a lightweight file log once per process."""
    if _LOGGER.handlers:
        return
    _LOGGER.setLevel(logging.INFO)
    try:
        handler = logging.FileHandler(_LOG_PATH, encoding='utf-8')
    except Exception:
        handler = logging.StreamHandler()
    handler.setFormatter(logging.Formatter(
        '%(asctime)s %(levelname)s [%(threadName)s] %(message)s'
    ))
    _LOGGER.addHandler(handler)
    _LOGGER.info('Logging initialized')

def _log_exception(context):
    _configure_logging()
    _LOGGER.exception(context)

