def get_mw(sp):
    if sp in _MW_KNOWN: return _MW_KNOWN[sp]
    c, h = parse_species(sp)
    if c == 0 and h == 0: return 100.0
    return c*12.011 + h*1.008

def check_balance(reactants, products):
    dC=dH=dO=0.
    for sp,n in reactants.items():
        c,h,o=count_atoms(sp); dC-=c*n; dH-=h*n; dO-=o*n
    for sp,n in products.items():
        c,h,o=count_atoms(sp); dC+=c*n; dH+=h*n; dO+=o*n
    return abs(dC)<1e-9 and abs(dH)<1e-9 and abs(dO)<1e-9


