    def build_arrays(self, species_list):
        n = len(species_list); Hf = np.zeros(n); A = np.zeros(n); B = np.zeros(n)
        C  = np.zeros(n); D = np.zeros(n)
        for i, sp in enumerate(species_list):
            if sp in self._DATA:
                Hf[i], A[i], B[i], C[i], D[i] = self._DATA[sp]
            else:
                nc, nh = parse_species(sp)
                A[i]  = nc*5.0 + nh*2.0; B[i] = nc*40.0e-3
                Hf[i] = -45000.0 - 20000.0*max(0, nc-2)
        return Hf, A, B, C, D


