#  v24  NEW PHYSICS CLASSES
# ═════════════════════════════════════════════════════════════════════════════

class LarsonMillerLifeModel:
    """
    v24 — Larson-Miller creep life prediction for HP-alloy furnace tubes.

    LMP = T_K · (log₁₀(t_r) + C)
    Miner's rule: D = Σ(Δt / t_r,i)  →  D ≥ 1 means predicted rupture.

    Reference: Larson & Miller (1952) Trans. ASME 74; Woerde et al. (2002) AIChE.
    """
    _ALLOY_PARAMS = {
        'HP40':        (20.0, [(7,26500),(14,24000),(21,22000),(35,20000)]),
        'Manaurite36X':(20.5, [(7,27500),(14,25000),(21,23000),(35,21000)]),
        'HK40':        (19.5, [(7,25500),(14,23000),(21,21000),(35,19000)]),
        '35Cr45Ni':    (21.0, [(7,28500),(14,26000),(21,24000),(35,22000)]),
    }

    def __init__(self, alloy='HP40', C_LM=None):
        params = self._ALLOY_PARAMS.get(alloy, self._ALLOY_PARAMS['HP40'])
        self.C_LM  = C_LM if C_LM is not None else params[0]
        self._table= params[1]

    def _lmp(self, sigma_MPa):
        sigs = [r[0] for r in self._table]
        lmps = [r[1] for r in self._table]
        return float(np.interp(sigma_MPa, sigs, lmps, left=lmps[0], right=lmps[-1]))

    def time_to_rupture(self, T_K, sigma_MPa):
        """Expected time to rupture [h] at constant T_K and hoop stress."""
        log10_tr = self._lmp(sigma_MPa) / max(T_K, 500.) - self.C_LM
        return 10.**log10_tr if log10_tr >= 0 else 0.

    def hoop_stress(self, P_Pa, Di, wall_m):
        """Thin-wall hoop stress σ = P·r/t [MPa]."""
        return P_Pa * (Di/2.) / max(wall_m, 1e-6) / 1e6

    def cumulative_damage(self, T_arr, z_arr, t_hours, sigma_MPa):
        """Miner's-rule damage fraction after t_hours at TMT profile T_arr [K]."""
        L = max(float(z_arr[-1]-z_arr[0]), 1e-3)
        D = 0.
        for i, T_i in enumerate(T_arr):
            t_r = self.time_to_rupture(float(T_i), sigma_MPa)
            if t_r <= 0: D += 1e6; continue
            w = (abs(float(z_arr[1]-z_arr[0]))*0.5/L if i in (0,len(T_arr)-1)
                 else abs(float(z_arr[i+1]-z_arr[i-1]))/(2.*L))
            D += w * t_hours / t_r
        peak = int(np.argmax(T_arr))
        t_r_pk = self.time_to_rupture(float(T_arr[peak]), sigma_MPa)
        return {
            'damage'       : D,
            't_remaining_h': t_r_pk * max(1.-D, 0.) if t_r_pk < 1e9 else np.inf,
            'peak_z_m'     : float(z_arr[peak]),
            'peak_T_C'     : float(T_arr[peak]) - 273.15,
            't_rupture_h'  : t_r_pk,
            'fraction_used': min(D, 1.0),
        }


class CrackerEngine:
    # ── Lennard-Jones parameters for Chapman-Enskog viscosity ── UPGRADE v22 ──
    # (σ [Å], ε/k_B [K])  Source: Reid, Prausnitz & Poling (1987) App. A
    _LJ = {
        'H2':    (2.827,  59.7), 'H2O':   (2.641, 809.1), 'CH4':   (3.758, 148.6),
        'C2H4':  (4.163, 224.7), 'C2H6':  (4.443, 215.7), 'C2H2':  (4.033, 231.8),
        'C3H6':  (4.678, 298.9), 'C3H8':  (5.118, 237.1), 'C3H4':  (4.760, 251.8),
        'C4H8':  (5.176, 315.0), 'C4H10': (5.278, 330.1), 'C4H6':  (5.180, 357.0),
        'C6H6':  (5.349, 412.3), 'C7H8':  (5.680, 453.0), 'H'  :   (2.708,  37.0),
        'OH':    (3.147, 100.0), 'CH3r':  (3.758, 148.6), 'CO':    (3.690,  91.7),
        'CO2':   (3.941, 195.2),
        # v24: C4 isomers
        '1C4H8': (5.176, 315.0),   # 1-butene  (DIPPR)
        '2C4H8': (5.200, 320.0),   # 2-butene  (DIPPR, slightly higher ε)
    }
    # Neufeld (1972) collision-integral constants for viscosity
    _NEUFELD_A = (1.16145, 0.14874, 0.52487, 0.7732, 2.16178, 2.43787)

    def __init__(self, raw_reactions, geom, solver_opts=None):
        g = geom
        self.coils  = g.get('coils', 1)
        self.tube_id = g['tube_id']; self.tube_id_clean = g['tube_id']
        self.tube_od = g['tube_od']
        self.passes  = g.get('passes', 4)
        self.length_per_pass = g.get('length_per_pass', 20.0)
        self.total_length    = self.length_per_pass * self.passes
        self.roughness       = g.get('roughness', 4.5e-4)
        self.Ac              = np.pi*(g['tube_id']/2)**2
        self.emissivity      = g.get('emissivity', 0.75)
        self.k_tube          = g.get('k_tube', 25.0)
        self.h_o_flue        = g.get('h_o_flue', 25.0)
        self.heat_flux_profile   = g.get('heat_flux_profile', 'uniform')
        self.profile_amplitude_K = g.get('profile_amplitude_K', 0.0)
        self.k_heat          = g.get('k_heat', 1.0)
        self.k_dp            = g.get('k_dp',   1.0)
        self.firebox_temp_K  = 1300.0
        self.rho_coke        = RHO_COKE

        # ── UPGRADE v22: per-pass geometry ───────────────────────────────────
        # tube_id_per_pass: list of inner diameters, one per pass.
        # If not supplied, all passes use the single tube_id value.
        raw_ids = g.get('tube_id_per_pass', None)
        if raw_ids and len(raw_ids) == self.passes:
            self._tube_id_per_pass = [float(d) for d in raw_ids]
        else:
            self._tube_id_per_pass = [self.tube_id] * self.passes

        raw_lpp = g.get('length_per_pass_list', None)
        if raw_lpp and len(raw_lpp) == self.passes:
            self._length_per_pass_list = [float(l) for l in raw_lpp]
        else:
            self._length_per_pass_list = [self.length_per_pass] * self.passes
        self.total_length = sum(self._length_per_pass_list)

        # Minor loss coefficient per 180° bend between passes (default: 0.5)
        self.bend_kfactor = g.get('bend_kfactor', 0.5)

        # ── UPGRADE v22: zone-wise heat flux table (Lobo-Evans style) ────────
        # List of (z_start, z_end, q_kW/m²) tuples.  If None, falls back to
        # the legacy sinusoidal / front_high / uniform profile logic.
        self.heat_flux_zones = g.get('heat_flux_zones', None)  # list or None

        # ── UPGRADE v22: coke layer thickness ────────────────────────────────
        # δ_coke [m] — set by evolve_coke_layer(); used in pfr_odes TMT calc.
        self.k_coke = g.get('k_coke', 1.0)          # coke thermal conductivity W/m·K
        self._coke_thickness_profile = None           # set after evolve_coke_layer()
        self._coke_z_nodes           = None

        # ── UPGRADE v22: quench parameters ───────────────────────────────────
        self.quench_length      = g.get('quench_length', 3.0)      # m
        self.quench_conductance = g.get('quench_conductance', 5000.)# W/m·K per m tube

        opts = solver_opts or {}
        self.method     = opts.get('method', 'BDF')
        self.rtol       = opts.get('rtol', 1e-4)
        self.atol       = opts.get('atol', 1e-6)
        self.max_step   = opts.get('max_step', np.inf)
        self.first_step = opts.get('first_step', None)

        self._thermo = ThermoDatabase()
        # ── INDUSTRIAL UPGRADE: instantiate transport helper (used as fallback) ──
        self._ind_transport = IndustrialTransport()
        # ── INDUSTRIAL UPGRADE: instantiate RadiantBoxModel for firebox flux ──
        self._radiant_box = RadiantBoxModel()
        # ── INDUSTRIAL UPGRADE: instantiate TransferLineExchanger for quench ──
        self._tle = TransferLineExchanger()
        # ── INDUSTRIAL UPGRADE: instantiate DynamicCokeModel ─────────────────
        # One instance per engine; thickness accumulates across evolve_coke_layer
        # calls and is consumed by evolve_coke_layer to correct the stored profile.
        self._dynamic_coke = DynamicCokeModel()
        self._load(raw_reactions)

    def _load(self, raw_reactions):
        raw_reactions = dedupe_kinetic_reactions(raw_reactions)
        sp_set = {'H2O'}
        rxn_list = []
        for r in raw_reactions:
            for sp in list(r['reactants']) + list(r['products']): sp_set.add(sp)
            rxn_list.append({'A':r['A'], 'Ea':r['Ea']*1000.0,
                             'n':float(r.get('n', 0.0)),          # v24: T^n exponent
                             'falloff':r.get('falloff', None),    # v24: Lindemann/Troe
                             'reactants':r['reactants'], 'products':r['products'],
                             'type':r.get('type','')})
        self.reactions    = rxn_list
        self.species_list = list(sp_set)
        self.num_species  = len(self.species_list)
        self.sp_idx       = {sp:i for i,sp in enumerate(self.species_list)}

        nr = len(rxn_list)
        self.nu_matrix = np.zeros((self.num_species, nr))
        for j, rxn in enumerate(rxn_list):
            for sp, c in rxn['reactants'].items(): self.nu_matrix[self.sp_idx[sp], j] -= c
            for sp, c in rxn['products'].items():  self.nu_matrix[self.sp_idx[sp], j] += c

        self._k_A    = np.array([r['A']      for r in rxn_list])
        self._k_Ea_R = np.array([r['Ea']/R_GAS for r in rxn_list])
        self._k_n    = np.array([r['n']      for r in rxn_list])   # v24
        self._reac_idx = [np.array([self.sp_idx[sp] for sp in r['reactants']], dtype=int)
                          for r in rxn_list]
        self._reac_c   = [np.array(list(r['reactants'].values()), dtype=float)
                          for r in rxn_list]
        self._Hf, self._cpA, self._cpB, self._cpC, self._cpD = \
            self._thermo.build_arrays(self.species_list)
        self._mw = np.array([get_mw(sp) for sp in self.species_list])

        # ── INDUSTRIAL UPGRADE: NASA-7 Cp override array ─────────────────────
        # For species that have a NASASpecies entry, we store the object so
        # _cp_mix_nasa() can use the more accurate NASA-7 polynomial at T>1000 K.
        # Species without NASA data fall back to the DIPPR A+BT+CT²+DT³ poly.
        self._nasa_sp_map = {}    # sp_name → NASASpecies object
        for sp, nasa_obj in self._thermo._NASA_SPECIES.items():
            idx = self.sp_idx.get(sp)
            if idx is not None:
                self._nasa_sp_map[idx] = nasa_obj
        self._coke_rxns = [j for j,r in enumerate(rxn_list) if 'Coking' in r.get('type','')]
        cidx = self.sp_idx.get('COKE')
        self._coke_pairs = [(rxn_list[j], float(self.nu_matrix[cidx, j]))
                            for j in self._coke_rxns
                            if cidx is not None and self.nu_matrix[cidx, j] > 0]

    def _cp_mix_nasa(self, y_mol, T):
        """
        INDUSTRIAL UPGRADE — blended Cp [J/mol] for the mixture using NASA-7
        coefficients where available, DIPPR polynomial elsewhere.

        Returns a 1-D array of Cp_i [J/mol] in species_list order, which is
        identical in shape/use to the vectorised DIPPR expression:
            Cp_dippr = _cpA + _cpB*T + _cpC*T² + _cpD*T³

        This method is used in pfr_odes / spyro_metrics wherever Cp is needed
        at T > 800 K (cracking temperatures) to benefit from the NASA-7 fit.
        """
        cp_arr = np.maximum(
            self._cpA + self._cpB*T + self._cpC*T**2 + self._cpD*T**3, 10.0)
        # Override with NASA-7 for registered species
        for idx, nasa_obj in self._nasa_sp_map.items():
            cp_nasa = nasa_obj.cp(T)          # J/mol·K via R_UNIVERSAL
            if cp_nasa > 5.0:                 # sanity guard
                cp_arr[idx] = cp_nasa
        return cp_arr

    def _viscosity(self, y_mol, T):
        """
        UPGRADE v22 — Chapman-Enskog / Neufeld mixture viscosity [Pa·s].

        Rev-70: Vectorized. LJ-species partition cached once; Neufeld collision
        integral computed as numpy array op instead of per-species Python loop.

        Mixing rule: Herning-Zipperer   μ_mix = Σ(yᵢ·μᵢ·√Mᵢ) / Σ(yᵢ·√Mᵢ)
        """
        A_n, B_n, C_n, D_n, E_n, F_n = self._NEUFELD_A

        # Build cached LJ arrays once
        if not hasattr(self, '_visc_lj_idx'):
            lj_idx = []; lj_sig = []; lj_eps = []; nonlj_idx = []
            for idx, sp in enumerate(self.species_list):
                if sp in self._LJ:
                    sig, eps_kb = self._LJ[sp]
                    lj_idx.append(idx); lj_sig.append(sig); lj_eps.append(eps_kb)
                else:
                    nonlj_idx.append(idx)
            self._visc_lj_idx = np.array(lj_idx, dtype=int)
            self._visc_lj_sig = np.array(lj_sig)
            self._visc_lj_eps = np.array(lj_eps)
            self._visc_nonlj_idx = np.array(nonlj_idx, dtype=int)
            self._visc_sqM = np.sqrt(self._mw)

        mu_i = np.empty(self.num_species)

        # Vectorized LJ species (Neufeld collision integral)
        if len(self._visc_lj_idx) > 0:
            T_star = np.maximum(T / self._visc_lj_eps, 0.3)
            Omega = (A_n / T_star**B_n
                     + C_n / np.exp(D_n * T_star)
                     + E_n / np.exp(F_n * T_star))
            mw_lj = self._mw[self._visc_lj_idx]
            mu_i[self._visc_lj_idx] = (2.6693e-6 * np.sqrt(mw_lj * T)
                                       / (self._visc_lj_sig**2 * Omega))

        # Non-LJ heavy HCs (still need IndustrialTransport per species)
        for idx in self._visc_nonlj_idx:
            mu_i[idx] = self._ind_transport.viscosity_gas(T, self._mw[idx])

        num = np.dot(y_mol * mu_i, self._visc_sqM)
        den = np.dot(y_mol, self._visc_sqM)
        return num / max(den, 1e-30)

    def _conductivity(self, y_mol, T):
        """
        UPGRADE v23 — Mason-Saxena (1958) mixture thermal conductivity [W/(m·K)].

        Rev-70: Fully vectorized with numpy. The previous O(n²) Python double
        loop (676 iterations × 368 ODE calls = 250k inner iters with 1M max()
        calls) was 48% of total runtime. This matrix formulation is ~100×
        faster and bit-identical.

        Mixing rule (Mason-Saxena):
            k_mix = Σᵢ yᵢ·kᵢ / Σⱼ yⱼ·Φᵢⱼ
            Φᵢⱼ = [1 + (kᵢ/kⱼ)^½ (Mⱼ/Mᵢ)^¼]² / [8(1 + Mᵢ/Mⱼ)]^½
        """
        T6 = T / 600.0

        # Base heavy-HC conductivity (scalar — same for all species), then override
        k_base = self._ind_transport.conductivity_gas(T)
        k_i = np.full(self.num_species, k_base)
        # Cached override indices/params (built once)
        if not hasattr(self, '_cond_override_idx'):
            idxs = []; krefs = []; nexps = []
            for sp, k_ref, n_exp in [('H2', 0.320, 0.82), ('H2O', 0.048, 1.15),
                                       ('CH4', 0.055, 0.87), ('C2H4', 0.040, 0.86),
                                       ('C2H6', 0.035, 0.86), ('C3H6', 0.030, 0.86),
                                       ('C3H8', 0.028, 0.86)]:
                idx = self.sp_idx.get(sp)
                if idx is not None:
                    idxs.append(idx); krefs.append(k_ref); nexps.append(n_exp)
            self._cond_override_idx = np.array(idxs, dtype=int)
            self._cond_override_kref = np.array(krefs)
            self._cond_override_nexp = np.array(nexps)
            # Precompute MW interaction matrix (constant) once
            mw = self._mw
            self._cond_Mij = mw[None, :] / np.maximum(mw[:, None], 1e-30)  # M_j/M_i
            self._cond_denom_Mij = np.sqrt(np.maximum(
                8.0 * (1.0 + mw[:, None] / np.maximum(mw[None, :], 1e-30)), 1e-30))

        if len(self._cond_override_idx) > 0:
            k_i[self._cond_override_idx] = self._cond_override_kref * T6**self._cond_override_nexp

        y = np.asarray(y_mol)
        # Φ_ij = [1 + sqrt(k_i/k_j) * (M_j/M_i)^0.25]^2 / sqrt(8(1+M_i/M_j))
        ki_over_kj = k_i[:, None] / np.maximum(k_i[None, :], 1e-30)  # k_i/k_j
        phi = (1.0 + np.sqrt(ki_over_kj) * self._cond_Mij**0.25)**2 / self._cond_denom_Mij
        # phi_sum_i = Σ_j y_j Φ_ij
        phi_sum = phi @ y
        mask = y >= 1e-15
        num = np.sum(np.where(mask, y * k_i / np.maximum(phi_sum, 1e-30), 0.0))
        return max(float(num), 1e-4)

    def _compute_rates_v24(self, T: float, C: np.ndarray) -> np.ndarray:
        """
        v24 — Modified Arrhenius + Lindemann/Troe rate calculator.
        k(T) = A · T^n · exp(−Ea/RT)   [n=0 → standard Arrhenius]
        Fall-off reactions: k_eff = k_inf · [Pr/(1+Pr)] · F_troe
        """
        T_n   = np.power(float(T), self._k_n)
        k_arr = self._k_A * T_n * np.exp(-self._k_Ea_R / T)

        for j, rxn in enumerate(self.reactions):
            fo = rxn.get('falloff')
            if fo is None:
                continue
            k_inf = k_arr[j]
            k0_A  = fo.get('k0_A', 1.0)
            k0_n  = fo.get('k0_n', 0.0)
            k0_Ea = fo.get('k0_Ea', 0.0) * 1000.0 / R_GAS
            k0    = k0_A * (T ** k0_n) * np.exp(-k0_Ea / T)
            M     = float(C.sum())
            Pr    = k0 * max(M, 1e-30) / max(k_inf, 1e-300)
            troe  = fo.get('Troe')
            if troe is not None and len(troe) >= 3:
                a, T3, T1 = troe[:3]
                T2 = troe[3] if len(troe) > 3 else 1e30
                F_cent = ((1 - a)*np.exp(-T/max(T3,1e-6))
                          + a*np.exp(-T/max(T1,1e-6))
                          + np.exp(-T2/max(T,1e-6)))
                F_cent = max(F_cent, 1e-30)
                log_Fc = np.log10(F_cent)
                c_ = -0.4  - 0.67*log_Fc
                n_ =  0.75 - 1.27*log_Fc
                f1 = (np.log10(max(Pr,1e-30)) + c_) / (n_ - 0.14*(np.log10(max(Pr,1e-30))+c_))
                F  = 10.0**(log_Fc/(1.0+f1**2))
            else:
                F = 1.0
            k_arr[j] = k_inf * (Pr / (1.0 + Pr)) * F

        rates  = np.empty(len(self.reactions))
        log_C  = np.log(np.maximum(C, 1e-300))
        for j in range(len(self.reactions)):
            ci = self._reac_idx[j]; cc = self._reac_c[j]
            rates[j] = k_arr[j] * np.exp(np.dot(cc, log_C[ci]))
        return rates

    # ── v24: Circumferential heat-flux with view-factor shadowing ────────────
    _view_factor_phi: float = 1.0   # Hottel plane factor (1.0 = no shadowing)
    _view_factor_eta: float = 1.0   # shadowing factor

    def set_view_factor(self, tube_pitch_m: float, n_rows: int = 1,
                        emissivity_wall: float = 0.95) -> dict:
        """
        Pre-compute and cache Hottel view-factor shadowing correction.
        Call before engine.run() to activate circumferential correction.

        tube_pitch_m : centre-to-centre tube spacing [m]
        n_rows       : 1 (single bank) or 2 (double bank)

        Returns dict with 'phi', 'eta', 'q_ratio'.
        """
        d   = self.tube_od
        s   = max(tube_pitch_m, d * 1.001)
        rat = d / s
        phi = (1.0 - np.sqrt(max(1.0 - rat**2, 0.))
               + rat * np.arctan(np.sqrt(max((s/d)**2 - 1.0, 0.))))
        if n_rows == 2:
            phi = phi + (1.0 - phi) * phi * 0.8
        denom = 1.0/self.emissivity + phi*(1.0/emissivity_wall - 1.0)
        eta   = float(np.clip(phi / max(denom, 1e-9), 0.3, 1.0))
        self._view_factor_phi = float(phi)
        self._view_factor_eta = eta
        return {'phi': float(phi), 'eta': eta, 'q_ratio': eta*self.emissivity}

    def _q_outer(self, z, T_skin_K):
        """v24 — wraps legacy flux with optional circumferential view-factor correction."""
        q_base = self._q_outer_legacy(z, T_skin_K)
        phi    = getattr(self, '_view_factor_phi', 1.0)
        eta    = getattr(self, '_view_factor_eta', 1.0)
        if abs(phi - 1.0) < 1e-9:
            return q_base        # no correction — backward compatible
        q_front = q_base * eta
        # Back-face refractory re-radiation
        xi  = z / max(self.total_length, 1e-9)
        amp = self.profile_amplitude_K; p = self.heat_flux_profile
        if   p == 'sinusoidal': dT = amp*(np.sin(np.pi*xi) - 2./np.pi)
        elif p == 'front_high': dT = amp*(1.0 - 2.0*xi)
        elif p == 'rear_high':  dT = amp*(2.0*xi - 1.0)
        else:                   dT = 0.0
        T_fire  = self.firebox_temp_K + dT
        q_back  = (1.0 - phi)*0.95*SIGMA*max(T_fire, 0.)**4
        q_avg   = phi*q_front + (1.0 - phi)*q_back*self.emissivity
        return float(max(q_avg, 0.))

    @staticmethod
    def _churchill_f(Re, eps_D):
        """
        Churchill (1977) friction factor — valid for ALL flow regimes.

        FORMULA:
          f = 8·[ (8/Re)¹² + (A+B)^(-3/2) ]^(1/12)
          where A = [-2.457·ln((7/Re)^0.9 + 0.27·ε/D)]^16
                B = (37530/Re)^16

        VALIDITY: laminar (Re<2300), transition, and fully turbulent (Re>10⁴).
        ε/D = roughness ratio.  For new HP-alloy tubes: ε = 4.5×10⁻⁴ m.
        After coking: ε effectively increases → higher f_D → higher ΔP.

        IMPACT of changing roughness (ε):
          ε × 10  →  f_D ≈ +5–15%  →  ΔP ≈ +5–15%
          Clean tube ε=0.0001 m vs coked ε=0.002 m can double ΔP over run cycle.

        IMPACT of changing Re:
          Re↑ (higher flow)  →  f_D↓  →  ΔP↓ per unit length
          but ΔP ∝ ρ·v²·f → overall ΔP still rises with flow (quadratic)
        """
        Re = max(Re, 200.0)   # avoid division by zero at near-zero flow
        t1 = (-2.457*np.log((7.0/Re)**0.9 + 0.27*eps_D))**16
        t2 = (37530.0/Re)**16
        return 8.0*((8.0/Re)**12 + (t1+t2)**(-1.5))**(1.0/12.0)

    def _hi_gnielinski(self, F, T, P, Di):
        """
        Gnielinski (1976) inside heat-transfer coefficient.
        P is in Pa.  Returns (h_i [W/m²K], Re [-], Pr [-]).

        BUG FIXES vs v5:
          • Cp_m is in J/(mol·K); must divide by (mw_m/1000) [kg/mol] to get
            Cp_mass [J/(kg·K)] before computing Pr = mu*Cp_mass/k_g.
          • Pr clamped to [0.5, 2000] per Gnielinski validity range.
          • Re_g clamped at max(Re, 3000) — turbulent correlation requires Re>2300;
            using 3000 gives conservative margin and avoids negative Nu.
        """
        Ft   = max(F.sum(), 1e-30)
        y    = F / Ft
        mw_m = np.dot(y, self._mw)          # g/mol
        mw_m_kg = mw_m / 1000.0             # kg/mol
        # Density [kg/m³]: P[Pa] / (R[J/(mol·K)] * T[K]) * MW[kg/mol]
        rho  = P * mw_m_kg / (R_GAS * T)
        # Mass flow rate [kg/s] = molar_flow[mol/s] * MW[kg/mol]
        mdot = Ft * mw_m_kg
        vel  = mdot / max(rho * self.Ac, 1e-9)
        mu   = self._viscosity(y, T)        # Pa·s = kg/(m·s)
        k_g  = self._conductivity(y, T)     # W/(m·K)
        # INDUSTRIAL UPGRADE: delegate Re, Pr, Nu to the validated utility fns
        Re   = industrial_reynolds(rho, vel, Di, mu)
        f_D  = self._churchill_f(Re, self.roughness / Di)
        # Cp_m in J/(mol·K) — use NASA-7 blended Cp for accuracy at high T
        Cp_mol = np.dot(y, self._cp_mix_nasa(y, T))
        Cp_mass = Cp_mol / mw_m_kg          # J/(kg·K)
        Pr   = np.clip(industrial_prandtl(Cp_mass, mu, k_g), 0.5, 2000.0)
        Re_g = max(Re, 3000.0)
        Nu   = max(industrial_nusselt(Re_g, Pr), 3.66)
        # Override with Gnielinski correction for transitional/turbulent regime
        if Re_g > 2300:
            Nu_gni = (f_D/8.0) * (Re_g - 1000.0) * Pr / (
                1.0 + 12.7 * np.sqrt(f_D/8.0) * (Pr**(2.0/3.0) - 1.0))
            Nu = max(Nu_gni, 3.66)
        return Nu * k_g / Di, Re, Pr

    def _q_outer_legacy(self, z, T_skin_K):
        """
        UPGRADE v22 — Zone-wise (Lobo-Evans) external heat flux [W/m²].

        Priority order:
          1. heat_flux_zones: list of (z_start, z_end, q_kW/m²) — Lobo-Evans mode.
             Linear interpolation between zone midpoints gives a smooth profile.
          2. Legacy sinusoidal / front_high / rear_high / uniform profile.

        Radiation: q_rad = ε·σ·(T_fire⁴ − T_skin⁴)
        Convection: q_conv = h_o·(T_fire − T_skin)
        In zone mode T_fire is back-calculated from the specified flux and
        a single-step Newton on the radiation + convection equation.
        """
        if self.heat_flux_zones:
            # Interpolate specified flux at position z
            z_mids = [0.5*(z0+z1) for z0,z1,_ in self.heat_flux_zones]
            q_vals = [q*1000.0          for _,_,q  in self.heat_flux_zones]
            q_W_m2 = float(np.interp(z, z_mids, q_vals,
                                     left=q_vals[0], right=q_vals[-1]))
            return max(q_W_m2, 0.0)

        # Legacy profile logic
        xi  = z / max(self.total_length, 1e-9)
        amp = self.profile_amplitude_K
        p   = self.heat_flux_profile
        if   p == 'sinusoidal': dT = amp*(np.sin(np.pi*xi) - 2.0/np.pi)
        elif p == 'front_high': dT = amp*(1.0 - 2.0*xi)
        elif p == 'rear_high':  dT = amp*(2.0*xi - 1.0)
        else:                   dT = 0.0
        T_fire = self.firebox_temp_K + dT
        # INDUSTRIAL UPGRADE: use RadiantBoxModel for the incident radiation flux.
        # radiant_flux(T_flame, emissivity) = ε·σ·T⁴  — replaces the inline formula.
        q_rad_incident = self._radiant_box.radiant_flux(T_fire, self.emissivity)
        q_rad_absorbed = self._radiant_box.radiant_flux(T_skin_K, self.emissivity)
        q_rad  = max(q_rad_incident - q_rad_absorbed, 0.0)
        q_conv = max(self.h_o_flue*(T_fire - T_skin_K), 0.0)
        return q_rad + q_conv

    def _compressibility_Z(self, T, P, mw_mix_g, omega=0.30):
        """
        UPGRADE v22 — Pitzer truncated-virial compressibility factor Z.
        Significant for naphtha/kerosene inlets (Pr up to ~0.15).
        Z = 1 + (B0 + ω·B1)·Pr/Tr
        B0 = 0.083 − 0.422/Tr^1.6   (Pitzer-Curl)
        B1 = 0.139 − 0.172/Tr^4.2
        Pseudocritical estimated from MW (van der Waals group contribution).
        """
        Tc = max(190.0 + 30.0 * (mw_mix_g / 30.0), 300.0)   # K
        Pc = max(4.5e6 / (1.0 + 0.05 * mw_mix_g),  1.5e6)   # Pa
        try:
            return RealGasEOS.peng_robinson_z(T, P, Tc, Pc, omega)
        except Exception:
            _log_exception('Peng-Robinson EOS failed; falling back to Pitzer Z')
        Tr = T / Tc;  Pr = P / Pc
        B0 = 0.083 - 0.422 / max(Tr, 0.5)**1.6
        B1 = 0.139 - 0.172 / max(Tr, 0.5)**4.2
        return max(1.0 + (B0 + omega * B1) * Pr / max(Tr, 0.5), 0.80)

    def _tmt_resistance_chain(self, q_lin_W_m, T_gas_K, hi_W_m2K, z):
        """
        UPGRADE v22 — Full thermal-resistance TMT calculation [K].

        Resistances in series per unit tube length [K·m/W]:
          R_film = 1 / (hi · π · Di)
          R_coke = ln(Di / Di_coked) / (2π · k_coke)   [if coke layer present]
          R_wall = ln(Do / Di) / (2π · k_tube)

        Returns (T_inner_wall_K, T_outer_skin_K, delta_coke_m)
        """
        Di = self.tube_id
        Do = self.tube_od

        # Coke layer thickness at this axial position
        if (self._coke_thickness_profile is not None
                and self._coke_z_nodes is not None):
            delta_c = float(np.interp(z, self._coke_z_nodes,
                                      self._coke_thickness_profile))
            delta_c = max(min(delta_c, Di * 0.45), 0.0)   # clamp to 45 % of radius
        else:
            delta_c = 0.0

        Di_coked = max(Di - 2.0 * delta_c, Di * 0.1)

        # ── BUG-FIX v39: R_film must use coked inner diameter (the actual
        # wetted surface area), and the wall resistance must span Do→Di, not
        # Do→Di_coked.  Original code was internally consistent on R_film but
        # the comment implied Di while the code already used Di_coked — kept.
        # The real fix: R_coke must span Di_coked→Di (coke layer outer face),
        # and R_wall must span Di→Do (tube wall only).
        # Previously: R_wall = ln(Do/Di_coked) which includes the coke layer
        # thickness inside the metal wall resistance — thermally wrong.
        R_film = 1.0 / max(hi_W_m2K * np.pi * Di_coked, 1e-6)
        if delta_c > 1e-6:
            # Coke layer: from Di_coked (inner surface of coke) to Di (coke/metal interface)
            R_coke = np.log(Di / Di_coked) / max(2.0 * np.pi * self.k_coke, 1e-9)
        else:
            R_coke = 0.0
        # Tube wall: from Di (metal inner face) to Do (metal outer face)
        R_wall = np.log(Do / Di) / max(2.0 * np.pi * self.k_tube, 1e-9)

        T_inner_wall = T_gas_K + q_lin_W_m * (R_film + R_coke)
        T_outer_skin = T_inner_wall + q_lin_W_m * R_wall
        return T_inner_wall, T_outer_skin, delta_c

    def pfr_odes(self, z, y):
        """
        UPGRADE v22 — Plug-flow ODEs with Z-correction and TMT-in-ODE.

        State vector:  y = [F_0,...,F_ns-1,  T [K],  P [Pa],  tau [s]]

        New vs v21:
          • Ideal-gas density corrected by Pitzer Z-factor (relevant for
            heavy naphtha/kerosene inlet conditions).
          • T_skin for external flux computed via 3-step Newton on the full
            R_film + R_coke + R_wall thermal-resistance chain instead of
            using T_gas directly.  This makes the ODE energy balance
            self-consistent with the tube metallurgy model.
          • _q_outer now supports zone-wise (Lobo-Evans) flux tables.
        """
        F   = np.maximum(y[:self.num_species], 1e-8)
        T   = float(np.clip(y[self.num_species],     600.0, 1450.0))
        P   = float(np.clip(y[self.num_species+1],   1e4,   8e5  ))
        Ft  = F.sum()
        mw_mix_g  = np.dot(F, self._mw) / Ft   # g/mol
        mw_mix_kg = mw_mix_g / 1000.0

        # ── UPGRADE v22: Pitzer Z compressibility ───────────────────────────
        Z   = self._compressibility_Z(T, P, mw_mix_g)
        rho = P * mw_mix_kg / (Z * R_GAS * T)       # kg/m³
        vel = (Ft * mw_mix_kg) / max(rho * self.Ac, 1e-9)  # m/s
        y_mol = F / Ft

        # ── Concentrations [mol/m³] ──────────────────────────────────────────
        C = y_mol * (P / (R_GAS * T * Z))

        # ── Arrhenius rates (v24: modified Arrhenius + Lindemann fall-off) ────
        rates = self._compute_rates_v24(T, C)

        # ── Species balances [mol/(m·s)] ─────────────────────────────────────
        dF    = self.Ac * (self.nu_matrix @ rates)
        dFtot = dF.sum()

        # ── Energy balance ───────────────────────────────────────────────────
        # INDUSTRIAL UPGRADE: use NASA-7 blended Cp array for high-T accuracy
        Cp_arr = self._cp_mix_nasa(F / F.sum(), T)
        Tr = 298.15
        H_arr = (self._Hf
                 + self._cpA*(T-Tr)
                 + self._cpB/2*(T**2-Tr**2)
                 + self._cpC/3*(T**3-Tr**3)
                 + self._cpD/4*(T**4-Tr**4))
        Q_rxn = -float(rates @ (H_arr @ self.nu_matrix))
        SFCp  = float(F @ Cp_arr)

        # ── UPGRADE v22: TMT resistance chain for T_skin in ODE ─────────────
        # Compute h_i at current conditions for resistance-chain Newton solve.
        hi_ode, _, _ = self._hi_gnielinski(F, T, P, self.tube_id)
        # Initial T_skin guess = T_gas + 40 K (typical film drop)
        T_skin = T + 40.0
        for _nwt in range(4):
            q_surf = self._q_outer(z, T_skin)          # W/m² at current T_skin
            q_lin  = q_surf * np.pi * self.tube_od * self.k_heat  # W/m
            _, T_skin_new, _ = self._tmt_resistance_chain(q_lin, T, hi_ode, z)
            if abs(T_skin_new - T_skin) < 0.5: T_skin = T_skin_new; break
            T_skin = T_skin_new

        Q_ext = self._q_outer(z, T_skin) * np.pi * self.tube_od * self.k_heat
        dT = (Q_ext + self.Ac * Q_rxn) / max(SFCp, 1e-6)

        # ── Pressure drop (compressible PFR momentum) ─────────────────────────
        # UPGRADE v23: includes frictional + acceleration terms (Coil-1D standard)
        #   dP/dz = -(f_D·ρ·v²/2Di) - G²·d(1/ρ)/dz
        # where d(1/ρ)/dz ≈ (1/ρ)·(dFtot/Ft + dT/T)  (ideal-gas expansion)
        mu_mix   = self._viscosity(y_mol, T)
        Re_dp    = rho * vel * self.tube_id / max(mu_mix, 1e-12)
        f_D      = self._churchill_f(Re_dp, self.roughness / self.tube_id)
        vel_mom  = min(vel, 450.0)
        G        = rho * vel_mom                     # mass flux [kg/(m²·s)]
        G2       = G**2
        # Frictional contribution
        dP_fric  = -(f_D * G2) / (2.0 * rho * self.tube_id)
        # Acceleration contribution: G²·(1/ρ)·(dFtot/Ft + dT/T)
        drho_rho = dFtot / max(Ft, 1e-30) + dT / max(T, 1.0)  # relative density change
        dP_accel = -(G2 / max(rho, 1e-9)) * drho_rho
        dP_numer = (dP_fric + dP_accel) * self.k_dp
        # ── BUG-FIX v39: Mach-number guard (replaces wrong G²/(P·ρ) denominator)
        # The original dP_denom = max(1 - G²/(P·rho), 0.10) is dimensionally
        # inconsistent: G²/P has units kg/(m²·s²) / Pa = kg/(m²·s²·N/m²)
        # ≠ dimensionless.  The correct Mach-squared for an ideal gas is:
        #   Ma² = v² / (γ·R·T/MW) = G²/(rho²·γ·R·T/MW)
        # We simply clamp dP to never exceed 95% of the remaining pressure
        # over the remaining tube length, which is the physically meaningful
        # stability guard against the solver driving P < 0.
        dP = dP_numer   # no artificial denominator
        # Mach guard: cap |dP/dz| so pressure cannot go below P_floor in one step
        P_floor = 1e4   # Pa — absolute minimum tube pressure
        max_dP_rate = -(P - P_floor) / max(self.total_length * 0.005, 1e-3)
        if dP < max_dP_rate:
            dP = max_dP_rate

        dTau = 1.0 / max(vel, 0.01)

        dy = np.empty_like(y)
        dy[:self.num_species]  = dF
        dy[self.num_species]   = dT
        dy[self.num_species+1] = dP
        dy[self.num_species+2] = dTau
        return dy

    def run(self, init_flows, T_in_K, P_in_Pa, n_eval=200):
        """
        UPGRADE v22 — Per-pass integration with variable tube ID and bend losses.

        Each pass is integrated separately using its own tube_id and length.
        At each pass junction a 180° bend minor-loss is applied:
            ΔP_bend = k_bend · ½ · ρ · v²   [Pa]

        The output solution stitches all passes into a single arrays, matching
        the original API so all downstream code (spyro_metrics, plots) works unchanged.
        """
        ns = self.num_species

        def _run_pass(y0_p, z_start, L_p, Di_p, n_pts):
            """Integrate one pass of length L_p with inner diameter Di_p."""
            self.tube_id = Di_p
            self.Ac      = np.pi * (Di_p / 2)**2
            t_span = (z_start, z_start + L_p)
            t_eval = np.linspace(z_start, z_start + L_p, max(n_pts, 3))
            kw = dict(fun=self.pfr_odes, t_span=t_span, y0=y0_p,
                      method=self.method, rtol=self.rtol, atol=self.atol,
                      t_eval=t_eval)
            if np.isfinite(self.max_step): kw['max_step']   = self.max_step
            if self.first_step:            kw['first_step'] = self.first_step
            return solve_ivp(**kw)

        # Initial state vector
        y0 = np.full(ns + 3, 1e-8)
        for sp, f in init_flows.items():
            if sp in self.sp_idx: y0[self.sp_idx[sp]] = f / self.coils
        y0[ns]   = T_in_K
        y0[ns+1] = P_in_Pa
        y0[ns+2] = 0.0

        all_t = []; all_y = []
        z_cursor = 0.0
        n_pts_per_pass = max(n_eval // self.passes, 4)

        for p_idx in range(self.passes):
            Di_p = self._tube_id_per_pass[p_idx]
            L_p  = self._length_per_pass_list[p_idx]

            sol_p = _run_pass(y0, z_cursor, L_p, Di_p, n_pts_per_pass)
            if not sol_p.success:
                # Restore default tube geometry on failure
                self.tube_id = self.tube_id_clean
                self.Ac = np.pi * (self.tube_id / 2)**2
                # Return a synthetic failed solution object
                from types import SimpleNamespace
                fake = SimpleNamespace(success=False, t=np.array([0., L_p]),
                                       y=np.tile(y0[:,None], 2))
                return fake

            # Collect results (skip last point — will be re-used as next y0)
            all_t.append(sol_p.t[:-1])
            all_y.append(sol_p.y[:, :-1])

            # State at pass exit
            y0 = sol_p.y[:, -1].copy()
            last_sol_p = sol_p          # BUG-FIX v39: keep explicit reference
            z_cursor += L_p

            # Apply bend minor loss between passes (not after last pass)
            if p_idx < self.passes - 1:
                # Compute local rho·v² for bend ΔP
                F_b  = np.maximum(y0[:ns], 1e-8)
                T_b  = float(np.clip(y0[ns], 600, 1450))
                P_b  = float(np.clip(y0[ns+1], 1e4, 8e5))
                Ft_b = F_b.sum()
                mw_b = np.dot(F_b, self._mw) / Ft_b / 1000.0  # kg/mol
                Z_b  = self._compressibility_Z(T_b, P_b, mw_b*1000.)
                rho_b= P_b * mw_b / (Z_b * R_GAS * T_b)
                vel_b= (Ft_b * mw_b) / max(rho_b * self.Ac, 1e-9)
                dP_bend = self.bend_kfactor * 0.5 * rho_b * min(vel_b, 300.0)**2
                y0[ns+1] = max(y0[ns+1] - dP_bend, 1e4)

        # Append final point (BUG-FIX v39: use last_sol_p, not sol_p loop var)
        all_t.append(np.array([z_cursor]))
        all_y.append(last_sol_p.y[:, -1:])

        # Stitch into a single solution-like object
        from types import SimpleNamespace
        stitched = SimpleNamespace(
            success = True,
            t       = np.concatenate(all_t),
            y       = np.concatenate(all_y, axis=1),
        )

        # Restore default tube geometry
        self.tube_id = self.tube_id_clean
        self.Ac = np.pi * (self.tube_id / 2)**2
        return stitched

    def run_fast(self, init_flows, T_in_K, P_in_Pa, n_steps=60):
        """
        Rev-69b: Fast PFR integration for bracket evaluations.

        Uses LSODA with aggressive tolerances (rtol=1e-2, atol=1e-3) — the
        auto-stiffness-detection makes it safe for all feeds while being 3-10×
        faster than BDF at production tolerances. n_steps parameter is ignored
        (kept for API compat); LSODA chooses its own internal steps.

        Returns only the endpoint state for conversion evaluation.
        """
        ns = self.num_species

        # Save and swap solver settings
        _save = (self.method, self.rtol, self.atol, self.max_step, self.first_step)
        self.method = 'LSODA'
        self.rtol   = 1e-2
        self.atol   = 1e-3
        self.max_step = np.inf
        self.first_step = 0

        # Build y0
        y0 = np.full(ns + 3, 1e-8)
        for sp, f in init_flows.items():
            if sp in self.sp_idx:
                y0[self.sp_idx[sp]] = f / self.coils
        y0[ns]   = T_in_K
        y0[ns+1] = P_in_Pa
        y0[ns+2] = 0.0

        all_y_end = y0.copy()
        z_cursor = 0.0
        success = True

        for p_idx in range(self.passes):
            Di_p = self._tube_id_per_pass[p_idx]
            L_p  = self._length_per_pass_list[p_idx]
            self.tube_id = Di_p
            self.Ac = np.pi * (Di_p / 2)**2

            t_span = (z_cursor, z_cursor + L_p)
            # Only evaluate at endpoint — minimal overhead
            try:
                sol_p = solve_ivp(
                    fun=self.pfr_odes, t_span=t_span, y0=all_y_end,
                    method='LSODA', rtol=1e-2, atol=1e-3,
                    t_eval=[z_cursor + L_p],
                    dense_output=False)
                if not sol_p.success or sol_p.y.shape[1] == 0:
                    success = False; break
                all_y_end = sol_p.y[:, -1].copy()
            except Exception:
                success = False; break

            z_cursor += L_p

            # Bend loss
            if p_idx < self.passes - 1 and success:
                F_b  = np.maximum(all_y_end[:ns], 1e-8)
                T_b  = float(np.clip(all_y_end[ns], 600, 1450))
                P_b  = float(np.clip(all_y_end[ns+1], 1e4, 8e5))
                Ft_b = F_b.sum()
                mw_b = np.dot(F_b, self._mw) / Ft_b / 1000.0
                Z_b  = self._compressibility_Z(T_b, P_b, mw_b*1000.)
                rho_b= P_b * mw_b / (Z_b * R_GAS * T_b)
                vel_b= (Ft_b * mw_b) / max(rho_b * self.Ac, 1e-9)
                dP_bend = self.bend_kfactor * 0.5 * rho_b * min(vel_b, 300.0)**2
                all_y_end[ns+1] = max(all_y_end[ns+1] - dP_bend, 1e4)

        # Restore settings
        self.method, self.rtol, self.atol, self.max_step, self.first_step = _save
        self.tube_id = self.tube_id_clean
        self.Ac = np.pi * (self.tube_id / 2)**2

        from types import SimpleNamespace
        return SimpleNamespace(
            success=success,
            t=np.array([0.0, self.total_length]),
            y=np.column_stack([all_y_end, all_y_end]),
        )

    def coking_profile(self, sol):
        """
        UPGRADE v23 — Two-stage coke deposition model [kg/(m²·h)].

        Stage 1 – Catalytic coking (Fe/Ni surface sites):
            Dominant below ~900 °C (1173 K).  Rate proportional to C2H4 and
            alkene surface reactions.  A-factor boosted ×3 at fresh-tube start.

        Stage 2 – Pyrolytic coking (gas-phase radical):
            Dominant above ~750 °C (1023 K).  From C3H4, C4H4, C8H8, C4H6,
            C6H6 condensation routes.

        Transition: smooth sigmoid blend σ(T) = 1/(1+exp((T_mid-T)/ΔT))
            σ→0: catalytic dominant (low T)
            σ→1: pyrolytic dominant (high T)
        Combined:  ṁ = (1-σ)·ṁ_cat + σ·ṁ_pyr

        Vectorized over all axial points at once (~20× faster than loop).
        """
        ns = self.num_species
        n  = sol.t.shape[0]
        if not self._coke_pairs:
            return sol.t, np.zeros(n)

        F_all  = np.maximum(sol.y[:ns, :], 1e-8)              # (ns, n)
        T_all  = np.clip(sol.y[ns,    :], 600., 1450.)         # (n,)
        P_all  = np.clip(sol.y[ns+1,  :], 1e4,  8e5)          # (n,)
        Ft_all = F_all.sum(axis=0)
        C_all  = (F_all / Ft_all) * P_all / (R_GAS * T_all)   # (ns, n) [mol/m³]

        # Sigmoid transition function: σ→0 catalytic, σ→1 pyrolytic
        T_mid = 1073.0   # 800 °C crossover
        dT_sig = 80.0    # 80 K width
        sigma  = 1.0 / (1.0 + np.exp((T_mid - T_all) / dT_sig))  # (n,)

        prof_cat = np.zeros(n)   # catalytic contribution
        prof_pyr = np.zeros(n)   # pyrolytic contribution

        for rxn, nu_c in self._coke_pairs:
            k_arr = rxn['A'] * np.exp(-rxn['Ea'] / (R_GAS * T_all))
            rate  = k_arr.copy()
            for sp, coeff in rxn['reactants'].items():
                if sp in self.sp_idx:
                    rate *= C_all[self.sp_idx[sp], :] ** coeff
            contribution = nu_c * rate
            if 'Catalytic' in rxn.get('type', ''):
                prof_cat += contribution
            else:
                prof_pyr += contribution

        # Blend: low-T → catalytic dominates; high-T → pyrolytic dominates
        prof = (1.0 - sigma) * prof_cat + sigma * prof_pyr

        mass_flux = prof * (self.Ac / (np.pi * self.tube_id)) * (12.011 / 1000.)
        return sol.t, mass_flux * 3600.

    def transport_profiles(self, sol):
        """
        Vectorized transport profiles — all 200 axial points computed in one
        numpy pass instead of a Python for-loop.  ~15× faster than the
        point-by-point version.

        Returns dict: Re, h_i, vel, tau, Pr  (all shape [n_points])
        """
        ns = self.num_species
        # All species flows: shape (ns, n)
        F_all = np.maximum(sol.y[:ns, :], 1e-8)           # (ns, n)
        T_all = np.clip(sol.y[ns,   :], 600., 1450.)       # (n,)
        P_all = np.clip(sol.y[ns+1, :], 1e4,  8e5 )       # (n,)
        tau   = sol.y[ns+2, :]

        Ft_all    = F_all.sum(axis=0)                       # (n,)
        # mw_m_kg shape (n,): dot product over species axis
        mw_m_kg   = (F_all.T @ self._mw) / (Ft_all * 1000.)  # (n,)

        # ── BUG-FIX v39: apply Pitzer-Z compressibility, consistent with pfr_odes
        # Original code used ideal-gas density: rho = P·MW/(R·T)
        # pfr_odes uses Z-corrected: rho = P·MW/(Z·R·T).
        # Without this correction, Re and h_i in the profiles are ~2-5% high
        # for naphtha/kerosene inlets where Pr can reach 0.10-0.15.
        Z_all = np.array([
            self._compressibility_Z(float(T_all[i]), float(P_all[i]),
                                    float(mw_m_kg[i] * 1000.))
            for i in range(len(T_all))
        ])
        rho_all   = P_all * mw_m_kg / (Z_all * R_GAS * T_all)  # (n,)
        vel_all   = (Ft_all * mw_m_kg) / np.maximum(rho_all * self.Ac, 1e-9)

        # Mole fractions: shape (ns, n)
        y_all = F_all / Ft_all[np.newaxis, :]

        # ── UPGRADE v22: Vectorized Chapman-Enskog / Neufeld viscosity ──────────
        A_n, B_n, C_n, D_n, E_n, F_n = self._NEUFELD_A
        mu_i = np.empty((self.num_species, len(T_all)))
        for idx, sp in enumerate(self.species_list):
            if sp in self._LJ:
                sig, eps_kb = self._LJ[sp]
                T_star = np.maximum(T_all / eps_kb, 0.3)
                Omega  = A_n/T_star**B_n + C_n/np.exp(D_n*T_star) + E_n/np.exp(F_n*T_star)
                mu_i[idx, :] = 2.6693e-6 * np.sqrt(self._mw[idx] * T_all) / (sig**2 * Omega)
            else:
                T6_loc = T_all / 600.0
                mu_i[idx, :] = 8.5e-6 * (self._mw[idx] / 30.0)**0.22 * T6_loc**0.75
        sqM   = np.sqrt(self._mw)[:, np.newaxis]
        mu_all = np.sum(y_all * mu_i * sqM, axis=0) / np.maximum(np.sum(y_all * sqM, axis=0), 1e-30)

        # ── Vectorized conductivity — Mason-Saxena (UPGRADE v23) ─────────────
        T6 = T_all / 600.0
        k_i = 0.040 * (self._mw / 30.0)[:, np.newaxis]**(-0.30) * T6[np.newaxis, :]**0.85
        _k_override = [('H2', 0.320, 0.82), ('H2O', 0.048, 1.15),
                       ('CH4', 0.055, 0.87), ('C2H4', 0.040, 0.86),
                       ('C2H6', 0.035, 0.86), ('C3H6', 0.030, 0.86),
                       ('C3H8', 0.028, 0.86)]
        for sp, k_ref, n_exp in _k_override:
            idx = self.sp_idx.get(sp)
            if idx is not None:
                k_i[idx, :] = k_ref * T6**n_exp
        # Mason-Saxena vectorised: Φᵢⱼ = [1+(kᵢ/kⱼ)^½(Mⱼ/Mᵢ)^¼]²/[8(1+Mᵢ/Mⱼ)]^½
        # Shape: (ns, ns, n_points); compute per-species numerator sum
        mw_col = self._mw[:, np.newaxis]   # (ns,1)
        mw_row = self._mw[np.newaxis, :]   # (1,ns)
        # Precompute MW ratio matrix (ns x ns)
        mw_ratio = mw_row / np.maximum(mw_col, 1e-30)         # Mⱼ/Mᵢ
        ms_denom = np.sqrt(np.maximum(8.0 * (1.0 + 1.0/np.maximum(mw_ratio, 1e-30)), 1e-30))
        kg_all = np.zeros(len(T_all))
        for pt in range(len(T_all)):
            ki_pt = k_i[:, pt]                                 # (ns,)
            yi_pt = y_all[:, pt]                               # (ns,)
            ratio_k = ki_pt[:, np.newaxis] / np.maximum(ki_pt[np.newaxis, :], 1e-30)
            phi = (1.0 + np.sqrt(ratio_k) * mw_ratio**0.25)**2 / ms_denom
            phi_sum = phi @ yi_pt                              # (ns,)  Σⱼ yⱼ Φᵢⱼ
            kg_all[pt] = np.sum(yi_pt * ki_pt / np.maximum(phi_sum, 1e-30))

        # ── Vectorized Cp and Pr ──────────────────────────────────────────────
        Cp_all = np.maximum(
            self._cpA[:, np.newaxis]
            + self._cpB[:, np.newaxis] * T_all
            + self._cpC[:, np.newaxis] * T_all**2
            + self._cpD[:, np.newaxis] * T_all**3, 10.)          # (ns, n)
        Cp_mol_mean = np.sum(y_all * Cp_all, axis=0)              # (n,) J/(mol·K)
        Cp_mass_all = Cp_mol_mean / mw_m_kg                        # (n,) J/(kg·K)
        Pr_all = np.clip(mu_all * Cp_mass_all / np.maximum(kg_all, 1e-10), 0.5, 2000.)

        # ── Vectorized Gnielinski ─────────────────────────────────────────────
        Re_all = rho_all * vel_all * self.tube_id / np.maximum(mu_all, 1e-12)
        eps_D  = self.roughness / self.tube_id
        # Churchill friction factor — vectorized
        Re_c   = np.maximum(Re_all, 200.)
        t1     = (-2.457 * np.log((7./Re_c)**0.9 + 0.27*eps_D))**16
        t2     = (37530. / Re_c)**16
        f_D    = 8. * ((8./Re_c)**12 + (t1+t2)**(-1.5))**(1./12.)
        Re_g   = np.maximum(Re_all, 3000.)
        Nu_all = np.maximum(
            (f_D/8.) * (Re_g - 1000.) * Pr_all
            / (1. + 12.7 * np.sqrt(f_D/8.) * (Pr_all**(2./3.) - 1.)),
            3.66)
        hi_all = Nu_all * kg_all / self.tube_id

        return {'Re': Re_all, 'h_i': hi_all, 'vel': vel_all, 'tau': tau, 'Pr': Pr_all}

    # ─── UPGRADE v22: TLE / quench zone ─────────────────────────────────────
    def run_quench(self, sol_furnace, T_quench_target_K=700.0,
                   quench_length=None, n_eval=50):
        """
        UPGRADE v22 — Transfer Line Exchanger (TLE) quench simulation.

        Continues the PFR integration past the furnace exit with a forced-
        cooling boundary condition instead of firebox radiation.  Secondary
        reactions (e.g. diene oligomerisation, BTX growth) still proceed at
        the elevated inlet temperature and are quenched as T drops.

        The cooler is modelled as a distributed heat sink:
            dQ/dz = −UA_per_m · (T − T_quench_target)   [W/m]

        UA_per_m = self.quench_conductance [W/(m·K)] (set in geom or __init__).

        Returns a stitched solution object (same API as run()).
        """
        ns = self.num_species
        L_q = quench_length if quench_length is not None else self.quench_length
        z0  = sol_furnace.t[-1]
        y0  = sol_furnace.y[:, -1].copy()

        # INDUSTRIAL UPGRADE: use TransferLineExchanger to cross-check the
        # quench target. quench_temperature(T_in, duty_kW) gives a simple
        # duty-based estimate; we use it to clamp T_quench_target_K so it
        # never exceeds the furnace exit temperature (prevents sign reversal
        # in Q_cool that would add heat instead of removing it).
        T_furnace_exit = float(y0[ns])
        duty_estimate_kW = self.quench_conductance * L_q * (
            T_furnace_exit - T_quench_target_K) / 1000.0
        T_tle_estimate = self._tle.quench_temperature(T_furnace_exit, duty_estimate_kW)
        # Use the more conservative (higher) of the two estimates so we never
        # over-cool below what the TLE duty can physically achieve.
        T_quench_target_K = max(T_quench_target_K, min(T_tle_estimate, T_furnace_exit - 1.0))

        def quench_odes(z, y):
            dy = self.pfr_odes(z, y)   # full PFR physics (reactions + momentum)
            T  = float(np.clip(y[ns], 400.0, 1600.0))
            # Override the heat term: replace firebox flux with forced cooling
            # Back-calculate the firebox heat contribution from dT equation and remove it,
            # then add the quench cooling term.
            F      = np.maximum(y[:ns], 1e-8)
            Cp_arr = np.maximum(self._cpA + self._cpB*T + self._cpC*T**2
                                + self._cpD*T**3, 10.0)
            SFCp   = float(F @ Cp_arr)
            Q_cool = -self.quench_conductance * (T - T_quench_target_K)  # W/m  (<0 cooling)
            # Remove firebox external heat, add quench cooling
            hi_q, _, _ = self._hi_gnielinski(F, T, float(np.clip(y[ns+1],1e4,8e5)),
                                              self.tube_id)
            Q_fire = self._q_outer(z, T + 30.0) * np.pi * self.tube_od * self.k_heat
            dy[ns] += (Q_cool - Q_fire) / max(SFCp, 1e-6)
            return dy

        from types import SimpleNamespace
        try:
            sol_q = solve_ivp(quench_odes, (z0, z0 + L_q), y0,
                              method=self.method, rtol=self.rtol, atol=self.atol,
                              t_eval=np.linspace(z0, z0 + L_q, n_eval))
            if not sol_q.success:
                return None
            # Stitch furnace + quench
            stitched = SimpleNamespace(
                success = True,
                t       = np.concatenate([sol_furnace.t, sol_q.t[1:]]),
                y       = np.concatenate([sol_furnace.y, sol_q.y[:, 1:]], axis=1),
            )
            return stitched
        except Exception:
            return None

    # ─── UPGRADE v22: campaign coke evolution ────────────────────────────────
    def evolve_coke_layer(self, sol, run_hours):
        """
        UPGRADE v22 — Integrate deposition rate over a run campaign.

        Given the fresh-tube solution sol (δ = 0), computes the coke layer
        thickness profile δ(z) [m] after run_hours hours of operation.
        The result is stored internally and used by pfr_odes + spyro_metrics
        for the next call to run() (e.g. end-of-run simulation).

        Physics:
            δ(z, t) = ∫₀ᵗ [ṁ_dep(z) / ρ_coke] dt
            ṁ_dep   = coking_profile()[1]  [kg/(m²·h)]

        Updates:
            self._coke_z_nodes           → z positions [m]
            self._coke_thickness_profile → δ [m] at each z
            self.tube_id_clean           → unchanged (reference)

        Returns (z_nodes, thickness_m, Di_eff_m, tmt_increase_K)
        """
        z_nodes, coke_rate_kg_m2_h = self.coking_profile(sol)
        thickness_m = coke_rate_kg_m2_h * run_hours / self.rho_coke  # [m]

        # ── INDUSTRIAL UPGRADE: DynamicCokeModel correction ──────────────────
        # The two-stage rate profile above gives the spatially-resolved base
        # thickness.  DynamicCokeModel.update() adds an Arrhenius wall-temp
        # correction for each axial node, accounting for the fact that wall
        # temperature (not bulk gas temperature) drives the exponential
        # catalytic/surface growth term.  The correction is additive and
        # bounded to ≤30 % of the base thickness to avoid double-counting.
        #
        # hc_factor proxy: normalised local HC concentration (ethylene + propylene
        # mole fraction), which governs catalytic site availability.
        ns   = self.num_species
        T_all = np.clip(sol.y[ns, :], 600., 1450.)
        F_all = np.maximum(sol.y[:ns, :], 1e-8)
        Ft_all = F_all.sum(axis=0)
        y_all  = F_all / Ft_all

        hc_idx = [self.sp_idx[sp] for sp in ('C2H4', 'C3H6', 'C2H6', 'C3H8')
                  if sp in self.sp_idx]
        hc_frac = y_all[hc_idx, :].sum(axis=0) if hc_idx else np.ones(len(T_all))
        hc_frac = np.clip(hc_frac, 0.01, 1.0)

        dt_s = run_hours * 3600.0          # total run time in seconds
        dcm_correction = np.zeros(len(z_nodes))
        for i, (T_wall, hc) in enumerate(zip(T_all, hc_frac)):
            # update() is cumulative; use a fresh model per node so each node
            # gets an independent trajectory (avoids cross-node state bleed).
            dcm = DynamicCokeModel()
            dcm_correction[i] = dcm.update(dt_s, T_wall, float(hc))

        # Clamp correction to ≤30 % of the base two-stage thickness
        max_correction = 0.30 * np.maximum(thickness_m, 1e-9)
        dcm_correction  = np.minimum(dcm_correction, max_correction)

        thickness_m = thickness_m + dcm_correction
        # ── END DynamicCokeModel correction ──────────────────────────────────

        # Store for use in subsequent run() / pfr_odes calls
        self._coke_z_nodes           = z_nodes
        self._coke_thickness_profile = thickness_m

        Di_eff = np.maximum(self.tube_id_clean - 2.0 * thickness_m,
                             self.tube_id_clean * 0.10)

        # Estimate TMT increase from coke layer
        # δT_coke ≈ q̄ · δ / k_coke   (flat-wall approximation, conservative)
        ns = self.num_species
        T_all = np.clip(sol.y[ns, :], 600., 1450.)
        P_all = np.clip(sol.y[ns+1, :], 1e4, 8e5)
        F_all = np.maximum(sol.y[:ns, :], 1e-8)
        Ft    = F_all.sum(axis=0)
        y_all = F_all / Ft
        # mean heat flux from T_fire − T_gas
        q_mean_W_m2 = np.array([
            self._q_outer(z_nodes[i], T_all[i]) for i in range(len(z_nodes))])
        dT_coke = q_mean_W_m2 * thickness_m / max(self.k_coke, 0.1)
        tmt_increase_K = float(np.max(dT_coke))

        return z_nodes, thickness_m, Di_eff, tmt_increase_K




