def _profile_key_from_components(fc):
    f=set(fc or [])
    if 'C2H5OH' in f or 'CH3OH' in f: return 'bio'
    if any(s in f for s in ('nC18','nC20','nC22','nC24','C16H32')): return 'wax'
    if 'C2H6' in f and len(f)<=2: return 'ethane'
    if 'C3H8' in f and not any(s in f for s in ('C4H10','iC4H10')): return 'propane'
    if any(s in f for s in ('C4H10','iC4H10')) and 'C3H8' in f: return 'lpg'
    return 'naphtha_full'
def _product_profile_for_components(fc): return PROFILES.get(_profile_key_from_components(fc),NAPHTHA_DETAILED_PRODUCT_PROFILE)
