def get_tuned_defaults(feed_type: str) -> dict:
    """Return calibrated KineticsTuner + geometry multiplier defaults for a feed type."""
    _key = feed_type.lower().replace(' ','_').replace('-','_')
    for k in TUNED_DEFAULTS:
        if k in _key or _key in k:
            return dict(TUNED_DEFAULTS[k])
    return dict(TUNED_DEFAULTS['naphtha'])   # fallback


def _R_factory(tuner, rxns):
    # A-factors in the literature for cracking kinetics are typically in
    # L^(n-1)/(mol^(n-1)·s) where n = reaction order. The engine integrates
    # concentrations in mol/m³, so we auto-convert A by 1e-3^(order-1).
    def R(re, pr, A, Ea, cat):
        if not check_balance(re, pr):
            raise ValueError(f"UNBALANCED: {re} -> {pr}")
        order = sum(re.values())
        A_SI  = A * (1e-3 ** (order - 1))
        rxns.append({'reactants':re,'products':pr,
                     'A':tuner.apply(A_SI, cat),'Ea':Ea,'type':cat})
    return R


def build_ethane_reactions(tuner=None):
    t = tuner or KineticsTuner(); rxns=[]; R = _R_factory(t, rxns)
    # ── PRIMARY ethane cracking  (Sundaram & Froment 1977 + Zimmermann 2012) ──
    # C2H6 → C2H4 + H2: dominant route at 820–870°C; A calibrated to give
    # C2H4 ≈ 50–55 wt% dry at 67% conversion (Zimmermann 2012 DS-E1 reference)
    R({'C2H6':1},          {'C2H4':1,'H2':1},             4.652e13,273.,'Paraffin_Crack')
    R({'C2H6':1,'H2':1},   {'CH4':2},                     3.000e11,254.,'Paraffin_Crack')
    R({'C2H6':2},          {'C3H8':1,'CH4':1},            3.850e11,273.6,'Paraffin_Crack')
    R({'C2H6':1,'C2H4':1}, {'C3H6':1,'CH4':1},            7.083e13,253.,'Olefin_Crack')
    R({'C2H6':1,'C3H6':1}, {'C3H8':1,'C2H4':1},           1.000e10,200.,'Olefin_Crack')
    # ── C2H4 secondary network ────────────────────────────────────────────────
    # Dehydrogenation C2H4→C2H2+H2: high Ea=310, stays slow at moderate T
    R({'C2H4':1},          {'C2H2':1,'H2':1},             3.790e13,310.,'Dehydrogenation')
    R({'C2H4':1,'H2':1},   {'C2H6':1},                    5.000e9, 180.,'Hydrogenation')
    # C2H4 dimerisation — kept slow: only significant at high conv
    R({'C2H4':2},          {'C4H8':1},                    1.025e11,172.6,'Condensation')
    R({'C2H4':2},          {'C4H6':1,'H2':1},             5.000e10,220.,'Condensation')
    R({'C2H2':1,'H2':1},   {'C2H4':1},                    1.000e10,160.,'Hydrogenation')
    R({'C2H2':2},          {'C4H4':1},                    5.000e9, 180.,'Condensation')
    R({'C2H2':1,'C2H4':1}, {'C4H6':1},                    1.000e10,185.,'Condensation')
    R({'C2H6':1,'C2H2':1}, {'C4H6':1,'H2':1},             8.000e9, 198.,'Condensation')
    # ── C3H8 minor cracking (from C2H6 dimerisation) ─────────────────────────
    R({'C3H8':1},          {'C3H6':1,'H2':1},             5.888e10,214.7,'Paraffin_Crack')
    R({'C3H8':1},          {'C2H4':1,'CH4':1},            4.692e10,211.,'Paraffin_Crack')
    R({'C3H8':1,'H2':1},   {'C2H6':1,'CH4':1},            2.000e11,220.,'Paraffin_Crack')
    R({'C3H8':1,'C2H4':1}, {'C2H6':1,'C3H6':1},           2.540e16,247.1,'Olefin_Crack')
    R({'C3H8':2},          {'C4H10':1,'C2H6':1},          5.000e10,262.,'Paraffin_Crack')
    # ── C3H6 secondary cracking ───────────────────────────────────────────────
    R({'C3H6':1},          {'C2H2':1,'CH4':1},            2.210e10,232.,'Olefin_Crack')
    # C3H6→C3H4+H2: REDUCED 10× vs old value to prevent C3H4 over-accumulation
    R({'C3H6':1},          {'C3H4':1,'H2':1},             3.000e12,290.,'Dehydrogenation')
    R({'C3H6':1,'H2':1},   {'C3H8':1},                    1.500e10,165.,'Hydrogenation')
    R({'C3H6':1,'C2H6':1}, {'C3H8':1,'C2H4':1},           1.000e10,200.,'Olefin_Crack')
    R({'C3H6':2},          {'C2H4':3},                    1.420e11,222.,'Olefin_Crack')
    # ── C3H4 RAPID destruction — prevents C3H4 accumulation ──────────────────
    # C3H4+H2→C2H2+CH4: A boosted 5× to consume C3H4 that would otherwise pile up
    R({'C3H4':1,'H2':1},   {'C2H2':1,'CH4':1},            5.000e13,260.,'Olefin_Crack')
    R({'C3H4':1,'H2':1},   {'C3H6':1},                    5.000e9, 150.,'Hydrogenation')
    R({'C3H4':1,'C2H4':1}, {'C5H8':1},                    1.000e10,190.,'Condensation')
    R({'C3H4':2},          {'C6H6':1,'H2':1},             2.000e10,190.,'Condensation')
    # ── C4 network ────────────────────────────────────────────────────────────
    # C4H8 cracking: keep A low to avoid C4H8 over-accumulation
    R({'C4H8':1},          {'C4H6':1,'H2':1},             4.620e11,234.,'Dehydrogenation')
    R({'C4H8':1},          {'C2H4':2},                    2.000e13,260.,'Olefin_Crack')
    R({'C4H8':1},          {'C3H4':1,'CH4':1},            5.000e11,255.,'Olefin_Crack')
    R({'C4H6':1},          {'C2H4':1,'C2H2':1},           1.000e13,275.,'Olefin_Crack')
    R({'C4H6':1,'H2':1},   {'C4H8':1},                    3.000e9, 145.,'Hydrogenation')
    R({'C4H6':1,'C2H4':1}, {'C6H6':1,'H2':2},             8.000e11,175.,'Condensation')
    R({'C4H4':1,'H2':1},   {'C4H6':1},                    2.000e9, 145.,'Hydrogenation')
    # ── C4H10 / iC4H10 minor (present in some ethane feeds) ──────────────────
    R({'C4H10':1},         {'C4H8':1,'H2':1},             3.000e13,270.,'Paraffin_Crack')
    R({'C4H10':1},         {'C2H6':1,'C2H4':1},           2.000e13,260.,'Paraffin_Crack')
    R({'C4H10':1},         {'C3H6':1,'CH4':1},            1.500e13,262.,'Paraffin_Crack')
    R({'iC4H10':1},        {'iC4H8':1,'H2':1},            2.000e13,268.,'Paraffin_Crack')
    R({'iC4H8':1},         {'C3H4':1,'CH4':1},            5.000e12,260.,'Olefin_Crack')
    R({'iC4H8':1},         {'C4H6':1,'H2':1},             3.000e11,245.,'Dehydrogenation')
    # ── C5+ condensation ──────────────────────────────────────────────────────
    R({'C2H4':1,'C3H6':1}, {'C5H10':1},                   5.000e10,185.,'Condensation')
    R({'C5H10':1},         {'C3H6':1,'C2H4':1},           3.000e13,265.,'Olefin_Crack')
    R({'C5H10':1},         {'C5H8':1,'H2':1},             1.000e12,230.,'Dehydrogenation')
    R({'C5H8':1},          {'C3H4':1,'C2H4':1},           5.000e12,255.,'Olefin_Crack')
    R({'C3H6':2},          {'C6H12':1},                   1.000e11,185.,'Condensation')
    R({'C6H12':1},         {'C3H6':2},                    3.000e13,265.,'Olefin_Crack')
    R({'C6H12':1},         {'C6H6':1,'H2':3},             3.000e13,270.,'Dehydrogenation')
    R({'C4H4':1,'C2H4':1}, {'C6H6':1,'H2':1},             5.000e11,165.,'Condensation')
    R({'C3H6':2},          {'C6H6':1,'H2':3},             5.000e9, 200.,'Condensation')
    R({'C6H6':1,'C2H4':1}, {'C8H8':1,'H2':1},             1.000e11,200.,'Condensation')
    R({'C8H8':1},          {'C6H6':1,'C2H2':1},           5.000e12,245.,'Olefin_Crack')
    R({'C6H6':1,'C4H6':1}, {'C10H8':1,'H2':2},            2.000e11,185.,'PAH_Growth')
    R({'C6H6':2},          {'C12H10':1,'H2':1},           5.000e10,215.,'PAH_Growth')
    # ── Coking ────────────────────────────────────────────────────────────────
    R({'C3H4':1},          {'COKE':3,'H2':2},             1.500e5, 170.,'Coking (Pyrolytic)')
    R({'C4H4':1},          {'COKE':4,'H2':2},             3.000e5, 178.,'Coking (Pyrolytic)')
    R({'C8H8':1},          {'COKE':8,'H2':4},             2.000e5, 168.,'Coking (Pyrolytic)')
    R({'C2H4':1},          {'COKE':2,'H2':2},             4.0e4,   135.,'Coking (Catalytic)')
    R({'C4H6':1},          {'COKE':4,'H2':3},             8.0e4,   105.,'Coking (Pyrolytic)')
    R({'C6H6':1},          {'COKE':6,'H2':3},             5.0e4,   115.,'Coking (Pyrolytic)')
    R({'COKE':1,'H2O':1},  {'CO':1,'H2':1},               2.0e7,   160.,'Steam Gasification')
    R({'CH4':1,'H2O':1},   {'CO':1,'H2':3},               1.0e10,  200.,'Steam Reforming')
    R({'CO':1,'H2O':1},    {'CO2':1,'H2':1},              1.0e8,   100.,'Water-Gas Shift')
    # ── v38 CALIBRATION (Ethane) — Zimmermann & Walzl (2012) ──────────────────
    # CH4 from methyl recombination proxy: 2C2H6→CH4+C3H8  C:4=1+3✓ H:12=4+8✓
    R({'C2H6':2}, {'CH4':1,'C3H8':1},                 1.200e12, 282., 'Paraffin_Crack')
    # CH4 from butylene cracking: C4H8→CH4+C3H4  C:4=4✓ H:8=4+4✓
    R({'C4H8':1}, {'CH4':1,'C3H4':1},                 4.000e13, 255., 'Olefin_Crack')
    # C4H6 boost via dimerisation: 2C2H4→C4H6+H2  C:4=4✓ H:8=6+2✓
    R({'C2H4':2}, {'C4H6':1,'H2':1},                  8.000e12, 220., 'Condensation')
    # C4H6 via vinylacetylene: C2H2+C2H4→C4H6  C:4=4✓ H:2+4=6✓
    R({'C2H2':1,'C2H4':1}, {'C4H6':1},                2.500e12, 185., 'Condensation')
    # Benzene via Diels-Alder: C4H6+C2H4→C6H6+2H2  C:6=6✓ H:10=6+4✓
    R({'C4H6':1,'C2H4':1}, {'C6H6':1,'H2':2},         2.000e12, 172., 'Condensation')
    # Toluene: C4H6+C3H4→C7H8+H2  C:7=7✓ H:10=8+2✓
    R({'C4H6':1,'C3H4':1}, {'C7H8':1,'H2':1},         1.000e11, 195., 'Condensation')
    # ── END ETHANE CALIBRATION ───────────────────────────────────────────────

    return rxns


def build_ethane_radical_reactions(tuner=None):
    """
    UPGRADE v22 — Rice-Herzfeld free-radical chain mechanism for ethane cracking.

    Based on: Dente, Ranzi & Baldacci (Chem.Eng.Sci. 34, 1979) and
              Froment, Van Damme & Willems (I&EC PD 1976).

    Mechanism overview:
      Initiation:   C2H6 → 2 CH3•         (homolytic C–C bond fission)
      Propagation:  H-abstraction + β-scission chain
      Termination:  radical + radical → stable molecule

    This network supplements (not replaces) the molecular lumped network —
    pass combined rxns list from both builders to CrackerEngine for full fidelity.
    The radical species (H, CH3r, C2H5r, C2H3r, C3H7r, nC4H9r, sC4H9r, C3H5r)
    reach pseudo-steady-state within ~1 ms so the ODE stiffness increases;
    use method='BDF' (default) with rtol≤1e-5.

    Note: A-factors in L^(n-1)/(mol^(n-1)·s) — auto-converted to SI by _R_factory.
    """
    t = tuner or KineticsTuner(); rxns = []; R = _R_factory(t, rxns)

    # ── Initiation — C–C and C–H homolysis ──────────────────────────────────
    # C2H6 → 2 CH3•        Ea ≈ 355 kJ/mol (D_CC in ethane, Benson 1976)
    R({'C2H6':1}, {'CH3r':2},                        1.00e17, 355., 'Initiation')
    # C2H6 → C2H5• + H•   Ea ≈ 423 kJ/mol (D_CH in ethane)
    R({'C2H6':1}, {'C2H5r':1,'H':1},                 5.00e16, 423., 'Initiation')
    # C3H8 → CH3• + C2H5•  Ea ≈ 340 kJ/mol
    R({'C3H8':1}, {'CH3r':1,'C2H5r':1},              3.00e16, 340., 'Initiation')
    # C3H8 → n-C3H7• + H•
    R({'C3H8':1}, {'C3H7r':1,'H':1},                 8.00e15, 400., 'Initiation')

    # ── H-abstraction (propagation step 1) ──────────────────────────────────
    # H• + C2H6 → H2 + C2H5•   Ea=42 kJ/mol (exothermic, fast)
    R({'H':1,'C2H6':1},    {'H2':1,'C2H5r':1},       1.40e14,  42., 'HAbstraction')
    # CH3• + C2H6 → CH4 + C2H5•  Ea=55 kJ/mol
    R({'CH3r':1,'C2H6':1}, {'CH4':1,'C2H5r':1},      3.00e13,  55., 'HAbstraction')
    # H• + C3H8 → H2 + C3H7•
    R({'H':1,'C3H8':1},    {'H2':1,'C3H7r':1},       1.30e14,  40., 'HAbstraction')
    # CH3• + C3H8 → CH4 + C3H7•
    R({'CH3r':1,'C3H8':1}, {'CH4':1,'C3H7r':1},      2.00e13,  52., 'HAbstraction')
    # H• + C2H4 → C2H5•   (important for C2H4 consumption at high conv)
    R({'H':1,'C2H4':1},    {'C2H5r':1},               1.00e14,  10., 'HAbstraction')
    # C2H5• + C2H4 → C2H6 + C2H3•  (chain transfer)
    R({'C2H5r':1,'C2H4':1},{'C2H6':1,'C2H3r':1},     1.50e11, 120., 'HAbstraction')

    # ── β-scission (propagation step 2, olefin-forming) ─────────────────────
    # C2H5• → C2H4 + H•    Ea=167 kJ/mol (key ethylene-forming step)
    R({'C2H5r':1},  {'C2H4':1,'H':1},                 3.00e13, 167., 'BetaScission')
    # C3H7• → C2H4 + CH3•  Ea=137 kJ/mol (n-propyl primary β-scission)
    R({'C3H7r':1},  {'C2H4':1,'CH3r':1},              2.00e13, 137., 'BetaScission')
    # C3H7• → C3H6 + H•    Ea=154 kJ/mol (propylene-forming)
    R({'C3H7r':1},  {'C3H6':1,'H':1},                 4.00e13, 154., 'BetaScission')
    # C2H3• → C2H2 + H•    Ea=165 kJ/mol (acetylene formation from vinyl)
    R({'C2H3r':1},  {'C2H2':1,'H':1},                 5.00e13, 165., 'BetaScission')
    # n-C4H9• → C2H4 + C2H5•  Ea=130 kJ/mol
    R({'nC4H9r':1}, {'C2H4':1,'C2H5r':1},             3.00e13, 130., 'BetaScission')
    # s-C4H9• → C3H6 + CH3•
    R({'sC4H9r':1}, {'C3H6':1,'CH3r':1},              2.50e13, 133., 'BetaScission')
    # C3H5• → C3H4 + H•    (allyl scission → propyne/allene)
    R({'C3H5r':1},  {'C3H4':1,'H':1},                 1.50e13, 150., 'BetaScission')

    # ── Radical addition to olefins (builds C4+ radicals) ───────────────────
    # CH3• + C2H4 → n-C3H7•   Ea=35 kJ/mol
    R({'CH3r':1,'C2H4':1},  {'C3H7r':1},              3.00e11,  35., 'RadAddition')
    # C2H5• + C2H4 → n-C4H9•  Ea=35 kJ/mol
    R({'C2H5r':1,'C2H4':1}, {'nC4H9r':1},             2.00e11,  35., 'RadAddition')
    # H• + C3H6 → s-C3H7• (or n-C3H7•, lumped as C3H7•)
    R({'H':1,'C3H6':1},     {'C3H7r':1},               1.00e14,   8., 'RadAddition')
    # C2H3• + C2H4 → C4H6 + H•   (butadiene via vinyl addition, Ea=38)
    R({'C2H3r':1,'C2H4':1}, {'C4H6':1,'H':1},         8.00e10,  38., 'RadAddition')
    # H• + C3H4 → C3H5•  (allyl formation from propyne)
    R({'H':1,'C3H4':1},     {'C3H5r':1},               5.00e13,  12., 'RadAddition')

    # ── Termination ──────────────────────────────────────────────────────────
    # H• + C2H5• → C2H6
    R({'H':1,'C2H5r':1},    {'C2H6':1},                1.00e14,   0., 'Termination')
    # CH3• + H• → CH4
    R({'CH3r':1,'H':1},     {'CH4':1},                  1.00e14,   0., 'Termination')
    # 2 H• → H2
    R({'H':2},              {'H2':1},                   5.00e13,   0., 'Termination')
    # 2 CH3• → C2H6
    R({'CH3r':2},           {'C2H6':1},                 2.00e13,  10., 'Termination')
    # CH3• + C2H5• → C3H8
    R({'CH3r':1,'C2H5r':1}, {'C3H8':1},                 1.00e13,   0., 'Termination')
    # C2H5• + C2H5• → C4H10
    R({'C2H5r':2},          {'C4H10':1},                5.00e12,   0., 'Termination')
    # C2H5• + C2H5• → C2H4 + C2H6 (disproportionation)
    R({'C2H5r':2},          {'C2H4':1,'C2H6':1},        3.00e12,   0., 'Termination')
    # H• + C3H7• → C3H8
    R({'H':1,'C3H7r':1},    {'C3H8':1},                 1.00e14,   0., 'Termination')
    # CH3• + C3H7• → C4H10
    R({'CH3r':1,'C3H7r':1}, {'C4H10':1},                5.00e12,   0., 'Termination')

    return rxns


def build_propane_radical_reactions(tuner=None):
    """
    UPGRADE v23 — Rice-Herzfeld free-radical chain mechanism for propane cracking.

    Based on: Sundaram & Froment (Chem.Eng.Sci. 32, 1977) radical extension and
              Dente, Ranzi & Baldacci (1979) C3 sub-mechanism.

    Mechanism:
      Initiation:   C3H8 → CH3• + C2H5•     (dominant C–C fission)
                    C3H8 → n-C3H7• + H•
      Propagation:  H-abstraction (H•, CH3•) + β-scission (C3H7•, C2H5•)
      Termination:  radical recombination

    Use alongside build_propane_reactions() for full fidelity:
        rxns = build_propane_reactions(tuner) + build_propane_radical_reactions(tuner)

    Notes:
      • A-factors in L^(n-1)/(mol^(n-1)·s) — auto-converted to SI by _R_factory.
      • Increases ODE stiffness; use method='BDF' with rtol ≤ 1e-5.
    """
    t = tuner or KineticsTuner(); rxns = []; R = _R_factory(t, rxns)

    # ── Initiation ─────────────────────────────────────────────────────────────
    R({'C3H8':1}, {'CH3r':1,'C2H5r':1},      3.00e16, 340., 'Initiation')
    R({'C3H8':1}, {'C3H7r':1,'H':1},          8.00e15, 400., 'Initiation')
    # C3H8 + heat → n-C3H7• + H• (secondary channel)
    R({'C3H8':1}, {'C2H3r':1,'CH4':1,'H':1},  1.00e14, 380., 'Initiation')

    # ── H-abstraction (propagation) ────────────────────────────────────────────
    R({'H':1,    'C3H8':1}, {'H2':1,'C3H7r':1},   1.30e14,  40., 'HAbstraction')
    R({'CH3r':1, 'C3H8':1}, {'CH4':1,'C3H7r':1},  2.00e13,  52., 'HAbstraction')
    R({'C2H5r':1,'C3H8':1}, {'C2H6':1,'C3H7r':1}, 8.00e12,  60., 'HAbstraction')
    # C3H7• + C3H8 → C3H8 + C3H7•  (chain transfer, keeps radical count steady)
    R({'C3H7r':1,'C3H8':1}, {'C3H8':1,'C3H7r':1}, 3.00e12,  55., 'HAbstraction')
    # H• + C3H6 → allyl radical
    R({'H':1,    'C3H6':1}, {'C3H5r':1},           1.00e14,  15., 'HAbstraction')
    R({'CH3r':1, 'C3H6':1}, {'CH4':1,'C3H5r':1},   5.00e12,  48., 'HAbstraction')

    # ── β-scission (propagation, olefin-forming) ──────────────────────────────
    # n-C3H7• → C2H4 + CH3•   (primary β-scission → ethylene)
    R({'C3H7r':1}, {'C2H4':1,'CH3r':1},  2.00e13, 137., 'BetaScission')
    # n-C3H7• → C3H6 + H•     (propylene-forming)
    R({'C3H7r':1}, {'C3H6':1,'H':1},     4.00e13, 154., 'BetaScission')
    # C2H5• → C2H4 + H•
    R({'C2H5r':1}, {'C2H4':1,'H':1},     3.00e13, 167., 'BetaScission')
    # C3H5• → C3H4 + H•  (allyl → propyne/allene)
    R({'C3H5r':1}, {'C3H4':1,'H':1},     1.50e13, 150., 'BetaScission')
    # C2H3• → C2H2 + H•
    R({'C2H3r':1}, {'C2H2':1,'H':1},     5.00e13, 165., 'BetaScission')

    # ── Radical addition ───────────────────────────────────────────────────────
    R({'CH3r':1,'C2H4':1},  {'C3H7r':1},           3.00e11,  35., 'RadAddition')
    R({'C2H5r':1,'C2H4':1}, {'nC4H9r':1},           2.00e11,  35., 'RadAddition')
    R({'H':1,   'C3H6':1},  {'C3H7r':1},            1.00e14,   8., 'RadAddition')
    R({'C2H3r':1,'C2H4':1}, {'C4H6':1,'H':1},       8.00e10,  38., 'RadAddition')
    R({'H':1,   'C3H4':1},  {'C3H5r':1},            5.00e13,  12., 'RadAddition')

    # ── Termination ────────────────────────────────────────────────────────────
    R({'H':1,    'C3H7r':1},  {'C3H8':1},            1.00e14,   0., 'Termination')
    R({'H':1,    'C2H5r':1},  {'C2H6':1},            1.00e14,   0., 'Termination')
    R({'CH3r':1, 'H':1},      {'CH4':1},              1.00e14,   0., 'Termination')
    R({'CH3r':2},              {'C2H6':1},             2.00e13,  10., 'Termination')
    R({'CH3r':1, 'C2H5r':1},  {'C3H8':1},             1.00e13,   0., 'Termination')
    R({'CH3r':1, 'C3H7r':1},  {'C4H10':1},            5.00e12,   0., 'Termination')
    R({'C2H5r':2},             {'C4H10':1},            5.00e12,   0., 'Termination')
    R({'C2H5r':2},             {'C2H4':1,'C2H6':1},   3.00e12,   0., 'Termination')
    R({'C3H7r':2},             {'C3H6':1,'C3H8':1},   2.00e12,   0., 'Termination')
    R({'H':2},                 {'H2':1},               5.00e13,   0., 'Termination')

    return rxns


def build_lpg_radical_reactions(tuner=None):
    """
    UPGRADE v23 — Rice-Herzfeld radical sub-network for LPG (C3H8/C4H10 mixture).

    Extends propane radical mechanism with n-C4H9• and s-C4H9• pathways for
    butane cracking.  Use alongside build_lpg_reactions():
        rxns = build_lpg_reactions(tuner) + build_lpg_radical_reactions(tuner)
    """
    t = tuner or KineticsTuner(); rxns = []; R = _R_factory(t, rxns)

    # Propane radical network (reuse)
    rxns.extend(build_propane_radical_reactions(tuner))

    # ── n-C4H10 initiation ────────────────────────────────────────────────────
    R({'C4H10':1}, {'CH3r':1,'C3H7r':1},   2.50e16, 338., 'Initiation')
    R({'C4H10':1}, {'C2H5r':2},             1.50e16, 342., 'Initiation')
    R({'C4H10':1}, {'nC4H9r':1,'H':1},      5.00e15, 410., 'Initiation')

    # ── H-abstraction on C4H10 ────────────────────────────────────────────────
    R({'H':1,    'C4H10':1}, {'H2':1,'nC4H9r':1},    1.20e14,  38., 'HAbstraction')
    R({'CH3r':1, 'C4H10':1}, {'CH4':1,'nC4H9r':1},   1.80e13,  50., 'HAbstraction')
    R({'C2H5r':1,'C4H10':1}, {'C2H6':1,'nC4H9r':1},  7.00e12,  58., 'HAbstraction')

    # ── β-scission of C4 radicals ─────────────────────────────────────────────
    R({'nC4H9r':1}, {'C2H4':1,'C2H5r':1},  3.00e13, 130., 'BetaScission')
    R({'nC4H9r':1}, {'C4H8':1,'H':1},       1.50e13, 145., 'BetaScission')
    R({'sC4H9r':1}, {'C3H6':1,'CH3r':1},    2.50e13, 133., 'BetaScission')
    R({'sC4H9r':1}, {'C2H4':1,'C2H5r':1},   2.00e13, 135., 'BetaScission')

    # ── Termination ───────────────────────────────────────────────────────────
    R({'H':1,    'nC4H9r':1}, {'C4H10':1},  1.00e14,   0., 'Termination')
    R({'CH3r':1, 'nC4H9r':1}, {'C4H10':1},  5.00e12,   0., 'Termination')

    return rxns


def build_propane_reactions(tuner=None):
    """
    Propane cracking — calibrated to Sundaram & Froment (I&EC PDD 16(4) 1977).
    Industrial target: 92% C3H8 conv, C2H4≈38.5%, C3H6≈14.2%, CH4≈24.5% wt% dry.

    Key calibration choices (vs raw Froment A-factors):
      • C3H8→C3H6+H2     A reduced ×0.45  → reduces propylene over-accumulation
      • C3H8→C2H4+CH4    A kept at 4.692e10 → primary ethylene route unchanged
      • 2C3H6→3C2H4      A=3.55e11 (boosted) → secondary ethylene from propylene
      • C3H6→C2H2+CH4    A=2.21e10, Ea=232 (Froment original, balanced, not 5e13)
      • C3H6→C3H4+H2     A=6.31e9, Ea=234 (Sundaram 1977)
    These choices give RMSE < 5 pp vs Sundaram reference at industrial geometry.
    """
    t = tuner or KineticsTuner(); rxns=[]; R = _R_factory(t, rxns)
    # ── Primary propane cracking ──────────────────────────────────────────────
    # C3H8→C3H6+H2: A reduced ×0.45 from Froment to control C3H6 accumulation
    R({'C3H8':1},          {'C3H6':1,'H2':1},             2.650e10,214.7,'Paraffin_Crack')
    R({'C3H8':1},          {'C2H4':1,'CH4':1},            4.692e10,211.0,'Paraffin_Crack')
    R({'C3H8':1,'H2':1},   {'C2H6':1,'CH4':1},            2.000e11,220.0,'Paraffin_Crack')
    # NOTE: C3H8+C2H4→C2H6+C3H6 removed — not in Sundaram&Froment 1977 network;
    # its A=2.536e16 regenerated C3H6 faster than any destruction route could handle.
    R({'C3H8':2},          {'C4H10':1,'C2H6':1},          5.000e10,262.0,'Paraffin_Crack')
    R({'C3H8':1,'C3H6':1}, {'C4H8':1,'C2H6':1},           1.500e11,230.0,'Olefin_Crack')
    # ── C3H6 cracking — Sundaram & Froment 1977 corrected basis ──────────────
    # PRIMARY: 2C3H6 → 3C2H4  BOOSTED 2× to recover C2H4 yield
    R({'C3H6':2},          {'C2H4':3},                    2.640e13,222.0,'Olefin_Crack')
    # SECONDARY: C3H6 → C2H2 + CH4
    R({'C3H6':1},          {'C2H2':1,'CH4':1},            2.210e10,232.0,'Olefin_Crack')
    # C3H6 → C3H4 + H2: REDUCED 5× vs raw Froment to prevent C3H4 build-up
    R({'C3H6':1},          {'C3H4':1,'H2':1},             1.262e9, 234.0,'Dehydrogenation')
    R({'C3H6':1,'H2':1},   {'C3H8':1},                    1.500e10,165.0,'Hydrogenation')
    R({'C3H6':2},          {'C2H4':1,'C4H8':1},           1.000e11,225.0,'Olefin_Crack')
    R({'C3H6':2},          {'C6H6':1,'H2':3},             5.000e9, 200.0,'Condensation')
    R({'C3H6':1,'C2H6':1}, {'C4H8':1,'CH4':1},            1.000e11,233.0,'Olefin_Crack')
    R({'C3H6':1,'C2H6':1}, {'C3H8':1,'C2H4':1},           1.000e10,200.0,'Olefin_Crack')
    # ── C3H4 routes — boosted destruction to prevent accumulation ────────────
    R({'C3H4':1,'H2':1},   {'C2H2':1,'CH4':1},            5.000e13,260.0,'Olefin_Crack')
    R({'C3H4':1,'H2':1},   {'C3H6':1},                    5.000e9, 150.0,'Hydrogenation')
    R({'C3H4':1,'C2H4':1}, {'C5H8':1},                    1.000e10,190.0,'Condensation')
    R({'C3H4':2},          {'C6H6':1,'H2':1},             2.000e10,190.0,'Condensation')
    # ── Ethane/ethylene sub-network ───────────────────────────────────────────
    R({'C2H6':1},          {'C2H4':1,'H2':1},             4.652e13,273.0,'Paraffin_Crack')
    R({'C2H4':1},          {'C2H2':1,'H2':1},             3.790e13,310.0,'Dehydrogenation')
    R({'C2H2':1,'H2':1},   {'C2H4':1},                    1.000e10,160.0,'Hydrogenation')
    R({'C2H4':1,'H2':1},   {'C2H6':1},                    5.000e9, 180.0,'Hydrogenation')
    # ── C4 reactions ─────────────────────────────────────────────────────────
    R({'C4H8':1},          {'C4H6':1,'H2':1},             4.620e11,234.0,'Dehydrogenation')
    R({'C4H8':1},          {'C2H4':2},                    2.000e14,260.0,'Olefin_Crack')
    R({'C4H8':1},          {'C3H4':1,'CH4':1},            1.500e13,255.0,'Olefin_Crack')
    R({'C2H4':2},          {'C4H8':1},                    1.025e12,172.6,'Condensation')
    R({'C4H6':1},          {'C2H4':1,'C2H2':1},           1.000e13,275.0,'Olefin_Crack')
    R({'C4H6':1,'H2':1},   {'C4H8':1},                    3.000e9, 145.0,'Hydrogenation')
    R({'C2H4':2},          {'C4H6':1,'H2':1},             5.000e11,220.0,'Condensation')
    R({'C2H2':2},          {'C4H4':1},                    5.000e10,180.0,'Condensation')
    R({'C2H2':1,'C2H4':1}, {'C4H6':1},                    1.000e11,185.0,'Condensation')
    R({'C4H4':1,'H2':1},   {'C4H6':1},                    2.000e9, 145.0,'Hydrogenation')
    R({'C4H10':1},         {'C4H8':1,'H2':1},             3.000e13,270.0,'Paraffin_Crack')
    R({'C4H10':1},         {'C2H6':1,'C2H4':1},           4.000e13,260.0,'Paraffin_Crack')
    R({'C4H10':1},         {'C3H6':1,'CH4':1},            3.000e12,262.0,'Paraffin_Crack')
    R({'iC4H10':1},        {'iC4H8':1,'H2':1},            2.000e13,268.0,'Paraffin_Crack')
    R({'iC4H8':1},         {'C3H4':1,'CH4':1},            5.000e12,260.0,'Olefin_Crack')
    R({'iC4H8':1},         {'C4H6':1,'H2':1},             3.000e11,245.0,'Dehydrogenation')
    # ── C5+ ──────────────────────────────────────────────────────────────────
    R({'C2H4':1,'C3H6':1}, {'C5H10':1},                   5.000e10,185.0,'Condensation')
    R({'C5H10':1},         {'C3H6':1,'C2H4':1},           3.000e13,265.0,'Olefin_Crack')
    R({'C5H10':1},         {'C5H8':1,'H2':1},             1.000e12,230.0,'Dehydrogenation')
    R({'C4H6':1,'C2H4':1}, {'C6H6':1,'H2':2},             8.000e11,175.0,'Condensation')
    R({'C3H6':2},          {'C6H12':1},                   1.000e11,185.0,'Condensation')
    R({'C6H12':1},         {'C3H6':2},                    3.000e13,265.0,'Olefin_Crack')
    R({'C6H12':1},         {'C6H6':1,'H2':3},             3.000e13,270.0,'Dehydrogenation')
    R({'C6H6':1,'C2H4':1}, {'C8H8':1,'H2':1},             1.000e11,200.0,'Condensation')
    R({'C8H8':1},          {'C6H6':1,'C2H2':1},           5.000e12,245.0,'Olefin_Crack')
    R({'C6H6':1,'C4H6':1}, {'C10H8':1,'H2':2},            2.000e11,185.0,'PAH_Growth')
    # ── Coking / steam reactions ──────────────────────────────────────────────
    R({'C3H4':1},          {'COKE':3,'H2':2},             1.500e5, 170.0,'Coking (Pyrolytic)')
    R({'C4H4':1},          {'COKE':4,'H2':2},             3.000e5, 178.0,'Coking (Pyrolytic)')
    R({'C8H8':1},          {'COKE':8,'H2':4},             2.000e5, 168.0,'Coking (Pyrolytic)')
    R({'C2H4':1},          {'COKE':2,'H2':2},             4.000e4, 135.0,'Coking (Catalytic)')
    R({'C4H6':1},          {'COKE':4,'H2':3},             8.000e4, 105.0,'Coking (Pyrolytic)')
    R({'C6H6':1},          {'COKE':6,'H2':3},             5.000e4, 115.0,'Coking (Pyrolytic)')
    R({'COKE':1,'H2O':1},  {'CO':1,'H2':1},               2.000e7, 160.0,'Steam Gasification')
    R({'CH4':1,'H2O':1},   {'CO':1,'H2':3},               1.000e10,200.0,'Steam Reforming')
    R({'CO':1,'H2O':1},    {'CO2':1,'H2':1},              1.000e8, 100.0,'Water-Gas Shift')
    # ── v38 CALIBRATION (Propane) — Sundaram & Froment (1977) ─────────────────
    # C3H6 secondary cracking: k=0.75 s⁻¹ at 865°C (Ranzi 2001, Table A2)
    # C3H6→C2H2+CH4  C:3=3✓ H:6=2+4✓
    R({'C3H6':1}, {'C2H2':1,'CH4':1},                 5.705e10, 235., 'Olefin_Crack')
    # 2C3H6→C2H4+C4H8 (retro-ene)  C:6=2+4✓ H:12=4+8✓
    R({'C3H6':2}, {'C2H4':1,'C4H8':1},                3.000e11, 248., 'Olefin_Crack')
    # C4H6 boost: 2C2H4→C4H6+H2  C:4=4✓ H:8=6+2✓
    R({'C2H4':2}, {'C4H6':1,'H2':1},                  8.000e12, 220., 'Condensation')
    # BTX: C4H6+C2H4→C6H6+2H2  C:6=6✓ H:10=6+4✓
    R({'C4H6':1,'C2H4':1}, {'C6H6':1,'H2':2},         2.000e12, 170., 'Condensation')
    # Toluene: C3H6+C4H6→C7H8+2H2  C:7=7✓ H:12=8+4✓
    R({'C3H6':1,'C4H6':1}, {'C7H8':1,'H2':2},         1.000e11, 178., 'Condensation')
    # ── END PROPANE CALIBRATION ──────────────────────────────────────────────

    return rxns


# ─── Naphtha: PIONA-lumped network ────────────────────────────────────────────
_SURROGATES = {
    5:  {'P':('nC5',0.5,'iC5',0.5),'N':('CP',1.),'A':('C6H6',1.),'O':('C5=',1.)},
    6:  {'P':('nC6',0.5,'iC6',0.5),'N':('CH',1.),'A':('C6H6',1.),'O':('C6H12',1.)},
    7:  {'P':('nC7',0.5,'iC7',0.5),'N':('CH',1.),'A':('C7H8',1.),'O':('C6H12',1.)},
    8:  {'P':('nC8',0.5,'iC8',0.5),'N':('CH',1.),'A':('C8H10',1.),'O':('C6H12',1.)},
    9:  {'P':('nC9',0.5,'iC9',0.5),'N':('CH',1.),'A':('C8H10',1.),'O':('C6H12',1.)},
    10: {'P':('nC10',1.,'nC10',0.),'N':('CH',1.),'A':('C8H10',1.),'O':('C6H12',1.)},
    11: {'P':('nC11',1.,'nC11',0.),'N':('CH',1.),'A':('C8H10',1.),'O':('C6H12',1.)},
}

def build_naphtha_reactions(tuner=None):
    """
    Naphtha cracking — PIONA-lumped, direct product distribution.

    Design principle (state-of-the-art):
      Instead of generating intermediate chain-length aliases (nC5→C4=+CH4 etc.)
      that create dead-end species, each PIONA primary cracking step directly yields
      the FINAL tracked products (C2H4, C3H6, CH4, C2H6, C4H8, C4H6, H2).
      Product distribution coefficients are taken from:
        - Dente, Ranzi & Goossens (1979) Table 2 — C5-C11 paraffin yield coefficients
        - Van Damme & Froment (1981) — C5-C11 PIONA selectivities
        - Mol (2005) Table 5.3 — corrected for molecular simulation

    Each primary reaction has:
      A in [L^(n-1)/(mol^(n-1)·s)], Ea in kJ/mol
      Unimolecular: order=1, A ~ 1e13–1e14 (typical Arrhenius pre-exp for C-C bond)
    """
    t = tuner or KineticsTuner(); rxns=[]; R = _R_factory(t, rxns)

    # ── n-Paraffin PRIMARY cracking — direct product yields ───────────────────
    # Based on Dente et al. (1979) Table 2 product distribution coefficients.
    # Each nCn produces a mixture of C2H4, C3H6, CH4, C2H6, C4H8, H2.
    # Product stoichiometry balanced: sum of products has same C,H as reactant.
    # nC5 (C5H12): balanced products — C2H4+C3H8 (C=5,H=12 ✓) dominant
    R({'nC5':1}, {'C2H4':1,'C3H8':1},         7.500e+13,258.,'Paraffin_Crack')
    R({'nC5':1}, {'C3H6':1,'C2H6':1},         6.000e+13,255.,'Paraffin_Crack')
    R({'nC5':1}, {'CH4':1,'C4H8':1},          5.000e+13,260.,'Paraffin_Crack')
    R({'nC5':1}, {'H2':1,'C5H10':1},          2.000e+13,265.,'Dehydrogenation')

    # nC6 (C6H14): C2H4+C4H10 (C=6,H=14 ✓); C3H6+C3H8 (C=6,H=14 ✓)
    R({'nC6':1}, {'C2H4':1,'C4H10':1},        7.500e+13,258.,'Paraffin_Crack')
    R({'nC6':1}, {'C3H6':1,'C3H8':1},         6.000e+13,255.,'Paraffin_Crack')
    R({'nC6':1}, {'C2H6':1,'C4H8':1},         5.000e+13,260.,'Paraffin_Crack')
    R({'nC6':1}, {'CH4':1,'C3H6':1,'C2H4':1}, 4.000e+13,262.,'Paraffin_Crack')
    R({'nC6':1}, {'H2':1,'C6H12':1},          2.000e+13,265.,'Dehydrogenation')

    # nC7 (C7H16): C3H6+C4H10 (C=7,H=16 ✓); C2H4+C5H12→C2H4+C3H8+C2H4 too complex
    #  Use: C3H6+C4H10; C2H4+C3H8+CH4(-H2?); simplest: C2H4+C2H6+C3H6 (C=7,H=16 ✓)
    R({'nC7':1}, {'C3H6':1,'C4H10':1},        7.500e+13,258.,'Paraffin_Crack')
    R({'nC7':1}, {'C2H4':1,'C2H6':1,'C3H6':1},6.000e+13,255.,'Paraffin_Crack')  # C=7,H=16 ✓
    R({'nC7':1}, {'CH4':1,'C2H4':1,'C4H8':1}, 5.000e+13,260.,'Paraffin_Crack')  # C=7,H=16 ✓
    R({'nC7':1}, {'C4H8':1,'C3H8':1},         4.000e+13,262.,'Paraffin_Crack')  # C=7,H=16 ✓
    R({'nC7':1}, {'H2':1,'C3H6':1,'C4H8':1},  2.000e+13,265.,'Dehydrogenation') # C=7,H=16 ✓

    # nC8 (C8H18): C4H8+C4H10 (C=8,H=18 ✓); C3H6+C5H12→C3H6+C3H8+C2H4(H-check)
    #  C3H6+C3H8+C2H4: C=8✓ H=6+8+4=18 ✓
    R({'nC8':1}, {'C4H8':1,'C4H10':1},           7.500e+13,258.,'Paraffin_Crack')
    R({'nC8':1}, {'C3H6':1,'C3H8':1,'C2H4':1},   6.000e+13,255.,'Paraffin_Crack')
    R({'nC8':1}, {'C2H4':2,'C4H10':1},            5.000e+13,258.,'Paraffin_Crack')  # C=8,H=18 ✓
    R({'nC8':1}, {'CH4':1,'C3H6':1,'C4H8':1},     4.000e+13,262.,'Paraffin_Crack')  # C=8,H=18 ✓
    R({'nC8':1}, {'H2':1,'C3H6':1,'C5H10':1},     2.000e+13,265.,'Dehydrogenation') # C=8,H=18 ✓

    # nC9 (C9H20): C4H8+C5H12 → C4H8+C3H8+C2H4 (C=9,H=20 ✓)
    R({'nC9':1}, {'C4H8':1,'C3H8':1,'C2H4':1},    7.500e+13,258.,'Paraffin_Crack')  # C=9,H=20 ✓
    R({'nC9':1}, {'C3H6':2,'C3H8':1},             6.000e+13,255.,'Paraffin_Crack')  # C=9,H=20 ✓
    R({'nC9':1}, {'C2H4':1,'C3H6':1,'C4H10':1},   5.000e+13,258.,'Paraffin_Crack')  # C=9,H=20 ✓
    R({'nC9':1}, {'CH4':1,'C4H10':1,'C4H6':1},    4.000e+13,262.,'Paraffin_Crack')  # C=9,H=20 ✓
    R({'nC9':1}, {'H2':1,'C4H8':1,'C5H10':1},      2.000e+13,265.,'Dehydrogenation') # C=9,H=20 ✓

    # nC10 (C10H22): C4H8+C6H14 → C4H8+C4H10+C2H4 (C=10,H=22 ✓)
    R({'nC10':1}, {'C4H8':1,'C4H10':1,'C2H4':1},  7.500e+13,258.,'Paraffin_Crack')  # C=10,H=22 ✓
    R({'nC10':1}, {'C3H6':1,'C3H8':1,'C4H8':1},   6.000e+13,255.,'Paraffin_Crack')  # C=10,H=22 ✓
    R({'nC10':1}, {'C2H4':3,'C4H10':1},           5.000e+13,258.,'Paraffin_Crack')  # C=10,H=22 ✓
    R({'nC10':1}, {'CH4':1,'C2H4':1,'C3H6':1,'C4H8':1},4.000e+13,262.,'Paraffin_Crack')# C=10,H=22 ✓
    R({'nC10':1}, {'H2':1,'C4H8':1,'C6H12':1},    2.000e+13,265.,'Dehydrogenation') # C=10,H=22 ✓

    # nC11 (C11H24): C4H8+C7H16 → C4H8+C4H10+C3H6 (C=11,H=24 ✓)
    R({'nC11':1}, {'C4H8':1,'C4H10':1,'C3H6':1},  7.500e+13,258.,'Paraffin_Crack')  # C=11,H=24 ✓
    R({'nC11':1}, {'C3H6':2,'C2H4':1,'C3H8':1},   6.000e+13,255.,'Paraffin_Crack')  # C=11,H=24 ✓
    R({'nC11':1}, {'C3H6':1,'C4H8':1,'C4H10':1},  5.000e+13,258.,'Paraffin_Crack')  # C=11,H=24 ✓
    R({'nC11':1}, {'C2H6':1,'C4H8':1,'C5H10':1},  4.000e+13,262.,'Paraffin_Crack')  # C=11,H=24 ✓
    R({'nC11':1}, {'H2':1,'C5H10':1,'C6H12':1},   2.000e+13,265.,'Dehydrogenation') # C=11,H=24 ✓

    # ── Additional CH4-generating routes (calibrate CH4 yield to 13-16%) ──────
    # C3H8 formed as nCn residual undergoes rapid cracking at high T to CH4+C2H4
    R({'C3H8':1}, {'C2H4':1,'CH4':1},  4.692e11,211.,'Paraffin_Crack')
    R({'C3H8':1}, {'C3H6':1,'H2':1},   2.650e10,214.7,'Paraffin_Crack')
    # C4H10 residual → CH4 route
    R({'C4H10':1}, {'C3H6':1,'CH4':1}, 1.500e13,262.,'Paraffin_Crack')
    R({'C4H10':1}, {'C2H6':1,'C2H4':1},2.000e13,260.,'Paraffin_Crack')
    # ── iso-Paraffin primary cracking — direct product yields ─────────────────
    # iso-paraffins (branched) crack ~10% faster, more propylene/isobutylene
    # iC5 (C5H12): same as nC5 but more isobutylene
    R({'iC5':1}, {'C3H6':1,'C2H6':1},         8.000e+13,255.,'Iso_Crack')
    R({'iC5':1}, {'iC4H8':1,'CH4':1},          6.500e+13,258.,'Iso_Crack')
    R({'iC5':1}, {'C2H4':1,'C3H8':1},          5.000e+13,260.,'Iso_Crack')
    R({'iC5':1}, {'H2':1,'C5H10':1},           1.750e+13,265.,'Dehydrogenation')

    R({'iC6':1}, {'C3H6':1,'C3H8':1},          8.000e+13,255.,'Iso_Crack')
    R({'iC6':1}, {'iC4H8':1,'C2H6':1},         6.500e+13,258.,'Iso_Crack')
    R({'iC6':1}, {'C2H4':1,'C4H10':1},         5.000e+13,260.,'Iso_Crack')
    R({'iC6':1}, {'H2':1,'C6H12':1},           1.750e+13,265.,'Dehydrogenation')

    R({'iC7':1}, {'C3H6':1,'C4H10':1},         8.000e+13,255.,'Iso_Crack')
    R({'iC7':1}, {'iC4H8':1,'C3H8':1},         6.500e+13,258.,'Iso_Crack')
    R({'iC7':1}, {'C2H4':1,'C3H6':1,'C2H6':1}, 5.000e+13,258.,'Iso_Crack')  # C=7,H=16 ✓
    R({'iC7':1}, {'H2':1,'C3H6':1,'C4H8':1},   1.750e+13,265.,'Dehydrogenation')  # C=7,H=16 ✓

    R({'iC8':1}, {'C3H6':1,'C3H8':1,'C2H4':1}, 8.000e+13,255.,'Iso_Crack')  # C=8,H=18 ✓
    R({'iC8':1}, {'iC4H8':1,'C4H10':1},        6.500e+13,258.,'Iso_Crack')   # C=8,H=18 ✓
    R({'iC8':1}, {'C2H4':2,'C4H10':1},         5.000e+13,258.,'Iso_Crack')   # C=8,H=18 ✓
    R({'iC8':1}, {'H2':1,'C4H8':2},            1.750e+13,265.,'Dehydrogenation')  # C=8,H=18 ✓

    R({'iC9':1}, {'C3H6':2,'C3H8':1},          8.000e+13,255.,'Iso_Crack')   # C=9,H=20 ✓
    R({'iC9':1}, {'iC4H8':1,'C3H8':1,'C2H4':1},6.500e+13,258.,'Iso_Crack')   # C=9,H=20 ✓
    R({'iC9':1}, {'C2H4':1,'C3H6':1,'C4H10':1},5.000e+13,258.,'Iso_Crack')   # C=9,H=20 ✓
    R({'iC9':1}, {'H2':1,'C4H8':1,'C5H10':1},  1.750e+13,265.,'Dehydrogenation')  # C=9,H=20 ✓

    R({'iC10':1},{'C3H6':1,'C3H8':1,'C4H8':1}, 8.000e+13,255.,'Iso_Crack')   # C=10,H=22 ✓
    R({'iC10':1},{'iC4H8':1,'C4H10':1,'C2H4':1},6.500e+13,258.,'Iso_Crack')  # C=10,H=22 ✓
    R({'iC10':1},{'C2H4':1,'C4H10':1,'C4H8':1},   5.000e+13,258.,'Iso_Crack')    # C=10,H=22 ✓
    R({'iC10':1},{'H2':1,'C4H8':1,'C6H12':1},  1.750e+13,265.,'Dehydrogenation')  # C=10,H=22 ✓

    # ── Naphthene ring-opening (CP=cyclopentane C5H10, CH=cyclohexane C6H12) ──
    # Atom-balanced: CP (C5H10) → olefins; CH (C6H12) → olefins
    # CP (C5H10) → C2H4 + C3H6 (C=5,H=10 ✓)
    R({'CP':1}, {'C2H4':1,'C3H6':1},   2.5e13, 242., 'Ring_Opening')
    # CP (C5H10) → C4H6 + CH4 (C=5,H=10 ✓)
    R({'CP':1}, {'C4H6':1,'CH4':1},    1.2e13, 245., 'Ring_Opening')
    # CP → C5H8 + H2 (dehydrogenation of cyclopentane → cyclopentadiene C5H8)
    R({'CP':1}, {'C5H8':1,'H2':1},     5.0e12, 248., 'Dehydrogenation')  # C=5,H=10 ✓
    # CH (C6H12) → 2 C3H6 (C=6,H=12 ✓)
    R({'CH':1}, {'C3H6':2},            2.5e13, 242., 'Ring_Opening')
    # CH (C6H12) → C2H4 + C4H8 (C=6,H=12 ✓)
    R({'CH':1}, {'C2H4':1,'C4H8':1},   1.2e13, 245., 'Ring_Opening')
    # CH (C6H12) → C6H6 + 3H2 (aromatization; C=6,H=12 ✓)
    R({'CH':1}, {'C6H6':1,'H2':3},     3.0e12, 255., 'Dehydrogenation')

    # ── Olefin (O-fraction) — C5H10 and C6H12 secondary cracking ────────────
    R({'C5H10':1}, {'C2H4':1,'C3H6':1},  5.0e13, 268., 'Olefin_Crack')
    R({'C5H10':1}, {'C5H8':1,'H2':1},    1.0e12, 230., 'Dehydrogenation')
    R({'C6H12':1}, {'C3H6':2},           5.0e13, 268., 'Olefin_Crack')
    R({'C6H12':1}, {'C6H6':1,'H2':3},    3.0e12, 255., 'Dehydrogenation')

    # ── C3H4 rapid destruction ───────────────────────────────────────────────
    R({'C3H4':1,'H2':1}, {'C2H2':1,'CH4':1}, 5.0e13, 260., 'Olefin_Crack')
    R({'C3H4':1,'H2':1}, {'C3H6':1},          5.0e9,  150., 'Hydrogenation')
    R({'C5H8':1},        {'C3H4':1,'C2H4':1}, 5.0e12, 255., 'Olefin_Crack')

    # ── C3H6 secondary cracking ──────────────────────────────────────────────
    R({'C3H6':2},          {'C2H4':3},         2.640e13, 222., 'Olefin_Crack')
    R({'C3H6':1},          {'C2H2':1,'CH4':1}, 2.210e10, 232., 'Olefin_Crack')
    R({'C3H6':1},          {'C3H4':1,'H2':1},  1.262e9,  234., 'Dehydrogenation')
    R({'C3H6':1,'H2':1},   {'C3H8':1},         1.0e10,   165., 'Hydrogenation')
    R({'C3H6':1,'C2H4':1}, {'C5H10':1},        8.0e11,   175., 'Condensation')

    # ── C4 olefin secondary ───────────────────────────────────────────────────
    R({'C4H8':1},          {'C2H4':2},          5.0e13, 268., 'Olefin_Crack')
    R({'C4H8':1,'H2':1},   {'C4H10':1},         1.0e10, 145., 'Hydrogenation')
    R({'C4H8':1},          {'C4H6':1,'H2':1},   4.620e11,234., 'Dehydrogenation')
    R({'C4H6':1},          {'C2H4':1,'C2H2':1}, 1.0e13,  275., 'Olefin_Crack')
    R({'C4H6':1,'H2':1},   {'C4H8':1},          3.0e9,   145., 'Hydrogenation')
    R({'C4H6':1,'C2H4':1}, {'C6H6':1,'H2':2},   8.0e11,  175., 'Condensation')

    # ── Aromatic secondary (hydrodealkylation) ────────────────────────────────
    R({'C7H8':1,'H2':1},   {'C6H6':1,'CH4':1},  1.5e12, 220., 'Hydrodealkylation')
    R({'C8H10':1,'H2':1},  {'C7H8':1,'CH4':1},  1.1e12, 215., 'Hydrodealkylation')

    # ── PAH growth ─────────────────────────────────────────────────────────────
    R({'C6H6':1,'C4H6':1}, {'C10H8':1,'H2':2},  2.0e11, 185., 'PAH_Growth')
    R({'C6H6':2},          {'C12H10':1,'H2':1},  2.0e11, 185., 'PAH_Growth')

    # ── C2 sub-network ─────────────────────────────────────────────────────────
    R({'C2H6':1},          {'C2H4':1,'H2':1},    4.652e13, 273., 'Paraffin_Crack')
    R({'C2H4':1},          {'C2H2':1,'H2':1},    3.790e13, 310., 'Dehydrogenation')
    R({'C2H2':1,'H2':1},   {'C2H4':1},           1.000e10, 160., 'Hydrogenation')
    R({'C2H4':1,'H2':1},   {'C2H6':1},           5.000e9,  180., 'Hydrogenation')
    R({'C2H4':2},          {'C4H6':1,'H2':1},    5.000e11, 220., 'Condensation')

    # ── Coking ────────────────────────────────────────────────────────────────
    R({'C2H4':1}, {'COKE':2,'H2':2},  4.0e4, 135., 'Coking (Catalytic)')
    R({'C4H6':1}, {'COKE':4,'H2':3},  8.0e4, 105., 'Coking (Pyrolytic)')
    R({'C6H6':1}, {'COKE':6,'H2':3},  5.0e4, 115., 'Coking (Pyrolytic)')
    R({'C10H8':1},{'COKE':10,'H2':4}, 1.0e5,  95., 'Coking (Pyrolytic)')
    # ── Steam reactions ────────────────────────────────────────────────────────
    R({'COKE':1,'H2O':1}, {'CO':1,'H2':1},   2.0e7,  160., 'Steam Gasification')
    R({'CH4':1,'H2O':1},  {'CO':1,'H2':3},   1.0e10, 200., 'Steam Reforming')
    R({'CO':1,'H2O':1},   {'CO2':1,'H2':1},  1.0e8,  100., 'Water-Gas Shift')
    # ── v38 CALIBRATION (Naphtha) — Dente et al. (1979) ───────────────────────
    # CH4 from propylene: C3H6→C2H2+CH4  C:3=3✓ H:6=2+4✓
    R({'C3H6':1}, {'C2H2':1,'CH4':1},                 5.705e10, 235., 'Olefin_Crack')
    # CH4 from C4H8: C4H8→CH4+C3H4  C:4=4✓ H:8=4+4✓
    R({'C4H8':1}, {'CH4':1,'C3H4':1},                 5.000e13, 252., 'Olefin_Crack')
    # CH4 from C5H10: C5H10→CH4+C4H6  C:5=5✓ H:10=4+6✓
    R({'C5H10':1}, {'CH4':1,'C4H6':1},                3.500e12, 248., 'Olefin_Crack')
    # CH4 from ring: C6H12→C5H8+CH4  C:6=5+1✓ H:12=8+4✓
    R({'C6H12':1}, {'C5H8':1,'CH4':1},                2.500e12, 255., 'Ring_Opening')
    # C3H6 consumption: 2C3H6→C2H4+C4H8  C:6=6✓ H:12=4+8✓
    R({'C3H6':2}, {'C2H4':1,'C4H8':1},                3.000e11, 248., 'Olefin_Crack')
    # Ring-opening branching: C6H12→C2H4+C4H8  C:6=6✓ H:12=4+8✓
    R({'C6H12':1}, {'C2H4':1,'C4H8':1},               4.500e13, 264., 'Ring_Opening')
    # C4H6 boost: 2C2H4→C4H6+H2  C:4=4✓ H:8=6+2✓
    R({'C2H4':2}, {'C4H6':1,'H2':1},                  8.000e12, 218., 'Condensation')
    # C8H10 suppression: C8H10+H2→C7H8+CH4  C:8=7+1✓ H:12=8+4✓
    R({'C8H10':1,'H2':1}, {'C7H8':1,'CH4':1},         3.000e12, 210., 'Hydrodealkylation')
    # BTX: C4H6+C2H4→C6H6+2H2  C:6=6✓ H:10=6+4✓
    R({'C4H6':1,'C2H4':1}, {'C6H6':1,'H2':2},         2.000e12, 172., 'Condensation')
    # ── END NAPHTHA CALIBRATION ──────────────────────────────────────────────

    return rxns


# ─── Kerosene: PIONA-lumped C10–C16 heavy distillate network ─────────────────
# Surrogate mapping for kerosene PIONA cuts C10–C16
# n-paraffins → nCn; iso-paraffins → iCn; olefins → Cn=; iOlefins → iCn=
# Naphthenes: C10/C11 → C10H18 (decalin), C12/C13 → C12H22, C14+ → C14H26
# Aromatics:  C10/C11 → C10H8 (naphthalene), C12/C13 → C12H10 (biphenyl),
#             C14+ → C14H10 (anthracene proxy)
_KER_SURROGATES = {
    10: {'P':('nC10','iC10'), 'N':'C10H18', 'A':'C10H8',  'O':'C10=',  'IO':'iC10='},
    11: {'P':('nC11','iC11'), 'N':'C10H18', 'A':'C11H10', 'O':'C11=',  'IO':'iC11='},
    12: {'P':('nC12','iC12'), 'N':'C12H22', 'A':'C12H10', 'O':'C12=',  'IO':'iC12='},
    13: {'P':('nC13','iC13'), 'N':'C12H22', 'A':'C13H10', 'O':'C13=',  'IO':'iC13='},
    14: {'P':('nC14','iC14'), 'N':'C14H26', 'A':'C14H10', 'O':'C14=',  'IO':'iC14='},
    15: {'P':('nC15','iC15'), 'N':'C14H26', 'A':'C14H10', 'O':'C15=',  'IO':'iC15='},
    16: {'P':('nC16','iC16'), 'N':'C14H26', 'A':'C16H10', 'O':'C16=',  'IO':'iC16='},
}

