    R({'iC12':1},{'iC4H8':1,'C8H18':1},        5.000e13,252.,'Iso_Crack')
    R({'iC12':1},{'C3H6':2,'C2H4':1,'C4H10':1},4.500e13,249.,'Iso_Crack')
