    R({'nC13':1},{'C4H8':1,'C4H10':1,'C5H10':1},7.000e13,254.,'Paraffin_Crack')
    R({'nC13':1},{'C3H6':2,'C4H8':1,'C3H8':1}, 6.000e13,251.,'Paraffin_Crack')
    R({'nC13':1},{'C2H4':2,'C9H20':1},         5.000e13,254.,'Paraffin_Crack')
