    R({'iC13':1},{'iC4H8':1,'C9H20':1},        5.000e13,251.,'Iso_Crack')
    R({'iC13':1},{'C3H6':2,'C7H16':1},         4.500e13,248.,'Iso_Crack')

    R({'nC14':1},{'C4H8':1,'C4H10':1,'C6H12':1},7.000e13,253.,'Paraffin_Crack')
    R({'nC14':1},{'C3H6':2,'C4H8':1,'C4H10':1}, 6.000e13,250.,'Paraffin_Crack')
    R({'nC14':1},{'C2H4':3,'C8H18':1},          5.000e13,253.,'Paraffin_Crack')
    R({'nC14':1},{'H2':1,'C7H14':2},            2.000e13,261.,'Paraffin_Dehyd')
    R({'nC14':1},{'C2H6':1,'C12H24':1},         3.500e13,253.,'Paraffin_Crack')

    R({'iC14':1},{'iC4H8':1,'C10H22':1},       5.000e13,250.,'Iso_Crack')
    R({'iC14':1},{'C3H6':2,'C8H18':1},         4.500e13,247.,'Iso_Crack')

    R({'nC15':1},{'C4H8':1,'C4H10':1,'C7H14':1},7.000e13,252.,'Paraffin_Crack')
    R({'nC15':1},{'C3H6':2,'C3H8':1,'C6H12':1}, 6.000e13,249.,'Paraffin_Crack')
    R({'nC15':1},{'C2H4':3,'C9H20':1},          5.000e13,252.,'Paraffin_Crack')
    R({'nC15':1},{'C2H6':1,'C13H26':1},         3.500e13,252.,'Paraffin_Crack')
    R({'nC15':1},{'H2':1,'C7H14':1,'C8H16':1},  2.000e13,260.,'Paraffin_Dehyd')

    R({'iC15':1},{'iC4H8':1,'C11H24':1},       5.000e13,249.,'Iso_Crack')
    R({'iC15':1},{'C3H6':2,'C9H20':1},         4.500e13,246.,'Iso_Crack')

    R({'nC16':1},{'C4H8':1,'C4H10':1,'C8H16':1},7.000e13,251.,'Paraffin_Crack')
