    R({'nC12N':1},{'C8H16':1,'C4H8':1},        1.000e13,265.,'Ring_Opening')

    R({'nC14N':1},{'C7H14':2},                 2.000e13,266.,'Naphthene_Crack')
    R({'nC14N':1},{'C14H10':1,'H2':9},         1.000e11,265.,'Dehydrogenation')
    R({'nC14N':1},{'C8H16':1,'C6H12':1},       1.500e13,261.,'Ring_Opening')

    R({'nC16N':1},{'C8H16':2},                 2.000e13,264.,'Naphthene_Crack')
