#  SHALE CONDENSATE
# ═══════════════════════════════════════════════════════════════════════════════
def build_shale_condensate_reactions(tuner=None):
    """Shale gas condensate C2-C8 NGL cracking. Extends C2/C3/C4 + C5-C8."""
    t = tuner or KineticsTuner(); rxns=[]; R=_R_factory(t,rxns)
    rxns += build_ethane_radical(t)
    rxns += build_propane_radical(t)
    rxns += build_nbutane_reactions(t)
    rxns += build_isobutane_reactions(t)
    # C5-C8 NGL specific
    R({'nC5':1},{'C2H4':1,'C3H8':1},  7.500e13,258.,'Paraffin_Crack')
    R({'nC5':1},{'C3H6':1,'C2H6':1},  6.000e13,255.,'Paraffin_Crack')
    R({'nC5':1},{'CH4':1,'C4H8':1},   5.000e13,260.,'Paraffin_Crack')
    R({'nC5':1},{'H2':1,'C5H10':1},   2.000e13,265.,'Paraffin_Dehyd')
    R({'iC5':1},{'C2H4':1,'C3H8':1},  5.500e13,256.,'Iso_Crack')
    R({'iC5':1},{'iC4H8':1,'CH4':1},  6.000e13,258.,'Iso_Crack')
    R({'iC5':1},{'C3H6':1,'C2H6':1},  4.500e13,253.,'Iso_Crack')
    R({'nC6':1},{'C2H4':1,'C4H10':1}, 7.500e13,258.,'Paraffin_Crack')
    R({'nC6':1},{'C3H6':1,'C3H8':1},  6.000e13,255.,'Paraffin_Crack')
    R({'nC6':1},{'H2':1,'C6H12':1},   2.000e13,265.,'Paraffin_Dehyd')
    R({'iC6':1},{'C3H6':1,'C3H8':1},  5.500e13,253.,'Iso_Crack')
    R({'iC6':1},{'iC4H8':1,'C2H6':1}, 5.000e13,257.,'Iso_Crack')
    R({'nC7':1},{'C3H6':1,'C4H10':1}, 7.500e13,258.,'Paraffin_Crack')
    R({'nC7':1},{'C2H4':1,'C2H6':1,'C3H6':1},6.000e13,255.,'Paraffin_Crack')
    R({'iC7':1},{'iC4H8':1,'C3H8':1}, 5.500e13,256.,'Iso_Crack')
    R({'nC8':1},{'C4H8':1,'C4H10':1}, 7.500e13,258.,'Paraffin_Crack')
    R({'iC8':1},{'iC4H8':1,'C4H10':1},6.000e13,255.,'Iso_Crack')
    R({'C6H12':1},{'C6H6':1,'H2':3},  3.000e13,270.,'Dehydrogenation')
    R({'C7H14':1},{'C7H8':1,'H2':3},  5.000e12,255.,'Dehydrogenation')
    R({'C7H8':1,'H2':1},{'C6H6':1,'CH4':1},1.500e12,220.,'Hydrodealkylation')
    R({'C2H4':1,'C3H6':1},{'C5H10':1},5.000e10,185.,'Condensation')
    R({'C4H6':1,'C2H4':1},{'C6H6':1,'H2':2},8.000e11,175.,'Condensation')
    R({'C3H6':2},{'C6H12':1},         1.000e11,185.,'Condensation')
    R({'CH4':1,'H2O':1},{'CO':1,'H2':3},1.000e10,200.,'Steam Reforming')
    R({'CO':1,'H2O':1},{'CO2':1,'H2':1},1.000e8,100.,'Water-Gas Shift')
    R({'COKE':1,'H2O':1},{'CO':1,'H2':1},2.000e7,160.,'Steam Gasification')
    R({'C6H6':1},{'COKE':6,'H2':3},   5.000e4, 115.,'Coking (Pyrolytic)')
    R({'C2H4':1},{'COKE':2,'H2':2},   4.000e4, 135.,'Coking (Catalytic)')
    R({'C4H6':1},{'COKE':4,'H2':3},   8.000e4, 105.,'Coking (Pyrolytic)')
    return rxns


