def _strip_radical_reactions(rxns):
    """Remove reactions involving radical species (suffix 'r' or bare H/OH)
    so the molecular lumped network integrates stably in the PFR ODE solver.
    Radical (Rice-Herzfeld) networks are retained only for CHEMKIN export."""
    def _is_radical(sp):
        return sp.endswith('r') or sp in ('H', 'OH')
    out = []
    for r in rxns:
        species = list(r['reactants']) + list(r['products'])
        if any(_is_radical(s) for s in species):
            continue
        out.append(r)
    return out


def get_reactions(feed_key, tuner=None, include_secondary=True, include_radicals=False):
    """
    Build and return a reaction list compatible with CrackerEngine v24.

    Parameters
    ----------
    feed_key          : str — one of FEED_REGISTRY keys
    tuner             : KineticsTuner (default: all multipliers = 1.0)
    include_secondary : bool — append universal secondary network (default True)

    Returns
    -------
    list of reaction dicts: {'reactants', 'products', 'A', 'Ea', 'type', 'n'}

    Example
    -------
    >>> from cracker_kinetics_v38 import get_reactions, KineticsTuner
    >>> rxns = get_reactions('naphtha_full', KineticsTuner(p=1.1, o=0.95))
    >>> engine = CrackerEngine(rxns, geom, solver_opts)
    """
    if feed_key not in FEED_REGISTRY:
        avail = ', '.join(sorted(FEED_REGISTRY))
        raise KeyError(f"Unknown feed '{feed_key}'. Available: {avail}")
    t = tuner or KineticsTuner()
    rxns = FEED_REGISTRY[feed_key]['builder'](t)
    if include_secondary:
        sec = build_universal_secondary(t)
        existing = {(frozenset(r['reactants'].items()),
                     frozenset(r['products'].items())) for r in rxns}
        for r in sec:
            k = (frozenset(r['reactants'].items()),
                 frozenset(r['products'].items()))
            if k not in existing:
                rxns.append(r)
                existing.add(k)
    if not include_radicals:
        rxns = _strip_radical_reactions(rxns)
    return rxns



# Auto-apply balance patch at module load time
_patch_all_builders()

def get_universal_secondary(tuner=None):
    """Return the universal secondary network standalone."""
    return build_universal_secondary(tuner or KineticsTuner())


def list_feeds():
    """Return sorted list of available feed keys."""
    return sorted(FEED_REGISTRY)


def feed_info(feed_key):
    """Return metadata for a given feed (excludes builder function)."""
    if feed_key not in FEED_REGISTRY:
        raise KeyError(f"Unknown feed: {feed_key}")
    info = {k: v for k, v in FEED_REGISTRY[feed_key].items() if k != 'builder'}
    return info


def count_reactions(feed_key=None):
    """Count reactions per feed (with and without universal secondary)."""
    results = {}
    keys = [feed_key] if feed_key else list(FEED_REGISTRY)
    for k in keys:
        t = KineticsTuner()
        rxns = FEED_REGISTRY[k]['builder'](t)
        sec  = build_universal_secondary(t)
        results[k] = {'feed_rxns': len(rxns), 'secondary': len(sec),
                      'total_with_secondary': len(rxns) + len(sec)}
    return results




def parse_d2887_to_piona(d2887_curve, piona_guess=None, feed_type='naphtha'):
    """
    v24 — Convert an ASTM D2887 SimDis curve to D86 cut-points + PIONA weights.

    Parameters
    ----------
    d2887_curve : list of (mass_pct, boiling_point_C) — sorted ascending
    piona_guess : dict with keys P,I,N,A,O summing to 100 (optional override)
    feed_type   : 'naphtha' or 'kerosene'

    Returns
    -------
    d86_dict  : {'IBP','T5','T10','T30','T50','T70','T90','T95','FBP'}
    piona_dict: {'P','I','N','A','O'}  — wt% summing to 100

    Reference: API TDB (1997) Ch.2; Riazi & Al-Sahhaf (1996).
    """
    pcts = np.array([p[0] for p in d2887_curve])
    tbps = np.array([p[1] for p in d2887_curve])
    idx  = np.argsort(pcts); pcts=pcts[idx]; tbps=tbps[idx]

    def interp(pct):
        return float(np.interp(pct, pcts, tbps))

    d86 = {'IBP':interp(0.5),'T5':interp(5.),'T10':interp(10.),
            'T30':interp(30.),'T50':interp(50.),'T70':interp(70.),
            'T90':interp(90.),'T95':interp(95.),'FBP':interp(99.5)}

    if piona_guess is not None:
        tot = sum(piona_guess.values())
        piona = {k: v/tot*100. for k,v in piona_guess.items()}
    else:
        T50_K = d86['T50']+273.15; T10_K = d86['T10']+273.15; T90_K = d86['T90']+273.15
        Kw    = T50_K**(1./3.) / 0.75
        if   Kw >= 12.0: P,I,N,A,O = 65.,15.,15., 4.,1.
        elif Kw >= 11.0: P,I,N,A,O = 50.,15.,25., 8.,2.
        else:            P,I,N,A,O = 30.,10.,35.,23.,2.
        # Skew by D86 gradient (steep tail → more aromatics)
        if (T90_K-T10_K)/max(T50_K,1.) > 0.45:
            A+=5.; P-=2.5; N-=2.5
        piona = {'P':P,'I':I,'N':N,'A':A,'O':O}

    tot = sum(piona.values())
    return d86, {k: round(v/tot*100.,2) for k,v in piona.items()}


def build_gas_feed(comp_wt, feed_kghr, steam_ratio, engine):
    """
    Convert a wt% composition dict into per-coil molar flows [mol/s].

    comp_wt : {species_name: wt%}  — values need not sum to 100; they are
              normalised internally so that the feed rate sets the total.
    feed_kghr : total HC feed rate [kg/hr] for the whole furnace.
    steam_ratio : kg steam / kg HC.
    engine  : CrackerEngine (provides coils count and sp_idx).

    Only species present in engine.sp_idx are included in the output dict;
    anything else is silently dropped (e.g. trace N2, O2 in LPG).
    H2O is added separately at the steam dilution ratio.
    """
    total_wt = sum(comp_wt.values())
    if total_wt <= 0:
        raise ValueError('build_gas_feed: composition weights sum to zero')
    flows = {}
    for sp, wt_pct in comp_wt.items():
        if sp not in engine.sp_idx:
            continue
        mass_kghr = feed_kghr * (wt_pct / total_wt)          # kg/hr for whole furnace
        mol_s_fce = mass_kghr * 1000.0 / (get_mw(sp) * 3600.0)  # mol/s per furnace
        flows[sp] = mol_s_fce                                  # kept as per-furnace here
    # Add steam (per-furnace, will be split per coil inside engine.run)
    flows['H2O'] = (feed_kghr * steam_ratio * 1000.0) / (get_mw('H2O') * 3600.0)
    return flows


# ─── Feed builder for LPG ────────────────────────────────────────────────────
def build_lpg_feed(comp_wt, feed_kghr, steam_ratio, engine):
    """
    LPG feed builder — same as build_gas_feed but accepts the extended
    component set: C3H8, C4H10, iC4H10, C3H6, iC4H8, C2H6, CH4.
    comp_wt: dict {species: wt%}; normalised to 100% internally.
    """
    return build_gas_feed(comp_wt, feed_kghr, steam_ratio, engine)


# ─── Feed builder for Kerosene ───────────────────────────────────────────────
def build_kerosene_feed(dist, piona, feed_kghr, steam_ratio, engine):
    """
    Kerosene PIONA-lumped feed builder.

    dist : ASTM D86 temperatures dict. Accepted keys and their volume%:
           IBP=0, T5=5, T10=10, T30=30, T50=50, T70=70, T90=90, T95=95, FBP=100
           Any subset is accepted; the curve is linearly interpolated.
           Typical kerosene: IBP=150°C, T50=200°C, FBP=280°C.
    piona: wt% dict with keys P(n-paraffin), I(iso-paraffin), N(naphthene),
           A(aromatic), O(olefin). Values need not sum to 100 — normalised internally.
    feed_kghr : total HC feed rate [kg/hr]
    steam_ratio: kg steam / kg HC

    Carbon-number assignment:
      For kerosene the Antoine-based NBP correlation (API TDB, 1997) gives:
          Cn ≈ 0.04399 × NBP_K + 0.321    where NBP_K = NBP_°C + 273.15
      Simplified linear fit calibrated over C10–C16 (IBP 150–280°C):
          Cn ≈ (NBP_°C - 100) / 13.5 + 9.5
      → Cn = int(clip(round((T_m - 100.)/13.5 + 9.5), 10, 16))
      This maps: 150°C → C10.7→C11; 200°C → C14.5→C15; 250°C → C16
    """
    # Build D86 curve from provided points
    _key_pct = {'IBP':0.,'T5':5.,'T10':10.,'T30':30.,'T50':50.,
                'T70':70.,'T90':90.,'T95':95.,'FBP':100.}
    pts = sorted([(pct, dist[k]) for k,pct in _key_pct.items() if k in dist and dist[k] > 0],
                 key=lambda x: x[0])
    if len(pts) < 2:
        # Default full kerosene curve
        pts = [(0.,150.),(10.,165.),(50.,200.),(90.,248.),(100.,278.)]
    pct_a = np.array([p[0] for p in pts])
    T_a   = np.array([p[1] for p in pts])

    # Normalise PIONA weights
    piona_tot = max(sum(piona.values()), 1.)
    p_frac = piona.get('P', 38.) / piona_tot
    i_frac = piona.get('I', 22.) / piona_tot
    n_frac = piona.get('N', 18.) / piona_tot
    a_frac = piona.get('A', 19.) / piona_tot
    o_frac = piona.get('O',  3.) / piona_tot

    n_slices = 28  # More slices → better C-number distribution
    pe = np.linspace(0., 100., n_slices + 1)
    T_c = np.interp(pe, pct_a, T_a)

    mapped = {}
    for i in range(n_slices):
        T_m  = 0.5 * (T_c[i] + T_c[i + 1])
        # Calibrated NBP → Cn formula for kerosene/light gas oil (C10–C16)
        C = int(np.clip(round((T_m - 100.) / 13.5 + 9.5), 10, 16))
        cut_kg = feed_kghr / n_slices

        sur    = _KER_SURROGATES.get(C, _KER_SURROGATES[16])
        nsp, isp = sur['P']

        mapped[nsp]       = mapped.get(nsp,       0.) + cut_kg * p_frac
        mapped[isp]       = mapped.get(isp,       0.) + cut_kg * i_frac
        mapped[sur['N']]  = mapped.get(sur['N'],  0.) + cut_kg * n_frac
        mapped[sur['A']]  = mapped.get(sur['A'],  0.) + cut_kg * a_frac
        mapped[sur['O']]  = mapped.get(sur['O'],  0.) + cut_kg * o_frac

    flows = {sp: (mass_kg * 1000.) / (get_mw(sp) * 3600.)
             for sp, mass_kg in mapped.items()
             if mass_kg > 0 and sp in engine.sp_idx}
    flows['H2O'] = (feed_kghr * steam_ratio * 1000.) / (get_mw('H2O') * 3600.)
    return flows


def build_wax_feed(dist, piona, feed_kghr, steam_ratio, engine):
    """Wax feed builder — heavy n-paraffin slate (C18-C24).
    Maps the PIONA/D86 inputs onto the wax builder's actual species
    (nC18, nC20, nC24, C16H32) rather than naphtha-range species."""
    sp_idx = engine.sp_idx
    # Distribute heavy paraffins by typical FT-wax / slack-wax cut
    slate = {'nC18': 0.35, 'nC20': 0.35, 'nC24': 0.30}
    slate = {k: v for k, v in slate.items() if k in sp_idx}
    if not slate:
        # fall back to whatever heavy paraffin exists
        for cand in ('nC24', 'nC20', 'nC18', 'nC16'):
            if cand in sp_idx:
                slate = {cand: 1.0}; break
    tot = sum(slate.values()) or 1.0
    flows = {}
    for sp, frac in slate.items():
        mw = engine.get_mw(sp) if hasattr(engine, 'get_mw') else get_mw(sp)
        flows[sp] = (frac/tot) * feed_kghr * 1000. / (3600. * mw)
    flows['H2O'] = steam_ratio * feed_kghr * 1000. / (3600. * 18.015)
    return {k: v for k, v in flows.items() if v > 0 and k in sp_idx}


def build_gasoil_feed(dist, piona, feed_kghr, steam_ratio, engine):
    """Gas-oil/VGO feed builder — C15-C24 paraffin/naphthene/aromatic slate.
    Maps PIONA fractions onto the gas-oil builder's lumped heavy species."""
    sp_idx = engine.sp_idx
    P = piona.get('P', 40.) + piona.get('I', 0.)
    N = piona.get('N', 15.)
    A = piona.get('A', 16.)
    tot_piona = max(P + N + A, 1e-9)
    # Representative heavy lumps for each family
    slate = {}
    for sp, w in [('nC16', P*0.4), ('nC18', P*0.35), ('nC20', P*0.25),
                  ('nC14N', N*0.5), ('nC16N', N*0.5),
                  ('nC14A', A*0.5), ('nC16A', A*0.5)]:
        if sp in sp_idx:
            slate[sp] = slate.get(sp, 0.) + w
    if not slate:
        for cand in ('nC16', 'nC18', 'nC20'):
            if cand in sp_idx:
                slate = {cand: 1.0}; break
    tot = sum(slate.values()) or 1.0
    flows = {}
    for sp, frac in slate.items():
        mw = engine.get_mw(sp) if hasattr(engine, 'get_mw') else get_mw(sp)
        flows[sp] = (frac/tot) * feed_kghr * 1000. / (3600. * mw)
    flows['H2O'] = steam_ratio * feed_kghr * 1000. / (3600. * 18.015)
    return {k: v for k, v in flows.items() if v > 0 and k in sp_idx}


def build_naphtha_feed(dist, piona, feed_kghr, steam_ratio, engine):
    pts_pct=[]; pts_T=[]
    for lbl,pct in [('IBP',0),('T5',5),('T10',10),('T30',30),('T50',50),
                    ('T70',70),('T90',90),('T95',95),('FBP',100)]:
        v = dist.get(lbl, 0.)
        if v > 0: pts_pct.append(float(pct)); pts_T.append(v)
    if len(pts_pct) < 2: pts_pct=[0.,100.]; pts_T=[35.,172.]
    pct_a = np.array(pts_pct); T_a = np.array(pts_T)
    n = 20; pe = np.linspace(0., 100., n+1)
    T_c = np.interp(pe, pct_a, T_a)
    mapped = {}
    for i in range(n):
        T_m = 0.5*(T_c[i]+T_c[i+1])
        C   = int(np.clip(5 + (T_m-36)/20, 5, 11))
        cut = feed_kghr/n
        p_m = cut*(piona['P']/100.); n_m = cut*(piona['N']/100.)
        a_m = cut*(piona['A']/100.); o_m = cut*(piona['O']/100.)
        sur = _SURROGATES.get(C, _SURROGATES[11])
        sn,fn,si,fi = sur['P']
        for sp,m in [(sn,p_m*fn),(si,p_m*fi),(sur['N'][0],n_m),
                     (sur['A'][0],a_m),(sur['O'][0],o_m)]:
            mapped[sp] = mapped.get(sp,0.) + m
    flows = {sp: (m*1000.)/(get_mw(sp)*3600.)
             for sp,m in mapped.items() if m > 0 and sp in engine.sp_idx}
    flows['H2O'] = (feed_kghr*steam_ratio*1000.) / (get_mw('H2O')*3600.)
    return flows


