def _fmt_rxn(rxn):
    """Format a reaction dict into a human-readable string."""
    def side(d):
        return ' + '.join((f"{v:g} " if abs(v-1) > 1e-9 else '') + k for k, v in d.items())
    return f"{side(rxn['reactants'])}  →  {side(rxn['products'])}"



class ScrollableFrame(ttk.Frame):
    """Cross-platform scrollable frame.
    Windows/macOS: <MouseWheel>.  Linux X11: <Button-4>/<Button-5>.
    Shift+scroll = horizontal. Canvas always fills width.
    """
    def __init__(self, container, *args, **kwargs):
        super().__init__(container, *args, **kwargs)
        self.canvas = tk.Canvas(self, borderwidth=0, highlightthickness=0)
        self.scrollbar_y = ttk.Scrollbar(self, orient="vertical",   command=self.canvas.yview)
        self.scrollbar_x = ttk.Scrollbar(self, orient="horizontal", command=self.canvas.xview)
        self.scrollable_frame = ttk.Frame(self.canvas)
        self.canvas_window = self.canvas.create_window(
            (0, 0), window=self.scrollable_frame, anchor="nw")

        def _on_frame_configure(event):
            self.canvas.configure(scrollregion=self.canvas.bbox("all"))

        def _on_canvas_configure(event):
            req_w = self.scrollable_frame.winfo_reqwidth()
            self.canvas.itemconfigure(self.canvas_window,
                                      width=max(event.width, req_w))

        self.scrollable_frame.bind("<Configure>", _on_frame_configure)
        self.canvas.bind("<Configure>", _on_canvas_configure)
        self.canvas.configure(yscrollcommand=self.scrollbar_y.set,
                              xscrollcommand=self.scrollbar_x.set)

        self.scrollbar_y.pack(side="right",  fill="y")
        self.scrollbar_x.pack(side="bottom", fill="x")
        self.canvas.pack(side="left", fill="both", expand=True)
        self.canvas.bind("<Enter>", self._bind_mouse)
        self.canvas.bind("<Leave>", self._unbind_mouse)

    def _bind_mouse(self, event):
        self.canvas.bind_all("<MouseWheel>",       self._mw_vert)
        self.canvas.bind_all("<Shift-MouseWheel>", self._mw_horiz)
        self.canvas.bind_all("<Button-4>",         lambda e: self.canvas.yview_scroll(-3,"units"))
        self.canvas.bind_all("<Button-5>",         lambda e: self.canvas.yview_scroll( 3,"units"))
        self.canvas.bind_all("<Shift-Button-4>",   lambda e: self.canvas.xview_scroll(-3,"units"))
        self.canvas.bind_all("<Shift-Button-5>",   lambda e: self.canvas.xview_scroll( 3,"units"))

    def _unbind_mouse(self, event):
        for seq in ("<MouseWheel>","<Shift-MouseWheel>","<Button-4>","<Button-5>",
                    "<Shift-Button-4>","<Shift-Button-5>"):
            try: self.canvas.unbind_all(seq)
            except Exception: pass

    def _mw_vert(self, event):
        d = event.delta
        if sys.platform == "darwin": d = -d
        self.canvas.yview_scroll(int(-1*(d/120)), "units")

    def _mw_horiz(self, event):
        d = event.delta
        if sys.platform == "darwin": d = -d
        self.canvas.xview_scroll(int(-1*(d/120)), "units")

    def scroll_top(self): self.canvas.yview_moveto(0)


