def severity_default_for_feed(feed_label, mode):
    key = _gui_feed_key(feed_label)
    if key == 'naphtha': key = 'naphtha_full'
    d = SEVERITY_TARGET_DEFAULTS.get(key, SEVERITY_TARGET_DEFAULTS['naphtha_full'])
    return float(d.get(str(mode), d.get('ethane_conversion', 0.80)))

def _gui_normalize_setpoint(mode, value):
    v = float(value)
    if str(mode).endswith('_conversion'):
        return v / 100.0 if v > 1.5 else v
    if mode in ('ethylene_yield', 'methane_yield'):
        return v if v > 1.5 else v * 100.0
    return v

def _gui_specific_conversion(sol, engine, init_flows, species):
    if species not in engine.sp_idx:
        return np.nan
    coils = max(getattr(engine, 'coils', 1), 1)
    fin_pc = max(init_flows.get(species, 0.0) / coils, 0.0)
    if fin_pc <= 1e-30:
        return np.nan
    fout_pc = max(sol.y[engine.sp_idx[species], -1], 0.0)
    return float(np.clip(1.0 - fout_pc / fin_pc, 0.0, 1.0))

def _gui_methane_yield_wt(sol, engine, init_flows, feed_components):
    coils = max(getattr(engine, 'coils', 1), 1)
    hc_mass_total = sum(init_flows.get(sp, 0.0) * get_mw(sp) for sp in feed_components if sp != 'H2O')
    if hc_mass_total <= 1e-30 or 'CH4' not in engine.sp_idx:
        return 0.0
    return float(sol.y[engine.sp_idx['CH4'], -1] * coils * get_mw('CH4') / hc_mass_total * 100.0)

def _gui_severity_metric(mode, sol, engine, init_flows, feed_components, cfg, Tfb):
    kpis, _table, _bal = spyro_metrics(sol, engine, init_flows, feed_components, cfg)
    mode = str(mode or 'ethane_conversion')
    if mode == 'cot': return float(kpis.get('COT_C', np.nan))
    if mode == 'pe_ratio': return float(kpis.get('pe_ratio', np.nan))
    if mode == 'mp_ratio':
        coils = max(getattr(engine, 'coils', 1), 1)
        ch4 = sol.y[engine.sp_idx['CH4'], -1] * coils if 'CH4' in engine.sp_idx else 0.0
        c3h6 = sol.y[engine.sp_idx['C3H6'], -1] * coils if 'C3H6' in engine.sp_idx else 0.0
        return float(ch4 / max(c3h6, 1e-30))
    conv_map = {'ethane_conversion':'C2H6','propane_conversion':'C3H8','nbutane_conversion':'C4H10','npentane_conversion':'nC5','nhexane_conversion':'nC6'}
    if mode in conv_map:
        val = _gui_specific_conversion(sol, engine, init_flows, conv_map[mode])
        # If the selected species is not present for this feed, use overall HC conversion
        # so the button is still linked to the solver and never silently becomes inert.
        return float(kpis.get('actual_conv', np.nan)) if not np.isfinite(val) else val
    if mode == 'ethylene_yield': return float(kpis.get('eth_yield', np.nan))
    if mode == 'methane_yield': return _gui_methane_yield_wt(sol, engine, init_flows, feed_components)
    if mode == 'yield_max':
        return (float(kpis.get('eth_yield', 0.0)) + 0.65*float(kpis.get('pro_yield', 0.0)) +
                0.25*float(kpis.get('c4_yield', 0.0)) - 0.20*_gui_methane_yield_wt(sol, engine, init_flows, feed_components) -
                1.50*float(kpis.get('coke_yield', 0.0)))
    return float(kpis.get('actual_conv', np.nan))

def solve_gui_severity(mode, setpoint, engine, init_flows, T_in_K, P_in_Pa, feed_components,
                       cfg=None, bracket_lo=700.0, bracket_hi=1450.0):
    """Solve selected GUI severity target by varying internal conversion target.
    Rev-67: Fast 5-point scan + secant convergence (was 15-point scan)."""
    mode = str(mode or 'ethane_conversion')
    cfg = cfg or {'geom': {'coils': getattr(engine, 'coils', 1)}}
    lo, hi = 0.02, 0.995
    cache = {}
    def run_at(x):
        x = float(np.clip(x, lo, hi)); key = round(x, 7)
        if key not in cache:
            cache[key] = find_cot(x, engine, init_flows, T_in_K, P_in_Pa, feed_components,
                                  bracket_lo=bracket_lo, bracket_hi=bracket_hi)
        return cache[key]

    # Conversion modes go straight to find_cot — already fast
    if mode in _R58_CONV_MODES or mode == 'cot':
        pass  # handled by the R58 overlay below

    elif mode == 'yield_max':
        def obj(x):
            sol, Tfb, err = run_at(x)
            if err or sol is None: return 1e9
            return -_gui_severity_metric(mode, sol, engine, init_flows, feed_components, cfg, Tfb)
        res = minimize_scalar(obj, bounds=(lo, hi), method='bounded', options={'xatol': 5e-3, 'maxiter': 16})
        return run_at(float(res.x if res.success else 0.70))

    else:
        # Non-conversion, non-COT modes (P/E, yields, M/P, etc.)
        # Fast approach: 5-point scan + secant refinement
        target = _gui_normalize_setpoint(mode, setpoint)

        def diff(x):
            sol, Tfb, err = run_at(x)
            if err or sol is None: return np.nan
            return _gui_severity_metric(mode, sol, engine, init_flows, feed_components, cfg, Tfb) - target

        # 5-point coarse scan to find a bracket
        xs = np.linspace(lo, hi, 5)
        finite = [(x, diff(x)) for x in xs]
        finite = [(x, v) for x, v in finite if np.isfinite(v)]

        if finite:
            # Find bracket pair or closest point
            bracket_found = False
            for (x1, v1), (x2, v2) in zip(finite[:-1], finite[1:]):
                if v1 * v2 <= 0:
                    # Secant refinement within this bracket (faster than brentq for 3-4 iters)
                    xa, ea = x1, v1
                    xb, eb = x2, v2
                    for _it in range(6):
                        if abs(eb) < 0.001 * max(abs(target), 1.0):
                            break
                        de = eb - ea
                        if abs(de) < 1e-12:
                            break
                        xn = xb - eb * (xb - xa) / de
                        xn = float(np.clip(xn, lo, hi))
                        en = diff(xn)
                        if not np.isfinite(en):
                            break
                        xa, ea = xb, eb
                        xb, eb = xn, en
                    bracket_found = True
                    return run_at(xb)

            if not bracket_found:
                # No bracket — monotone relationship.  Use the closest point + secant.
                best_x, best_v = min(finite, key=lambda xv: abs(xv[1]))
                if len(finite) >= 2:
                    sorted_f = sorted(finite, key=lambda xv: abs(xv[1]))
                    xa, ea = sorted_f[0]
                    xb, eb = sorted_f[1]
                    for _it in range(4):
                        de = eb - ea
                        if abs(de) < 1e-12:
                            break
                        xn = xb - eb * (xb - xa) / de
                        xn = float(np.clip(xn, lo, hi))
                        en = diff(xn)
                        if not np.isfinite(en):
                            break
                        xa, ea = xb, eb
                        xb, eb = xn, en
                    return run_at(xb)
                return run_at(best_x)

        return None, None, f'Severity solver could not evaluate target mode {mode!r}'

# ── Rev-68: Parallel Multi-Coil worker ──────────────────────────────────────
# Module-level function so it is picklable by multiprocessing.
# Receives plain dicts (no tkinter objects), constructs engine + feed inside
# the worker process, solves, and returns plain-dict results.

def _mc_worker(coil_cfg):
    """Solve a single coil in a subprocess. Returns a plain dict of results."""
    i           = coil_cfg['coil_index']
    ft          = coil_cfg['feed_type']
    feed_rate   = coil_cfg['feed_rate']
    steam       = coil_cfg['steam_ratio']
    t_in        = coil_cfg['t_in']
    p_in        = coil_cfg['p_in']
    target_conv = coil_cfg['target_conv']
    sev_mode    = coil_cfg['severity_mode']
    geom        = coil_cfg['geom']
    comp        = coil_cfg['comp']
    dist        = coil_cfg['dist']
    piona       = coil_cfg['piona']
    tuner_args  = coil_cfg['tuner_args']
    solver_opts = coil_cfg['solver_opts']

    try:
        tuner = KineticsTuner(**tuner_args)
        rxns = build_reactions_for_gui_feed(ft, tuner, include_radicals=False)
        eng = CrackerEngine(rxns, geom, solver_opts)

        T_IN = t_in + 273.15
        P_IN = p_in * 101325.0

        feed = build_feed_for_gui_feed(ft, comp, dist, piona, feed_rate, steam, eng)
        fc = feed_components_for_gui_feed(ft, feed, eng)

        _severity_solver = globals().get('solve_gui_severity')
        cfg_mc = {'geom': geom, 'p_in': p_in}
        if _severity_solver:
            sol, T_fb, err = _severity_solver(
                sev_mode, target_conv, eng, feed, T_IN, P_IN, fc,
                cfg=cfg_mc, bracket_lo=700.0, bracket_hi=1450.0)
        else:
            sol, T_fb, err = find_cot(target_conv, eng, feed, T_IN, P_IN, fc)

        if err or sol is None:
            return {
                'coil': i + 1, 'active': True,
                'error': err or 'solver failed',
                'ft': ft, 'n_coils': 1, 'feed_rate': feed_rate,
                't_in': t_in, 'p_in': p_in, 'target_conv': target_conv,
                'geom': geom,
            }

        kpis, table, bal = spyro_metrics(sol, eng, feed, fc, cfg_mc)
        kpis['Firebox_C'] = T_fb
        hc_mass_flow_kgs = feed_rate / 3600.0

        return {
            'coil':          i + 1,
            'active':        True,
            'error':         None,
            'ft':            ft,
            'n_coils':       1,
            'feed_rate':     feed_rate,
            't_in':          t_in,
            'p_in':          p_in,
            'target_conv':   target_conv,
            'sol':           sol,
            'eng':           eng,
            'rxns':          rxns,
            'geom':          geom,
            'kpis':          kpis,
            'table':         table,
            'bal':           bal,
            'feed':          feed,
            'fc':            fc,
            'hc_mass_flow_kgs': hc_mass_flow_kgs,
        }
    except Exception as exc:
        return {
            'coil': i + 1, 'active': True,
            'error': str(exc),
            'ft': ft, 'n_coils': 1, 'feed_rate': feed_rate,
            't_in': t_in, 'p_in': p_in, 'target_conv': target_conv,
            'geom': geom,
        }

# Maximum parallel workers — default to CPU count, capped at 8 to avoid
# memory pressure on machines with many cores.
_MC_MAX_WORKERS = min(int(os.environ.get('CRACKER_MC_WORKERS', '0')) or os.cpu_count() or 4, 8)


