    # ── JSON snapshot path — resolved at runtime (works in script and Jupyter) ─
    @property
    def _JSON_PATH(self):
        return os.path.join(_app_base_dir(), 'cracker_params.json')

    def __init__(self, root):
        self.root = root
        root.title(f"{_APP_TITLE} (Multi-Coil | JSON Snapshot)")
        root.geometry("1600x970")
        try: root.state('zoomed')
        except tk.TclError:
            try: root.attributes('-zoomed', True)
            except tk.TclError: pass

        self._timer      = None
        self._running    = False
        self._dirty      = False
        self._suppress   = False
        self._last_result = None
        self._fig        = None
        self._canvas     = None
        self._axes       = None

        self._build_vars()
        self._init_param_defaults()
        # Multi-coil state (populated by _build_multi_coil_tab during _build_ui)
        self._mc_coil_vars  = []
        self._mc_row_frames = []
        self._build_ui()
        self._attach_traces()
        # ── Load saved JSON snapshot (if it exists) ───────────────────────────
        self._load_params_from_json()
        # Initial auto-run after UI settles
        self.root.after(500, self._force_run)

    # ─── JSON parameter persistence ───────────────────────────────────────────
    def _params_to_dict(self):
        """Serialise all GUI parameters to a plain dict (JSON-safe)."""
        d = {}
        simple = [
            ('feed_type',   self.v_feed_type),
            ('feed_rate',   self.v_feed_rate),
            ('steam_ratio', self.v_steam_ratio),
            ('t_in',        self.v_t_in),
            ('p_in',        self.v_p_in),
            ('target_conv', self.v_target_conv), ('severity_mode', self.v_severity_mode), ('severity_mode', self.v_severity_mode),
            ('g_c2h6',      self.v_g_c2h6), ('g_ch4',  self.v_g_ch4),
            ('g_c3h8',      self.v_g_c3h8), ('g_c2h4', self.v_g_c2h4),
            ('g_c3h6',      self.v_g_c3h6), ('g_ic4',  self.v_g_ic4),
            ('g_nc4',       self.v_g_nc4),  ('g_ic4h8',self.v_g_ic4h8),
            ('p_p', self.v_p_p), ('p_i', self.v_p_i), ('p_n', self.v_p_n),
            ('p_a', self.v_p_a), ('p_o', self.v_p_o),
            ('d_ibp', self.v_d_ibp), ('d_t5', self.v_d_t5), ('d_t10', self.v_d_t10),
            ('d_t30', self.v_d_t30), ('d_t50', self.v_d_t50), ('d_t70', self.v_d_t70),
            ('d_t90', self.v_d_t90), ('d_t95', self.v_d_t95), ('d_fbp', self.v_d_fbp),
            ('coils',   self.v_coils), ('passes', self.v_passes),
            ('lpp',     self.v_lpp),   ('tube_id', self.v_tube_id),
            ('tube_od', self.v_tube_od), ('emiss', self.v_emiss),
            ('rough',   self.v_rough), ('k_tube', self.v_k_tube),
            ('h_o',     self.v_h_o),   ('hfp',    self.v_hfp),
            ('hamp',    self.v_hamp),  ('k_heat', self.v_k_heat),
            ('k_dp',    self.v_k_dp),
            ('metal',   self.v_metal), ('dmds',   self.v_dmds),
            ('tp',      self.v_tp),    ('to',     self.v_to),
            ('ta',      self.v_ta),    ('tc',     self.v_tc),
            ('solver',  self.v_solver),('rtol',   self.v_rtol),
            ('atol',    self.v_atol),
            ('mc_enabled', self.v_mc_enabled),
            ('mc_n_coils', self.v_mc_n_coils),
        ]
        for k, v in simple:
            try: d[k] = v.get()
            except Exception:
                _log_exception(f'Could not serialize GUI parameter: {k}')

        # Multi-coil coil group vars
        mc_list = []
        for cv in getattr(self, '_mc_coil_vars', []):
            row = {}
            for k, v in cv.items():
                try: row[k] = v.get()
                except Exception:
                    _log_exception(f'Could not serialize multi-coil parameter: {k}')
            mc_list.append(row)
        d['mc_coil_vars'] = mc_list
        return d

    def _save_params_to_json(self):
        """Write current GUI state to JSON file (called on every run)."""
        try:
            import json
            data = self._params_to_dict()
            if os.path.exists(self._JSON_PATH):
                shutil.copy2(self._JSON_PATH, self._JSON_PATH + '.bak')
            with open(self._JSON_PATH, 'w') as f:
                json.dump(data, f, indent=2)
        except Exception as e:
            _log_exception(f'Could not save parameter snapshot to {self._JSON_PATH}')

    def _load_params_from_json(self):
        """Restore GUI state from JSON file if it exists."""
        try:
            import json
            if not os.path.exists(self._JSON_PATH):
                return
            with open(self._JSON_PATH, 'r') as f:
                d = json.load(f)
        except Exception:
            _log_exception(f'Could not load parameter snapshot from {self._JSON_PATH}')
            return
        self._suppress = True
        try:
            simple = [
                ('feed_type',   self.v_feed_type),
                ('feed_rate',   self.v_feed_rate),   ('steam_ratio', self.v_steam_ratio),
                ('t_in',        self.v_t_in),         ('p_in',        self.v_p_in),
                ('target_conv', self.v_target_conv),
                ('g_c2h6', self.v_g_c2h6), ('g_ch4',  self.v_g_ch4),
                ('g_c3h8', self.v_g_c3h8), ('g_c2h4', self.v_g_c2h4),
                ('g_c3h6', self.v_g_c3h6), ('g_ic4',  self.v_g_ic4),
                ('g_nc4',  self.v_g_nc4),  ('g_ic4h8',self.v_g_ic4h8),
                ('p_p', self.v_p_p), ('p_i', self.v_p_i), ('p_n', self.v_p_n),
                ('p_a', self.v_p_a), ('p_o', self.v_p_o),
                ('d_ibp', self.v_d_ibp), ('d_t5', self.v_d_t5), ('d_t10', self.v_d_t10),
                ('d_t30', self.v_d_t30), ('d_t50', self.v_d_t50), ('d_t70', self.v_d_t70),
                ('d_t90', self.v_d_t90), ('d_t95', self.v_d_t95), ('d_fbp', self.v_d_fbp),
                ('coils',   self.v_coils),   ('passes', self.v_passes),
                ('lpp',     self.v_lpp),     ('tube_id', self.v_tube_id),
                ('tube_od', self.v_tube_od), ('emiss',   self.v_emiss),
                ('rough',   self.v_rough),   ('k_tube',  self.v_k_tube),
                ('h_o',     self.v_h_o),     ('hfp',     self.v_hfp),
                ('hamp',    self.v_hamp),    ('k_heat',  self.v_k_heat),
                ('k_dp',    self.v_k_dp),
                ('metal',   self.v_metal),   ('dmds',    self.v_dmds),
                ('tp',      self.v_tp),      ('to',      self.v_to),
                ('ta',      self.v_ta),      ('tc',      self.v_tc),
                ('solver',  self.v_solver),  ('rtol',    self.v_rtol),
                ('atol',    self.v_atol),
                ('mc_enabled', self.v_mc_enabled),
                ('mc_n_coils', self.v_mc_n_coils),
            ]
            for k, v in simple:
                if k in d:
                    try: v.set(d[k])
                    except Exception: pass
            # Restore multi-coil groups
            mc_list = d.get('mc_coil_vars', [])
            if mc_list and hasattr(self, '_mc_coil_vars'):
                n_restore = min(len(mc_list), self.MAX_MC_COILS)
                self.v_mc_n_coils.set(n_restore)
                self._mc_rebuild_rows()
                for i, row in enumerate(mc_list[:n_restore]):
                    cv = self._mc_coil_vars[i]
                    for k, val in row.items():
                        if k in cv:
                            try: cv[k].set(val)
                            except Exception: pass
        finally:
            self._suppress = False
        # Re-apply feed type change (panels, geometry)
        try: self._on_feed_type_change()
        except Exception: pass

