    def _project_save_as(self):
        import json
        fp = filedialog.asksaveasfilename(
            title='Save Cracker Project',
            defaultextension='.cracker.json',
            filetypes=[('Cracker project', '*.cracker.json'), ('JSON', '*.json'), ('All files', '*.*')])
        if not fp:
            return
        try:
            data = self._params_to_dict()
            data['_app_version'] = _APP_VERSION
            data['_saved_at'] = time.strftime('%Y-%m-%d %H:%M:%S')
            with open(fp, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2)
            self.v_status.set(f'Project saved: {fp}')
        except Exception as exc:
            _log_exception(f'Could not save project to {fp}')
            messagebox.showerror('Save Project', str(exc))

    def _project_load(self):
        import json
        fp = filedialog.askopenfilename(
            title='Load Cracker Project',
            filetypes=[('Cracker project', '*.cracker.json'), ('JSON', '*.json'), ('All files', '*.*')])
        if not fp:
            return
        try:
            with open(fp, 'r', encoding='utf-8') as f:
                data = json.load(f)
            self._apply_project_dict(data)
            self.v_status.set(f'Project loaded: {fp}')
            self._schedule_run()
        except Exception as exc:
            _log_exception(f'Could not load project from {fp}')
            messagebox.showerror('Load Project', str(exc))

    def _reset_all_defaults(self):
        if not messagebox.askyesno('Reset Defaults', 'Reset all main inputs to Ethane defaults?'):
            return
        self._suppress = True
        try:
            d = self.DEFAULTS['Ethane']; g = self.GEOM; t = self.TUNE; s = self.SOLVER
            self.v_feed_type.set('Ethane')
            for key, var in [
                ('feed_rate', self.v_feed_rate), ('steam_ratio', self.v_steam_ratio),
                ('t_in', self.v_t_in), ('p_in', self.v_p_in), ('target_conv', self.v_target_conv),
                ('g_c2h6', self.v_g_c2h6), ('g_ch4', self.v_g_ch4), ('g_c3h8', self.v_g_c3h8),
                ('g_c2h4', self.v_g_c2h4), ('g_c3h6', self.v_g_c3h6),
                ('g_ic4', self.v_g_ic4), ('g_nc4', self.v_g_nc4), ('g_ic4h8', self.v_g_ic4h8),
            ]:
                var.set(d.get(key, 0.0))
            self.v_coils.set(g['coils']); self.v_passes.set(g['passes'])
            self.v_lpp.set(g['lpp']); self.v_tube_id.set(g['tube_id']); self.v_tube_od.set(g['tube_od'])
            self.v_emiss.set(g['emissivity']); self.v_rough.set(g['roughness'])
            self.v_k_tube.set(g['k_tube']); self.v_h_o.set(g['h_o_flue'])
            self.v_hfp.set(g['hfp']); self.v_hamp.set(g['hamp'])
            self.v_k_heat.set(g['k_heat']); self.v_k_dp.set(g['k_dp'])
            self.v_tp.set(t['tune_p']); self.v_to.set(t['tune_o'])
            self.v_ta.set(t['tune_a']); self.v_tc.set(t['tune_coke'])
            self.v_solver.set(s['solver']); self.v_rtol.set(s['rtol']); self.v_atol.set(s['atol'])
            self.v_mc_enabled.set(False); self.v_mc_n_coils.set(2)
            self.v_run_hours.set(0.0); self.v_quench_length.set(0.0)
        finally:
            self._suppress = False
        self._on_feed_type_change()
        self.v_status.set('Defaults restored.')
        self._schedule_run()

    def _validate_inputs(self):
        issues = []
        def finite(name, value, low=None, high=None):
            try:
                x = float(value.get() if hasattr(value, 'get') else value)
            except Exception:
                issues.append(f'{name}: not a number')
                return None
            if not np.isfinite(x):
                issues.append(f'{name}: not finite')
            if low is not None and x < low:
                issues.append(f'{name}: must be >= {low}')
            if high is not None and x > high:
                issues.append(f'{name}: must be <= {high}')
            return x
        finite('Feed rate kg/hr', self.v_feed_rate, 1.0)
        finite('Steam ratio', self.v_steam_ratio, 0.0, 10.0)
        finite('Inlet temperature C', self.v_t_in, 0.0, 1000.0)
        finite('Inlet pressure atm', self.v_p_in, 0.05, 20.0)
        finite('Severity setpoint', self.v_target_conv, 0.0, 2000.0)
        tube_id = finite('Tube ID m', self.v_tube_id, 0.001, 5.0)
        tube_od = finite('Tube OD m', self.v_tube_od, 0.001, 5.0)
        finite('Length per pass m', self.v_lpp, 0.1, 1000.0)
        finite('Coils', self.v_coils, 1, 10000)
        finite('Passes', self.v_passes, 1, 1000)
        if tube_id is not None and tube_od is not None and tube_od <= tube_id:
            issues.append('Tube OD must be greater than Tube ID')
        ft = self.v_feed_type.get()
        if ft in ('Ethane', 'Propane', 'LPG'):
            gas_sum = sum(v.get() for v in [
                self.v_g_c2h6, self.v_g_ch4, self.v_g_c3h8, self.v_g_c2h4,
                self.v_g_c3h6, self.v_g_ic4, self.v_g_nc4, self.v_g_ic4h8])
            if gas_sum <= 0:
                issues.append('Gas composition sum must be positive')
            elif abs(gas_sum - 100.0) > 5.0:
                issues.append(f'Gas composition sum is {gas_sum:.1f}%, expected near 100%')
        else:
            piona_sum = sum(v.get() for v in [self.v_p_p, self.v_p_i, self.v_p_n, self.v_p_a, self.v_p_o])
            if abs(piona_sum - 100.0) > 5.0:
                issues.append(f'PIONA sum is {piona_sum:.1f}%, expected near 100%')
        return issues

    def _show_install_check(self):
        try:
            import numpy, scipy, matplotlib, openpyxl
            rxns = build_ethane_reactions()
            problems = self._validate_inputs()
            msg = [
                f'{_APP_TITLE}',
                '',
                f'numpy {numpy.__version__}',
                f'scipy {scipy.__version__}',
                f'matplotlib {matplotlib.__version__}',
                f'openpyxl {openpyxl.__version__}',
                f'Ethane reactions: {len(rxns)}',
                f'Log file: {_LOG_PATH}',
            ]
            msg += ['', 'Current inputs passed validation.' if not problems else 'Input warnings:']
            msg += [] if not problems else [f'- {p}' for p in problems]
            messagebox.showinfo('Installation Check', '\n'.join(msg))
        except Exception as exc:
            _log_exception('Installation check failed')
            messagebox.showerror('Installation Check', str(exc))

    def _view_log_file(self):
        win = tk.Toplevel(self.root)
        win.title('Application Log')
        win.geometry('900x520')
        txt = tk.Text(win, font=('Consolas', 9), wrap='none')
        txt.pack(fill='both', expand=True)
        try:
            with open(_LOG_PATH, 'r', encoding='utf-8', errors='replace') as f:
                txt.insert('1.0', f.read() or '(log is empty)')
        except Exception as exc:
            txt.insert('1.0', f'Could not read log file:\n{_LOG_PATH}\n\n{exc}')
        txt.configure(state='disabled')

    def _write_crash_report(self, tb):
        crash_path = os.path.join(_app_base_dir(), 'cracker_crash_report.txt')
        try:
            with open(crash_path, 'w', encoding='utf-8') as f:
                f.write(f'{_APP_TITLE}\n')
                f.write(time.strftime('%Y-%m-%d %H:%M:%S') + '\n\n')
                f.write(tb)
            return crash_path
        except Exception:
            _log_exception('Could not write crash report')
            return None

    def _export_pdf_report(self):
        if not self._last_result:
            messagebox.showinfo('Export Report', 'Run a simulation first.')
            return
        fp = filedialog.asksaveasfilename(
            title='Export PDF Report',
            defaultextension='.pdf',
            filetypes=[('PDF', '*.pdf'), ('All files', '*.*')])
        if not fp:
            return
        try:
            from matplotlib.backends.backend_pdf import PdfPages
            R = self._last_result; k = R['kpis']; bal = R['bal']
            lines = [
                _APP_TITLE,
                f'Generated: {time.strftime("%Y-%m-%d %H:%M:%S")}',
                f'Feed: {R.get("ft", self.v_feed_type.get())}',
                '',
                'Key KPIs',
                f'COT: {k.get("COT_C", 0):.2f} C',
                f'Conversion: {k.get("actual_conv", 0)*100:.2f} %',
                f'Ethylene yield: {k.get("eth_yield", 0):.2f} wt% feed',
                f'Propylene yield: {k.get("pro_yield", 0):.2f} wt% feed',
                f'Pressure drop: {k.get("dP_atm", 0):.3f} atm',
                f'TMT max: {k.get("tmt_max_C", 0):.1f} C',
                '',
                'Balance',
                f'C closure: {bal.get("C_cls", 0):.4f} %',
                f'H closure: {bal.get("H_cls", 0):.4f} %',
                f'O closure: {bal.get("O_cls", 0):.4f} %',
            ]
            fig = plt.figure(figsize=(8.27, 11.69))
            fig.text(0.08, 0.95, '\n'.join(lines), va='top', family='monospace', fontsize=10)
            with PdfPages(fp) as pdf:
                pdf.savefig(fig, bbox_inches='tight')
            plt.close(fig)
            self.v_status.set(f'PDF report exported: {fp}')
        except Exception as exc:
            _log_exception(f'Could not export PDF report to {fp}')
            messagebox.showerror('Export Report', str(exc))

    def _restyle_all_treeviews(self, widget=None):
        """Apply premium dark Treeview row/tag colors to every treeview."""
        pal = getattr(self, '_theme_palette', {})
        if not pal:
            return
        if widget is None:
            widget = self.root
        try:
            if widget.winfo_class() == 'Treeview':
                try:
                    widget.tag_configure('oddrow', background=pal.get('card','#111C2E'), foreground=pal.get('text','#EAF2FF'))
                    widget.tag_configure('evenrow', background=pal.get('card2','#172338'), foreground=pal.get('text','#EAF2FF'))
                except Exception:
                    pass
            for child in widget.winfo_children():
                self._restyle_all_treeviews(child)
        except Exception:
            pass

    def _eradicate_white_backgrounds(self, widget=None, pal=None):
        """Force-remove residual white backgrounds from classic Tk, ttk containers,
        matplotlib canvas hosts, and nested scrollable frames.

        Tk/ttk can leave white islands because some widgets are classic tk
        objects or embedded canvas/window children rather than pure ttk.  This
        routine is deliberately aggressive and is called after UI build and
        after theme changes.
        """
        if pal is None:
            pal = getattr(self, '_theme_palette', {
                'root':'#07111F','bg':'#0B1628','card':'#111C2E','card2':'#172338',
                'card3':'#1E2D46','entry':'#0D1829','text':'#EAF2FF','muted':'#9AA9BC',
                'accent':'#38BDF8','select':'#0E7490','white':'#FFFFFF','red':'#EF4444',
                'line':'#2B3A55','amber':'#F59E0B','accent2':'#22C55E','violet':'#A78BFA'
            })
        if widget is None:
            widget = self.root
        try:
            cls = widget.winfo_class()
            keys = set(widget.keys()) if hasattr(widget, 'keys') else set()
            name = str(widget)
            # Containers and canvases are the main white-background offenders.
            if 'background' in keys or 'bg' in keys:
                bg_key = 'background' if 'background' in keys else 'bg'
                if cls in ('Frame','TFrame','Labelframe','TLabelframe','Canvas','TCanvas','Pane','Panedwindow','TPanedwindow'):
                    widget.configure(**{bg_key: pal['bg']})
                elif cls in ('Text','Listbox'):
                    widget.configure(**{bg_key: pal['entry']})
                elif cls in ('Entry','Spinbox'):
                    widget.configure(**{bg_key: pal['entry']})
                elif cls in ('Label','Message'):
                    widget.configure(**{bg_key: pal['bg']})
                elif cls == 'Button':
                    label = ''
                    try: label = str(widget.cget('text'))
                    except Exception: pass
                    widget.configure(**{bg_key: pal['red'] if ('Exit' in label or '✕' in label) else pal['card2']})
                elif cls == 'Menu':
                    widget.configure(**{bg_key: pal['card']})
                else:
                    # Last resort: if it is exactly white-ish, repaint it.
                    try:
                        cur = str(widget.cget(bg_key)).lower()
                        if cur in ('white', '#ffffff', '#fff', 'systemwindow'):
                            widget.configure(**{bg_key: pal['bg']})
                    except Exception:
                        pass
            if 'foreground' in keys or 'fg' in keys:
                fg_key = 'foreground' if 'foreground' in keys else 'fg'
                if cls in ('Label','Message','Text','Listbox','Entry','Spinbox'):
                    widget.configure(**{fg_key: pal['text']})
                elif cls == 'Button':
                    widget.configure(**{fg_key: pal['white'] if ('Exit' in str(widget.cget('text')) or '✕' in str(widget.cget('text'))) else pal['text']})
            if cls == 'Canvas':
                try:
                    widget.configure(bg=pal['bg'], highlightbackground=pal['bg'], highlightcolor=pal['accent'], bd=0)
                except Exception:
                    pass
                # Canvas window items often host white frames.
                try:
                    for item in widget.find_all():
                        try:
                            child = widget.nametowidget(widget.itemcget(item, 'window'))
                            self._eradicate_white_backgrounds(child, pal)
                        except Exception:
                            pass
                except Exception:
                    pass
            if cls in ('Text','Listbox','Entry','Spinbox'):
                try:
                    widget.configure(insertbackground=pal['text'], selectbackground=pal['select'], selectforeground=pal['white'],
                                     highlightbackground=pal['line'], highlightcolor=pal['accent'])
                except Exception:
                    pass
        except Exception:
            pass
        try:
            for child in widget.winfo_children():
                self._eradicate_white_backgrounds(child, pal)
        except Exception:
            pass

    def _set_theme_mode(self, mode='dark'):
        """Premium dark/light theme — refinery control-room grade UI polish.

        Design goals:
          • OLED-style background with readable contrast, not flat black.
          • Card/panel hierarchy so dense engineering screens are scannable.
          • Cyan/emerald accents for process/solver actions.
          • Amber/red accents reserved for warnings and critical states.
          • Full coverage of ttk + classic tk + Treeview + Matplotlib canvases.
        """
        try:
            dark = (str(mode).lower() == 'dark')
            pal = {
                # Premium dark: midnight navy, graphite panels, subtle borders.
                'root':   '#07111F' if dark else '#F5F7FB',
                'bg':     '#0B1628' if dark else '#F8FAFC',
                'card':   '#111C2E' if dark else '#FFFFFF',
                'card2':  '#172338' if dark else '#EEF2F7',
                'card3':  '#1E2D46' if dark else '#E2E8F0',
                'text':   '#EAF2FF' if dark else '#1F2937',
                'muted':  '#9AA9BC' if dark else '#64748B',
                'faint':  '#64748B' if dark else '#94A3B8',
                'line':   '#2B3A55' if dark else '#CBD5E1',
                'entry':  '#0D1829' if dark else '#FFFFFF',
                'entry2': '#101F34' if dark else '#F8FAFC',
                'select': '#0E7490' if dark else '#DBEAFE',
                'accent': '#38BDF8' if dark else '#2563EB',   # cyan / blue
                'accent2':'#22C55E' if dark else '#16A34A',   # green
                'violet': '#A78BFA' if dark else '#7C3AED',
                'amber':  '#F59E0B',
                'red':    '#EF4444',
                'white':  '#FFFFFF',
            }
            self._theme_palette = pal
            try:
                self.root.configure(bg=pal['root'])
            except Exception:
                pass

            # Global classic Tk defaults, including combobox dropdown listboxes.
            try:
                self.root.option_add('*Background', pal['bg'])
                self.root.option_add('*Foreground', pal['text'])
                self.root.option_add('*Entry.Background', pal['entry'])
                self.root.option_add('*Entry.Foreground', pal['text'])
                self.root.option_add('*Text.Background', pal['entry'])
                self.root.option_add('*Text.Foreground', pal['text'])
                self.root.option_add('*Listbox.Background', pal['entry'])
                self.root.option_add('*Listbox.Foreground', pal['text'])
                self.root.option_add('*TCombobox*Listbox.background', pal['entry'])
                self.root.option_add('*TCombobox*Listbox.foreground', pal['text'])
                self.root.option_add('*TCombobox*Listbox.selectBackground', pal['select'])
                self.root.option_add('*TCombobox*Listbox.selectForeground', pal['white'])
            except Exception:
                pass

            sty = ttk.Style()
            try:
                sty.theme_use('clam')
            except Exception:
                pass

            font_ui = ('Segoe UI', 9)
            font_bold = ('Segoe UI Semibold', 9)
            font_tab = ('Segoe UI Semibold', 9)
            font_title = ('Segoe UI Semibold', 11)

            # Base ttk styling.
            sty.configure('.',
                          background=pal['bg'], foreground=pal['text'],
                          fieldbackground=pal['entry'], bordercolor=pal['line'],
                          lightcolor=pal['line'], darkcolor=pal['line'],
                          troughcolor=pal['card'], font=font_ui)
            sty.configure('TFrame', background=pal['bg'])
            sty.configure('Card.TFrame', background=pal['card'])
            sty.configure('TLabel', background=pal['bg'], foreground=pal['text'], font=font_ui)
            sty.configure('Title.TLabel', background=pal['bg'], foreground=pal['accent'], font=font_title)
            sty.configure('Muted.TLabel', background=pal['bg'], foreground=pal['muted'], font=font_ui)

            # Label frames as cards.
            sty.configure('TLabelframe', background=pal['bg'], foreground=pal['text'],
                          bordercolor=pal['line'], relief='solid', borderwidth=1)
            sty.configure('TLabelframe.Label', background=pal['bg'], foreground=pal['accent'],
                          font=font_bold)

            # Notebook / tabs.
            sty.configure('TNotebook', background=pal['root'], borderwidth=0, tabmargins=[2, 3, 2, 0])
            sty.configure('TNotebook.Tab', background=pal['card2'], foreground=pal['muted'],
                          padding=[12, 7], font=font_tab, borderwidth=0)
            sty.map('TNotebook.Tab',
                    background=[('selected', pal['accent']), ('active', pal['card3'])],
                    foreground=[('selected', pal['white']), ('active', pal['text'])])

            # Buttons.
            sty.configure('TButton', background=pal['card2'], foreground=pal['text'],
                          bordercolor=pal['line'], focusthickness=0, focuscolor=pal['accent'],
                          padding=[9, 5], font=font_bold, relief='flat')
            sty.map('TButton',
                    background=[('disabled', pal['card']), ('pressed', pal['select']), ('active', pal['accent'])],
                    foreground=[('disabled', pal['faint']), ('pressed', pal['white']), ('active', pal['white'])])
            sty.configure('Accent.TButton', background=pal['accent'], foreground=pal['white'], font=font_bold)
            sty.map('Accent.TButton', background=[('active', '#0284C7' if dark else '#1D4ED8'), ('pressed', '#075985' if dark else '#1E40AF')])

            # Inputs.
            for style_name in ('TEntry', 'TSpinbox'):
                sty.configure(style_name, fieldbackground=pal['entry'], foreground=pal['text'],
                              insertcolor=pal['text'], bordercolor=pal['line'],
                              lightcolor=pal['line'], darkcolor=pal['line'], padding=3)
                sty.map(style_name, fieldbackground=[('focus', pal['entry2'])], bordercolor=[('focus', pal['accent'])])
            sty.configure('Modified.TEntry', fieldbackground='#2B2210' if dark else '#FFF7ED',
                          foreground=pal['text'], bordercolor=pal['amber'])
            sty.configure('TCombobox', fieldbackground=pal['entry'], foreground=pal['text'],
                          background=pal['card2'], arrowcolor=pal['accent'],
                          bordercolor=pal['line'], lightcolor=pal['line'], darkcolor=pal['line'], padding=3)
            sty.map('TCombobox',
                    fieldbackground=[('readonly', pal['entry']), ('focus', pal['entry2'])],
                    foreground=[('readonly', pal['text'])],
                    selectbackground=[('readonly', pal['select'])],
                    selectforeground=[('readonly', pal['white'])],
                    bordercolor=[('focus', pal['accent'])])

            # Check/radio.
            sty.configure('TCheckbutton', background=pal['bg'], foreground=pal['text'], font=font_ui)
            sty.map('TCheckbutton', background=[('active', pal['bg'])], foreground=[('active', pal['accent'])])
            sty.configure('TRadiobutton', background=pal['bg'], foreground=pal['text'], font=font_ui)
            sty.map('TRadiobutton', background=[('active', pal['bg'])], foreground=[('active', pal['accent'])])

            # Scrollbars / progress.
            for sb in ('Vertical.TScrollbar', 'Horizontal.TScrollbar'):
                sty.configure(sb, background=pal['card2'], troughcolor=pal['root'],
                              bordercolor=pal['root'], arrowcolor=pal['muted'], relief='flat')
                sty.map(sb, background=[('active', pal['card3']), ('pressed', pal['select'])], arrowcolor=[('active', pal['accent'])])
            sty.configure('TProgressbar', background=pal['accent'], troughcolor=pal['card2'], bordercolor=pal['line'])

            # Treeviews: critical for reaction table readability.
            sty.configure('Treeview', background=pal['card'], fieldbackground=pal['card'],
                          foreground=pal['text'], rowheight=26, bordercolor=pal['line'],
                          lightcolor=pal['line'], darkcolor=pal['line'], font=('Consolas', 9))
            sty.configure('Treeview.Heading', background=pal['card3'], foreground=pal['accent'],
                          font=('Segoe UI Semibold', 9), relief='flat')
            sty.map('Treeview', background=[('selected', pal['select'])], foreground=[('selected', pal['white'])])
            sty.map('Treeview.Heading', background=[('active', pal['select'])], foreground=[('active', pal['white'])])

            # Paned windows / separators.
            sty.configure('TPanedwindow', background=pal['root'])
            sty.configure('TSeparator', background=pal['line'])

            # Matplotlib theme for existing and future figures.
            try:
                plt.rcParams.update({
                    'figure.facecolor': pal['root'],
                    'axes.facecolor': pal['card'],
                    'axes.edgecolor': pal['line'],
                    'axes.labelcolor': pal['text'],
                    'axes.titlecolor': pal['accent'],
                    'text.color': pal['text'],
                    'xtick.color': pal['muted'],
                    'ytick.color': pal['muted'],
                    'grid.color': '#2E405F' if dark else '#CBD5E1',
                    'legend.facecolor': pal['card2'],
                    'legend.edgecolor': pal['line'],
                    'savefig.facecolor': pal['root'],
                })
                for num in plt.get_fignums():
                    fig = plt.figure(num)
                    fig.patch.set_facecolor(pal['root'])
                    for ax in fig.axes:
                        ax.set_facecolor(pal['card'])
                        ax.tick_params(colors=pal['muted'])
                        ax.xaxis.label.set_color(pal['text'])
                        ax.yaxis.label.set_color(pal['text'])
                        ax.title.set_color(pal['accent'])
                        for spine in ax.spines.values():
                            spine.set_color(pal['line'])
                        ax.grid(True, color=('#2E405F' if dark else '#CBD5E1'), alpha=0.45)
                    try:
                        fig.canvas.draw_idle()
                    except Exception:
                        pass
            except Exception:
                pass

            # Recursive classic Tk restyling.
            def recolor(w):
                try:
                    cls = w.winfo_class()
                    if cls in ('Frame', 'Labelframe'):
                        w.configure(bg=pal['bg'])
                    elif cls in ('Label', 'Message'):
                        w.configure(bg=pal['bg'], fg=pal['text'])
                    elif cls in ('Text', 'Listbox'):
                        w.configure(bg=pal['entry'], fg=pal['text'], insertbackground=pal['text'],
                                    selectbackground=pal['select'], selectforeground=pal['white'],
                                    highlightbackground=pal['line'], highlightcolor=pal['accent'])
                    elif cls in ('Entry', 'Spinbox'):
                        w.configure(bg=pal['entry'], fg=pal['text'], insertbackground=pal['text'],
                                    selectbackground=pal['select'], selectforeground=pal['white'],
                                    highlightbackground=pal['line'], highlightcolor=pal['accent'])
                    elif cls == 'Button':
                        label = str(w.cget('text')) if 'text' in w.keys() else ''
                        if 'Exit' in label or '✕' in label:
                            w.configure(bg=pal['red'], fg=pal['white'], activebackground='#991B1B',
                                        activeforeground=pal['white'], relief='flat', bd=0)
                        else:
                            w.configure(bg=pal['card2'], fg=pal['text'], activebackground=pal['accent'],
                                        activeforeground=pal['white'], relief='flat', bd=0)
                    elif cls == 'Menu':
                        w.configure(bg=pal['card'], fg=pal['text'], activebackground=pal['select'],
                                    activeforeground=pal['white'], bd=0, relief='flat')
                except Exception:
                    pass
                try:
                    for child in w.winfo_children():
                        recolor(child)
                except Exception:
                    pass
            recolor(self.root)

            # Color-code reaction tree tags in a dark-compatible, non-garish way.
            tag_colors_dark = {
                'Paraffin_Crack':   '#102B3F',
                'Iso_Crack':        '#132F4C',
                'Ring_Opening':     '#12351F',
                'Olefin_Crack':     '#3A2A0F',
                'Dehydrogenation':  '#12351F',
                'Hydrogenation':    '#0F3528',
                'Condensation':     '#3A1430',
                'PAH_Growth':       '#2E1747',
                'Hydrodealkylation':'#3B260E',
                'Coking':           '#3B160E',
                'Steam':            '#1E293B',
                'Imported_CHEMKIN_Olefin': '#19314A',
                'Olefin_Metathesis': '#2A214B',
                'Aromatization': '#2E1747',
            }
            tag_colors_light = {
                'Paraffin_Crack':   '#E8F4FD',
                'Iso_Crack':        '#D6EAF8',
                'Ring_Opening':     '#D5E8D4',
                'Olefin_Crack':     '#FEF3C7',
                'Dehydrogenation':  '#EAF7EF',
                'Hydrogenation':    '#DCFCE7',
                'Condensation':     '#FDF2F8',
                'PAH_Growth':       '#F4ECF7',
                'Hydrodealkylation':'#FDEBD0',
                'Coking':           '#FEE2E2',
                'Steam':            '#F1F5F9',
            }
            if hasattr(self, 'rxn_tree'):
                for tag, bg in (tag_colors_dark if dark else tag_colors_light).items():
                    try:
                        self.rxn_tree.tag_configure(tag, background=bg, foreground=pal['text'] if dark else '#111827')
                    except Exception:
                        pass

            if hasattr(self, '_solver_log'):
                try:
                    self._solver_log.configure(bg='#08111F' if dark else '#FFFFFF', fg=pal['text'],
                                               insertbackground=pal['text'], selectbackground=pal['select'])
                    self._solver_log.tag_configure('INFO',  foreground=pal['accent'])
                    self._solver_log.tag_configure('OK',    foreground=pal['accent2'])
                    self._solver_log.tag_configure('WARN',  foreground=pal['amber'])
                    self._solver_log.tag_configure('ERROR', foreground=pal['red'])
                    self._solver_log.tag_configure('DATA',  foreground=pal['text'])
                    self._solver_log.tag_configure('HEAD',  foreground=pal['violet'], font=('Consolas', 8, 'bold'))
                except Exception:
                    pass

            # Final pass: eliminate white islands left by classic Tk/Canvas/embed widgets.
            try:
                self._eradicate_white_backgrounds(self.root, pal)
                self._restyle_all_treeviews(self.root)
                self._style_kinetics_editor_dark(self.root)
            except Exception:
                pass

            if hasattr(self, 'v_status'):
                self.v_status.set('Premium dark theme applied.' if dark else 'Premium light theme applied.')
        except Exception:
            _log_exception(f'Could not apply {mode} theme')


    def _build_vars(self):
        d = self.DEFAULTS['Ethane']
        g = self.GEOM; t = self.TUNE; s = self.SOLVER

        self.v_feed_type = tk.StringVar(value='Ethane')

        # Inlet process
        self.v_feed_rate    = tk.DoubleVar(value=d['feed_rate'])
        self.v_steam_ratio  = tk.DoubleVar(value=d['steam_ratio'])
        self.v_t_in         = tk.DoubleVar(value=d['t_in'])
        self.v_p_in         = tk.DoubleVar(value=d['p_in'])
        self.v_target_conv  = tk.DoubleVar(value=d['target_conv'])
        self.v_severity_mode = tk.StringVar(value='ethane_conversion')

        # Gas composition
        self.v_g_c2h6 = tk.DoubleVar(value=d['g_c2h6'])
        self.v_g_ch4  = tk.DoubleVar(value=d['g_ch4'])
        self.v_g_c3h8 = tk.DoubleVar(value=d['g_c3h8'])
        self.v_g_c2h4 = tk.DoubleVar(value=d['g_c2h4'])
        self.v_g_c3h6 = tk.DoubleVar(value=d['g_c3h6'])
        self.v_g_ic4  = tk.DoubleVar(value=d['g_ic4'])
        self.v_g_nc4  = tk.DoubleVar(value=d['g_nc4'])
        self.v_g_ic4h8 = tk.DoubleVar(value=d.get('g_ic4h8', 0.))   # isobutylene (LPG)

        # PIONA (shared vars — loaded with naphtha defaults; overwritten on feed type change)
        for k in ('p_p','p_i','p_n','p_a','p_o'):
            setattr(self, f'v_{k}', tk.DoubleVar(value=self.NAPHTHA_PIONA[k]))

        # D86 (shared vars — loaded with naphtha defaults; overwritten on feed type change)
        for k in ('d_ibp','d_t5','d_t10','d_t30','d_t50','d_t70','d_t90','d_t95','d_fbp'):
            setattr(self, f'v_{k}', tk.DoubleVar(value=self.NAPHTHA_D86[k]))

        # FINAL PATCH: feed-specific entry variables + independent liquid PIONA/D86.
        self._feed_comp_vars = {}
        for _ft, _spec in FEED_COMPOSITION_SPECS.items():
            self._feed_comp_vars[_ft] = {}
            for _sp, _lbl, _default in _spec:
                _v = tk.DoubleVar(value=_default)
                self._feed_comp_vars[_ft][_sp] = _v
                _v.trace_add('write', lambda *_: (self._update_selected_feed_entry_sum() if hasattr(self, '_selected_comp_sum_lbl') else None, self._schedule_run() if hasattr(self, '_timer') else None))
        self._liquid_feed_vars = {}
        for _ft, _cfg in LIQUID_FEED_DEFAULTS.items():
            self._liquid_feed_vars[_ft] = {'piona': {}, 'dist': {}}
            for _k, _val in _cfg['piona'].items():
                _v = tk.DoubleVar(value=_val); self._liquid_feed_vars[_ft]['piona'][_k] = _v
                _v.trace_add('write', lambda *_: (self._update_selected_feed_entry_sum() if hasattr(self, '_selected_comp_sum_lbl') else None, self._schedule_run() if hasattr(self, '_timer') else None))
            for _k, _val in _cfg['dist'].items():
                self._liquid_feed_vars[_ft]['dist'][_k] = tk.DoubleVar(value=_val)

        # Geometry
        self.v_coils   = tk.IntVar(value=g['coils'])
        self.v_passes  = tk.IntVar(value=g['passes'])
        self.v_lpp     = tk.DoubleVar(value=g['lpp'])
        self.v_tube_id = tk.DoubleVar(value=g['tube_id'])
        self.v_tube_od = tk.DoubleVar(value=g['tube_od'])
        self.v_emiss   = tk.DoubleVar(value=g['emissivity'])
        self.v_rough   = tk.DoubleVar(value=g['roughness'])
        self.v_k_tube  = tk.DoubleVar(value=g['k_tube'])
        self.v_h_o     = tk.DoubleVar(value=g['h_o_flue'])
        self.v_hfp     = tk.StringVar(value=g['hfp'])
        self.v_hamp    = tk.DoubleVar(value=g['hamp'])
        self.v_k_heat  = tk.DoubleVar(value=g['k_heat'])   # heat-flux correction factor
        self.v_k_dp    = tk.DoubleVar(value=g['k_dp'])     # pressure-drop correction factor

        # Metallurgy / DMDS
        self.v_metal = tk.StringVar(value='Standard HP-Alloy')
        self.v_dmds  = tk.BooleanVar(value=False)

        # Tuning
        self.v_tp = tk.DoubleVar(value=t['tune_p'])
        self.v_to = tk.DoubleVar(value=t['tune_o'])
        self.v_ta = tk.DoubleVar(value=t['tune_a'])
        self.v_tc = tk.DoubleVar(value=t['tune_coke'])

