    def _mc_notify_coil_change(self, *_):
        """Propagate multi-coil state changes to Yield Optimizer, Sensitivity
        Analysis, and Digital Twin coil selector comboboxes."""
        for method in ('_yo_refresh_coil_list', '_sa_refresh_coils', '_dt_refresh_coils'):
            if hasattr(self, method):
                try:
                    self.root.after(80, getattr(self, method))
                except Exception:
                    pass
        if hasattr(self, '_kt_rebuild_mc_entries'):
            self.root.after(120, self._kt_rebuild_mc_entries)

    def _attach_traces(self):
        """
        Reactive recalculation: attach a single debounced _on_change callback
        to all input variables.  The 1-second debounce means only ONE simulation
        fires per edit session (user types several digits → only one run).

        Composition/PIONA sums use a separate lightweight callback (no simulation).
        """
        # ── Auto-refresh coil selectors in Optimizer / SA / Digital Twin ────────
        self.v_mc_enabled.trace_add('write', self._mc_notify_coil_change)
        self.v_mc_n_coils.trace_add('write', self._mc_notify_coil_change)
        watched = [
            self.v_feed_rate, self.v_steam_ratio, self.v_t_in, self.v_p_in, self.v_target_conv,
            self.v_g_c2h6, self.v_g_ch4, self.v_g_c3h8, self.v_g_c2h4,
            self.v_g_c3h6, self.v_g_ic4, self.v_g_nc4, self.v_g_ic4h8,
            self.v_p_p, self.v_p_i, self.v_p_n, self.v_p_a, self.v_p_o,
            self.v_d_ibp, self.v_d_t5, self.v_d_t10, self.v_d_t30, self.v_d_t50,
            self.v_d_t70, self.v_d_t90, self.v_d_t95, self.v_d_fbp,
            self.v_coils, self.v_passes, self.v_lpp, self.v_tube_id, self.v_tube_od,
            self.v_emiss, self.v_rough, self.v_k_tube, self.v_h_o, self.v_hfp, self.v_hamp,
            self.v_k_heat, self.v_k_dp,
            self.v_metal, self.v_dmds,
            self.v_tp, self.v_to, self.v_ta, self.v_tc,
            self.v_solver, self.v_rtol, self.v_atol,
        ]
        for v in watched:
            v.trace_add('write', self._on_change)

        # Basis toggle: table refresh only (no re-simulation)
        self.v_basis.trace_add('write', lambda *_: self._refresh_products())

        # Feed type: updates defaults + geometry preset + panel visibility
        self.v_feed_type.trace_add('write', lambda *_: self._on_feed_type_change())

        # Live composition sums (cheap — just adds up 7 numbers)
        def _upd_comp(*_): self._update_comp_sum()
        def _upd_piona(*_): self._update_piona_sum()
        for v in (self.v_g_c2h6, self.v_g_ch4, self.v_g_c3h8, self.v_g_c2h4,
                  self.v_g_c3h6, self.v_g_ic4, self.v_g_nc4, self.v_g_ic4h8):
            v.trace_add('write', _upd_comp)
        for v in (self.v_p_p, self.v_p_i, self.v_p_n, self.v_p_a, self.v_p_o):
            v.trace_add('write', _upd_piona)

    # ─── Layout helpers ───────────────────────────────────────────────────────
    def _row(self, parent, label, var, row, tip='', col=0, key=None):
        """
        Grid a label + entry + optional tip.
        If key is given the entry is registered in _param_widgets so we can:
          • show 'std: <default>' in grey beside the field
          • highlight the entry in gold when the user deviates from default
        """
        ttk.Label(parent, text=label).grid(row=row, column=col,
                                            sticky=tk.W, padx=8, pady=2)
        ent = ttk.Entry(parent, textvariable=var, width=12)
        ent.grid(row=row, column=col+1, pady=2, padx=(0, 4))

        # Reference (std) label shown to the right
        ref_text = ''
        if key and key in self._param_defaults:
            ref_text = f'std: {self._param_defaults[key]}'
        elif tip:
            ref_text = tip
        ref_lbl = ttk.Label(parent, text=ref_text,
                             foreground='#888', font=('Helvetica', 7, 'italic'))
        ref_lbl.grid(row=row, column=col+2, sticky=tk.W, padx=2)

        if key:
            self._param_widgets[key] = (ent, ref_lbl)
            # Highlight on FocusOut only (not every keystroke) — much faster
            def _on_focus_out(event, _key=key, _var=var, _ent=ent):
                dv = self._param_defaults.get(_key)
                if dv is None: return
                try:
                    cur = _var.get()
                    try:    modified = abs(float(str(cur)) - float(str(dv))) > 1e-9
                    except: modified = str(cur) != str(dv)
                    _ent.configure(style='Modified.TEntry' if modified else 'TEntry')
                except Exception: pass
            ent.bind('<FocusOut>', _on_focus_out)

        return ent

    def _init_param_defaults(self):
        """Call after _build_vars to snapshot all default values."""
        pairs = [
            ('feed_rate', self.v_feed_rate), ('steam_ratio', self.v_steam_ratio),
            ('t_in', self.v_t_in), ('p_in', self.v_p_in),
            ('target_conv', self.v_target_conv),
            ('g_c2h6', self.v_g_c2h6), ('g_ch4', self.v_g_ch4),
            ('g_c3h8', self.v_g_c3h8), ('g_c2h4', self.v_g_c2h4),
            ('g_c3h6', self.v_g_c3h6), ('g_ic4', self.v_g_ic4),
            ('g_nc4',  self.v_g_nc4),
            ('coils',   self.v_coils),  ('passes', self.v_passes),
            ('lpp',     self.v_lpp),    ('tube_id', self.v_tube_id),
            ('tube_od', self.v_tube_od),('emiss',   self.v_emiss),
            ('rough',   self.v_rough),  ('k_tube',  self.v_k_tube),
            ('h_o',     self.v_h_o),    ('hamp',    self.v_hamp),
            ('k_heat',  self.v_k_heat), ('k_dp',    self.v_k_dp),
            ('tp',      self.v_tp),     ('to',      self.v_to),
            ('ta',      self.v_ta),     ('tc',      self.v_tc),
            ('rtol',    self.v_rtol),   ('atol',    self.v_atol),
        ]
        for k, v in pairs:
            try:
                self._param_defaults[k] = v.get()
            except Exception:
                pass
        # Define Modified entry style
        try:
            sty = ttk.Style()
            sty.configure('Modified.TEntry', fieldbackground='#fff8dc')
        except Exception:
            pass

