    @classmethod
    def _all_preset_pairs(cls):
        """Return ordered list of (category, name) tuples — for the combobox."""
        result = []
        for cat, presets in cls.ALL_FURNACE_PRESETS.items():
            for name in presets:
                result.append((cat, name))
        return result

    @classmethod
    def _get_preset(cls, category, name):
        return cls.ALL_FURNACE_PRESETS[category][name]

    def _build_geometry_tab(self, nb):
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='② Furnace Geometry'); tab = _scroll_tab.scrollable_frame

        # ── Two-tier Furnace Preset Selector ─────────────────────────────────
        sf = ttk.LabelFrame(tab,
                            text='Furnace Geometry Preset  '
                                 '(Lummus SRT · Linde SRT · KBR GK · Technip USC/USRT · Lummus SCORE · '
                                 'MHI MERT · BASF-Linde · Toyo · IFP · Heavy Feed · Custom)',
                            padding=8)
        sf.pack(fill='x', padx=6, pady=(6, 2))

        row0 = ttk.Frame(sf); row0.pack(fill='x', pady=(0, 4))

        # Category combobox
        ttk.Label(row0, text='Vendor / Family:', width=18, anchor='e').pack(side=tk.LEFT)
        self.v_preset_cat = tk.StringVar(value='Lummus SRT')
        cat_cb = ttk.Combobox(row0, textvariable=self.v_preset_cat, state='readonly',
                               width=26,
                               values=list(self.ALL_FURNACE_PRESETS.keys()))
        cat_cb.pack(side=tk.LEFT, padx=6)

        # Model combobox (populated dynamically from category selection)
        ttk.Label(row0, text='Model:', width=8, anchor='e').pack(side=tk.LEFT)
        self.v_preset_model = tk.StringVar(value='SRT-VII (latest-generation cracking coil)')
        self._model_cb = ttk.Combobox(row0, textvariable=self.v_preset_model,
                                       state='readonly', width=34)
        self._model_cb.pack(side=tk.LEFT, padx=6)

        ttk.Button(row0, text='Apply →', width=8,
                   command=self._apply_furnace_preset).pack(side=tk.LEFT, padx=4)

        # KPI reference row (τ range, COT range, vendor, feeds)
        self._kpi_ref_var = tk.StringVar(value='')
        ttk.Label(sf, textvariable=self._kpi_ref_var,
                  foreground='#1a6b3a', font=('Helvetica', 8, 'bold')
                  ).pack(anchor=tk.W, pady=(0, 2))

        # Description label
        self._preset_desc_var = tk.StringVar(
            value='Select a vendor family and model above, then press Apply →')
        desc_lbl = ttk.Label(sf, textvariable=self._preset_desc_var,
                             foreground='#2c5f8a', font=('Courier', 8),
                             justify='left', wraplength=680)
        desc_lbl.pack(anchor=tk.W)

        # Wire up category→model cascade
        def _on_cat_change(*_):
            cat = self.v_preset_cat.get()
            models = list(self.ALL_FURNACE_PRESETS.get(cat, {}).keys())
            self._model_cb['values'] = models
            if models:
                self.v_preset_model.set(models[0])
                _preview_desc()

        def _preview_desc(*_):
            cat   = self.v_preset_cat.get()
            model = self.v_preset_model.get()
            try:
                p = self._get_preset(cat, model)
                self._preset_desc_var.set(p.get('description', ''))
                tau   = p.get('tau_ms_range', '—')
                cot   = p.get('cot_range_C',  '—')
                feeds = p.get('feeds',         '—')
                vend  = p.get('vendor',         '—')
                yr    = p.get('year', '')
                self._kpi_ref_var.set(
                    f"  τ={tau} ms  |  COT={cot} °C  |  "
                    f"Feeds: {feeds}  |  {vend}  ({yr})")
            except Exception:
                pass

        cat_cb.bind('<<ComboboxSelected>>', _on_cat_change)
        self._model_cb.bind('<<ComboboxSelected>>', _preview_desc)

        # Initialise model list for default category
        _on_cat_change()
        self.v_preset_model.set('SRT-VII (latest-generation cracking coil)')
        _preview_desc()

        # ── Geometry Diagram ──────────────────────────────────────────────────
        pic_frame = ttk.LabelFrame(tab, text='Coil Schematic (live)', padding=6)
        pic_frame.pack(fill='x', padx=6, pady=4)

        canvas_w, canvas_h = 390, 185
        # Geometry Canvas with direct scrollbars
        pic_scroll_y = ttk.Scrollbar(pic_frame, orient='vertical')
        pic_scroll_x = ttk.Scrollbar(pic_frame, orient='horizontal')
        pic = tk.Canvas(pic_frame, width=canvas_w, height=canvas_h,
                        bg='#1a2433', highlightthickness=1, highlightbackground='#444',
                        yscrollcommand=pic_scroll_y.set, xscrollcommand=pic_scroll_x.set)
        pic_scroll_y.config(command=pic.yview)
        pic_scroll_x.config(command=pic.xview)
        
        pic_scroll_y.pack(side='right', fill='y')
        pic_scroll_x.pack(side='bottom', fill='x')
        pic.pack(side='left', fill='both', expand=True, padx=4, pady=2)
        self._geom_canvas = pic

        self._draw_geometry_diagram()
        self._geom_timer = None
        def _sched_geom(*_):
            if self._geom_timer: self.root.after_cancel(self._geom_timer)
            self._geom_timer = self.root.after(500, self._draw_geometry_diagram)
            try:
                if getattr(self, '_mc_geom_timer', None):
                    self.root.after_cancel(self._mc_geom_timer)
                self._mc_geom_timer = self.root.after(
                    550, lambda: self._mc_sync_from_selected_geometry('geometry edit'))
            except Exception:
                pass
        for v in [self.v_coils, self.v_passes, self.v_lpp,
                  self.v_tube_id, self.v_tube_od, self.v_rough,
                  self.v_k_tube, self.v_emiss, self.v_h_o,
                  self.v_hfp, self.v_hamp, self.v_k_heat, self.v_k_dp]:
            v.trace_add('write', _sched_geom)

        # ── Coil / tube dimensions ────────────────────────────────────────────
        fg = ttk.LabelFrame(tab,
                            text='Radiant Coil — Tube Dimensions  '
                                 '(auto-populated by preset; override as needed)',
                            padding=8)
        fg.pack(fill='x', padx=6, pady=4)
        for lbl, v, row, tip, key in [
            ('Parallel Coils:',         self.v_coils,   0,
             'Linde SRT-IV=8 | KBR GK=10 | Technip=8 | Millisecond=24',  'coils'),
            ('Passes per Coil:',        self.v_passes,  1,
             'SRT-I=1 | SRT-III/IV=4 | SRT-V=6 | SRT-VII=8 | Millisec=1','passes'),
            ('Length per Pass (m):',    self.v_lpp,     2,
             'SRT-I=80 | SRT-IV=15 | SRT-VII=5 | Millisec=7.5',           'lpp'),
            ('Tube Inner Dia. Di (m):', self.v_tube_id, 3,
             'SRT-I=127mm | SRT-IV=105mm | SRT-VII=62mm | Millisec=35mm', 'tube_id'),
            ('Tube Outer Dia. Do (m):', self.v_tube_od, 4,
             'Di + wall (10–25 mm); Heavy feed: Di+25–28 mm',              'tube_od'),
            ('Wall Roughness ε (m):',   self.v_rough,   5,
             '4.5e-4 HP-alloy | 5.5e-4 heavily coked heavy feed',         'rough'),
        ]:
            self._row(fg, lbl, v, row, tip, key=key)

        # ── Heat transfer ─────────────────────────────────────────────────────
        fh = ttk.LabelFrame(tab, text='Heat Transfer — Firebox & Wall', padding=8)
        fh.pack(fill='x', padx=6, pady=4)
        for lbl, v, row, tip, key in [
            ('Tube Emissivity ε_t:',  self.v_emiss,  0,
             '0.80 SRT-I | 0.83 SRT-IV | 0.87 SRT-VII | 0.88 Millisec', 'emiss'),
            ('k_tube  [W/(m·K)]:',    self.v_k_tube, 1,
             'HP40-Micro=25 | 35Cr45Ni-Nb=23 | HK-40=22',                'k_tube'),
            ('h_o flue [W/(m²·K)]:', self.v_h_o,    2,
             '20 SRT-I | 26 SRT-IV | 32 SRT-VII | 35 Millisecond',       'h_o'),
        ]:
            self._row(fh, lbl, v, row, tip, key=key)

        fhp = ttk.LabelFrame(tab, text='Axial Heat-Flux Profile', padding=8)
        fhp.pack(fill='x', padx=6, pady=4)
        ttk.Label(fhp, text='Profile:').grid(row=0, column=0, sticky=tk.W, padx=8)
        ttk.Combobox(fhp, textvariable=self.v_hfp, state='readonly', width=14,
                     values=['uniform', 'sinusoidal', 'front_high', 'rear_high']
                     ).grid(row=0, column=1)
        ttk.Label(fhp, text='uniform=constant | sinusoidal=peak at centre | front/rear_high=tilted',
                  foreground='#666', font=('Helvetica', 8)
                  ).grid(row=1, column=0, columnspan=3, sticky=tk.W, padx=8)
        self._row(fhp, 'Peak ΔT_firebox (K):', self.v_hamp, 2, '0 = flat (uniform)')

        # ── Profile Correction Factors ────────────────────────────────────────
        fcf = ttk.LabelFrame(tab, text='Profile Correction Factors  (plant calibration)', padding=8)
        fcf.pack(fill='x', padx=6, pady=4)
        ttk.Label(fcf,
                  text='Scale simulated heat-flux and pressure-drop profiles to match plant measurements.\n'
                       'k_heat > 1 increases absorbed heat (raises COT/TMT); k_dp > 1 increases ΔP.',
                  foreground='#555', font=('Helvetica', 8), justify='left'
                  ).grid(row=0, column=0, columnspan=4, sticky=tk.W, padx=8, pady=(0, 4))
        self._row(fcf, 'k_heat  (heat-flux factor):', self.v_k_heat, 1,
                  'Multiplies outer Q per unit length.  1.0 = uncorrected.  Typ. 0.85–1.20',
                  key='k_heat')
        self._row(fcf, 'k_dp    (pressure-drop factor):', self.v_k_dp, 2,
                  'Multiplies dP/dz numerator.  1.0 = uncorrected.  Typ. 0.80–1.30',
                  key='k_dp')
        btn_cf = ttk.Frame(fcf)
        btn_cf.grid(row=3, column=0, columnspan=4, sticky=tk.W, padx=8, pady=(4, 2))
        ttk.Button(btn_cf, text='↺ Reset to 1.0',
                   command=lambda: (self.v_k_heat.set(1.0), self.v_k_dp.set(1.0))
                   ).pack(side=tk.LEFT)

        # ── UPGRADE v22: Advanced physics panel ───────────────────────────────
        fv22 = ttk.LabelFrame(tab, text='▲ UPGRADE v22 — Advanced Physics (SPYRO-level)', padding=8)
        fv22.pack(fill='x', padx=6, pady=4)
        ttk.Label(fv22,
                  text='New in v22: Pitzer Z-factor, Chapman-Enskog viscosity, per-pass tube IDs,\n'
                       'zone-wise heat flux (Lobo-Evans), TMT resistance chain, TLE quench ODE,\n'
                       'coke campaign evolution, and free-radical (Rice-Herzfeld) ethane kinetics.',
                  foreground='#1E3A5F', font=('Helvetica', 8, 'italic'), justify='left'
                  ).grid(row=0, column=0, columnspan=6, sticky=tk.W, padx=4, pady=(0,4))

        # Run-length and coke layer
        ttk.Label(fv22, text='Run-length (hr):', anchor='e', width=20
                  ).grid(row=1, column=0, sticky=tk.E, padx=4)
        ttk.Entry(fv22, textvariable=self.v_run_hours, width=8
                  ).grid(row=1, column=1, sticky=tk.W)
        ttk.Label(fv22, text='0 = fresh tube. >0 evolves coke layer δ(z) and re-runs end-of-run.',
                  foreground='#555', font=('Helvetica', 8)
                  ).grid(row=1, column=2, columnspan=4, sticky=tk.W, padx=4)

        ttk.Label(fv22, text='k_coke [W/m·K]:', anchor='e', width=20
                  ).grid(row=2, column=0, sticky=tk.E, padx=4)
        ttk.Entry(fv22, textvariable=self.v_k_coke, width=8
                  ).grid(row=2, column=1, sticky=tk.W)
        ttk.Label(fv22, text='Coke thermal conductivity. Typ. 0.8–1.2 W/m·K.',
                  foreground='#555', font=('Helvetica', 8)
                  ).grid(row=2, column=2, columnspan=4, sticky=tk.W, padx=4)

        # TLE quench
        ttk.Label(fv22, text='TLE quench length (m):', anchor='e', width=20
                  ).grid(row=3, column=0, sticky=tk.E, padx=4)
        ttk.Entry(fv22, textvariable=self.v_quench_length, width=8
                  ).grid(row=3, column=1, sticky=tk.W)
        ttk.Label(fv22, text='TLE / quench zone length. 0 = disabled.',
                  foreground='#555', font=('Helvetica', 8)
                  ).grid(row=3, column=2, columnspan=4, sticky=tk.W, padx=4)

        ttk.Label(fv22, text='TLE UA [W/m·K]:', anchor='e', width=20
                  ).grid(row=4, column=0, sticky=tk.E, padx=4)
        ttk.Entry(fv22, textvariable=self.v_quench_ua, width=8
                  ).grid(row=4, column=1, sticky=tk.W)
        ttk.Label(fv22, text='Overall heat-transfer conductance per metre of TLE tube.',
                  foreground='#555', font=('Helvetica', 8)
                  ).grid(row=4, column=2, columnspan=4, sticky=tk.W, padx=4)

        # Per-pass tube IDs (comma-separated string)
        ttk.Label(fv22, text='Per-pass Di (m), CSV:', anchor='e', width=20
                  ).grid(row=5, column=0, sticky=tk.E, padx=4)
        ttk.Entry(fv22, textvariable=self.v_pass_ids, width=28
                  ).grid(row=5, column=1, columnspan=3, sticky=tk.W)
        ttk.Label(fv22, text='e.g. "0.090,0.090,0.100,0.100"  (leave blank = uniform)',
                  foreground='#555', font=('Helvetica', 8)
                  ).grid(row=5, column=4, columnspan=2, sticky=tk.W, padx=4)

        # Bend loss coefficient
        ttk.Label(fv22, text='Bend k-factor:', anchor='e', width=20
                  ).grid(row=6, column=0, sticky=tk.E, padx=4)
        ttk.Entry(fv22, textvariable=self.v_bend_kf, width=8
                  ).grid(row=6, column=1, sticky=tk.W)
        ttk.Label(fv22, text='Minor-loss coefficient per 180° return bend. Typ. 0.4–0.8.',
                  foreground='#555', font=('Helvetica', 8)
                  ).grid(row=6, column=2, columnspan=4, sticky=tk.W, padx=4)

        # Zone flux table (CSV: z0,z1,q_kW/m² rows separated by |)
