    # ─── GEOMETRY DIAGRAM PAINTER ─────────────────────────────────────────────
    def _draw_geometry_diagram(self):
        c=self._geom_canvas; c.delete('all'); W,H=390,185
        # Set scrollregion to allow scrolling if canvas is smaller than drawn elements
        c.bind('<Configure>', lambda e: c.configure(scrollregion=c.bbox('all')))

        try:
            Di=float(self.v_tube_id.get()); Do=float(self.v_tube_od.get())
            Lp=float(self.v_lpp.get()); Nc=int(self.v_coils.get()); Np=int(self.v_passes.get())
        except Exception: return

        import math

        # ── Cross-section (left) ─────────────────────────────────────────────
        cx,cy,R_max=82,96,58
        R_outer=R_max; R_inner=int(R_max*(Di/Do))
        wall=(Do-Di)/2.

        # Glow effect: concentric outer rings (valid 6-digit colors only)
        for i,(clr,wd) in enumerate([('#8B0000',3),('#B22222',1)]):
            r=R_outer+8-i*5
            c.create_oval(cx-r,cy-r,cx+r,cy+r,fill='',outline=clr,width=wd)

        # Outer metal tube (gradient via two ovals)
        c.create_oval(cx-R_outer,cy-R_outer,cx+R_outer,cy+R_outer,fill='#6B7280',outline='#94A3B8',width=1.5)
        c.create_oval(cx-R_outer+2,cy-R_outer+2,cx+R_outer-2,cy+R_outer-2,fill='#78828F',outline='')

        # Inner bore — deep blue gradient feel
        c.create_oval(cx-R_inner,cy-R_inner,cx+R_inner,cy+R_inner,fill='#1E3A8A',outline='#93C5FD',width=1.5)
        c.create_oval(cx-R_inner+3,cy-R_inner+3,cx+R_inner-3,cy+R_inner-3,fill='#1D4ED8',outline='')

        # Flow arrow
        c.create_text(cx,cy,text='→ gas',fill='#BFDBFE',font=('Helvetica',7,'bold'))
        c.configure(scrollregion=c.bbox('all'))

        # Roughness ticks
        for deg in range(0,360,30):
            a=math.radians(deg)
            x1=cx+R_inner*math.cos(a); y1=cy+R_inner*math.sin(a)
            x2=cx+(R_inner+4)*math.cos(a); y2=cy+(R_inner+4)*math.sin(a)
            c.create_line(x1,y1,x2,y2,fill='#CBD5E0',width=1.2)

        # Di dimension arrow (below)
        ay=cy+R_outer+12
        c.create_line(cx-R_inner,ay,cx+R_inner,ay,fill='#93C5FD',arrow='both',arrowshape=(6,8,3))
        c.create_text(cx,ay+10,text=f'Di={Di*1000:.0f}mm',fill='#93C5FD',font=('Helvetica',7,'bold'))

        # Do dimension arrow (above)
        ay2=cy-R_outer-10
        c.create_line(cx-R_outer,ay2,cx+R_outer,ay2,fill='#94A3B8',arrow='both',arrowshape=(6,8,3))
        c.create_text(cx,ay2-10,text=f'Do={Do*1000:.0f}mm',fill='#94A3B8',font=('Helvetica',7,'bold'))

        # Wall label
        wx=cx+R_inner+(R_outer-R_inner)//2
        c.create_text(wx+20,cy-8,text=f'wall\n{wall*1000:.1f}mm',fill='#FCD34D',font=('Helvetica',6),justify='center')
        c.create_line(wx,cy,wx+14,cy-8,fill='#FCD34D',dash=(2,2))

        c.create_text(cx,H-8,text='Cross-Section',fill='#94A3B8',font=('Helvetica',7))

        # ── Firebox side view (right) ─────────────────────────────────────────
        bx0,bx1=170,W-8; by0,by1=16,H-24
        bw,bh=bx1-bx0,by1-by0

        # Firebox gradient background (dark red → orange)
        for i in range(14):
            frac=i/14.
            r=int(30+frac*25); g=int(frac*12)
            shade=f'#{r:02x}{g:02x}00'
            c.create_rectangle(bx0+i*3,by0+i*2,bx1-i*3,by1-i*2,fill=shade,outline='')
        c.create_rectangle(bx0,by0,bx1,by1,outline='#F97316',width=2,fill='')
        c.create_text((bx0+bx1)//2,by0-9,text='RADIANT FIREBOX',fill='#FB923C',font=('Helvetica',7,'bold'))

        # Draw passes as horizontal bands with serpentine flow
        n_show=min(Np,6); spacing=bh/(n_show+1); tube_r=max(4,min(9,int(spacing*0.28)))
        _pass_colors=['#3B82F6','#60A5FA']
        prev_x=prev_y=None
        for i in range(n_show):
            y_tube=by0+spacing*(i+1)
            x_start,x_end=(bx0+20,bx1-20) if i%2==0 else (bx1-20,bx0+20)
            clr=_pass_colors[i%2]
            # Tube rectangle with highlight
            c.create_rectangle(min(x_start,x_end),y_tube-tube_r,max(x_start,x_end),y_tube+tube_r,
                                fill=clr,outline='#BFDBFE',width=1.2)
            c.create_rectangle(min(x_start,x_end)+2,y_tube-tube_r+2,max(x_start,x_end)-2,y_tube-tube_r+4,
                                fill='#93C5FD',outline='')
            c.create_text((x_start+x_end)//2,y_tube,text=f'pass {i+1}  L={Lp:.0f}m',
                          fill='#DBEAFE',font=('Helvetica',6))
            if prev_x is not None:
                bxb=x_start
                c.create_arc(bxb-tube_r*2,prev_y,bxb+tube_r*2,y_tube,
                             start=90,extent=180 if i%2==1 else -180,
                             style='arc',outline='#FCD34D',width=2)
            prev_x,prev_y=x_end,y_tube

        # If more passes were hidden, show ellipsis
        if Np>6:
            c.create_text((bx0+bx1)//2,by1-8,text=f'+ {Np-6} more passes',
                          fill='#94A3B8',font=('Helvetica',6,'italic'))

        # In/out labels
        c.create_text(bx0+16,by0+12,text='IN→',fill='#86EFAC',font=('Helvetica',7,'bold'))
        c.create_text(bx1-16,by1-12,text='→OUT',fill='#FCA5A5',font=('Helvetica',7,'bold'))

        # Length annotation
        c.create_line(bx0+18,by1+7,bx1-18,by1+7,fill='#94A3B8',arrow='both',arrowshape=(5,7,3))
        c.create_text((bx0+bx1)//2,by1+17,
                      text=f'L/pass={Lp:.0f}m ×{Np}={Lp*Np:.0f}m total  |  {Nc} coils',
                      fill='#94A3B8',font=('Helvetica',7))

        # Preset label overlay
        model_v=getattr(self,'v_preset_model',None)
        cat_v=getattr(self,'v_preset_cat',None)
        if model_v and cat_v:
            short=model_v.get().split('(')[0].strip()
            if short and short!='— Manual entry —':
                c.create_text(W-6,8,text=short,anchor='ne',fill='#FCD34D',font=('Helvetica',9,'bold'))
                c.create_text(W-6,20,text=cat_v.get(),anchor='ne',fill='#FCD34D',font=('Helvetica',7))

    
    def _style_kinetics_editor_dark(self, widget=None):
        """Hard-apply premium dark theme to the Kinetics Editor tab.

        The Kinetics Editor has its own Treeview tags ('normal'/'modified') and
        several hard-coded foreground colors.  This method corrects those after
        the tab widgets exist and after every reload/theme switch.
        """
        pal = getattr(self, '_theme_palette', {
            'root':'#07111F','bg':'#0B1628','card':'#111C2E','card2':'#172338',
            'card3':'#1E2D46','entry':'#0D1829','text':'#EAF2FF','muted':'#9AA9BC',
            'accent':'#38BDF8','select':'#0E7490','white':'#FFFFFF','red':'#EF4444',
            'line':'#2B3A55','amber':'#F59E0B','accent2':'#22C55E','violet':'#A78BFA'
        })
        try:
            sty = ttk.Style()
            sty.configure('KineticEditor.Treeview', background=pal['card'], fieldbackground=pal['card'],
                          foreground=pal['text'], rowheight=27, bordercolor=pal['line'],
                          lightcolor=pal['line'], darkcolor=pal['line'], font=('Consolas', 9))
            sty.configure('KineticEditor.Treeview.Heading', background=pal['card3'], foreground=pal['accent'],
                          font=('Segoe UI Semibold', 9), relief='flat')
            sty.map('KineticEditor.Treeview', background=[('selected', pal['select'])], foreground=[('selected', pal['white'])])
        except Exception:
            pass
        try:
            if hasattr(self, '_ke_tree'):
                self._ke_tree.configure(style='KineticEditor.Treeview')
                self._ke_tree.tag_configure('normal', background=pal['card'], foreground=pal['text'])
                self._ke_tree.tag_configure('modified', background='#3B2A0F', foreground='#FDE68A')
                self._ke_tree.tag_configure('oddrow', background=pal['card'], foreground=pal['text'])
                self._ke_tree.tag_configure('evenrow', background=pal['card2'], foreground=pal['text'])
        except Exception:
            pass
        try:
            self._eradicate_white_backgrounds(widget or self.root, pal)
        except Exception:
            pass

    def _build_kinetics_editor_tab(self, nb):
        """
        Expose every reaction's A-factor and Ea for direct manual tuning.
        Changes take effect on the next simulation run.
        The edited values are stored in self._rxn_overrides and injected
        into the reaction list in _run_simulation().
        """
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='⑥ Kinetics Editor'); tab = _scroll_tab.scrollable_frame
        self._rxn_overrides = {}   # {rxn_index: {'A': new_A, 'Ea': new_Ea_kJ}}

        hdr = ttk.Frame(tab); hdr.pack(fill='x', padx=8, pady=(6,2))
        ttk.Label(hdr, text='🧪  REACTION KINETICS EDITOR',
                  font=('Helvetica',11,'bold'), foreground='#38BDF8').pack(side=tk.LEFT)
        ttk.Label(hdr,
            text='  Edit A-factor or Ea for any reaction → applies on next Run',
            font=('Helvetica',9), foreground='#9AA9BC').pack(side=tk.LEFT, padx=6)

        # ── Kinetics Editor Scope (Overall vs MultiCoil) ──────────────────────
        ke_scope_f = ttk.LabelFrame(tab, text='Editor Scope', padding=6)
        ke_scope_f.pack(fill='x', padx=8, pady=(0,4))
        self._ke_scope = tk.StringVar(value='Overall')
        ke_scope_row = ttk.Frame(ke_scope_f); ke_scope_row.pack(fill='x')
        ttk.Radiobutton(ke_scope_row,
            text='Overall  (A/Ea overrides apply to ALL coils identically)',
            variable=self._ke_scope, value='Overall',
            command=self._ke_update_scope_note).pack(side=tk.LEFT, padx=8)
        ttk.Radiobutton(ke_scope_row,
            text='MultiCoil  (select coil group to edit its specific reaction parameters)',
            variable=self._ke_scope, value='MultiCoil',
            command=self._ke_update_scope_note).pack(side=tk.LEFT, padx=8)
        self._ke_scope_note_sv = tk.StringVar(value='')
        ttk.Label(ke_scope_f, textvariable=self._ke_scope_note_sv,
                  font=('Helvetica',7,'italic'), foreground='#A7F3D0',
                  wraplength=750, justify='left').pack(anchor='w', padx=4)

        # MultiCoil coil selector (shown when scope=MultiCoil)
        self._ke_mc_sel_frame = ttk.Frame(ke_scope_f)
        ttk.Label(self._ke_mc_sel_frame, text='Edit Coil Group:',
                  font=('Helvetica',8,'bold')).pack(side=tk.LEFT, padx=4)
        self._ke_mc_coil_var = tk.StringVar(value='CG1 (Primary)')
        self._ke_mc_coil_cb  = ttk.Combobox(self._ke_mc_sel_frame,
            textvariable=self._ke_mc_coil_var, state='readonly', width=20)
        self._ke_mc_coil_cb['values'] = ['CG1 (Primary)']
        self._ke_mc_coil_cb.pack(side=tk.LEFT, padx=4)
        self._ke_mc_coil_cb.bind('<<ComboboxSelected>>', lambda *_: self._ke_reload())
        ttk.Label(self._ke_mc_sel_frame,
            text='Each coil group maintains its own override set. '
                 'Overrides not set for a coil fall back to the Overall set.',
            font=('Helvetica',7,'italic'), foreground='#9AA9BC').pack(side=tk.LEFT, padx=6)
        # Note: _ke_update_scope_note() is deferred until after _ke_tree is built (see end of method)

        guide_f = ttk.LabelFrame(tab, text='Quick Guide — what each parameter controls', padding=8)
        guide_f.pack(fill='x', padx=8, pady=4)
        guide_text = (
            'A-factor  (pre-exponential, units vary with reaction order):\n'
            '  • Multiply A × 10  → reaction 10× faster at ALL temperatures\n'
            '  • Halve A × 0.5   → reaction 2× slower — useful to suppress side products\n'
            '  • A does NOT shift the temperature at which cracking starts — Ea does that\n\n'
            'Ea (activation energy, kJ/mol):\n'
            '  • Lower Ea → reaction starts at LOWER temperatures (earlier in tube)\n'
            '  • Higher Ea → reaction needs HIGHER temperature to proceed\n'
            '  • Δ10 kJ/mol at 1100K changes rate by factor exp(-10000/8.314/1100) ≈ 3.3×\n\n'
            'Rule of thumb for calibration:\n'
            '  ① Product too LOW  → increase A of the producing reaction\n'
            '  ② Product too HIGH → decrease A of the producing reaction  OR  increase A of its consuming reaction\n'
            '  ③ Conversion too low → increase A or decrease Ea of primary cracking reaction\n'
            '  ④ COT too high for target conversion → kinetics are too slow; increase primary A'
        )
        ttk.Label(guide_f, text=guide_text, font=('Helvetica',8),
                  foreground='#EAF2FF', justify='left').pack(anchor='w')

        # Controls
        ctrl = ttk.Frame(tab); ctrl.pack(fill='x', padx=8, pady=4)
        ttk.Button(ctrl, text='🔄 Reload from current feed type',
                   command=self._ke_reload).pack(side=tk.LEFT, padx=4)
        ttk.Button(ctrl, text='↺ Reset ALL to tuner defaults',
                   command=self._ke_reset_all).pack(side=tk.LEFT, padx=4)
        ttk.Button(ctrl, text='💾 Export overrides CSV',
                   command=self._ke_export).pack(side=tk.LEFT, padx=4)
        ttk.Button(ctrl, text='📂 Import overrides CSV',
                   command=self._ke_import).pack(side=tk.LEFT, padx=4)
        self._ke_filter_var = tk.StringVar(value='')
        ttk.Label(ctrl, text='  Filter type:').pack(side=tk.LEFT, padx=(12,2))
        ttk.Combobox(ctrl, textvariable=self._ke_filter_var, width=18, state='readonly',
                     values=['(all)','Paraffin_Crack','Iso_Crack','Olefin_Crack',
                             'Dehydrogenation','Hydrogenation','Condensation',
                             'Ring_Opening','PAH_Growth','Hydrodealkylation',
                             'Coking (Catalytic)','Coking (Pyrolytic)',
                             'Steam Gasification','Steam Reforming','Water-Gas Shift']
                     ).pack(side=tk.LEFT)
        self._ke_filter_var.trace_add('write', lambda *_: self._ke_reload())

        # Treeview table of reactions
        cols = ('#','Type','Reaction','A_base','Ea_base','A_edit','Ea_edit','Effect')
        self._ke_tree = ttk.Treeview(tab, columns=cols, show='headings', height=18, style='KineticEditor.Treeview')
        widths = [40,140,340,90,80,90,80,200]
        anchors = [tk.E,tk.W,tk.W,tk.E,tk.E,tk.E,tk.E,tk.W]
        for c, w, a in zip(cols, widths, anchors):
            self._ke_tree.heading(c, text=c)
            self._ke_tree.column(c, width=w, anchor=a)
        self._ke_tree.tag_configure('modified', background='#3B2A0F', foreground='#FDE68A')
        self._ke_tree.tag_configure('normal', background='#111C2E', foreground='#EAF2FF')
        sb_v = ttk.Scrollbar(tab, orient=tk.VERTICAL, command=self._ke_tree.yview)
        sb_h = ttk.Scrollbar(tab, orient=tk.HORIZONTAL, command=self._ke_tree.xview)
        self._ke_tree.configure(yscrollcommand=sb_v.set, xscrollcommand=sb_h.set)
        sb_v.pack(side=tk.RIGHT, fill=tk.Y)
        sb_h.pack(side=tk.BOTTOM, fill=tk.X)
        self._ke_tree.pack(fill='both', expand=True, padx=(8,0))

        # Edit panel at bottom
        edit_f = ttk.LabelFrame(tab, text='Edit selected reaction', padding=6)
        edit_f.pack(fill='x', padx=8, pady=4)
        self._ke_A_var  = tk.StringVar(value='')
        self._ke_Ea_var = tk.StringVar(value='')
        ttk.Label(edit_f, text='A-factor (SI):').grid(row=0, column=0, sticky='e', padx=4)
        ttk.Entry(edit_f, textvariable=self._ke_A_var, width=14).grid(row=0,column=1,padx=4)
        ttk.Label(edit_f, text='Ea (kJ/mol):').grid(row=0, column=2, sticky='e', padx=4)
        ttk.Entry(edit_f, textvariable=self._ke_Ea_var, width=10).grid(row=0,column=3,padx=4)
        ttk.Button(edit_f, text='✔ Apply',
                   command=self._ke_apply).grid(row=0,column=4,padx=6)
        ttk.Button(edit_f, text='✖ Clear override',
                   command=self._ke_clear_one).grid(row=0,column=5,padx=4)
        ttk.Label(edit_f,
            text='Click a row → values populate above → edit → Apply → Run simulation',
            font=('Helvetica',8), foreground='#A7F3D0'
        ).grid(row=1, column=0, columnspan=6, sticky='w', padx=4, pady=(4,0))

        # Bind row click to populate edit panel
        self._ke_tree.bind('<<TreeviewSelect>>', self._ke_on_select)

        # Store current rxns for the editor
        self._ke_rxns_cache = []
        # Per-coil override store: {'Overall': {idx: ov}, 'CG1': {idx: ov}, ...}
        self._rxn_overrides_mc = {'Overall': {}}
        # Deferred scope-note init — runs after _ke_tree is fully constructed
        self.root.after(100, self._ke_update_scope_note)
        # Kinetics Editor has its own Treeview tags and hard-coded widgets;
        # force premium dark styling now and once more after Tk finishes layout.
        try:
            self._style_kinetics_editor_dark(tab)
            self.root.after(150, lambda: self._style_kinetics_editor_dark(tab))
        except Exception:
            pass

    def _ke_update_scope_note(self):
        notes = {
            'Overall':   'Overall: A/Ea overrides apply identically to every coil in the furnace.',
            'MultiCoil': ('MultiCoil: use the coil-group selector to load and edit the kinetic '
                          'parameters for each coil independently. '
                          'Coils without a per-coil override inherit from Overall.'),
        }
        sv = getattr(self, '_ke_scope_note_sv', None)
        if sv: sv.set(notes.get(self._ke_scope.get(), ''))
        mc_frame = getattr(self, '_ke_mc_sel_frame', None)
        if mc_frame is None: return
        if self._ke_scope.get() == 'MultiCoil':
            mc_frame.pack(fill='x', pady=2)
            # Rebuild coil options from multi-coil vars
            mc_vars = getattr(self, '_mc_coil_vars', [])
            active = [cv for cv in mc_vars if cv.get('active') and cv['active'].get()]
            opts = ['Overall'] + [f'CG{cv.get("coil_num", i+1)} ({cv["feed_type"].get() if "feed_type" in cv else "?"})'
                                   for i, cv in enumerate(active)]
            self._ke_mc_coil_cb['values'] = opts
            if self._ke_mc_coil_var.get() not in opts:
                self._ke_mc_coil_var.set(opts[0])
        else:
            mc_frame.pack_forget()
        # Only reload the tree if it already exists
        if getattr(self, '_ke_tree', None) is not None:
            self._ke_reload()

    def _ke_current_scope_key(self):
        """Return the dict key for the current scope/coil selection."""
        if getattr(self, '_ke_scope', None) and self._ke_scope.get() == 'MultiCoil':
            sel = self._ke_mc_coil_var.get()
            # Use 'CG{n}' as key, or 'Overall' if 'Overall' selected
            key = sel.split(' ')[0] if sel else 'Overall'
            return key
        return 'Overall'

    @property
    def _rxn_overrides(self):
        key = self._ke_current_scope_key()
        mc = getattr(self, '_rxn_overrides_mc', {})
        if key not in mc: mc[key] = {}
        return mc[key]

    @_rxn_overrides.setter
    def _rxn_overrides(self, val):
        # Called once at init with {}; seed the store
        if not hasattr(self, '_rxn_overrides_mc'):
            self._rxn_overrides_mc = {}
        self._rxn_overrides_mc['Overall'] = val

    def _ke_reload(self):
        """Rebuild the kinetics editor table from the exact solver reaction set."""
        ft = self.v_feed_type.get()
        tuner = KineticsTuner(p=self.v_tp.get(), o=self.v_to.get(),
                              a=self.v_ta.get(), coke=self.v_tc.get(),
                              metallurgy=self.v_metal.get(), dmds=self.v_dmds.get())
        _use_radical = getattr(self, 'v_radical_kinetics', None) and self.v_radical_kinetics.get()
        rxns = build_reactions_for_gui_feed(ft, tuner, include_radicals=bool(_use_radical))
        rxns = dedupe_kinetic_reactions(rxns)
        self._ke_rxns_cache = rxns
        self._ke_populate(rxns)

    # Map reaction type to which product component is mainly affected
    _KE_EFFECT = {
        'Paraffin_Crack':     '↑ C₂H₄/CH₄ from heavy paraffins',
        'Iso_Crack':          '↑ iC₄H₈/C₃H₆ from iso-paraffins',
        'Olefin_Crack':       '↑ C₂H₄/C₂H₂ from olefins',
        'Dehydrogenation':    '↑ H₂ + unsaturated product',
        'Hydrogenation':      '↓ unsaturates, ↑ saturates (reverse)',
        'Ring_Opening':       '↑ C₂H₄+C₃H₆ from naphthenes',
        'Condensation':       '↑ C₄–C₆ from small olefins',
        'PAH_Growth':         '↑ naphthalene/biphenyl (coke precursors)',
        'Hydrodealkylation':  '↑ C₆H₆, ↓ C₇H₈/C₈H₁₀ (BTX shift)',
        'Coking (Catalytic)': '↑ catalytic coke (Fe/Ni surface)',
        'Coking (Pyrolytic)': '↑ gas-phase coke (radical)',
        'Steam Gasification': '↑ CO + H₂ from coke + steam',
        'Steam Reforming':    '↑ CO + H₂ from CH₄ + steam',
        'Water-Gas Shift':    '↑ CO₂ + H₂ from CO + H₂O',
    }

    def _ke_populate(self, rxns):
        for iid in self._ke_tree.get_children():
            self._ke_tree.delete(iid)
        filt = self._ke_filter_var.get()
        for i, rxn in enumerate(rxns):
            rtype = rxn.get('type','')
            if filt and filt != '(all)' and filt not in rtype:
                continue
            A_base  = rxn['A']
            Ea_base = rxn['Ea']          # display kJ/mol
            ov = self._rxn_overrides.get(i, {})
            A_edit  = f"{ov.get('A', '')}"
            _ea_ov = ov.get('Ea', '')
            if _ea_ov != '':
                try:
                    _ea_ov = float(_ea_ov)
                    if _ea_ov > 2500.0: _ea_ov = _ea_ov / 1000.0  # backward compatibility with old J/mol overrides
                except Exception:
                    pass
            Ea_edit = f"{_ea_ov}"
            effect  = self._KE_EFFECT.get(rtype, '—')
            tag = 'modified' if i in self._rxn_overrides else ('evenrow' if (i % 2 == 0) else 'normal')
            self._ke_tree.insert('', tk.END, iid=str(i), values=(
                i+1, rtype, _fmt_rxn(rxn),
                f'{A_base:.3e}', f'{Ea_base:.1f}',
                A_edit, Ea_edit, effect
            ), tags=(tag,))
        try:
            self._style_kinetics_editor_dark(getattr(self, '_ke_tree', None))
        except Exception:
            pass


    def _ke_on_select(self, event):
        sel = self._ke_tree.selection()
        if not sel: return
        i = int(sel[0])
        rxn = self._ke_rxns_cache[i] if i < len(self._ke_rxns_cache) else None
        if rxn is None: return
        ov = self._rxn_overrides.get(i, {})
        self._ke_A_var.set(str(ov.get('A', f"{rxn['A']:.6e}")))
        _ea_val = ov.get('Ea', None)
        if _ea_val is not None:
            try:
                _ea_val = float(_ea_val)
                if _ea_val > 2500.0: _ea_val = _ea_val / 1000.0  # backward compatibility with old J/mol overrides
                self._ke_Ea_var.set(f"{_ea_val:.2f}")
            except Exception:
                self._ke_Ea_var.set(str(_ea_val))
        else:
            self._ke_Ea_var.set(f"{rxn['Ea']:.2f}")

    def _ke_apply(self):
        sel = self._ke_tree.selection()
        if not sel: return
        i = int(sel[0])
        try:
            A_new  = float(self._ke_A_var.get())
            Ea_new = float(self._ke_Ea_var.get())   # user enters kJ/mol
            assert A_new > 0 and Ea_new > 0
        except Exception:
            messagebox.showerror('Invalid', 'Enter positive numeric values for A and Ea.'); return
        self._rxn_overrides[i] = {'A': A_new, 'Ea': Ea_new}  # store as kJ/mol, matching reaction dictionaries
        self._ke_reload()
        self._schedule_run()

    def _ke_clear_one(self):
        sel = self._ke_tree.selection()
        if not sel: return
        i = int(sel[0])
        self._rxn_overrides.pop(i, None)
        self._ke_reload()
        self._schedule_run()

    def _ke_reset_all(self):
        key = self._ke_current_scope_key()
        mc  = getattr(self, '_rxn_overrides_mc', {})
        if key in mc: mc[key].clear()
        self._ke_reload()
        self._schedule_run()

    def _ke_export(self):
        fp = filedialog.asksaveasfilename(defaultextension='.csv',
             filetypes=[('CSV','*.csv'),('All','*.*')])
        if not fp: return
        with open(fp,'w',newline='') as f:
            w = csv.writer(f)
            w.writerow(['rxn_index','A_SI','Ea_kJ_per_mol'])
            for i, ov in self._rxn_overrides.items():
                _ea = float(ov['Ea'])
                if _ea > 2500.0: _ea = _ea / 1000.0
                w.writerow([i, ov['A'], _ea])
        messagebox.showinfo('Saved', fp)

    def _ke_import(self):
        fp = filedialog.askopenfilename(filetypes=[('CSV','*.csv'),('All','*.*')])
        if not fp: return
        with open(fp,'r') as f:
            reader = csv.DictReader(f)
            for row in reader:
                try:
                    i = int(row['rxn_index'])
                    _ea = float(row.get('Ea_kJ_per_mol', row.get('Ea_J_per_mol')))
                    if 'Ea_J_per_mol' in row and row.get('Ea_J_per_mol') and not row.get('Ea_kJ_per_mol'):
                        _ea = _ea / 1000.0
                    self._rxn_overrides[i] = {
                        'A':  float(row['A_SI']),
                        'Ea': _ea,
                    }
                except Exception: pass
        self._ke_reload()
        messagebox.showinfo('Imported', f'{len(self._rxn_overrides)} overrides loaded.')
        self._schedule_run()

    # ─── HELP SYSTEM (Requirement 4) ──────────────────────────────────────────
    def _help_window(self, title, content):
        """Generic scrollable help window."""
        win = tk.Toplevel(self.root)
        win.title(title)
        win.geometry('780x560')
        sb = ttk.Scrollbar(win)
        sb.pack(side=tk.RIGHT, fill=tk.Y)
        txt = tk.Text(win, wrap='word', font=('Helvetica',10),
                      yscrollcommand=sb.set, padx=16, pady=12,
                      bg='#fafafa', relief='flat')
        sb.config(command=txt.yview)
        txt.pack(fill='both', expand=True)
        txt.tag_configure('h1', font=('Helvetica',13,'bold'), foreground='#1a3a5c', spacing1=8)
        txt.tag_configure('h2', font=('Helvetica',11,'bold'), foreground='#1565c0', spacing1=6)
        txt.tag_configure('code', font=('Courier',9), background='#f0f0f0', relief='groove')
        txt.tag_configure('warn', foreground='#b71c1c', font=('Helvetica',10,'bold'))
        txt.tag_configure('ok',   foreground='#2e7d32', font=('Helvetica',10,'bold'))
        txt.tag_configure('norm', font=('Helvetica',10))
        for line in content:
            if isinstance(line, tuple):
                txt.insert('end', line[0]+'\n', line[1])
            else:
                txt.insert('end', line+'\n', 'norm')
        txt.config(state='disabled')
        return win

