    # ─── ③ METALLURGY & DMDS TAB ──────────────────────────────────────────────
    def _build_metallurgy_tab(self, nb):
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='③ Metallurgy & DMDS'); tab = _scroll_tab.scrollable_frame

        fm = ttk.LabelFrame(tab, text='Tube Metallurgy', padding=10)
        fm.pack(fill='x', padx=6, pady=8)
        ttk.Label(fm, text='Alloy:').grid(row=0, column=0, sticky=tk.W, padx=8, pady=4)
        ttk.Combobox(fm, textvariable=self.v_metal, state='readonly', width=24,
                     values=['Standard HP-Alloy', 'Aluminized/Coated',
                             '25Cr-35Ni (HK-40)', 'Manaurite 36X', 'Supertherm']
                     ).grid(row=0, column=1, pady=4)
        ttk.Label(fm, text=(
            'Standard HP-Alloy  — baseline Fe/Ni catalytic coking\n'
            'Aluminized/Coated  — Al₂O₃ layer: −90% catalytic, −5% pyrolytic coking\n'
            '25Cr-35Ni (HK-40)  — similar to HP; use k_metal ≈ 22 W/(m·K)\n'
            'Manaurite 36X      — low-coke Ni-Cr alloy, k ≈ 25 W/(m·K)\n'
            'Supertherm          — Cr-Si, k ≈ 20 W/(m·K)'),
            foreground='#555', font=('Helvetica', 8), justify=tk.LEFT
            ).grid(row=1, column=0, columnspan=2, sticky=tk.W, padx=8, pady=(0, 6))

        fd = ttk.LabelFrame(tab, text='DMDS Chemical Mitigation', padding=10)
        fd.pack(fill='x', padx=6, pady=6)
        ttk.Checkbutton(fd, text='Inject DMDS  (Di-Methyl Di-Sulfide)',
                        variable=self.v_dmds
                        ).grid(row=0, column=0, sticky=tk.W, padx=8, pady=4)
        ttk.Label(fd, text=(
            'DMDS decomposes → H₂S at cracker temperatures.\n'
            'H₂S passivates Fe/Ni active sites → −20% catalytic coking.\n'
            'Typical dose: 50–200 ppm wt in HC feed.'),
            foreground='#555', font=('Helvetica', 8), justify=tk.LEFT
            ).grid(row=1, column=0, sticky=tk.W, padx=8, pady=(0, 4))

    # ─── ④ KINETIC TUNING TAB ─────────────────────────────────────────────────
    def _build_kinetics_tab(self, nb):
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='④ Kinetic Tuning'); tab = _scroll_tab.scrollable_frame

        # ── Kinetic Tuning Scope (Overall vs MultiCoil) ──────────────────────
        fkt_scope = ttk.LabelFrame(tab, text='Tuning Scope', padding=8)
        fkt_scope.pack(fill='x', padx=6, pady=(8,4))
        self.v_kt_scope = tk.StringVar(value='Overall')
        scope_row = ttk.Frame(fkt_scope); scope_row.pack(fill='x')
        ttk.Radiobutton(scope_row,
            text='Overall  (single kp/ko/ka/kc applied identically to every coil)',
            variable=self.v_kt_scope, value='Overall',
            command=self._kt_update_scope_ui).pack(side=tk.LEFT, padx=8)
        ttk.Radiobutton(scope_row,
            text='MultiCoil  (each coil group can have independent kp/ko/ka — requires Multi-Coil mode)',
            variable=self.v_kt_scope, value='MultiCoil',
            command=self._kt_update_scope_ui).pack(side=tk.LEFT, padx=8)
        self._kt_scope_note_sv = tk.StringVar(value='')
        ttk.Label(fkt_scope, textvariable=self._kt_scope_note_sv,
                  font=('Helvetica',7,'italic'), foreground='#2c5f8a',
                  wraplength=700, justify='left').pack(anchor='w', padx=4, pady=(2,0))

        fk = ttk.LabelFrame(tab, text='Reaction-Class Multipliers  (1.0 = literature defaults)',
                             padding=10)
        fk.pack(fill='x', padx=6, pady=8)
        for lbl, v, row, tip in [
            ('Primary Paraffin/Ring  k_p:',  self.v_tp, 0, 'nC/iC cracking + ring opening'),
            ('Olefin Secondary     k_o:',    self.v_to, 1, 'olefin cracking A-factors'),
            ('Aromatisation        k_a:',    self.v_ta, 2, 'condensation, PAH, HAD'),
            ('Coking Rate          k_coke:', self.v_tc, 3, 'match plant decoking freq.'),
        ]:
            self._row(fk, lbl, v, row, tip)

        # MultiCoil per-coil kinetic override section
        self._kt_mc_frame = ttk.LabelFrame(tab,
            text='MultiCoil Per-Coil Kinetic Overrides  (shown only when MultiCoil scope is selected)',
            padding=8)
        self._kt_mc_entries = {}   # coil_num -> {kp, ko, ka} DoubleVar
        self._kt_mc_inner   = ttk.Frame(self._kt_mc_frame)
        self._kt_mc_inner.pack(fill='x')
        ttk.Label(self._kt_mc_frame,
            text='Enable Multi-Coil mode in the 🔀 tab and select MultiCoil scope above to see per-coil fields.',
            font=('Helvetica',8,'italic'), foreground='#555').pack(anchor='w', padx=4)

        ttk.Label(fk, text=(
            'CALIBRATION WORKFLOW:\n'
            '  1.  k_p     → match total conversion + CH₄/C₂H₆ yields\n'
            '  2.  k_o     → match P/E ratio (C₃H₆ / C₂H₄) and C₄ yields\n'
            '  3.  k_a     → match BTX (benzene + toluene + xylene)\n'
            '  4.  k_coke  → match plant decoking interval (run-length)\n\n'
            'Check the Validation tab for RMSE vs literature reference.'),
            foreground='navy', font=('Helvetica', 8), justify=tk.LEFT
            ).grid(row=4, column=0, columnspan=3, sticky=tk.W, padx=8, pady=(8, 4))

        # Init scope UI
        self.root.after(200, self._kt_update_scope_ui)

    def _kt_update_scope_ui(self):
        """Show/hide MultiCoil per-coil kinetic override fields based on scope selection."""
        scope = getattr(self, 'v_kt_scope', None)
        if scope is None: return
        notes = {
            'Overall':   ('Overall: the kp/ko/ka/kc multipliers above apply to every coil in the furnace. '
                          'This is the standard single-coil and uniform multi-coil mode.'),
            'MultiCoil': ('MultiCoil: assign independent kp/ko/ka values per coil group. '
                          'The global kp/ko/ka above serve as defaults; per-coil overrides take precedence. '
                          'Multi-Coil mode must be ON in the 🔀 tab.'),
        }
        sv = getattr(self, '_kt_scope_note_sv', None)
        if sv: sv.set(notes.get(scope.get(), ''))

        mc_frame = getattr(self, '_kt_mc_frame', None)
        if mc_frame is None: return

        if scope.get() == 'MultiCoil':
            mc_frame.pack(fill='x', padx=6, pady=(0,6))
            self._kt_rebuild_mc_entries()
        else:
            mc_frame.pack_forget()

    def _kt_rebuild_mc_entries(self):
        """Rebuild per-coil kp/ko/ka entry rows from current multi-coil configuration."""
        inner = getattr(self, '_kt_mc_inner', None)
        if inner is None: return
        for w in inner.winfo_children(): w.destroy()
        mc_vars = getattr(self, '_mc_coil_vars', [])
        active = [cv for cv in mc_vars if cv.get('active') and cv['active'].get()]
        if not active:
            ttk.Label(inner,
                text='No active coil groups found. Enable Multi-Coil mode in the 🔀 tab first.',
                font=('Helvetica',8,'italic'), foreground='#888').pack(anchor='w', padx=4)
            return
        # Header
        hdr = ttk.Frame(inner); hdr.pack(fill='x', pady=(2,2))
        for col, lbl, w in [(0,'Coil Group',12),(1,'Feed',10),(2,'k_p (override)',10),
                             (3,'k_o (override)',10),(4,'k_a (override)',10)]:
            ttk.Label(hdr, text=lbl, font=('Helvetica',8,'bold'), foreground='#1a3a5c',
                      width=w, anchor='center').grid(row=0, column=col, padx=4, pady=1)
        self._kt_mc_entries = {}
        for ri, cv in enumerate(active):
            cnum = cv.get('coil_num', ri+1)
            ft   = cv['feed_type'].get() if 'feed_type' in cv else '—'
            row  = ttk.Frame(inner); row.pack(fill='x')
            ttk.Label(row, text=f'CG{cnum}', width=12, anchor='center',
                      font=('Helvetica',8,'bold')).grid(row=0,column=0,padx=4,pady=2)
            ttk.Label(row, text=ft, width=10, anchor='w',
                      font=('Courier',8)).grid(row=0,column=1,padx=4,pady=2)
            # Per-coil kp/ko/ka — default to global value
            self._kt_mc_entries.setdefault(cnum, {})
            for ci, (key, gv) in enumerate([('kp', self.v_tp),('ko', self.v_to),('ka', self.v_ta)]):
                if key not in self._kt_mc_entries[cnum]:
                    self._kt_mc_entries[cnum][key] = tk.DoubleVar(value=gv.get())
                ttk.Entry(row, textvariable=self._kt_mc_entries[cnum][key], width=10
                          ).grid(row=0, column=ci+2, padx=4, pady=2)
        ttk.Label(inner,
            text='  Leave at global value or edit individually. Click ↺ Reset to sync from global sliders.',
            font=('Helvetica',7,'italic'), foreground='#555').pack(anchor='w', padx=6, pady=2)
        ttk.Button(inner, text='↺ Sync all from global kp/ko/ka',
                   command=self._kt_sync_mc_from_global).pack(anchor='w', padx=4, pady=2)

    def _kt_sync_mc_from_global(self):
        """Reset all per-coil overrides to the current global kp/ko/ka values."""
        for cnum, dv_dict in self._kt_mc_entries.items():
            dv_dict.get('kp', self.v_tp).set(self.v_tp.get())
            dv_dict.get('ko', self.v_to).set(self.v_to.get())
            dv_dict.get('ka', self.v_ta).set(self.v_ta.get())

    def _kt_get_coil_tuner(self, coil_num):
        """Return a KineticsTuner for a specific coil group, respecting MultiCoil scope."""
        scope = getattr(self, 'v_kt_scope', None)
        if scope and scope.get() == 'MultiCoil':
            mc_e = getattr(self, '_kt_mc_entries', {})
            if coil_num in mc_e:
                kp = mc_e[coil_num].get('kp', self.v_tp).get()
                ko = mc_e[coil_num].get('ko', self.v_to).get()
                ka = mc_e[coil_num].get('ka', self.v_ta).get()
                return KineticsTuner(p=kp, o=ko, a=ka, coke=self.v_tc.get(),
                                     metallurgy=self.v_metal.get(), dmds=self.v_dmds.get())
        return KineticsTuner(p=self.v_tp.get(), o=self.v_to.get(), a=self.v_ta.get(),
                             coke=self.v_tc.get(), metallurgy=self.v_metal.get(),
                             dmds=self.v_dmds.get())

    # ─── ⑤ SOLVER SETTINGS + LOG TAB ─────────────────────────────────────────
    def _build_solver_tab(self, nb):
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='⑤ Solver & Log'); tab = _scroll_tab.scrollable_frame

        # ── ODE settings ──────────────────────────────────────────────────────
        fs = ttk.LabelFrame(tab, text='ODE Integrator  (scipy solve_ivp)', padding=8)
        fs.pack(fill='x', padx=6, pady=(6,3))
        ttk.Label(fs, text='Method:').grid(row=0, column=0, sticky=tk.W, padx=6, pady=3)
        ttk.Combobox(fs, textvariable=self.v_solver, state='readonly', width=10,
                     values=['BDF', 'Radau', 'LSODA', 'RK45', 'DOP853']
                     ).grid(row=0, column=1, pady=3, sticky=tk.W)

        # reference annotations beside each field
        for lbl, v, row, tip, ref in [
            ('rtol:', self.v_rtol, 1, '↓ tighter → slower, more accurate', 'std: 1e-4'),
            ('atol:', self.v_atol, 2, '↓ tighter → slower, more accurate', 'std: 1e-6'),
        ]:
            ttk.Label(fs, text=lbl).grid(row=row, column=0, sticky=tk.W, padx=6, pady=2)
            e = ttk.Entry(fs, textvariable=v, width=10); e.grid(row=row, column=1, pady=2, padx=4)
            ttk.Label(fs, text=ref, foreground='#888', font=('Helvetica',7,'italic')
                      ).grid(row=row, column=2, sticky=tk.W, padx=2)
            ttk.Label(fs, text=tip, foreground='#555', font=('Helvetica',7)
                      ).grid(row=row, column=3, sticky=tk.W, padx=4)

        guide = ttk.Label(fs, text=(
            'BDF / Radau — stiff (recommended) | LSODA — auto-stiff | RK45 / DOP853 — non-stiff\n'
            'For mass balance ≥99.99%: rtol=1e-6, atol=1e-8  (3–5× slower)\n'
            'Default rtol=1e-4 gives ≥99.9% closure in <3 s.'),
            foreground='navy', font=('Helvetica', 8), justify=tk.LEFT)
        guide.grid(row=3, column=0, columnspan=4, sticky=tk.W, padx=6, pady=(4,2))

        # ── Firebox COT-solver settings ───────────────────────────────────────
        fc_f = ttk.LabelFrame(tab, text='COT / Firebox Solver', padding=8)
        fc_f.pack(fill='x', padx=6, pady=3)
        self.v_cot_bracket_lo = tk.DoubleVar(value=700.)
        self.v_cot_bracket_hi = tk.DoubleVar(value=1450.)
        for lbl, v, row, ref in [
            ('Firebox bracket low  (°C):', self.v_cot_bracket_lo, 0, 'std: 700'),
            ('Firebox bracket high (°C):', self.v_cot_bracket_hi, 1, 'std: 1450'),
        ]:
            ttk.Label(fc_f, text=lbl).grid(row=row, column=0, sticky=tk.W, padx=6, pady=2)
            ttk.Entry(fc_f, textvariable=v, width=8).grid(row=row, column=1, padx=4)
            ttk.Label(fc_f, text=ref, foreground='#888', font=('Helvetica',7,'italic')
                      ).grid(row=row, column=2, sticky=tk.W, padx=2)

        # ── Solver log ────────────────────────────────────────────────────────
        lf = ttk.LabelFrame(tab, text='Solver Log  (last run diagnostics)', padding=6)
        lf.pack(fill='both', expand=True, padx=6, pady=4)

        log_bar = ttk.Frame(lf); log_bar.pack(fill='x', pady=(0,4))
        ttk.Button(log_bar, text='🗑 Clear Log',
                   command=self._solver_log_clear).pack(side=tk.LEFT, padx=4)
        ttk.Button(log_bar, text='💾 Save Log',
                   command=self._solver_log_save).pack(side=tk.LEFT, padx=4)
        self.v_verbose_log = tk.BooleanVar(value=True)
        ttk.Checkbutton(log_bar, text='Verbose (log every ODE step count)',
                        variable=self.v_verbose_log).pack(side=tk.LEFT, padx=8)

        log_frame = ttk.Frame(lf); log_frame.pack(fill='both', expand=True)
        self._solver_log = tk.Text(log_frame, height=10, font=('Courier', 8),
                                   state='disabled', wrap='none',
                                   bg='#1a1a2e', fg='#e0e0e0',
                                   insertbackground='white',
                                   selectbackground='#3a3a5c')
        sb_sv = ttk.Scrollbar(log_frame, orient=tk.VERTICAL,  command=self._solver_log.yview)
        sb_sh = ttk.Scrollbar(log_frame, orient=tk.HORIZONTAL, command=self._solver_log.xview)
        self._solver_log.configure(yscrollcommand=sb_sv.set, xscrollcommand=sb_sh.set)
        sb_sv.pack(side=tk.RIGHT, fill=tk.Y)
        sb_sh.pack(side=tk.BOTTOM, fill=tk.X)
        self._solver_log.pack(fill='both', expand=True)

        # Tag colours for log levels
        self._solver_log.tag_configure('INFO',  foreground='#64b5f6')
        self._solver_log.tag_configure('OK',    foreground='#81c784')
        self._solver_log.tag_configure('WARN',  foreground='#ffb74d')
        self._solver_log.tag_configure('ERROR', foreground='#e57373')
        self._solver_log.tag_configure('DATA',  foreground='#e0e0e0')
        self._solver_log.tag_configure('HEAD',  foreground='#ce93d8', font=('Courier',8,'bold'))

    def _solver_log_write(self, msg, tag='DATA'):
        """Thread-safe append to solver log."""
        def _append():
            self._solver_log.configure(state='normal')
            self._solver_log.insert('end', msg + '\n', tag)
            self._solver_log.see('end')
            self._solver_log.configure(state='disabled')
        self.root.after(0, _append)

    def _solver_log_clear(self):
        self._solver_log.configure(state='normal')
        self._solver_log.delete('1.0', 'end')
        self._solver_log.configure(state='disabled')

    def _solver_log_save(self):
        fp = filedialog.asksaveasfilename(defaultextension='.txt',
             filetypes=[('Text','*.txt'),('All','*.*')])
        if not fp: return
        content = self._solver_log.get('1.0', 'end')
        with open(fp, 'w') as f: f.write(content)
        messagebox.showinfo('Saved', fp)

    # ─── ① PROFILES & KPIS (OUTPUT) ───────────────────────────────────────────
    def _build_profiles_tab(self, nb):
        tab = ttk.Frame(nb); nb.add(tab, text='① Profiles & KPIs')
        pw2 = ttk.PanedWindow(tab, orient=tk.HORIZONTAL)
        pw2.pack(fill='both', expand=True)

        # ── Left KPI panel ────────────────────────────────────────────────────
        kpi_outer = tk.Frame(pw2, bg='#F8FAFC'); pw2.add(kpi_outer, weight=0)
        # Banner header
        banner = tk.Frame(kpi_outer, bg='#1E3A5F', height=38)
        banner.pack(fill='x')
        tk.Label(banner, text='📊  KPI DASHBOARD', font=('Helvetica',10,'bold'),
                 fg='#DBEAFE', bg='#1E3A5F', pady=8).pack(side=tk.LEFT, padx=10)

        _kpi_scroll = ScrollableFrame(kpi_outer)
        _kpi_scroll.pack(fill='both', expand=True, padx=2, pady=2)
        kpi_frame = _kpi_scroll.scrollable_frame
        # Note: bg='#F8FAFC' is lost unless we configure it, but it's okay for now.

        self.kpi_labels = {}
        _KPI_GROUPS = [
            ('🌡  Process', '#EFF6FF', '#2563EB', [
                ('COT',          'COT (this coil)',    '°C',  '#DC2626'),
                ('combined_cot', 'Combined COT 🔀',    '°C',  '#7C3AED'),
                ('conv',         'Conversion',          '%',   '#1D4ED8'),
                ('firebox',      'Firebox T',           '°C',  '#B45309'),
                ('dP',           'Coil ΔP',             'atm', '#374151'),
                ('heat',         'Heat Duty',           'kW',  '#374151'),
                ('tau',          'Residence τ',         'ms',  '#0F766E'),
                ('CPR',          'CPR = Pout/Pin',     '',    '#38BDF8'),
            ]),
            ('⚙  Transport', '#F0FDF4', '#15803D', [
                ('Re',  'Re (outlet)',      '',         '#1D4ED8'),
                ('Pr',  'Pr (outlet)',      '',         '#1D4ED8'),
                ('hi',  'h_i [W/m²K]',     '',         '#0369A1'),
                ('tmt', 'TMT max',          '°C',       '#B91C1C'),
            ]),
            ('⚗  Yields [g/100g HC]', '#FFF7ED', '#EA580C', [
                ('C2H4',  'C₂H₄ Ethylene',  '', '#15803D'),
                ('C3H6',  'C₃H₆ Propylene', '', '#15803D'),
                ('BTX',   'BTX',            '', '#0369A1'),
                ('C4s',   'C4s',            '', '#0369A1'),
                ('PE',    'P/E Ratio',       '', '#92400E'),
                ('H2CH4', 'H₂/CH₄ (mol)',   '', '#92400E'),
            ]),
            ('🔥  Coking', '#FEF2F2', '#DC2626', [
                ('coke_y', 'Coke yield',  'g/100g', '#7C2D12'),
                ('coke_a', 'Avg coking', 'kg/m²h',  '#7C2D12'),
                ('coke_m', 'Max coking', 'kg/m²h',  '#7C2D12'),
            ]),
        ]

        for grp_title, grp_bg, accent, kpis in _KPI_GROUPS:
            # Section strip
            tk.Frame(kpi_frame, bg=accent, height=2).pack(fill='x', padx=6, pady=(8,0))
            tk.Label(kpi_frame, text=grp_title, font=('Helvetica',8,'bold'),
                     fg=accent, bg='#F8FAFC', anchor='w').pack(fill='x', padx=8, pady=(3,2))
            card = tk.Frame(kpi_frame, bg=grp_bg, padx=8, pady=5)
            card.pack(fill='x', padx=6, pady=(0,4))
            for key, label, unit, clr in kpis:
                row = tk.Frame(card, bg=grp_bg); row.pack(fill='x', pady=1)
                lbl_text = f'{label}' + (f' ({unit})' if unit else '')
                tk.Label(row, text=lbl_text, font=('Helvetica',8), fg='#64748B',
                         bg=grp_bg, anchor='w', width=18).pack(side=tk.LEFT)
                lv = tk.Label(row, text='—', fg=clr, bg=grp_bg,
                              font=('Courier',10,'bold'), anchor='e', width=10)
                lv.pack(side=tk.RIGHT)
                self.kpi_labels[key] = lv

        # ── Right plot area ────────────────────────────────────────────────────
        plot_frame = ttk.Frame(pw2); pw2.add(plot_frame, weight=1)

        # ── Tube / Coil selector toolbar ─────────────────────────────────────
        tube_bar = tk.Frame(plot_frame, bg='#EEF2FF', pady=4)
        tube_bar.pack(fill='x')
        tk.Label(tube_bar, text='View Profile for Tube:', font=('Helvetica',9,'bold'),
                 bg='#EEF2FF', fg='#1E3A5F').pack(side=tk.LEFT, padx=8)
        self._profile_tube_var = tk.StringVar(value='Coil 1 (Primary)')
        self._profile_tube_cb = ttk.Combobox(tube_bar, textvariable=self._profile_tube_var,
                                              state='readonly', width=22)
        self._profile_tube_cb['values'] = ['Coil 1 (Primary)']
        self._profile_tube_cb.pack(side=tk.LEFT, padx=4)
        ttk.Button(tube_bar, text='Show',
                   command=self._on_profile_tube_select).pack(side=tk.LEFT, padx=4)
        tk.Label(tube_bar, text='(Select a coil in Multi-Coil mode to view its axial profiles)',
                 font=('Helvetica',8,'italic'), bg='#EEF2FF', fg='#64748B').pack(side=tk.LEFT, padx=8)

        fig, self._axes = plt.subplots(4, 1, figsize=(7.5, 11), dpi=88)
        fig.patch.set_facecolor('#F8FAFC')
        fig.subplots_adjust(hspace=0.52, left=0.10, right=0.88, top=0.96, bottom=0.04)
        self._fig = fig
        self._plot_scroll = ScrollableFrame(plot_frame)
        self._plot_scroll.pack(fill=tk.BOTH, expand=True)
        self._canvas = FigureCanvasTkAgg(fig, master=self._plot_scroll.scrollable_frame)
        self._canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
        NavigationToolbar2Tk(self._canvas, plot_frame).update()
        self._plot_pending = False
        self._plot_data    = None
        self._all_coil_results = []   # stores list of per-coil result dicts (multi-coil mode)
        self._ax_twin = [None, None, None, None]
        self._ax_twin[1] = self._axes[1].twinx()
        self._ax_twin[2] = self._axes[2].twinx()
        self._ax_twin[3] = self._axes[3].twinx()

        # ─── ② PRODUCTS (OUTPUT) ──────────────────────────────────────────────────
    def _build_products_tab(self, nb):
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='② Products (SPYRO)'); tab = _scroll_tab.scrollable_frame

        bar = ttk.Frame(tab); bar.pack(fill='x', padx=8, pady=4)
        ttk.Label(bar, text='Basis:').pack(side=tk.LEFT)
        ttk.Radiobutton(bar, text='Dry', variable=self.v_basis, value='dry'
                        ).pack(side=tk.LEFT, padx=4)
        ttk.Radiobutton(bar, text='Wet', variable=self.v_basis, value='wet'
                        ).pack(side=tk.LEFT, padx=4)
        ttk.Button(bar, text='📋 Copy TSV', command=self._copy_products
                   ).pack(side=tk.RIGHT, padx=4)
        ttk.Button(bar, text='💾 Export CSV', command=self._export_products
                   ).pack(side=tk.RIGHT, padx=4)

        ttk.Label(tab, text=('g/100g Feed: g product per 100 g HC feed (excl. steam).    '
                              'g/100g Conv: selectivity per 100 g of converted feed.'),
                  foreground='navy', font=('Helvetica', 8)
                  ).pack(anchor=tk.W, padx=10, pady=(0, 4))

        cols = ('Species','MW','mol/s','g/100g Feed','g/100g Conv','mol% dry','wt% dry')
        self.prod_tree = ttk.Treeview(tab, columns=cols, show='headings', height=30)
        for c, w, a in [('Species',95,tk.W), ('MW',60,tk.E), ('mol/s',90,tk.E),
                         ('g/100g Feed',100,tk.E), ('g/100g Conv',100,tk.E),
                         ('mol% dry',90,tk.E), ('wt% dry',90,tk.E)]:
            self.prod_tree.heading(c, text=c)
            self.prod_tree.column(c, width=w, anchor=a)
        vsb = ttk.Scrollbar(tab, orient=tk.VERTICAL, command=self.prod_tree.yview)
        self.prod_tree.configure(yscroll=vsb.set)
        vsb.pack(side=tk.RIGHT, fill=tk.Y, padx=(0, 8), pady=4)
        self.prod_tree.pack(side=tk.LEFT, fill='both', expand=True, padx=(8, 0), pady=4)

    # ─── ③ BALANCE (OUTPUT) ───────────────────────────────────────────────────
    def _build_balance_tab(self, nb):
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='③ Atom & Mass Balance'); tab = _scroll_tab.scrollable_frame

        ttk.Label(tab, text=('Atom balance checks conservation of C, H, O across the PFR.  '
                              'Closure ≥99.9% with rtol=1e-4.  '
                              'Use rtol=1e-6, atol=1e-8 in ⑤ Solver for ≥99.99%.'),
                  foreground='navy', font=('Helvetica', 8), wraplength=900
                  ).pack(anchor=tk.W, padx=10, pady=(8, 6))

        cols = ('Quantity','Feed (in)','Effluent (out)','Closure %')
        self.bal_tree = ttk.Treeview(tab, columns=cols, show='headings', height=5)
        for c, w, a in [('Quantity',240,tk.W), ('Feed (in)',180,tk.E),
                         ('Effluent (out)',180,tk.E), ('Closure %',160,tk.E)]:
            self.bal_tree.heading(c, text=c)
            self.bal_tree.column(c, width=w, anchor=a)
        self.bal_tree.pack(fill='x', padx=10, pady=4)

        self.bal_health = ttk.Label(tab, text='', font=('Helvetica', 10, 'bold'))
        self.bal_health.pack(anchor=tk.W, padx=14, pady=8)

    # ─── ④ REACTION NETWORK (OUTPUT) ──────────────────────────────────────────
    def _build_reactions_tab(self, nb):
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='④ Reaction Network'); tab = _scroll_tab.scrollable_frame

        bar = ttk.Frame(tab); bar.pack(fill='x', padx=8, pady=4)
        self.rxn_header = ttk.Label(bar, text='',
                                      font=('Helvetica', 10, 'bold'), foreground='#38BDF8')
        self.rxn_header.pack(side=tk.LEFT)
        ttk.Button(bar, text='📋 Copy', command=self._copy_reactions
                   ).pack(side=tk.RIGHT, padx=4)

        ttk.Label(tab, text=('All reactions used in the simulation with effective A-factors '
                              '(after metallurgy, DMDS, and tuning multipliers applied).  '
                              'A-factors are in SI units [m³/(mol·s)]^(order-1)/s.'),
                  foreground='navy', font=('Helvetica', 8), wraplength=1100
                  ).pack(anchor=tk.W, padx=10, pady=(0, 4))

        cols = ('#', 'Type', 'Reaction', 'A (eff)', 'Ea (kJ/mol)', 'Order')
        self.rxn_tree = ttk.Treeview(tab, columns=cols, show='headings', height=28)
        for c, w, a in [('#',40,tk.E), ('Type',130,tk.W), ('Reaction',420,tk.W),
                         ('A (eff)',110,tk.E), ('Ea (kJ/mol)',100,tk.E), ('Order',60,tk.E)]:
            self.rxn_tree.heading(c, text=c)
            self.rxn_tree.column(c, width=w, anchor=a)
        # Tag colours by reaction class
        for tag, bg in [
            ('Paraffin_Crack',   '#e8f4fd'),
            ('Iso_Crack',        '#d6eaf8'),
            ('Ring_Opening',     '#d5e8d4'),
            ('Olefin_Crack',     '#fef9e7'),
            ('Dehydrogenation',  '#eafaf1'),
            ('Hydrogenation',    '#d5f5e3'),
            ('Condensation',     '#fdf2f8'),
            ('PAH_Growth',       '#f4ecf7'),
            ('Hydrodealkylation','#fdebd0'),
            ('Coking',           '#fdf5e6'),
            ('Steam',            '#f5f5f5'),
        ]:
            self.rxn_tree.tag_configure(tag, background=bg)

        vsb = ttk.Scrollbar(tab, orient=tk.VERTICAL, command=self.rxn_tree.yview)
        self.rxn_tree.configure(yscroll=vsb.set)
        vsb.pack(side=tk.RIGHT, fill=tk.Y, padx=(0, 8), pady=4)
        self.rxn_tree.pack(side=tk.LEFT, fill='both', expand=True, padx=(8, 0), pady=4)

    # ─── ⑤ VALIDATION (OUTPUT) ────────────────────────────────────────────────
    def _build_validation_tab(self, nb):
        """
        ⑤ Validation — comprehensive parameter check against 5+ literature datasets per feed.

        Layout:
          Top bar  : feed selector combobox + dataset combobox + Run button
          Row 2    : KPI panel (COT, dP, τ, Re, h_i, TMT, heat duty)
          Row 3    : Yield comparison treeview (ref vs model, Δ pp, Δ %, traffic-light)
          Bottom   : RMSE summary + pass/fail tally + param-limit check table
        """
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='⑤ Validation'); tab = _scroll_tab.scrollable_frame

        # ── Top control bar ───────────────────────────────────────────────────
        cbar = ttk.Frame(tab); cbar.pack(fill='x', padx=8, pady=(6, 2))

        ttk.Label(cbar, text='Feed:', font=('Helvetica', 9, 'bold')).pack(side=tk.LEFT)
        self._val_feed_var = tk.StringVar(value='ethane')
        feed_cb = ttk.Combobox(cbar, textvariable=self._val_feed_var, state='readonly',
                                width=10,
                                values=['ethane','propane','lpg','naphtha','kerosene','nbutane','isobutane','gasoil'])
        feed_cb.pack(side=tk.LEFT, padx=6)

        ttk.Label(cbar, text='Dataset:').pack(side=tk.LEFT)
        self._val_ds_var = tk.StringVar()
        self._val_ds_cb  = ttk.Combobox(cbar, textvariable=self._val_ds_var,
                                         state='readonly', width=20)
        self._val_ds_cb.pack(side=tk.LEFT, padx=6)

        ttk.Button(cbar, text='▶ Run Validation',
                   command=self._run_validation).pack(side=tk.LEFT, padx=4)
        ttk.Button(cbar, text='▶▶ Run All Datasets',
                   command=self._run_all_validations).pack(side=tk.LEFT, padx=2)
        ttk.Button(cbar, text='📋 Copy',
                   command=lambda: self._copy_tree(
                       self.val_tree,
                       ('Item','Ref','Model','Δ','Δ %','Status'))
                   ).pack(side=tk.RIGHT, padx=4)

        # Source label
        self._val_src_var = tk.StringVar(value='Select a feed and dataset above, then press ▶ Run Validation')
        ttk.Label(tab, textvariable=self._val_src_var,
                  foreground='#2c5f8a', font=('Courier', 8),
                  wraplength=780, justify='left').pack(anchor=tk.W, padx=10, pady=(0, 2))

        # ── KPI summary panel ─────────────────────────────────────────────────
        kf = ttk.LabelFrame(tab, text='Operating KPIs  (model vs reference + industrial range check)',
                            padding=6)
        kf.pack(fill='x', padx=8, pady=(2, 4))
        self._val_kpi_vars = {}
        kpi_defs = [
            ('COT',    'COT_C',      '°C'),  ('Firebox', 'Firebox_C',   '°C'),
            ('dP',     'dP_atm',     'atm'), ('τ',       'tau_ms',      'ms'),
            ('Re_out', 'Re_out',     '—'),   ('h_i',     'hi_out',      'W/(m²K)'),
            ('TMT',    'tmt_max_C',  '°C'),  ('Duty',    'heat_duty_kW','kW'),
        ]
        for col, (label, key, unit) in enumerate(kpi_defs):
            cf = ttk.Frame(kf); cf.grid(row=0, column=col, padx=6, pady=2)
            ttk.Label(cf, text=f'{label} [{unit}]',
                      font=('Helvetica', 7, 'bold'), foreground='navy').pack()
            sv = tk.StringVar(value='—')
            lbl = ttk.Label(cf, textvariable=sv, font=('Courier', 9),
                            foreground='#333', width=10, anchor='center')
            lbl.pack()
            rv = tk.StringVar(value='')
            ttk.Label(cf, textvariable=rv, font=('Helvetica', 7),
                      foreground='#555').pack()
            self._val_kpi_vars[key] = (sv, rv, lbl)

        # ── Main paned: yield table (left) + param-limit table (right) ────────
        pw = ttk.PanedWindow(tab, orient=tk.HORIZONTAL)
        pw.pack(fill='both', expand=True, padx=8, pady=4)

        # ── LEFT: yield comparison treeview ──────────────────────────────────
        yf = ttk.Frame(pw); pw.add(yf, weight=3)
        ttk.Label(yf, text='Yield Comparison  (wt % dry basis)',
                  font=('Helvetica', 9, 'bold'), foreground='#154360').pack(anchor='w')

        ycols = ('Item', 'Ref wt%', 'Model wt%', 'Δ pp', 'Δ %', 'Status')
        self.val_tree = ttk.Treeview(yf, columns=ycols, show='headings', height=16)
        for c, w, a in [('Item',100,tk.W),('Ref wt%',85,tk.E),('Model wt%',95,tk.E),
                        ('Δ pp',70,tk.E),('Δ %',70,tk.E),('Status',70,tk.CENTER)]:
            self.val_tree.heading(c, text=c)
            self.val_tree.column(c, width=w, anchor=a)
        for tag, clr in [('pass','darkgreen'),('warn','darkorange'),('fail','red'),
                         ('kpi','#1a5276'),('sep','#888'),('info','#555')]:
            self.val_tree.tag_configure(tag, foreground=clr)
        vsb1 = ttk.Scrollbar(yf, orient=tk.VERTICAL, command=self.val_tree.yview)
        self.val_tree.configure(yscroll=vsb1.set)
        vsb1.pack(side=tk.RIGHT, fill=tk.Y)
        self.val_tree.pack(fill='both', expand=True)

        # ── RIGHT: parameter limit check table ───────────────────────────────
        pf = ttk.Frame(pw); pw.add(pf, weight=2)
        ttk.Label(pf, text='Parameter Range Checks  (industrial limits)',
                  font=('Helvetica', 9, 'bold'), foreground='#154360').pack(anchor='w')

        pcols = ('Parameter', 'Value', 'Range', 'Ref', 'Pass?')
        self._param_tree = ttk.Treeview(pf, columns=pcols, show='headings', height=16)
        for c, w, a in [('Parameter',105,tk.W),('Value',70,tk.E),('Range',90,tk.CENTER),
                        ('Ref',130,tk.W),('Pass?',50,tk.CENTER)]:
            self._param_tree.heading(c, text=c)
            self._param_tree.column(c, width=w, anchor=a)
        for tag, clr in [('pass','darkgreen'),('fail','red'),('warn','darkorange')]:
            self._param_tree.tag_configure(tag, foreground=clr)
        vsb2 = ttk.Scrollbar(pf, orient=tk.VERTICAL, command=self._param_tree.yview)
        self._param_tree.configure(yscroll=vsb2.set)
        vsb2.pack(side=tk.RIGHT, fill=tk.Y)
        self._param_tree.pack(fill='both', expand=True)

        # ── Bottom summary bar ────────────────────────────────────────────────
        bf = ttk.Frame(tab); bf.pack(fill='x', padx=10, pady=(2, 6))
        self._val_rmse_var = tk.StringVar(value='')
        ttk.Label(bf, textvariable=self._val_rmse_var,
                  font=('Helvetica', 10, 'bold')).pack(side=tk.LEFT)
        self._val_pass_var = tk.StringVar(value='')
        ttk.Label(bf, textvariable=self._val_pass_var,
                  font=('Helvetica', 9), foreground='navy').pack(side=tk.LEFT, padx=20)
        self._val_multi_var = tk.StringVar(value='')
        ttk.Label(bf, textvariable=self._val_multi_var,
                  font=('Helvetica', 8), foreground='#555').pack(side=tk.RIGHT)

        # Wire feed combobox → dataset list update
        def _upd_ds(*_):
            feed = self._val_feed_var.get()
            ds_names = list(VALIDATION.get(feed, {}).keys())
            self._val_ds_cb['values'] = ds_names
            if ds_names:
                self._val_ds_var.set(ds_names[0])
        feed_cb.bind('<<ComboboxSelected>>', _upd_ds)
        _upd_ds()

    # ─── Validation runner ────────────────────────────────────────────────────
    def _run_validation(self):
        """Run one dataset and populate the validation tab."""
        feed  = self._val_feed_var.get()
        ds_id = self._val_ds_var.get()
        ds    = VALIDATION.get(feed, {}).get(ds_id)
        if ds is None:
            self._val_src_var.set('Dataset not found.')
            return

        self._val_src_var.set(
            f"  {ds_id} | {ds.get('source','')}  |  "
            f"Furnace: {ds.get('furnace','—')} ({ds.get('vendor','—')})")

        # Build simulation for this dataset
        try:
            result = self._run_validation_sim(feed, ds)
        except Exception as e:
            self._val_src_var.set(f'Simulation error: {e}')
            return

        kpis   = result['kpis']
        table  = result['table']
        bal    = result['bal']
        ref    = ds.get('ref', {})
        tol_pp = ds.get('tol_pp', 5.0)

        # ── KPI panel update ─────────────────────────────────────────────────
        ref_kpis = ds.get('kpis', {})
        for key, (sv, rv, lbl) in self._val_kpi_vars.items():
            val = kpis.get(key)
            if val is None:
                sv.set('—'); rv.set(''); lbl.config(foreground='#333'); continue
            sv.set(f'{val:.1f}' if abs(val) < 10000 else f'{val:.0f}')
            lo, hi = PARAM_LIMITS.get(key, {}).get('lo', -1e9), PARAM_LIMITS.get(key, {}).get('hi', 1e9)
            # Also check feed-specific tighter range
            feed_rng = FEED_KPI_RANGES.get(feed, {}).get(key)
            if feed_rng: lo, hi = feed_rng
            in_range = lo <= val <= hi
            ref_val  = ref_kpis.get(key)
            if ref_val is not None:
                delta = val - ref_val
                rv.set(f'ref={ref_val:.0f}  Δ={delta:+.1f}')
                ok = abs(delta) < 0.08 * abs(ref_val) + 5
                lbl.config(foreground='darkgreen' if ok else 'darkorange')
            else:
                rv.set(f'range [{lo:.0f}–{hi:.0f}]')
                lbl.config(foreground='darkgreen' if in_range else 'red')

        # ── Yield comparison treeview ────────────────────────────────────────
        for row in self.val_tree.get_children():
            self.val_tree.delete(row)

        # Build wt% dry dict from table
        model = {r['Species']: r['wt_pct_dry'] for r in table if not r['is_steam']}

        errors_sq = []; n_pass = 0; n_total = 0

        # Header separator
        self.val_tree.insert('', 'end', values=('── YIELD COMPARISON ──','','','','',''),
                             tags=('sep',))
        key_species = ['H2','CH4','C2H2','C2H4','C2H6','C3H4','C3H6',
                       'C4H6','C4H8','C4H10','C5H10','C6H6','C7H8','C8H10','COKE']
        for sp in key_species:
            ref_v = ref.get(sp)
            mod_v = model.get(sp, 0.)
            if ref_v is None and mod_v < 0.05:
                continue
            if ref_v is not None:
                delta  = mod_v - ref_v
                delta_pct = delta / max(ref_v, 0.1) * 100.
                errors_sq.append(delta ** 2)
                n_total += 1
                ok = abs(delta) <= tol_pp
                if ok: n_pass += 1
                tag  = 'pass' if ok else ('warn' if abs(delta) < 2*tol_pp else 'fail')
                self.val_tree.insert('', 'end',
                    values=(sp, f'{ref_v:.2f}', f'{mod_v:.2f}',
                            f'{delta:+.2f}', f'{delta_pct:+.1f}%',
                            '✓' if ok else '✗'),
                    tags=(tag,))
            else:
                self.val_tree.insert('', 'end',
                    values=(sp, '—', f'{mod_v:.2f}', '—', '—', 'info'),
                    tags=('info',))

        # KPI rows in yield tree
        self.val_tree.insert('', 'end', values=('── KPI CHECK ──','','','','',''),
                             tags=('sep',))
        kpi_show = [
            ('COT [°C]',       'COT_C',       ref_kpis.get('COT_C'),     10.),
            ('dP [atm]',       'dP_atm',      ref_kpis.get('dP_atm'),    0.15),
            ('τ [ms]',         'tau_ms',      ref_kpis.get('tau_ms'),    60.),
            ('Re [-]',         'Re_out',      ref_kpis.get('Re_out'),    80000.),
            ('P/E ratio',      'pe_ratio',    None,                       0.),
            ('H₂/CH₄ mol',    'h2ch4',       None,                       0.),
            ('C-balance [%]',  'C_balance',   100.,                       3.),
            ('H-balance [%]',  'H_balance',   100.,                       3.),
        ]
        for label, key, ref_v, tol in kpi_show:
            mod_v = kpis.get(key) or bal.get(key)
            if mod_v is None: continue
            if ref_v is not None and tol > 0:
                delta = mod_v - ref_v
                ok = abs(delta) <= tol
                tag = 'pass' if ok else ('warn' if abs(delta) < 2*tol else 'fail')
                if ok: n_pass += 1
                n_total += 1
                self.val_tree.insert('', 'end',
                    values=(label, f'{ref_v:.1f}', f'{mod_v:.1f}',
                            f'{delta:+.1f}', f'{delta/max(abs(ref_v),0.1)*100:+.1f}%',
                            '✓' if ok else '✗'),
                    tags=(tag,))
            else:
                self.val_tree.insert('', 'end',
                    values=(label, '—', f'{mod_v:.2f}', '—', '—', 'info'),
                    tags=('info',))

        # Atom balance rows
        for balkey, label in [('C_balance','C-balance [%]'),('H_balance','H-balance [%]')]:
            bv = bal.get(balkey, 100.)
            ok = 97. <= bv <= 103.
            self.val_tree.insert('', 'end',
                values=(label,'100.0',f'{bv:.2f}',f'{bv-100:+.2f}','—','✓' if ok else '✗'),
                tags=('pass' if ok else 'fail',))

        # ── Parameter range check table ──────────────────────────────────────
        for row in self._param_tree.get_children():
            self._param_tree.delete(row)
        for pkey, info in PARAM_LIMITS.items():
            val = kpis.get(pkey) or bal.get(pkey)
            if val is None: continue
            lo_g, hi_g = info['lo'], info['hi']
            # Feed-specific override
            fk = FEED_KPI_RANGES.get(feed, {}).get(pkey)
            lo, hi = (fk if fk else (lo_g, hi_g))
            in_rng  = lo <= val <= hi
            tag     = 'pass' if in_rng else 'fail'
            rng_str = f'{lo:.0f}–{hi:.0f}'
            self._param_tree.insert('', 'end',
                values=(pkey, f'{val:.2f}', rng_str, info['ref'][:25], '✓' if in_rng else '✗'),
                tags=(tag,))

        # ── Summary bar ──────────────────────────────────────────────────────
        rmse = (sum(errors_sq)/max(len(errors_sq),1))**0.5
        self._val_rmse_var.set(f'RMSE = {rmse:.2f} pp')
        color = 'darkgreen' if n_pass >= n_total*0.85 else ('darkorange' if n_pass >= n_total*0.70 else 'red')
        self._val_pass_var.set(f'{n_pass}/{n_total} checks passed')

    def _run_all_validations(self):
        """Iterate through every dataset for the current feed and report aggregate RMSE."""
        feed = self._val_feed_var.get()
        datasets = VALIDATION.get(feed, {})
        if not datasets:
            return
        all_rmse = []; all_pass = 0; all_total = 0
        for ds_id, ds in datasets.items():
            self._val_ds_var.set(ds_id)
            try:
                result = self._run_validation_sim(feed, ds)
            except Exception:
                continue
            kpis  = result['kpis']
            table = result['table']
            ref   = ds.get('ref', {})
            tol   = ds.get('tol_pp', 5.0)
            model = {r['Species']: r['wt_pct_dry'] for r in table if not r['is_steam']}
            errs  = [(model.get(sp, 0.) - v)**2 for sp, v in ref.items()]
            pss   = sum(1 for sp, v in ref.items() if abs(model.get(sp, 0.) - v) <= tol)
            all_rmse.append((sum(errs)/max(len(errs),1))**0.5)
            all_pass  += pss
            all_total += len(ref)
        avg_rmse = sum(all_rmse) / max(len(all_rmse), 1)
        self._val_multi_var.set(
            f'All {len(all_rmse)} datasets: avg RMSE={avg_rmse:.2f} pp  |  '
            f'{all_pass}/{all_total} yield checks passed')
        # Show first dataset in detail
        first_ds = list(datasets.keys())[0]
        self._val_ds_var.set(first_ds)
        self._run_validation()

    def _run_validation_sim(self, feed, ds):
        """
        Build and run a simulation for a validation dataset.
        Handles gas, naphtha (PIONA+D86), and kerosene feeds.
        Returns the same dict as _run_simulation().
        """
        ft = feed.capitalize()
        if feed == 'lpg': ft = 'LPG'

        tuner = KineticsTuner(p=self.v_tp.get(), o=self.v_to.get(),
                              a=self.v_ta.get(), coke=self.v_tc.get(),
                              metallurgy=self.v_metal.get(), dmds=self.v_dmds.get())
        if feed == 'ethane':    rxns = build_ethane_reactions(tuner)
        elif feed == 'propane': rxns = build_propane_reactions(tuner)
        elif feed == 'lpg':     rxns = build_lpg_reactions(tuner)
        elif feed == 'kerosene':rxns = build_kerosene_reactions(tuner)
        else:                   rxns = build_naphtha_reactions(tuner)

        gp = self.GEOM_PRESETS.get(ft, self.GEOM_PRESETS['Naphtha'])
        geom = dict(
            coils=gp['coils'], passes=gp['passes'],
            length_per_pass=gp['lpp'], tube_id=gp['tube_id'], tube_od=gp['tube_od'],
            emissivity=self.v_emiss.get(), roughness=self.v_rough.get(),
            k_tube=self.v_k_tube.get(), h_o_flue=self.v_h_o.get(),
            heat_flux_profile=self.v_hfp.get(),
            profile_amplitude_K=self.v_hamp.get(),
            k_heat=self.v_k_heat.get(), k_dp=self.v_k_dp.get(),
        )
        opts = dict(method='BDF', rtol=1e-4, atol=1e-6)
        eng  = CrackerEngine(rxns, geom, opts)

        cond = ds['cond']
        T_IN = cond['t_in_C']  + 273.15
        P_IN = cond['p_in_atm'] * 101325.

        # Build feed flows
        if feed in ('ethane', 'propane', 'lpg'):
            feed_comp = ds.get('feed', {})
            # normalise
            tot = sum(feed_comp.values()); feed_comp = {k:v/tot*100 for k,v in feed_comp.items()}
            # map field names to species
            sp_map = {'C2H6':'C2H6','CH4':'CH4','C3H8':'C3H8','C2H4':'C2H4',
                      'C3H6':'C3H6','iC4H10':'iC4H10','C4H10':'C4H10','iC4H8':'iC4H8',
                      'C3H4':'C3H4','C4H6':'C4H6'}
            comp = {sp_map.get(k,k): v for k,v in feed_comp.items() if k in sp_map}
            init_flows = build_gas_feed(comp, 20000., cond['steam_ratio'], eng)
            fc = (['C2H6'] if feed == 'ethane'
                  else ['C3H8'] if feed == 'propane'
                  else [s for s in ('C3H8','C4H10','iC4H10')
                        if s in eng.sp_idx and init_flows.get(s,0.)>1e-8])
        else:
            piona_raw = ds.get('feed_piona', {})
            d86_raw   = ds.get('feed_d86', {})
            # Map PIONA keys
            piona = {k.strip():v for k,v in piona_raw.items()}
            dist  = {}
            key_map = {'IBP':'IBP','T5':'T5','T10':'T10','T30':'T30','T50':'T50',
                       'T70':'T70','T90':'T90','T95':'T95','FBP':'FBP'}
            for k,v in d86_raw.items():
                dist[key_map.get(k,k)] = v
            if feed == 'kerosene':
                # PIONA keys: P,I,N,A,O
                ker_piona = {'P': piona.get('P',38.),'I': piona.get('I',22.),
                             'N': piona.get('N',18.),'A': piona.get('A',19.),
                             'O': piona.get('O',3.)}
                init_flows = build_kerosene_feed(dist, ker_piona, 22000.,
                                                 cond['steam_ratio'], eng)
            else:
                naph_piona = {'P': piona.get('P',35.)+piona.get('I',0.),
                              'N': piona.get('N',30.),
                              'A': piona.get('A',14.),
                              'O': piona.get('O',1.)}
                init_flows = build_naphtha_feed(dist, naph_piona, 22000.,
                                                cond['steam_ratio'], eng)
            fc = [sp for sp in init_flows if sp != 'H2O']

        sol, Tfb, err = find_cot(cond['conversion'], eng, init_flows, T_IN, P_IN, fc)
        if err or sol is None:
            raise RuntimeError(err or 'COT solver failed')

        cfg  = {'geom': geom, 'p_in': cond['p_in_atm']}
        kpis, table, bal = spyro_metrics(sol, eng, init_flows, fc, cfg)
        kpis['Firebox_C'] = Tfb
        kpis['severity_mode'] = severity_mode
        kpis['severity_setpoint'] = self.v_target_conv.get()
        try:
            kpis['severity_actual'] = _gui_severity_metric(severity_mode, sol, eng, feed, fc, cfg, Tfb)
        except Exception:
            kpis['severity_actual'] = float('nan')

        # Atom balance fields
        bal['C_balance'] = bal.get('C_cls', 100.)
        bal['H_balance'] = bal.get('H_cls', 100.)

        return dict(ft=ft, sol=sol, eng=eng, geom=geom, rxns=rxns,
                    kpis=kpis, table=table, bal=bal)

    # ─── ⑥ ONLINE PLANT TUNER TAB ────────────────────────────────────────────
    def _build_tuner_tab(self, nb):
        """
        Advancement 3 — Multi-Dataset Kinetic Optimizer.
        User can enter up to 10 real plant / literature data sets.
        Each dataset has its own operating conditions (feed rate, steam, T_in,
        P_in, conversion) and measured yields (wt% dry).
        
        The optimizer (scipy.minimize) searches kp / ko / ka / kc to minimise
        the combined weighted RMSE across ALL active datasets simultaneously:
        
            J = Σ_ds  w_ds × RMSE(model_yields_ds, meas_yields_ds)
                + w_KPI × Σ_ds Σ_kpi  w_kpi × |model_kpi - meas_kpi|
        
        Progress is streamed in real-time to the Solver Log tab.
        On completion the tuned factors are written back to ④ Kinetic Tuning
        and a fresh simulation is triggered.
        """
        _scroll_tab = ScrollableFrame(nb); nb.add(_scroll_tab, text='⑥ Multi-Dataset Optimizer'); tab = _scroll_tab.scrollable_frame
        self._tuner_running  = False
        self._tuner_stop_flag = False
        self._tuner_obj_history = []
        self._tuner_iter = [0]

        MAX_DS = 10
        YIELD_SP = ['H2','CH4','C2H2','C2H4','C2H6','C3H4',
                    'C3H6','C4H6','C4H8','C6H6','C7H8','C8H10']

        # ── Header ───────────────────────────────────────────────────────────
        hdr = ttk.Frame(tab); hdr.pack(fill='x', padx=10, pady=(8,4))
        ttk.Label(hdr, text='🔬  MULTI-DATASET KINETIC OPTIMIZER',
                  font=('Helvetica',12,'bold'), foreground='#1a5276').pack(side=tk.LEFT)
        ttk.Label(hdr, text='  Enter up to 10 plant / literature datasets → simultaneous kp/ko/ka/kc fit',
                  font=('Helvetica',9), foreground='#555').pack(side=tk.LEFT, padx=8)

        # ── Main paned layout: datasets on left, settings+log on right ───────
        pw = ttk.PanedWindow(tab, orient=tk.HORIZONTAL)
        pw.pack(fill='both', expand=True, padx=6, pady=4)

        # ─── LEFT: scrollable dataset notebook ───────────────────────────────
        ds_outer = ttk.Frame(pw); pw.add(ds_outer, weight=3)
        ttk.Label(ds_outer, text='Plant / Literature Datasets  (leave yields blank = not used)',
                  font=('Helvetica',9,'bold'), foreground='#154360').pack(anchor='w', padx=4)

        # Toolbar above dataset tabs
        ds_bar = ttk.Frame(ds_outer); ds_bar.pack(fill='x', padx=4, pady=(2,4))
        ttk.Button(ds_bar, text='+ Add Dataset',
                   command=lambda: self._ds_add()).pack(side=tk.LEFT, padx=2)
        ttk.Button(ds_bar, text='− Remove Last',
                   command=lambda: self._ds_remove()).pack(side=tk.LEFT, padx=2)
        ttk.Button(ds_bar, text='📂 Load Lit Ref',
                   command=self._ds_load_lit).pack(side=tk.LEFT, padx=6)
        ttk.Button(ds_bar, text='📋 Copy All TSV',
                   command=self._ds_copy_tsv).pack(side=tk.RIGHT, padx=2)

        self._ds_nb = ttk.Notebook(ds_outer)
        self._ds_nb.pack(fill='both', expand=True)

        # Internal dataset storage: list of dicts per dataset
        self._datasets = []   # list of {vars, widgets}
        for i in range(1):    # start with 1 dataset
            self._ds_add(init=True)

        # ─── RIGHT: optimizer settings + convergence + result ─────────────────
        right_col = ttk.Frame(pw); pw.add(right_col, weight=2)

        # Optimizer parameters
        # ── Optimize Mode selector ────────────────────────────────────────────
        fom = ttk.LabelFrame(right_col, text='Optimize Mode', padding=8)
        fom.pack(fill='x', pady=(4,2))
        self.tv_optim_mode = tk.StringVar(value='Overall')
        mode_info = tk.Frame(fom); mode_info.pack(fill='x')
        ttk.Radiobutton(mode_info, text='Overall  (single kp/ko/ka tuned across all datasets simultaneously)',
                        variable=self.tv_optim_mode, value='Overall'
                        ).pack(anchor='w', padx=4, pady=1)
        ttk.Radiobutton(mode_info, text='MultiCoil  (optimize pass-by-pass: each pass gets independent kp/ko — useful for non-uniform severity profiles)',
                        variable=self.tv_optim_mode, value='Multipass'
                        ).pack(anchor='w', padx=4, pady=1)
        self._optim_mode_note = ttk.Label(fom,
            text='Overall: minimises RMSE across all datasets with a single global set of kinetic factors. '
                 'MultiCoil (Multipass): divides the tube into N passes and tunes kp/ko independently per pass, '
                 'producing a pass-resolved kinetic correction vector for non-uniform severity profiles.',
            font=('Helvetica',7,'italic'), foreground='#64748B', wraplength=340, justify='left')
        self._optim_mode_note.pack(anchor='w', padx=6, pady=(2,4))

        fos = ttk.LabelFrame(right_col, text='Optimizer Settings', padding=8)
        fos.pack(fill='x', pady=4)
        self.tv_kp_lo = tk.DoubleVar(value=0.3);  self.tv_kp_hi = tk.DoubleVar(value=5.0)
        self.tv_ko_lo = tk.DoubleVar(value=0.1);  self.tv_ko_hi = tk.DoubleVar(value=3.0)
        self.tv_ka_lo = tk.DoubleVar(value=0.01); self.tv_ka_hi = tk.DoubleVar(value=2.0)
        self.tv_kc_lo = tk.DoubleVar(value=0.1);  self.tv_kc_hi = tk.DoubleVar(value=5.0)
        self.tv_tune_kc  = tk.BooleanVar(value=False)
        self.tv_maxiter  = tk.IntVar(value=120)
        self.tv_method   = tk.StringVar(value='Nelder-Mead')
        self.tv_w_yield  = tk.DoubleVar(value=1.0)
        self.tv_w_kpi    = tk.DoubleVar(value=0.2)
        bnd_rows = [
            ('kp bounds [0.3–5]:', self.tv_kp_lo, self.tv_kp_hi),
            ('ko bounds [0.1–3]:', self.tv_ko_lo, self.tv_ko_hi),
            ('ka bounds [0.01–2]:', self.tv_ka_lo, self.tv_ka_hi),
            ('kc bounds [0.1–5]:', self.tv_kc_lo, self.tv_kc_hi),
        ]
        for i,(lbl,lo,hi) in enumerate(bnd_rows):
            ttk.Label(fos,text=lbl,font=('Helvetica',8)).grid(row=i,column=0,sticky='w',padx=4,pady=1)
            ttk.Entry(fos,textvariable=lo,width=5).grid(row=i,column=1,padx=2)
            ttk.Label(fos,text='–').grid(row=i,column=2)
            ttk.Entry(fos,textvariable=hi,width=5).grid(row=i,column=3,padx=2)
        ttk.Checkbutton(fos,text='Also tune kc (coking)',variable=self.tv_tune_kc
                        ).grid(row=4,column=0,columnspan=2,sticky='w',padx=4,pady=2)
        ttk.Label(fos,text='Method:',font=('Helvetica',8)).grid(row=5,column=0,sticky='w',padx=4)
        ttk.Combobox(fos,textvariable=self.tv_method,width=12,state='readonly',
                     values=['Nelder-Mead','L-BFGS-B','SLSQP']
                     ).grid(row=5,column=1,columnspan=3,pady=2,padx=2,sticky='w')
        ttk.Label(fos,text='Max iters:',font=('Helvetica',8)).grid(row=6,column=0,sticky='w',padx=4)
        ttk.Entry(fos,textvariable=self.tv_maxiter,width=6).grid(row=6,column=1,padx=2)
        ttk.Label(fos,text='w_yield:',font=('Helvetica',8)).grid(row=7,column=0,sticky='w',padx=4)
        ttk.Entry(fos,textvariable=self.tv_w_yield,width=6).grid(row=7,column=1,padx=2)
        ttk.Label(fos,text='  w_KPI:',font=('Helvetica',8)).grid(row=7,column=2,sticky='w')
        ttk.Entry(fos,textvariable=self.tv_w_kpi,width=6).grid(row=7,column=3,padx=2)

        # Control buttons
        btn_f = ttk.Frame(right_col); btn_f.pack(fill='x', pady=4)
        self._btn_tune = ttk.Button(btn_f, text='▶  Run Optimizer',
                                    command=self._launch_tuner)
        self._btn_tune.pack(side=tk.LEFT, padx=4)
        ttk.Button(btn_f,text='⏹ Stop',command=self._stop_tuner).pack(side=tk.LEFT,padx=4)
        ttk.Button(btn_f,text='↺ Reset kp/ko/ka/kc',
                   command=self._reset_tune).pack(side=tk.LEFT,padx=4)

        # Convergence plot
        ttk.Label(right_col,text='Objective convergence',
                  font=('Helvetica',9,'bold')).pack(anchor='w',pady=(6,0))
        self._tuner_fig, self._tuner_ax = plt.subplots(figsize=(4.5,2.2),dpi=90)
        self._tuner_fig.patch.set_facecolor('#f8f8f8')
        self._tuner_ax.set_facecolor('#ffffff')
        self._tuner_ax.set_xlabel('Function evaluation',fontsize=8)
        self._tuner_ax.set_ylabel('Combined J',fontsize=8)
        self._tuner_scroll = ScrollableFrame(right_col)
        self._tuner_scroll.pack(fill='both', expand=True, pady=2)
        self._tuner_canvas = FigureCanvasTkAgg(self._tuner_fig, self._tuner_scroll.scrollable_frame)
        self._tuner_canvas.get_tk_widget().pack(fill='both', expand=True)

        # Per-dataset fit summary
        ttk.Label(right_col,text='Per-dataset RMSE after last run:',
                  font=('Helvetica',9,'bold')).pack(anchor='w',pady=(4,0))
        self._tuner_result_lbl = ttk.Label(right_col, text='—',
                                            font=('Helvetica',9), foreground='navy',
                                            wraplength=460, justify='left')
        self._tuner_result_lbl.pack(anchor='w', padx=8, pady=4)

    # ─── DATASET MANAGEMENT ───────────────────────────────────────────────────
    def _ds_add(self, init=False):
        MAX_DS = 10
        if len(self._datasets) >= MAX_DS:
            messagebox.showinfo('Limit', f'Maximum {MAX_DS} datasets.')
            return
        idx = len(self._datasets)
        ds = {}

        # Per-dataset variables
        ft = self.v_feed_type.get()
        d = self.DEFAULTS.get(ft, {})
        ds['active']      = tk.BooleanVar(value=True)
        ds['weight']      = tk.DoubleVar(value=1.0)
        ds['feed_rate']   = tk.DoubleVar(value=d.get('feed_rate', 20000.))
        ds['steam_ratio'] = tk.DoubleVar(value=d.get('steam_ratio', 0.35))
        ds['t_in']        = tk.DoubleVar(value=d.get('t_in', 650.))
        ds['p_in']        = tk.DoubleVar(value=d.get('p_in', 3.0))
        ds['conv']        = tk.DoubleVar(value=d.get('target_conv', 0.67))
        # KPI targets (optional)
        ds['meas_cot']    = tk.StringVar(value='')
        ds['meas_dp']     = tk.StringVar(value='')
        ds['meas_tau']    = tk.StringVar(value='')
        # Yield measurements
        YIELD_SP = ['H2','CH4','C2H2','C2H4','C2H6','C3H4',
                    'C3H6','C4H6','C4H8','C6H6','C7H8','C8H10']
        ds['yields'] = {sp: tk.StringVar(value='') for sp in YIELD_SP}

        # Build tab
        _scroll_tab_frame = ScrollableFrame(self._ds_nb)
        tab_frame = _scroll_tab_frame.scrollable_frame
        self._ds_nb.add(_scroll_tab_frame, text=f'DS {idx+1}')

        # Active + weight header
        top = ttk.Frame(tab_frame); top.pack(fill='x', padx=6, pady=(6,2))
        ttk.Checkbutton(top,text='Active',variable=ds['active']).pack(side=tk.LEFT)
        ttk.Label(top,text='  Dataset weight:',font=('Helvetica',8)).pack(side=tk.LEFT,padx=(12,2))
        ttk.Entry(top,textvariable=ds['weight'],width=6).pack(side=tk.LEFT)
        ttk.Label(top,text='  (relative importance vs other datasets)',
                  font=('Helvetica',7,'italic'),foreground='#888').pack(side=tk.LEFT,padx=4)

        # Two-column body
        body = ttk.Frame(tab_frame); body.pack(fill='both', expand=True, padx=4)
        lcol = ttk.Frame(body); lcol.pack(side=tk.LEFT, fill='y', padx=(0,6))
        rcol = ttk.Frame(body); rcol.pack(side=tk.LEFT, fill='both', expand=True)

        # Conditions
        fc = ttk.LabelFrame(lcol,text='Operating Conditions',padding=6)
        fc.pack(fill='x', pady=4)
        cond_rows = [
            ('HC Feed (kg/hr):',  ds['feed_rate'],   'feed_rate'),
            ('Steam/HC ratio:',   ds['steam_ratio'],  'steam_ratio'),
            ('T_in (°C):',        ds['t_in'],         't_in'),
            ('P_in (atm):',       ds['p_in'],         'p_in'),
            ('Conversion (0–1):', ds['conv'],         'target_conv'),
        ]
        for r,(lbl,var,_) in enumerate(cond_rows):
            ttk.Label(fc,text=lbl,font=('Helvetica',8)).grid(row=r,column=0,sticky='w',padx=4,pady=1)
            ttk.Entry(fc,textvariable=var,width=10).grid(row=r,column=1,padx=4,pady=1)

        # KPI targets
        fk = ttk.LabelFrame(lcol,text='KPI Targets (optional)',padding=6)
        fk.pack(fill='x', pady=4)
        for r,(lbl,var) in enumerate([
            ('Measured COT (°C):', ds['meas_cot']),
            ('Measured ΔP (atm):', ds['meas_dp']),
            ('Measured τ (ms):',   ds['meas_tau']),
        ]):
            ttk.Label(fk,text=lbl,font=('Helvetica',8)).grid(row=r,column=0,sticky='w',padx=4,pady=1)
            ttk.Entry(fk,textvariable=var,width=10).grid(row=r,column=1,padx=4,pady=1)

        # Yield measurements (2-column grid in right panel)
        fy = ttk.LabelFrame(rcol,text='Measured Yields  (wt% dry — leave blank to skip)',padding=6)
        fy.pack(fill='both', expand=True, pady=4)
        for i,sp in enumerate(YIELD_SP):
            r,c = divmod(i,2)
            ttk.Label(fy,text=f'{sp}:',font=('Helvetica',8),width=6,anchor='e'
                      ).grid(row=r,column=c*2,sticky='e',padx=(8,2),pady=1)
            ttk.Entry(fy,textvariable=ds['yields'][sp],width=9
                      ).grid(row=r,column=c*2+1,padx=2,pady=1)

        # Result label per dataset
        ds['result_lbl'] = ttk.Label(tab_frame, text='', font=('Helvetica',8),
                                      foreground='navy')
        ds['result_lbl'].pack(anchor='w', padx=8, pady=2)

        self._datasets.append(ds)

    def _ds_remove(self):
        if len(self._datasets) <= 1:
            messagebox.showinfo('Cannot remove', 'At least one dataset must remain.')
            return
        self._datasets.pop()
        tabs = self._ds_nb.tabs()
        if tabs:
            self._ds_nb.forget(tabs[-1])

    def _ds_load_lit(self):
        """Load literature reference data into the currently selected dataset tab."""
        sel = self._ds_nb.index('current')
        if sel < 0 or sel >= len(self._datasets): return
        ds = self._datasets[sel]
        ft = self.v_feed_type.get().lower()
        val = VALIDATION.get(ft, {})
        ref = val.get('ref', {})
        c   = val.get('cond', {})
        for sp, sv in ds['yields'].items():
            sv.set(f'{ref[sp]:.2f}' if sp in ref else '')
        if 'feed_rate'   in c: ds['feed_rate'].set(c['feed_rate'])
        if 'steam_ratio' in c: ds['steam_ratio'].set(c['steam_ratio'])
        if 't_in_C'      in c: ds['t_in'].set(c['t_in_C'])
        if 'p_in_atm'    in c: ds['p_in'].set(c['p_in_atm'])
        if 'conversion'  in c: ds['conv'].set(c['conversion'])
        self._solver_log_write(f'[DS {sel+1}] Loaded {ft} literature reference.','INFO')

    def _ds_copy_tsv(self):
        """Copy all dataset conditions + yields as TSV to clipboard."""
        YIELD_SP = ['H2','CH4','C2H2','C2H4','C2H6','C3H4',
                    'C3H6','C4H6','C4H8','C6H6','C7H8','C8H10']
        header = 'DS\tActive\tWeight\tFeed\tSteam\tTin\tPin\tConv\t' + '\t'.join(YIELD_SP)
        rows = [header]
        for i,ds in enumerate(self._datasets):
            yv = '\t'.join(ds['yields'][sp].get() for sp in YIELD_SP)
            rows.append(f'{i+1}\t{ds["active"].get()}\t{ds["weight"].get():.2f}\t'
                        f'{ds["feed_rate"].get()}\t{ds["steam_ratio"].get()}\t'
                        f'{ds["t_in"].get()}\t{ds["p_in"].get()}\t{ds["conv"].get()}\t{yv}')
        text = '\n'.join(rows)
        self.root.clipboard_clear(); self.root.clipboard_append(text)
        messagebox.showinfo('Copied', f'{len(self._datasets)} datasets copied.')

    # ─── TUNER: helpers ───────────────────────────────────────────────────────
    def _tuner_log_write(self, msg):
        self._solver_log_write(msg, 'DATA')

    def _tuner_log_clear(self):
        self._solver_log_clear()

    def _reset_tune(self):
        self.v_tp.set(1.3); self.v_to.set(0.8)
        self.v_ta.set(0.05); self.v_tc.set(1.0)
        self._solver_log_write('[INFO] Kinetic factors reset to calibrated defaults (kp=1.3 ko=0.8 ka=0.05 kc=1.0).','INFO')

    def _stop_tuner(self):
        self._tuner_stop_flag = True
        self._solver_log_write('[INFO] Stop requested — halting after current evaluation.','WARN')

    # ─── TUNER: launch ────────────────────────────────────────────────────────
    def _launch_tuner(self):
        if self._tuner_running:
            self._solver_log_write('[WARN] Optimizer already running.','WARN'); return

        # Collect active datasets
        active_ds = []
        for i, ds in enumerate(self._datasets):
            if not ds['active'].get(): continue
            yields = {}
            for sp, sv in ds['yields'].items():
                try:
                    v = float(sv.get())
                    if v > 0: yields[sp] = v
                except Exception: pass
            def _flt(sv, default=None):
                try: return float(sv.get()) if sv.get().strip() else default
                except: return default
            active_ds.append({
                'idx':        i+1,
                'weight':     ds['weight'].get(),
                'feed_rate':  ds['feed_rate'].get(),
                'steam':      ds['steam_ratio'].get(),
                't_in':       ds['t_in'].get(),
                'p_in':       ds['p_in'].get(),
                'conv':       ds['conv'].get(),
                'meas_cot':   _flt(ds['meas_cot']),
                'meas_dp':    _flt(ds['meas_dp']),
                'meas_tau':   _flt(ds['meas_tau']),
                'yields':     yields,
                'result_lbl': ds['result_lbl'],
            })

        if not active_ds:
            messagebox.showwarning('No active datasets', 'Enable at least one dataset.'); return
        has_data = any(bool(d['yields']) or d['meas_cot'] or d['meas_dp'] for d in active_ds)
        if not has_data:
            messagebox.showwarning('No data', 'Enter at least one measured yield or KPI.'); return

        self._tuner_stop_flag  = False
        self._tuner_obj_history = []
        self._tuner_iter[0]    = 0
        self._solver_log_clear()
        self._tuner_ax.cla(); self._tuner_canvas.draw_idle()
        self._solver_log_write(f'[START] Multi-dataset optimizer  │  {len(active_ds)} active datasets','HEAD')
        self._solver_log_write(f'        Feed: {self.v_feed_type.get()}  │  Method: {self.tv_method.get()}  │  maxiter: {self.tv_maxiter.get()}','INFO')
        self._solver_log_write(f'        kp∈[{self.tv_kp_lo.get()},{self.tv_kp_hi.get()}]  '
                               f'ko∈[{self.tv_ko_lo.get()},{self.tv_ko_hi.get()}]  '
                               f'ka∈[{self.tv_ka_lo.get()},{self.tv_ka_hi.get()}]','INFO')
        for d in active_ds:
            self._solver_log_write(
                f'        DS{d["idx"]:2d}  w={d["weight"]:.2f}  '
                f'feed={d["feed_rate"]:.0f}kg/hr  steam={d["steam"]:.2f}  '
                f'T_in={d["t_in"]:.0f}°C  P={d["p_in"]:.2f}atm  conv={d["conv"]:.2f}  '
                f'yields={list(d["yields"].keys())}','DATA')

        optim_mode = self.tv_optim_mode.get()
        self._solver_log_write(f'        Optimize Mode: {optim_mode}', 'INFO')
        self._tuner_running = True
        self._btn_tune.configure(state='disabled')
        worker_fn = self._tuner_worker_multipass if optim_mode == 'Multipass' else self._tuner_worker
        threading.Thread(target=worker_fn,
                         kwargs=dict(active_ds=active_ds,
                                     tune_kc=self.tv_tune_kc.get(),
                                     method=self.tv_method.get(),
                                     maxiter=self.tv_maxiter.get(),
                                     w_yield=self.tv_w_yield.get(),
                                     w_kpi=self.tv_w_kpi.get()),
                         daemon=True).start()

    # ─── TUNER: per-dataset objective ─────────────────────────────────────────
    def _eval_dataset(self, ds, kp, ko, ka, kc):
        """Run one simulation for a dataset dict, return (kpis, model_yields) or None."""
        ft = self.v_feed_type.get()
        tuner = KineticsTuner(p=kp, o=ko, a=ka, coke=kc,
                              metallurgy=self.v_metal.get(), dmds=self.v_dmds.get())
        if ft == 'Ethane':      rxns = build_ethane_reactions(tuner)
        elif ft == 'Propane':   rxns = build_propane_reactions(tuner)
        elif ft == 'LPG':       rxns = build_lpg_reactions(tuner)
        elif ft == 'Kerosene':  rxns = build_kerosene_reactions(tuner)
        else:                   rxns = build_naphtha_reactions(tuner)

        gp = self.GEOM_PRESETS[ft]
        geom = dict(
            coils=gp['coils'], passes=gp['passes'],
            length_per_pass=gp['lpp'], tube_id=gp['tube_id'], tube_od=gp['tube_od'],
            emissivity=self.v_emiss.get(), roughness=self.v_rough.get(),
            k_tube=self.v_k_tube.get(), h_o_flue=self.v_h_o.get(),
            heat_flux_profile=self.v_hfp.get(), profile_amplitude_K=self.v_hamp.get(),
            k_heat=self.v_k_heat.get(), k_dp=self.v_k_dp.get(),
        )
        opts = dict(method='BDF', rtol=1e-4, atol=1e-6)
        eng = CrackerEngine(rxns, geom, opts)

        T_IN = ds['t_in'] + 273.15
        P_IN = ds['p_in'] * 101325.

        # ── Feed flow builder — dispatches by feed type ─────────────────────
        def _get_dist():
            return {'IBP':self.v_d_ibp.get(), 'T5':self.v_d_t5.get(),
                    'T10':self.v_d_t10.get(), 'T30':self.v_d_t30.get(),
                    'T50':self.v_d_t50.get(), 'T70':self.v_d_t70.get(),
                    'T90':self.v_d_t90.get(), 'T95':self.v_d_t95.get(),
                    'FBP':self.v_d_fbp.get()}
        def _get_piona(lpg_combined=False):
            p = self.v_p_p.get(); i = self.v_p_i.get()
            return {'P': p+i if lpg_combined else p,
                    'I': 0. if lpg_combined else i,
                    'N': self.v_p_n.get(), 'A': self.v_p_a.get(), 'O': self.v_p_o.get()}
        def _get_gas_comp():
            return {'C2H6':   self.v_g_c2h6.get(), 'CH4':   self.v_g_ch4.get(),
                    'C3H8':   self.v_g_c3h8.get(), 'C2H4':  self.v_g_c2h4.get(),
                    'C3H6':   self.v_g_c3h6.get(), 'iC4H10':self.v_g_ic4.get(),
                    'C4H10':  self.v_g_nc4.get(),  'iC4H8': self.v_g_ic4h8.get()}

        if ft == 'Gas Oil':
            feed = build_gasoil_feed(_get_dist(), _get_piona(), ds['feed_rate'], ds['steam'], eng)
            fc   = [sp for sp in feed if sp != 'H2O']
        elif ft == 'Kerosene':
            feed = build_kerosene_feed(_get_dist(), _get_piona(), ds['feed_rate'], ds['steam'], eng)
            fc   = [sp for sp in feed if sp != 'H2O']
        elif ft in ('Naphtha', 'Lt Naphtha', 'Full Naphtha'):
            feed = build_naphtha_feed(_get_dist(), _get_piona(lpg_combined=True),
                                      ds['feed_rate'], ds['steam'], eng)
            fc   = [sp for sp in feed if sp != 'H2O']
        elif ft == 'Wax':
            feed = build_wax_feed(_get_dist(), _get_piona(), ds['feed_rate'], ds['steam'], eng)
            fc   = [sp for sp in feed if sp != 'H2O']
        elif ft in ('LPG', 'C2/C3 Co-crack', 'Off-Gas', 'Shale NGL'):
            comp = _get_gas_comp()
            feed = build_lpg_feed(comp, ds['feed_rate'], ds['steam'], eng)
            if ft == 'LPG':
                fc = [s for s in ('C3H8','C4H10','iC4H10') if s in eng.sp_idx and feed.get(s,0.)>1e-8]
            elif ft == 'C2/C3 Co-crack':
                fc = [s for s in ('C2H6','C3H8') if s in eng.sp_idx and feed.get(s,0.)>1e-8]
            elif ft == 'Shale NGL':
                fc = [s for s in ('C2H6','C3H8','C4H10','nC5') if s in eng.sp_idx and feed.get(s,0.)>1e-8]
            else:
                fc = [s for s in ('CH4','C2H6','C3H8') if s in eng.sp_idx and feed.get(s,0.)>1e-8]
        elif ft in ('n-Butane', 'iso-Butane'):
            comp = _get_gas_comp()
            feed = build_gas_feed(comp, ds['feed_rate'], ds['steam'], eng)
            fc   = ['C4H10'] if ft == 'n-Butane' else ['iC4H10']
        elif ft == 'Bio-Ethanol':
            # Bio-ethanol: treat as gas feed with C2H5OH as primary component
            mw_eth = 46.068
            F_eth  = ds['feed_rate'] * 1000. / (3600. * mw_eth)
            F_h2o  = ds['steam'] * ds['feed_rate'] * 1000. / (3600. * 18.015)
            feed   = {'C2H5OH': F_eth, 'H2O': F_h2o}
            feed   = {sp: v for sp, v in feed.items() if sp in eng.sp_idx}
            fc     = ['C2H5OH']
        else:
            comp = _get_gas_comp()
            feed = build_gas_feed(comp, ds['feed_rate'], ds['steam'], eng)
            fc   = ['C2H6'] if ft == 'Ethane' else ['C3H8']

        sol, Tfb, err = find_cot(ds['conv'], eng, feed, T_IN, P_IN, fc)
        if err or sol is None: return None, None

        kpis, table, _ = spyro_metrics(sol, eng, feed, fc,
                                        {'geom': geom, 'p_in': ds['p_in']})
        kpis['Firebox_C'] = Tfb
        model = {d['Species']: d['wt_pct_dry'] for d in table}
        return kpis, model

    # ─── TUNER: combined objective across all datasets ─────────────────────────
    def _multi_objective(self, params, active_ds, tune_kc, w_yield, w_kpi):
        if self._tuner_stop_flag: raise StopIteration()
        kp = float(np.clip(params[0], 0.1, 10.))
        ko = float(np.clip(params[1], 0.05, 5.))
        ka = float(np.clip(params[2], 0.005, 3.))
        kc = float(np.clip(params[3], 0.1, 10.)) if tune_kc else 1.0

        J_total = 0.0
        w_sum   = sum(d['weight'] for d in active_ds)
        for ds in active_ds:
            try:
                kpis, model = self._eval_dataset(ds, kp, ko, ka, kc)
            except Exception:
                kpis, model = None, None
            if kpis is None or model is None:
                J_total += ds['weight'] * 1e4; continue

            J_ds = 0.0
            # Yield RMSE
            if ds['yields']:
                n = len(ds['yields'])
                sse = sum((model.get(sp,0.) - ref)**2
                          for sp, ref in ds['yields'].items())
                J_ds += w_yield * np.sqrt(sse / max(n, 1))
            # KPI terms
            if ds['meas_cot'] is not None:
                J_ds += w_kpi * abs(kpis['COT_C'] - ds['meas_cot'])
            if ds['meas_dp'] is not None:
                J_ds += w_kpi * abs(kpis['dP_atm'] - ds['meas_dp']) * 10.
            if ds['meas_tau'] is not None:
                J_ds += w_kpi * abs(kpis['tau_ms'] - ds['meas_tau']) / 50.

            J_total += ds['weight'] * J_ds

        return float(J_total / max(w_sum, 1e-9))

    # ─── TUNER: background worker ─────────────────────────────────────────────
    def _tuner_worker(self, active_ds, tune_kc, method, maxiter, w_yield, w_kpi):
        from scipy.optimize import minimize
        x0 = [self.v_tp.get(), self.v_to.get(), self.v_ta.get()]
        bounds = [(self.tv_kp_lo.get(), self.tv_kp_hi.get()),
                  (self.tv_ko_lo.get(), self.tv_ko_hi.get()),
                  (self.tv_ka_lo.get(), self.tv_ka_hi.get())]
        if tune_kc:
            x0.append(self.v_tc.get())
            bounds.append((self.tv_kc_lo.get(), self.tv_kc_hi.get()))

        call_count = [0]

        def wrapped(params):
            if self._tuner_stop_flag: return 1e8
            try:
                J = self._multi_objective(params, active_ds, tune_kc, w_yield, w_kpi)
            except StopIteration:
                return 1e8
            except Exception as e:
                self.root.after(0, self._solver_log_write, f'[EVAL ERR] {e}', 'ERROR')
                J = 1e6
            call_count[0] += 1
            self._tuner_obj_history.append(J)
            if call_count[0] % 5 == 0 or call_count[0] <= 2:
                kp,ko,ka = float(params[0]),float(params[1]),float(params[2])
                kc = float(params[3]) if tune_kc else 1.0
                msg = (f'  iter={call_count[0]:4d}  J={J:9.4f}  '
                       f'kp={kp:.4f}  ko={ko:.4f}  ka={ka:.5f}  kc={kc:.4f}')
                self.root.after(0, self._solver_log_write, msg, 'DATA')
                self.root.after(0, self._update_tuner_plot)
            return J

        try:
            opts_kw = ({'maxiter':maxiter,'xatol':5e-4,'fatol':0.02}
                       if method=='Nelder-Mead' else {'maxiter':maxiter})
            result = minimize(wrapped, x0, method=method,
                              bounds=bounds if method!='Nelder-Mead' else None,
                              options=opts_kw)
            self.root.after(0, self._tuner_done, result, active_ds, tune_kc)
        except Exception as e:
            self.root.after(0, self._solver_log_write, f'[OPTIMIZER ERROR] {e}', 'ERROR')
            self.root.after(0, self._tuner_done, None, active_ds, tune_kc)

    def _update_tuner_plot(self):
        hist = self._tuner_obj_history
        if len(hist) < 2: return
        ax = self._tuner_ax; ax.cla()
        ax.plot(range(1,len(hist)+1), hist, 'b-', lw=1.2)
        ax.set_xlabel('Evaluation',fontsize=8)
        ax.set_ylabel('J',fontsize=8)
        ax.set_title(f'Best J={min(hist):.4f}  (iter {len(hist)})',fontsize=8)
        ax.grid(ls='--',alpha=0.4)
        self._tuner_fig.tight_layout()
        self._tuner_canvas.draw_idle()

    def _tuner_done(self, result, active_ds, tune_kc):
        self._tuner_running = False
        self._btn_tune.configure(state='normal')
        self._update_tuner_plot()
        if result is None or self._tuner_stop_flag:
            self._solver_log_write('\n[STOPPED or FAILED]','WARN'); return

        kp = float(result.x[0])
        ko = float(result.x[1])
        ka = float(result.x[2])
        kc = float(result.x[3]) if tune_kc else self.v_tc.get()
        J  = float(result.fun)
        self._solver_log_write(
            f'\n[DONE]  J={J:.4f}  ({result.message})', 'OK')
        self._solver_log_write(
            f'        kp={kp:.4f}  ko={ko:.4f}  ka={ka:.5f}  kc={kc:.4f}', 'OK')

        # Per-dataset breakdown
        summary_parts = []
        for ds in active_ds:
            try:
                kpis, model = self._eval_dataset(ds, kp, ko, ka, kc)
            except Exception:
                kpis, model = None, None
            if kpis is None:
                lbl_txt = f'DS{ds["idx"]}: ❌ solver failed'
            else:
                if ds['yields']:
                    n = len(ds['yields'])
                    sse = sum((model.get(sp,0.)-ref)**2 for sp,ref in ds['yields'].items())
                    rmse = np.sqrt(sse/max(n,1))
                    lbl_txt = (f'DS{ds["idx"]}: RMSE={rmse:.2f}pp  '
                               f'COT={kpis["COT_C"]:.0f}°C  dP={kpis["dP_atm"]:.3f}atm')
                else:
                    lbl_txt = f'DS{ds["idx"]}: COT={kpis["COT_C"]:.0f}°C  dP={kpis["dP_atm"]:.3f}atm'
            self._solver_log_write(f'   {lbl_txt}', 'DATA')
            summary_parts.append(lbl_txt)
            self.root.after(0, ds['result_lbl'].config, {'text': lbl_txt})

        self._tuner_result_lbl.config(
            text=f'✅ kp={kp:.4f}  ko={ko:.4f}  ka={ka:.5f}  kc={kc:.4f}  │  J={J:.4f}\n' +
                 '\n'.join(f'   {s}' for s in summary_parts))

        # Write results back to kinetic tuning tab
        self.v_tp.set(round(kp,4)); self.v_to.set(round(ko,4))
        self.v_ta.set(round(ka,5)); self.v_tc.set(round(kc,4))
        # Trigger fresh simulation
        self._force_run()

    # ─── TUNER: Multipass optimizer worker ───────────────────────────────────
    def _tuner_worker_multipass(self, active_ds, tune_kc, method, maxiter, w_yield, w_kpi):
        """
        Multipass optimizer: runs the overall optimizer once per tube pass,
        using only the pass-relevant portion of the objective.  Each pass gets
        its own (kp, ko) while ka and kc stay global.  Results are reported
        pass-by-pass and the final values written to the tuning sliders are the
        average across passes (weighted by pass count).

        Implementation strategy
        ────────────────────────
        Because the PFR integrates the *full* tube length, true pass-resolved
        sensitivities would require a multi-segment integrator.  Instead we
        approximate by running N sequential single-pass optimizations where the
        initial conditions for pass i+1 are the outlet of the optimal pass i.
        This gives a consistent pass-resolved kinetic correction profile.
        """
        from scipy.optimize import minimize

        n_passes = int(self.v_passes.get()) if hasattr(self, 'v_passes') else 1
        if n_passes < 2:
            self.root.after(0, self._solver_log_write,
                '[INFO] Multipass mode: only 1 pass configured — falling back to Overall.',  'WARN')
            self._tuner_worker(active_ds=active_ds, tune_kc=tune_kc, method=method,
                               maxiter=maxiter, w_yield=w_yield, w_kpi=w_kpi)
            return

        self.root.after(0, self._solver_log_write,
            f'[MULTIPASS] {n_passes} passes — optimizing pass-by-pass (kp,ko per pass; ka,kc global)', 'HEAD')

        # Global ka/kc are optimized once (overall) before pass-by-pass kp/ko
        x0_global = [self.v_tp.get(), self.v_to.get(), self.v_ta.get()]
        bounds_global = [(self.tv_kp_lo.get(), self.tv_kp_hi.get()),
                         (self.tv_ko_lo.get(), self.tv_ko_hi.get()),
                         (self.tv_ka_lo.get(), self.tv_ka_hi.get())]
        if tune_kc:
            x0_global.append(self.v_tc.get())
            bounds_global.append((self.tv_kc_lo.get(), self.tv_kc_hi.get()))

        kp_list = []
        ko_list = []
        call_count = [0]

        def _obj_global(params):
            if self._tuner_stop_flag: return 1e8
            try:
                J = self._multi_objective(params, active_ds, tune_kc, w_yield, w_kpi)
            except Exception:
                J = 1e6
            call_count[0] += 1
            self._tuner_obj_history.append(J)
            if call_count[0] % 5 == 0:
                self.root.after(0, self._update_tuner_plot)
            return J

        # Phase 1: overall fit to find global ka/kc baseline
        self.root.after(0, self._solver_log_write, '  Phase 1: Global baseline (ka/kc)', 'INFO')
        opts_kw = ({'maxiter': max(20, maxiter//4)} if method == 'Nelder-Mead'
                   else {'maxiter': max(20, maxiter//4)})
        try:
            res_global = minimize(_obj_global, x0_global, method=method,
                                  bounds=bounds_global if method != 'Nelder-Mead' else None,
                                  options=opts_kw)
            kp_base = float(res_global.x[0])
            ko_base = float(res_global.x[1])
            ka_best = float(res_global.x[2])
            kc_best = float(res_global.x[3]) if tune_kc else self.v_tc.get()
        except Exception as e:
            self.root.after(0, self._solver_log_write, f'  Phase 1 failed: {e}', 'ERROR')
            kp_base, ko_base, ka_best, kc_best = (self.v_tp.get(), self.v_to.get(),
                                                   self.v_ta.get(), self.v_tc.get())

        self.root.after(0, self._solver_log_write,
            f'  Baseline: kp={kp_base:.4f}  ko={ko_base:.4f}  ka={ka_best:.5f}  kc={kc_best:.4f}', 'DATA')

        # Phase 2: per-pass kp/ko scan
        self.root.after(0, self._solver_log_write, f'  Phase 2: Per-pass kp/ko ({n_passes} passes)', 'INFO')

        # For the per-pass optimization we shift the target conversion proportionally
        for pass_idx in range(n_passes):
            if self._tuner_stop_flag: break
            frac_lo = pass_idx / n_passes
            frac_hi = (pass_idx + 1) / n_passes
            pass_label = f'Pass {pass_idx+1}/{n_passes}  (z fraction {frac_lo:.2f}–{frac_hi:.2f})'
            self.root.after(0, self._solver_log_write, f'  [{pass_label}]', 'INFO')

            # Build a synthetic dataset subset scaled to partial conversion
            pass_ds = []
            for ds in active_ds:
                total_conv = ds['conv']
                # Linear approximation: pass i contributes ~1/N of total conversion
                pass_conv = max(0.05, total_conv * frac_hi - total_conv * frac_lo)
                # Yield targets are scaled proportionally (rough but consistent)
                scaled_yields = {sp: v * (1 / n_passes) for sp, v in ds['yields'].items()}
                pass_ds.append({**ds, 'conv': total_conv * frac_hi, 'yields': scaled_yields})

            def _obj_pass(params, _ka=ka_best, _kc=kc_best):
                if self._tuner_stop_flag: return 1e8
                full_params = [params[0], params[1], _ka] + ([_kc] if tune_kc else [])
                try:
                    J = self._multi_objective(full_params, pass_ds, tune_kc, w_yield, w_kpi)
                except Exception:
                    J = 1e6
                self._tuner_obj_history.append(J)
                self.root.after(0, self._update_tuner_plot)
                return J

            x0_pass = [kp_base, ko_base]
            bounds_pass = [(self.tv_kp_lo.get(), self.tv_kp_hi.get()),
                           (self.tv_ko_lo.get(), self.tv_ko_hi.get())]
            try:
                res_pass = minimize(_obj_pass, x0_pass, method=method,
                                    bounds=bounds_pass if method != 'Nelder-Mead' else None,
                                    options={'maxiter': max(30, maxiter // n_passes)})
                kp_p = float(np.clip(res_pass.x[0], 0.1, 10.))
                ko_p = float(np.clip(res_pass.x[1], 0.05, 5.))
            except Exception as e:
                self.root.after(0, self._solver_log_write, f'    pass err: {e}', 'ERROR')
                kp_p, ko_p = kp_base, ko_base

            kp_list.append(kp_p); ko_list.append(ko_p)
            self.root.after(0, self._solver_log_write,
                f'    kp={kp_p:.4f}  ko={ko_p:.4f}  J={self._tuner_obj_history[-1]:.4f}', 'DATA')

        # Report & write back average
        if not kp_list:
            self.root.after(0, self._solver_log_write, '[MULTIPASS] No passes completed.', 'WARN')
            self.root.after(0, lambda: self._tuner_done_multipass(None, active_ds, tune_kc, ka_best, kc_best))
            return

        kp_final = float(np.mean(kp_list))
        ko_final = float(np.mean(ko_list))
        self.root.after(0, self._solver_log_write,
            f'[MULTIPASS DONE]  Average kp={kp_final:.4f}  ko={ko_final:.4f}  '
            f'ka={ka_best:.5f}  kc={kc_best:.4f}', 'OK')
        for i,(kp_p,ko_p) in enumerate(zip(kp_list,ko_list)):
            self.root.after(0, self._solver_log_write,
                f'  Pass {i+1}: kp={kp_p:.4f}  ko={ko_p:.4f}', 'DATA')
        self.root.after(0, self._tuner_done_multipass,
                        (kp_final, ko_final, ka_best, kc_best), active_ds, tune_kc, ka_best, kc_best)

    def _tuner_done_multipass(self, result_tuple, active_ds, tune_kc, ka_best, kc_best):
        """Finalize multipass optimizer: write back average kp/ko and trigger re-run."""
        self._tuner_running = False
        self._btn_tune.configure(state='normal')
        self._update_tuner_plot()
        if result_tuple is None or self._tuner_stop_flag:
            self._solver_log_write('[STOPPED or FAILED]', 'WARN'); return
        kp, ko, ka, kc = result_tuple
        self._tuner_result_lbl.config(
            text=f'✅ MULTIPASS  kp={kp:.4f}  ko={ko:.4f}  ka={ka:.5f}  kc={kc:.4f}')
        self.v_tp.set(round(kp, 4)); self.v_to.set(round(ko, 4))
        self.v_ta.set(round(ka, 5)); self.v_tc.set(round(kc, 4))
        self._force_run()

    # ─── Feed type change handler ─────────────────────────────────────────────
    def _severity_target_units(self, mode=None):
        mode = mode or self.v_severity_mode.get()
        if mode == 'cot': return '°C COT'
        if mode in ('pe_ratio','mp_ratio'): return 'mol/mol ratio'
        if mode.endswith('_conversion'): return 'fraction conversion (0–1); % also accepted'
        if mode in ('ethylene_yield','methane_yield'): return 'wt% on HC feed; fraction also accepted'
        if mode == 'yield_max': return 'optimizer mode; setpoint ignored'
        return ''

    def _severity_default_value(self, ft=None, mode=None):
        ft = ft or self.v_feed_type.get()
        mode = mode or self.v_severity_mode.get()
        return severity_default_for_feed(ft, mode)

    def _apply_severity_default(self, schedule=True):
        """Link selected solver target to setpoint by loading feed/mode default."""
        mode = self.v_severity_mode.get()
        ft = self.v_feed_type.get()
        val = self._severity_default_value(ft, mode)
        old = self._suppress
        self._suppress = True
        try:
            self.v_target_conv.set(val)
            if hasattr(self, '_severity_setpoint_hint'):
                label = SEVERITY_MODES.get(mode, mode)
                self._severity_setpoint_hint.set(
                    f'{label} setpoint = {val:g} {self._severity_target_units(mode)}  |  Feed: {ft}'
                )
        finally:
            self._suppress = old
        if schedule and not self._suppress:
            self._schedule_run()

    def _on_severity_mode_change(self):
        self._apply_severity_default(schedule=True)

    def _on_feed_type_change(self):
        ft = self.v_feed_type.get()
        self._suppress = True
        try:
            # Update inlet defaults
            d = self.DEFAULTS[ft]
            self.v_feed_rate.set(d['feed_rate'])
            self.v_steam_ratio.set(d['steam_ratio'])
            self.v_t_in.set(d['t_in'])
            self.v_p_in.set(d['p_in'])
            self.v_target_conv.set(self._severity_default_value(ft, self.v_severity_mode.get() if hasattr(self, 'v_severity_mode') else 'ethane_conversion'))

            is_gas     = ft in ('Ethane', 'Propane', 'n-Butane', 'iso-Butane',
                               'LPG', 'Off-Gas', 'C2/C3 Co-crack', 'Shale NGL',
                               'Bio-Ethanol')
            is_liquid  = ft in ('Naphtha', 'Lt Naphtha', 'Full Naphtha',
                                'Kerosene', 'Gas Oil', 'Wax')

            if is_gas:
                for k in ('g_c2h6','g_ch4','g_c3h8','g_c2h4',
                          'g_c3h6','g_ic4','g_nc4','g_ic4h8'):
                    getattr(self, f'v_{k}').set(d.get(k, 0.))

            # Apply per-feedstock geometry preset
            gp = self.GEOM_PRESETS.get(ft, self.GEOM_PRESETS['Naphtha'])
            self.v_coils.set(gp['coils'])
            self.v_passes.set(gp['passes'])
            self.v_lpp.set(gp['lpp'])
            self.v_tube_id.set(gp['tube_id'])
            self.v_tube_od.set(gp['tube_od'])

            # Load PIONA / D86 defaults for the liquid feeds
            if ft in ('Kerosene', 'Gas Oil'):
                for k, v in self.KEROSENE_PIONA.items():
                    getattr(self, f'v_{k}').set(v)
                for k, v in self.KEROSENE_D86.items():
                    getattr(self, f'v_{k}').set(v)
                if ft == 'Gas Oil':
                    # Gas oil: heavier PIONA — more paraffins, less aromatic
                    self.v_p_p.set(42.); self.v_p_i.set(25.)
                    self.v_p_n.set(15.); self.v_p_a.set(16.); self.v_p_o.set(2.)
                    self.v_d_ibp.set(240.); self.v_d_t10.set(280.)
                    self.v_d_t50.set(320.); self.v_d_t90.set(380.); self.v_d_fbp.set(420.)
            elif ft in ('Naphtha', 'Lt Naphtha', 'Full Naphtha', 'Wax'):
                for k, v in self.NAPHTHA_PIONA.items():
                    getattr(self, f'v_{k}').set(v)
                for k, v in self.NAPHTHA_D86.items():
                    getattr(self, f'v_{k}').set(v)
                if ft == 'Lt Naphtha':
                    self.v_d_t50.set(70.); self.v_d_t90.set(110.); self.v_d_fbp.set(130.)
                elif ft == 'Wax':
                    # Wax: C18-C24 heavy paraffin slate
                    self.v_p_p.set(85.); self.v_p_i.set(10.)
                    self.v_p_n.set(3.); self.v_p_a.set(2.); self.v_p_o.set(0.)
                    self.v_d_ibp.set(290.); self.v_d_t10.set(310.)
                    self.v_d_t50.set(340.); self.v_d_t90.set(380.); self.v_d_fbp.set(420.)

            # FINAL PATCH: rebuild selected-feed entry panel instead of common panel
            self._rebuild_selected_feed_entry_panel()
        finally:
            self._suppress = False
        self._apply_severity_default(schedule=False)
        # Reload kinetics editor for new feed type (after slight delay so GUI settles)
        if hasattr(self, '_ke_rxns_cache'):
            self.root.after(200, self._ke_reload)
        self._schedule_run()

    # ─── Live composition/PIONA sum feedback ──────────────────────────────────
    def _update_comp_sum(self):
        s = sum(v.get() for v in [self.v_g_c2h6, self.v_g_ch4, self.v_g_c3h8,
                                   self.v_g_c2h4, self.v_g_c3h6, self.v_g_ic4,
                                   self.v_g_nc4, self.v_g_ic4h8])
        if abs(s - 100) < 1:
            self.comp_sum_lbl.config(text=f'✓ Sum = {s:.1f}%', foreground='darkgreen')
        else:
            self.comp_sum_lbl.config(text=f'⚠  Sum = {s:.1f}% (should be ≈100%)',
                                       foreground='darkorange')

    def _update_piona_sum(self):
        s = sum(v.get() for v in [self.v_p_p, self.v_p_i, self.v_p_n, self.v_p_a, self.v_p_o])
        if abs(s - 100) < 1:
            self.piona_sum_lbl.config(text=f'✓ PIONA sum = {s:.1f}%', foreground='darkgreen')
        else:
            self.piona_sum_lbl.config(text=f'⚠  PIONA sum = {s:.1f}% (should be ≈100%)',
                                        foreground='darkorange')

    # ─── Reactive scheduler ───────────────────────────────────────────────────
    def _on_change(self, *_):
        if self._suppress: return
        if self.v_auto.get():
            self._schedule_run()

    def _schedule_run(self):
        if self._timer is not None:
            self.root.after_cancel(self._timer)
        self._timer = self.root.after(1000, self._launch_calc)

    def _force_run(self):
        if self._timer is not None:
            self.root.after_cancel(self._timer)
            self._timer = None
        self._launch_calc()

    def _launch_calc(self):
        if self._running:
            self._dirty = True
            return
        issues = self._validate_inputs()
        if issues:
            msg = 'Fix input issues before running:\n\n' + '\n'.join(f'- {i}' for i in issues[:12])
            self.v_status.set('Input validation failed.')
            self._solver_log_write('[VALIDATION] ' + ' | '.join(issues), 'ERROR')
            messagebox.showwarning('Input Validation', msg)
            return
        self._running = True
        self.v_status.set('⏳  Calculating …')
        threading.Thread(target=self._run_worker, daemon=True).start()

    def _reset_section(self, vars_list, keys_list):
        """Reset a group of variables to their recorded defaults."""
        self._suppress = True
        try:
            for v, k in zip(vars_list, keys_list):
                dv = self._param_defaults.get(k)
                if dv is not None:
                    v.set(dv)
        finally:
            self._suppress = False
        self._schedule_run()

    def _run_worker(self):
        # ── Snapshot parameters to JSON before every run ───────────────────────
        self._save_params_to_json()
        t0 = time.perf_counter()
        mc_mode = getattr(self, 'v_mc_enabled', None) and self.v_mc_enabled.get()
        ft = self.v_feed_type.get()
        mode_str = f'MULTI-COIL ({int(self.v_mc_n_coils.get())} groups)' if mc_mode else ft
        self.root.after(0, self._solver_log_write,
                        f'\n{"═"*55}', 'HEAD')
        self.root.after(0, self._solver_log_write,
                        f'  RUN  {mode_str}  │  {time.strftime("%H:%M:%S")}', 'HEAD')
        self.root.after(0, self._solver_log_write,
                        f'{"═"*55}', 'HEAD')
        try:
            if mc_mode and hasattr(self, '_mc_coil_vars') and self._mc_coil_vars:
                # ── Multi-coil mode ──────────────────────────────────────────
                coil_results, combined_cot, primary, combined_kpis = self._run_multi_coil_simulation()
                dt = time.perf_counter() - t0
                self.root.after(0, self._solver_log_write,
                    f'  [MC] {len(coil_results)} coil groups done in {dt:.2f}s  '
                    f'| Combined COT={combined_cot:.1f}°C', 'OK')
                for cr in coil_results:
                    if not cr.get('active'): continue
                    if cr.get('error'):
                        self.root.after(0, self._solver_log_write,
                            f'  [CG{cr["coil"]}] ❌ {cr["error"]}', 'ERROR')
                    else:
                        k = cr['kpis']
                        self.root.after(0, self._solver_log_write,
                            f'  [CG{cr["coil"]}] {cr["ft"]}  '
                            f'COT={k["COT_C"]:.1f}°C  Conv={k["actual_conv"]*100:.1f}%  '
                            f'ΔP={k["dP_atm"]:.3f}atm  τ={k["tau_ms"]:.0f}ms  '
                            f'n_coils={cr["n_coils"]}  '
                            f'feed={cr["feed_rate"]:.0f}kg/hr', 'DATA')
                self.root.after(0, self._update_multi_coil_results, coil_results, combined_cot)
                # Update KPIs / dashboard with COMBINED outlet conditions
                if combined_kpis:
                    self.root.after(0, self._update_kpis, combined_kpis)
                # Store all coil results and update tube selector
                self.root.after(0, self._update_profile_tube_selector, coil_results)
                # Update single-coil output panels with primary coil result
                if primary:
                    # Add needed fields for primary coil result dict
                    primary['tp'] = primary['eng'].transport_profiles(primary['sol'])
                    ck_z, ck_p = primary['eng'].coking_profile(primary['sol'])
                    primary['ck_z'] = ck_z; primary['ck_p'] = ck_p
                    primary['feed'] = {}; primary['fc'] = []
                    self._last_result = primary
                    self.root.after(0, self._update_all_outputs_mc, primary, combined_kpis, dt)
                else:
                    self.root.after(0, lambda: self.v_status.set(
                        '⚠ Multi-coil: no active coil produced valid results'))
            else:
                # ── Single-coil mode (original behaviour) ────────────────────
                result = self._run_simulation()
                dt = time.perf_counter() - t0
                k = result['kpis']
                self.root.after(0, self._solver_log_write,
                    f'  [OK] Converged in {dt:.2f}s  '
                    f'| COT={k["COT_C"]:.1f}°C  Conv={k["actual_conv"]*100:.2f}%  '
                    f'dP={k["dP_atm"]:.3f}atm  τ={k["tau_ms"]:.0f}ms', 'OK')
                self.root.after(0, self._solver_log_write,
                    f'       Re={k["Re_out"]:.0f}  Pr={k["Pr_out"]:.3f}  '
                    f'h_i={k["hi_out"]:.0f}W/m²K  TMT={k["tmt_max_C"]:.0f}°C', 'DATA')
                self.root.after(0, self._solver_log_write,
                    f'       C-bal={result["bal"]["C_cls"]:.4f}%  '
                    f'H-bal={result["bal"]["H_cls"]:.4f}%', 'DATA')
                self._last_result = result
                # Reset tube selector to single-coil view
                self.root.after(0, self._update_profile_tube_selector, None)
                self.root.after(0, self._update_all_outputs, result, dt)
        except Exception as e:
            import traceback
            msg = f'⚠  Error: {e}'
            tb = traceback.format_exc()
            _log_exception('Simulation run failed')
            crash_path = self._write_crash_report(tb)
            self.root.after(0, self._solver_log_write, f'  [ERROR] {e}', 'ERROR')
            if crash_path:
                self.root.after(0, self._solver_log_write, f'  [CRASH REPORT] {crash_path}', 'ERROR')
            if self.v_verbose_log.get():
                for line in tb.splitlines():
                    self.root.after(0, self._solver_log_write, f'    {line}', 'ERROR')
            self.root.after(0, lambda: self.v_status.set(msg))
        finally:
            self._running = False
            if self._dirty:
                self._dirty = False
                self.root.after(100, self._launch_calc)

    # ─── Build & run one simulation ───────────────────────────────────────────
    def _run_simulation(self, coil_num=None):
        """Run one PFR simulation. coil_num: if given, use per-coil kinetic scope."""
        ft = self.v_feed_type.get()

        # Use per-coil tuner when MultiCoil Kinetic Tuning scope is active
        if coil_num is not None and hasattr(self, '_kt_get_coil_tuner'):
            tuner = self._kt_get_coil_tuner(coil_num)
        else:
            tuner = KineticsTuner(
                p=self.v_tp.get(), o=self.v_to.get(), a=self.v_ta.get(),
                coke=self.v_tc.get(),
                metallurgy=self.v_metal.get(),
                dmds=self.v_dmds.get(),
            )
        # ── Select kinetic network ──────────────────────────────────────────────
        _use_radical = getattr(self, 'v_radical_kinetics', None) and self.v_radical_kinetics.get()
        # ── v38: apply calibrated tuner defaults per feed type ────────────────
        _td = get_tuned_defaults(ft)
        # Only auto-apply if the user hasn't explicitly overridden individual sliders
        # (detect by checking if ALL tuner sliders are at their startup defaults)
        _auto_tune = getattr(self, 'v_auto_tune_defaults', None)
        if _auto_tune and _auto_tune.get():
            tuner = KineticsTuner(
                p=_td['kp'], o=_td['ko'], a=_td['ka'], coke=_td.get('kc',1.0),
                metallurgy=self.v_metal.get(), dmds=self.v_dmds.get(),
            )
        # FINAL PATCH: unified kinetics + outlet species carriers
        rxns = build_reactions_for_gui_feed(ft, tuner, include_radicals=bool(_use_radical))

        # Apply any manual overrides from the ⑥ Kinetics Editor
        # Merge: Overall overrides first, then coil-specific overrides (if MultiCoil scope)
        mc_store = getattr(self, '_rxn_overrides_mc', {'Overall': {}})
        overrides = dict(mc_store.get('Overall', {}))
        if coil_num is not None:
            cg_key = f'CG{coil_num}'
            coil_ov = mc_store.get(cg_key, {})
            overrides.update(coil_ov)   # coil-specific takes precedence
        for i, ov in overrides.items():
            if i < len(rxns):
                if 'A'  in ov: rxns[i]['A']  = ov['A']
                if 'Ea' in ov:
                    _ea = float(ov['Ea'])
                    if _ea > 2500.0: _ea = _ea / 1000.0  # backward compatibility with old J/mol overrides
                    rxns[i]['Ea'] = _ea   # kJ/mol, CrackerEngine converts to J/mol

        # Log override count
        if overrides:
            scope_tag = f'CG{coil_num}' if coil_num else 'Overall'
            self._solver_log_write(
                f'  [EDITOR] {len(overrides)} kinetic override(s) active [{scope_tag}]', 'WARN')

        geom = dict(
            coils=self.v_coils.get(), passes=self.v_passes.get(),
            length_per_pass=self.v_lpp.get(), tube_id=self.v_tube_id.get(),
            tube_od=self.v_tube_od.get(), emissivity=self.v_emiss.get(),
            roughness=self.v_rough.get(), k_tube=self.v_k_tube.get(),
            h_o_flue=self.v_h_o.get(), heat_flux_profile=self.v_hfp.get(),
            profile_amplitude_K=self.v_hamp.get(),
            k_heat=self.v_k_heat.get(), k_dp=self.v_k_dp.get(),
            # ── UPGRADE v22: advanced physics parameters ─────────────────────
            k_coke         = self.v_k_coke.get(),
            bend_kfactor   = self.v_bend_kf.get(),
            quench_length  = self.v_quench_length.get(),
            quench_conductance = self.v_quench_ua.get(),
            # Per-pass tube IDs (CSV string → list of floats)
            tube_id_per_pass = [float(x.strip())
                                for x in self.v_pass_ids.get().split(',')
                                if x.strip()] or None,
            # Zone flux table (pipe-separated: "z0,z1,q|z0,z1,q|...")
            heat_flux_zones = [
                tuple(float(v) for v in seg.split(','))
                for seg in self.v_flux_zones.get().split('|')
                if seg.strip() and len(seg.split(',')) == 3
            ] or None,
        )
        opts = dict(method=self.v_solver.get(),
                    rtol=self.v_rtol.get(), atol=self.v_atol.get())
        eng = CrackerEngine(rxns, geom, opts)
        # v40: preserve the effective GUI tuner for the plant-responsive ROM path.
        # Reaction A-factors already contain tuning, but the ROM bypasses rate equations;
        # this object lets fast mode respond to kp/ko/ka/kc exactly like the GUI sliders.
        eng._gui_tuner_effective = tuner

        # FINAL PATCH: feed construction from selected feed entry panel
        dist = self._selected_dist_dict(ft)
        piona = self._selected_piona_dict(ft)
        if ft in ('Naphtha','Lt Naphtha','Full Naphtha','Wax'):
            piona=dict(piona); piona['P']=piona.get('P',0.0)+piona.get('I',0.0); piona['I']=0.0
        comp = self._selected_feed_comp_dict(ft)
        feed = build_feed_for_gui_feed(ft, comp, dist, piona, self.v_feed_rate.get(), self.v_steam_ratio.get(), eng)
        fc = feed_components_for_gui_feed(ft, feed, eng)

        T_IN = self.v_t_in.get() + 273.15
        P_IN = self.v_p_in.get() * 101325.

        severity_mode = self.v_severity_mode.get() if hasattr(self, 'v_severity_mode') else 'ethane_conversion'
        cfg_pre = {'geom': geom, 'p_in': self.v_p_in.get()}
        _severity_solver = globals().get('solve_gui_severity')
        if _severity_solver is None:
            raise RuntimeError('Internal severity solver was not loaded; use the v49 Rev-49 file.')
        sol, Tfb, err = _severity_solver(
            severity_mode, self.v_target_conv.get(), eng, feed, T_IN, P_IN, fc, cfg_pre,
            bracket_lo=getattr(self, 'v_cot_bracket_lo', None) and self.v_cot_bracket_lo.get() or 700.0,
            bracket_hi=getattr(self, 'v_cot_bracket_hi', None) and self.v_cot_bracket_hi.get() or 1450.0,
        )
        if err or sol is None:
            raise RuntimeError(err or 'COT solver failed — check inputs.')

        # ── UPGRADE v22: coke campaign evolution ─────────────────────────────
        run_hrs = getattr(self, 'v_run_hours', None)
        if run_hrs and run_hrs.get() > 0.0:
            z_ck, thick_ck, Di_eff, tmt_pen = eng.evolve_coke_layer(sol, run_hrs.get())
            # Re-run with evolved coke layer baked into the resistance chain
            sol_eor, Tfb_eor, err_eor = _severity_solver(
                severity_mode, self.v_target_conv.get(), eng, feed, T_IN, P_IN, fc, cfg_pre,
                bracket_lo=getattr(self, 'v_cot_bracket_lo', None) and self.v_cot_bracket_lo.get() or 700.0,
                bracket_hi=getattr(self, 'v_cot_bracket_hi', None) and self.v_cot_bracket_hi.get() or 1450.0,
            )
            if not err_eor and sol_eor is not None:
                sol  = sol_eor
                Tfb  = Tfb_eor

        # ── UPGRADE v22: TLE / quench zone ───────────────────────────────────
        q_len = getattr(self, 'v_quench_length', None)
        if q_len and q_len.get() > 0.0:
            sol_q = eng.run_quench(sol, T_quench_target_K=700.0,
                                   quench_length=q_len.get())
            if sol_q is not None:
                sol = sol_q   # stitched furnace+TLE solution

        cfg = {'geom': geom, 'p_in': self.v_p_in.get()}
        kpis, table, bal = spyro_metrics(sol, eng, feed, fc, cfg)
        kpis['Firebox_C'] = Tfb
        tp = eng.transport_profiles(sol)
        ck_z, ck_p = eng.coking_profile(sol)

        return dict(ft=ft, sol=sol, eng=eng, geom=geom, rxns=rxns,
                    kpis=kpis, table=table, bal=bal, tp=tp,
                    ck_z=ck_z, ck_p=ck_p,
                    feed=feed, fc=fc)   # feed+fc needed by Profile Manipulator

    # ─── Update all output panels ─────────────────────────────────────────────
    def _update_all_outputs_mc(self, R, combined_kpis, dt):
        """Update all output panels for multi-coil mode using combined KPIs for dashboard."""
        # Dashboard shows COMBINED outlet conditions
        self._update_kpis(combined_kpis)
        # Plots still show primary coil profiles
        self._plot_data = R
        self._plot_pending = True
        self._maybe_draw_plots()
        self._refresh_products()
        self._update_reactions(R['rxns'], R['ft'])
        self._refresh_variables(R)
        self.root.after(100, self._highlight_modified_fields)
        k = combined_kpis
        kh = self.v_k_heat.get(); kdp = self.v_k_dp.get()
        corr_str = ''
        if abs(kh - 1.0) > 0.001 or abs(kdp - 1.0) > 0.001:
            corr_str = f' │ k_heat={kh:.3f}  k_dp={kdp:.3f}'
        comb_cot = self._mc_combined_cot_var.get()
        self.v_status.set(
            f"✓ MULTI-COIL {dt:.2f}s │ Combined COT {comb_cot}°C │ "
            f"Conv {k.get('actual_conv',0)*100:.1f}% │ "
            f"C₂H₄ {k.get('eth_yield',0):.2f}% │ P/E {k.get('pe_ratio',0):.3f} │ "
            f"τ {k.get('tau_ms',0):.0f}ms{corr_str}"
        )

    def _update_all_outputs(self, R, dt):
        self._update_kpis(R['kpis'])
        # Cache plot data; render immediately only if Profiles tab is showing
        self._plot_data = R
        self._plot_pending = True
        self._maybe_draw_plots()
        self._refresh_products()
        self._update_reactions(R['rxns'], R['ft'])
        self._refresh_variables(R)
        # Highlight modified fields after each run (single pass, not per-keystroke)
        self.root.after(100, self._highlight_modified_fields)
        k = R['kpis']
        kh = self.v_k_heat.get(); kdp = self.v_k_dp.get()
        corr_str = ''
        if abs(kh - 1.0) > 0.001 or abs(kdp - 1.0) > 0.001:
            corr_str = f' │ k_heat={kh:.3f}  k_dp={kdp:.3f}'
        mc_mode = getattr(self, 'v_mc_enabled', None) and self.v_mc_enabled.get()
        if mc_mode:
            combined_cot_str = self._mc_combined_cot_var.get()
            self.v_status.set(
                f"✓ MULTI-COIL {dt:.2f}s │ Combined COT {combined_cot_str}°C │ "
                f"CG1 COT {k['COT_C']:.1f}°C │ CG1 Conv {k['actual_conv']*100:.1f}% │ "
                f"P/E {k['pe_ratio']:.3f}{corr_str}"
            )
        else:
            self.v_status.set(
                f"✓  Done {dt:.2f}s │ COT {k['COT_C']:.1f}°C │ "
                f"Conv {k['actual_conv']*100:.1f}% │ Firebox {k['Firebox_C']:.1f}°C │ "
                f"P/E {k['pe_ratio']:.3f} │ Target {k.get('severity_mode','')}: {k.get('severity_actual', float('nan')):.3g}/{k.get('severity_setpoint', float('nan')):.3g} │ τ {k['tau_ms']:.0f}ms{corr_str}"
            )

    def _maybe_draw_plots(self):
        """Only do the expensive matplotlib render if Profiles tab is visible."""
        if not self._plot_pending or self._plot_data is None:
            return
        try:
            # nb_out is the right-side notebook; check if tab 0 (Profiles) is selected
            if hasattr(self, '_nb_out') and self._nb_out.index('current') != 0:
                return   # not looking at plots — skip render, will draw on tab switch
        except Exception:
            pass
        self._update_plots(self._plot_data)
        self._plot_pending = False

    def _highlight_modified_fields(self):
        """Single-pass highlight of all fields that differ from their defaults."""
        for key, (ent, _) in self._param_widgets.items():
            dv = self._param_defaults.get(key)
            if dv is None: continue
            # Find the variable associated with this key
            var_map = {
                'feed_rate': self.v_feed_rate, 'steam_ratio': self.v_steam_ratio,
                't_in': self.v_t_in, 'p_in': self.v_p_in,
                'target_conv': self.v_target_conv, 'coils': self.v_coils,
                'passes': self.v_passes, 'lpp': self.v_lpp,
                'tube_id': self.v_tube_id, 'tube_od': self.v_tube_od,
                'emiss': self.v_emiss, 'rough': self.v_rough,
                'k_tube': self.v_k_tube, 'h_o': self.v_h_o,
                'k_heat': self.v_k_heat, 'k_dp': self.v_k_dp,
                'tp': self.v_tp, 'to': self.v_to, 'ta': self.v_ta, 'tc': self.v_tc,
                'rtol': self.v_rtol, 'atol': self.v_atol,
            }
            v = var_map.get(key)
            if v is None: continue
            try:
                cur = v.get()
                try:    modified = abs(float(str(cur)) - float(str(dv))) > 1e-9
                except: modified = str(cur) != str(dv)
                ent.configure(style='Modified.TEntry' if modified else 'TEntry')
            except Exception: pass

    # ─── All Calculated Variables tab ─────────────────────────────────────────

    def _build_variables_tab(self, nb):
        """
        Build the '🧮 All Variables' output tab — v37 INNER-NOTEBOOK LAYOUT.

        Six sub-tabs inside the tab, one per data section.  Every sub-tab
        holds a ttk.Treeview that expands to fill the full panel height with
        its own vertical + horizontal scrollbars — so ALL rows are always
        reachable via the scrollbar, with no height caps.

          ① KPIs & Scalars     — every scalar variable (12 sub-groups)
          ② Species Outlet     — per-species flows, fractions, concentrations
          ③ Axial Transport    — Re, Pr, h_i, vel, μ, Z, q_ext, TMT
          ④ Axial Thermo       — ρ, Cp, k, MW, G, f_D, Nu, X_local, dP/dz
          ⑤ Axial Species      — top-10 mole fractions vs z (auto-labelled)
          ⑥ Rxn Network        — per-type counts, A/Ea ranges

        The tab is read-only; values are populated by _refresh_variables()
        after every run.  The global Search bar + Copy/Export buttons sit
        above the inner notebook and act on whichever section is active.
        """
        # ── Outer frame (fills the output-panel tab) ──────────────────────
        outer = ttk.Frame(nb, style='DarkVars.TFrame')
        nb.add(outer, text='🧮 All Variables')
        try:
            st = ttk.Style()
            st.configure('DarkVars.TFrame', background='#07111F')
            st.configure('DarkVars.TNotebook', background='#07111F', borderwidth=0)
            st.configure('DarkVars.TNotebook.Tab', background='#172338', foreground='#BFD7FF', padding=[10, 6])
            st.map('DarkVars.TNotebook.Tab', background=[('selected', '#38BDF8'), ('active', '#1E2D46')], foreground=[('selected', '#FFFFFF'), ('active', '#EAF2FF')])
            st.configure('DarkVars.Treeview', background='#0D1829', fieldbackground='#0D1829', foreground='#EAF2FF', rowheight=23, borderwidth=0)
            st.configure('DarkVars.Treeview.Heading', background='#1E2D46', foreground='#38BDF8', relief='flat', font=('Segoe UI Semibold', 9))
            st.map('DarkVars.Treeview', background=[('selected', '#2563EB')], foreground=[('selected', '#FFFFFF')])
        except Exception: pass

        # ── Toolbar ───────────────────────────────────────────────────────
        bar = tk.Frame(outer, bg='#1E3A5F')
        bar.pack(fill='x', pady=(0, 2))
        tk.Label(bar, text='🧮  ALL CALCULATED VARIABLES',
                 font=('Helvetica', 10, 'bold'), fg='#DBEAFE',
                 bg='#1E3A5F', pady=5).pack(side=tk.LEFT, padx=10)
        tk.Label(bar,
                 text='6 sections — use sub-tabs below; every computed '
                      'quantity from the last run',
                 font=('Helvetica', 8), fg='#93C5FD',
                 bg='#1E3A5F').pack(side=tk.LEFT, padx=4)

        # ── Search + Copy + Export ────────────────────────────────────────
        ctrl = tk.Frame(outer, bg='#07111F')
        ctrl.pack(fill='x', padx=4, pady=(0, 2))
        tk.Label(ctrl, text='🔍 Filter:', bg='#07111F',
                 font=('Helvetica', 9)).pack(side=tk.LEFT, padx=(4, 0))
        self._var_search = tk.StringVar()
        ttk.Entry(ctrl, textvariable=self._var_search,
                  width=26).pack(side=tk.LEFT, padx=(2, 6))
        self._var_search.trace_add('write',
                                   lambda *_: self._vars_apply_filter())
        ttk.Button(ctrl, text='📋 Copy TSV',
                   command=self._vars_copy_tsv).pack(side=tk.LEFT, padx=2)
        ttk.Button(ctrl, text='💾 Export CSV…',
                   command=self._vars_export_csv).pack(side=tk.LEFT, padx=2)
        ttk.Button(ctrl, text='↺ Reset',
                   command=lambda: self._var_search.set('')
                   ).pack(side=tk.LEFT, padx=2)
        self._var_stats_lbl = tk.Label(
            ctrl, text='', font=('Helvetica', 8, 'italic'),
            fg='#93C5FD', bg='#07111F')
        self._var_stats_lbl.pack(side=tk.RIGHT, padx=8)

        # ── Inner Notebook (one sub-tab per section) ──────────────────────
        inner_nb = ttk.Notebook(outer, style='DarkVars.TNotebook')
        inner_nb.pack(fill='both', expand=True, padx=2, pady=2)
        self._var_inner_nb = inner_nb

        # Helper: create one sub-tab with a proper full-height Treeview
        def _make_section(tab_label, cols, col_widths):
            frm = ttk.Frame(inner_nb, style='DarkVars.TFrame')
            inner_nb.add(frm, text=tab_label)
            vsb = ttk.Scrollbar(frm, orient='vertical')
            hsb = ttk.Scrollbar(frm, orient='horizontal')
            tv  = ttk.Treeview(frm, columns=cols, show='headings',
                               yscrollcommand=vsb.set,
                               xscrollcommand=hsb.set,
                               selectmode='extended', style='DarkVars.Treeview')
            vsb.config(command=tv.yview)
            hsb.config(command=tv.xview)
            for c, w in zip(cols, col_widths):
                tv.heading(c, text=c, anchor='w')
                tv.column(c, width=w, minwidth=40, stretch=False)
            vsb.pack(side='right', fill='y')
            hsb.pack(side='bottom', fill='x')
            tv.pack(fill='both', expand=True)
            # Row colour tags
            tv.tag_configure('odd',     background='#0D1829', foreground='#EAF2FF')
            tv.tag_configure('even',    background='#111C2E', foreground='#EAF2FF')
            tv.tag_configure('header',  background='#1E3A5F',
                             foreground='white',
                             font=('Helvetica', 9, 'bold'))
            tv.tag_configure('subhead', background='#334155',
                             foreground='#DBEAFE',
                             font=('Helvetica', 8, 'bold'))
            tv.tag_configure('warn',    background='#78350F', foreground='#FDE68A')
            tv.tag_configure('alert',   background='#7F1D1D', foreground='#FECACA')
            tv.tag_configure('good',    background='#064E3B', foreground='#BBF7D0')
            tv.tag_configure('spacer',  background='#F1F5F9')
            return tv

        # ① Process KPIs ──────────────────────────────────────────────────
        self._var_tv_kpi = _make_section(
            '① KPIs & Scalars',
            ('Variable', 'Symbol', 'Value', 'Unit', 'Description'),
            (250, 90, 130, 80, 400))

        # ② Species Outlet ─────────────────────────────────────────────────
        self._var_tv_sp = _make_section(
            '② Species Outlet',
            ('Species', 'MW\n[g/mol]', 'Flow/coil\n[mol/s]',
             'Flow/coil\n[g/s]', 'Flow total\n[kg/h]',
             'Conc out\n[mol/m³]',
             'g/100g\nFeed', 'g/100g\nConv',
             'mol%\n(dry)', 'wt%\n(dry)', 'mol%\n(wet)', 'wt%\n(wet)',
             'Selectivity\n[g/g conv]'),
            (90, 70, 95, 95, 95, 95, 80, 80, 75, 75, 75, 75, 95))

        # ③ Axial Transport ────────────────────────────────────────────────
        self._var_tv_ax = _make_section(
            '③ Axial Transport',
            ('z [m]', 'T [°C]', 'P [bar]', 'τ [ms]',
             'Re [-]', 'Pr [-]', 'h_i\n[W/m²K]',
             'vel\n[m/s]', 'μ\n[μPa·s]', 'Z [-]',
             'q_ext\n[kW/m²]', 'TMT\n[°C]'),
            (65, 70, 65, 65, 80, 65, 80, 70, 75, 65, 85, 75))

        # ④ Axial Thermo ───────────────────────────────────────────────────
        self._var_tv_ax2 = _make_section(
            '④ Axial Thermo',
            ('z [m]', 'ρ\n[kg/m³]', 'MW_mix\n[g/mol]',
             'Cp_mol\n[J/molK]', 'Cp_mass\n[J/kgK]',
             'k\n[W/mK]', 'G\n[kg/m²s]',
             'f_D [-]', 'Nu [-]', 'X_local\n[%]',
             'F_total\n[mol/s]', 'q_lin\n[kW/m]',
             'T_skin\n[°C]', 'dP/dz\n[Pa/m]'),
            (65, 75, 85, 85, 85, 75, 85, 70, 70, 80, 85, 80, 75, 80))

        # ⑤ Axial Species Fractions ───────────────────────────────────────
        self._var_tv_ax3 = _make_section(
            '⑤ Axial Species',
            ('z [m]', 'T [°C]',
             'Species1', 'Species2', 'Species3', 'Species4', 'Species5',
             'Species6', 'Species7', 'Species8', 'Species9', 'Species10'),
            (65, 70, 80, 80, 80, 80, 80, 80, 80, 80, 80, 80))

        # ⑥ Reaction Network Stats ────────────────────────────────────────
        self._var_tv_rxn = _make_section(
            '⑥ Rxn Network',
            ('Category', 'Count',
             'log10(A)\nmin', 'log10(A)\nmax',
             'Ea min\n[kJ/mol]', 'Ea max\n[kJ/mol]',
             'Description'),
            (180, 60, 90, 90, 95, 95, 360))

        # Master list used by filter, copy, export helpers
        self._var_trees = [
            self._var_tv_kpi, self._var_tv_sp,
            self._var_tv_ax,  self._var_tv_ax2,
            self._var_tv_ax3, self._var_tv_rxn,
        ]
        self._var_all_rows = []   # populated by _refresh_variables

        tk.Label(outer,
                 text='Run a simulation to populate — every calculated '
                      'variable appears here across the six sub-tabs.',
                 font=('Helvetica', 9, 'italic'),
                 fg='#94A3B8', bg='#F8FAFC').pack(pady=4)

    def _refresh_variables(self, R):
        """
        Populate all six sub-tab Treeviews with every calculated variable.
        Each of the 12 KPI sub-sections and each tree section runs inside its
        own try/except so a failure in one block never silences the others.
        """
        if not hasattr(self, '_var_tv_kpi'):
            return

        kpis  = R.get('kpis', {})
        table = R.get('table', [])
        sol   = R.get('sol')
        eng   = R.get('eng')
        bal   = R.get('bal', {})
        tp    = R.get('tp', {})
        geom  = R.get('geom', {})
        rxns  = R.get('rxns', [])
        feed  = R.get('feed', {})
        fc    = R.get('fc', [])
        ft    = R.get('ft', '')

        # Clear every tree
        for tv in self._var_trees:
            tv.delete(*tv.get_children())
        self._var_all_rows = []

        # ── helpers ──────────────────────────────────────────────────────────
        def _ins(tv, values, tag='odd'):
            rid = tv.insert('', 'end', values=values, tags=(tag,))
            self._var_all_rows.append((tv, rid, values))

        def _tag(i, warn=False, alert=False, good=False):
            if alert: return 'alert'
            if warn:  return 'warn'
            if good:  return 'good'
            return 'even' if i % 2 == 0 else 'odd'

        def _hdr(tv, title, ncols=5):
            _ins(tv, ([title] + [''] * (ncols - 1)), 'header')

        def _spc(tv, ncols=5):
            _ins(tv, [''] * ncols, 'spacer')

        def _err(tv, section, exc, ncols=5):
            _ins(tv, ([f'⚠ {section} — {type(exc).__name__}: {exc}'] +
                      [''] * (ncols - 1)), 'alert')

        def _f(val, fmt='.4g'):
            try:
                return '—' if val is None else (val if isinstance(val, str)
                                                else f'{float(val):{fmt}}')
            except Exception:
                return '—'

        # Pre-compute commonly used scalars safely
        ns      = eng.num_species if eng else 0
        coils_n = max(int(geom.get('coils', 1)), 1)
        tube_id = float(geom.get('tube_id', 0.05))
        tube_od = float(geom.get('tube_od', 0.062))
        L_pass  = float(geom.get('length_per_pass', 20.))
        n_pass  = int(geom.get('passes', 4))
        L_total = L_pass * n_pass

        # Inlet / outlet scalars (used across multiple sections)
        try:
            if sol is not None and ns > 0:
                T_in_K  = float(sol.y[ns,    0])
                T_out_K = float(sol.y[ns,   -1])
                P_in_Pa = float(sol.y[ns+1,  0])
                P_out_Pa= float(sol.y[ns+1, -1])
            else:
                T_in_K = T_out_K = P_in_Pa = P_out_Pa = 0.
        except Exception:
            T_in_K = T_out_K = P_in_Pa = P_out_Pa = 0.
        T_in_C  = T_in_K  - 273.15
        T_out_C = T_out_K - 273.15

        # Pre-extract axial arrays once (used by transport stats and axial sections)
        try:
            if sol is not None and ns > 0:
                z_all   = sol.t
                T_all_K = np.clip(sol.y[ns,   :], 600., 1450.)
                P_all_Pa= np.clip(sol.y[ns+1, :], 1e4,  8e5 )
                tau_all = sol.y[ns+2, :]
                F_all   = np.maximum(sol.y[:ns, :], 1e-8)
                Ft_all  = F_all.sum(axis=0)
                re_all  = np.array(tp.get('Re',  np.zeros_like(z_all)))
                pr_all  = np.array(tp.get('Pr',  np.zeros_like(z_all)))
                hi_all  = np.array(tp.get('h_i', np.zeros_like(z_all)))
                vel_all = np.array(tp.get('vel', np.zeros_like(z_all)))
                _have_arrays = True
            else:
                _have_arrays = False
        except Exception:
            _have_arrays = False

        # ════════════════════════════════════════════════════════════════════
        # ①  KPIs & SCALARS  — 12 independent sub-sections
        # ════════════════════════════════════════════════════════════════════
        tv1   = self._var_tv_kpi
        idx   = [0]   # mutable counter (list trick to allow mutation in nested fn)

        def krow(nm, sy, vl, un, dc, warn=False, alert=False):
            tag = _tag(idx[0], warn=warn, alert=alert)
            _ins(tv1, (nm, sy, _f(vl), un, dc), tag)
            idx[0] += 1

        def krow3(nm, sy, vl, un, dc):   # convenience, no warn flags
            krow(nm, sy, vl, un, dc)

        # §1 Boundary Conditions ─────────────────────────────────────────────
        try:
            _hdr(tv1, '── §1. BOUNDARY CONDITIONS ──')
            bc = [
                ('Coil Inlet Temp.',   'CIT',   T_in_C,                        '°C',   'Process gas T at coil inlet'),
                ('Coil Inlet Temp.',   'CIT',   T_in_K,                        'K',    'Same in Kelvin'),
                ('Coil Outlet Temp.',  'COT',   T_out_C,                       '°C',   'Gas T leaving the last pass'),
                ('Coil Outlet Temp.',  'COT',   T_out_K,                       'K',    'Same in Kelvin'),
                ('Firebox Temp.',      'T_fb',  kpis.get('Firebox_C', 0.),     '°C',   'Radiant-box flame temperature'),
                ('ΔT process',         'ΔCIT→COT', T_out_C - T_in_C,          '°C',   'Temperature rise across coil'),
                ('ΔT Firebox − COT',   'ΔT_fb', kpis.get('Firebox_C', 0.) - T_out_C, '°C', 'Driving force flame→gas'),
                ('Inlet Pressure',     'P_in',  P_in_Pa / 101325.,             'atm',  'Coil inlet static pressure'),
                ('Inlet Pressure',     'P_in',  P_in_Pa / 1e5,                 'bar',  'Same in bar'),
                ('Outlet Pressure',    'P_out', P_out_Pa / 101325.,            'atm',  'Coil outlet pressure (COP)'),
                ('Outlet Pressure',    'P_out', P_out_Pa / 1e5,                'bar',  'Same in bar'),
                ('Coil ΔP',            'ΔP',    kpis.get('dP_atm', 0.),       'atm',  'Total pressure drop'),
                ('Coil ΔP',            'ΔP',    kpis.get('dP_atm', 0.) * 101.325, 'kPa', 'Same in kPa'),
                ('Steam/HC ratio',     'S/HC',  self.v_steam_ratio.get(),      'kg/kg','Dilution steam ratio'),
                ('Target conversion',  'X_tgt', self.v_target_conv.get() * 100., '%', 'User-set target conversion'),
                ('Actual conversion',  'X_act', kpis.get('actual_conv', 0.) * 100., '%', 'Achieved mass-based conversion'),
                ('Conv. error',        'ε_X',   abs(kpis.get('actual_conv', 0.) - self.v_target_conv.get()) * 100., '%', '|actual − target|'),
                ('Residence time',     'τ',     kpis.get('tau_ms', 0.),        'ms',   'Integrated dt/dz inlet→outlet'),
                ('Residence time',     'τ',     kpis.get('tau_ms', 0.) / 1000.,'s',   'Same in seconds'),
            ]
            for nm, sy, vl, un, dc in bc:
                krow3(nm, sy, vl, un, dc)
        except Exception as e:
            _err(tv1, '§1 Boundary Conditions', e)

        # §2 Flow & Mass ─────────────────────────────────────────────────────
        # Convention used throughout:
        #   feed[sp]   = per-FURNACE mol/s  (build_gas_feed returns total for all coils)
        #   sol.y[i,:] = per-COIL   mol/s  (engine.run divides by self.coils)
        #   table['mol_s'] / ['mass_gs'] = per-FURNACE (spyro_metrics × coils)
        try:
            _spc(tv1); _hdr(tv1, '── §2. FLOW & MASS RATES ──')
            # feed[] is per-furnace; divide by coils_n for per-coil
            hc_gs_fce   = sum(feed.get(sp, 0.) * get_mw(sp) for sp in fc) if fc else 0.
            stm_gs_fce  = feed.get('H2O', 0.) * get_mw('H2O')
            tot_gs_fce  = hc_gs_fce + stm_gs_fce
            hc_gs_coil  = hc_gs_fce  / max(coils_n, 1)   # per-coil g/s
            stm_gs_coil = stm_gs_fce / max(coils_n, 1)
            tot_gs_coil = tot_gs_fce / max(coils_n, 1)
            hc_kgh_coil  = hc_gs_coil  * 3.6              # per-coil kg/h
            stm_kgh_coil = stm_gs_coil * 3.6
            tot_kgh_coil = tot_gs_coil * 3.6
            hc_kgh_fce   = hc_gs_fce   * 3.6              # per-furnace kg/h
            stm_kgh_fce  = stm_gs_fce  * 3.6
            tot_kgh_fce  = tot_gs_fce  * 3.6
            # Outlet: sol.y[:ns,-1] is already per-coil
            if _have_arrays and ns > 0:
                F_out_coil    = sol.y[:ns, -1]
                mol_out_coil  = float(F_out_coil.sum())
                mass_out_coil = float(np.dot(F_out_coil, eng._mw))
            else:
                mol_out_coil = mass_out_coil = 0.
            fin_mols_coil = sum(feed.values()) / max(coils_n, 1) if feed else 1e-9
            fm = [
                ('# Parallel coils',              'N_c',       coils_n,                    '—',    'Parallel coil count in furnace'),
                ('HC feed — per coil',            'ṁ_HC/c',    hc_kgh_coil,                'kg/h', 'HC mass flow into one coil  [= total / N_coils]'),
                ('HC feed — per coil',            'ṁ_HC/c',    hc_gs_coil,                 'g/s',  'Same in g/s'),
                ('HC feed — network (all coils)', 'ṁ_HC,net',  hc_kgh_fce,                 'kg/h', 'Total HC feed entering the furnace'),
                ('HC feed — network',             'ṁ_HC,net',  hc_kgh_fce / 1000.,         't/h',  'Same in metric t/h'),
                ('HC feed — daily throughput',    'ṁ_HC,day',  hc_kgh_fce * 24. / 1000.,   't/day','HC processed per 24 h'),
                ('Steam — per coil',              'ṁ_S/c',     stm_kgh_coil,               'kg/h', 'Dilution steam entering one coil'),
                ('Steam — network (total)',       'ṁ_S,net',   stm_kgh_fce,                'kg/h', 'Total dilution steam for furnace'),
                ('Total feed — per coil',         'ṁ_tot/c',   tot_kgh_coil,               'kg/h', 'HC + steam entering one coil'),
                ('Total feed — network',          'ṁ_tot,net', tot_kgh_fce,                'kg/h', 'Total process stream into furnace'),
                ('Outlet mol flow — per coil',    'F_t,out/c', mol_out_coil,               'mol/s','Total moles leaving one coil'),
                ('Outlet mol flow — per coil',    'F_t,out/c', mol_out_coil * 3.6e-3,      'kmol/h','Same in kmol/h'),
                ('Outlet mass — per coil',        'ṁ_out/c',   mass_out_coil * 3.6,        'kg/h', 'Mass leaving one coil (= inlet mass, by balance)'),
                ('Outlet mass — network',         'ṁ_out,net', mass_out_coil * 3.6 * coils_n, 'kg/h','Total cracked gas leaving furnace'),
                ('Mole expansion — per coil',     'F_out/F_in',mol_out_coil / max(fin_mols_coil, 1e-9), '—', 'Outlet/inlet molar ratio (>1 = cracking expansion)'),
            ]
            for nm, sy, vl, un, dc in fm:
                krow3(nm, sy, vl, un, dc)
        except Exception as e:
            _err(tv1, '§2 Flow & Mass', e)

        # §3 Heat Transfer (aggregate — uses tp arrays, no expensive loop) ────
        try:
            _spc(tv1); _hdr(tv1, '── §3. HEAT TRANSFER — Overall & Flux ──')
            Q_kW = kpis.get('heat_duty_kW', 0.)
            Ac   = np.pi * (tube_id / 2.) ** 2
            A_in = np.pi * tube_id * L_total
            A_out= np.pi * tube_od * L_total
            q_avg_int = (Q_kW / max(coils_n, 1) * 1e3) / max(A_in, 1e-9) / 1e3   # kW/m²
            # Transport stats from tp dict (already computed by engine)
            if _have_arrays and len(hi_all) > 0:
                hi_avg  = float(np.mean(hi_all)); hi_min = float(np.min(hi_all)); hi_max = float(np.max(hi_all))
                re_avg  = float(np.mean(re_all)); re_min = float(np.min(re_all)); re_max = float(np.max(re_all))
                pr_avg  = float(np.mean(pr_all)); pr_min = float(np.min(pr_all)); pr_max = float(np.max(pr_all))
                vel_avg = float(np.mean(vel_all)); vel_min= float(np.min(vel_all)); vel_max= float(np.max(vel_all))
            else:
                hi_avg = hi_min = hi_max = 0.
                re_avg = re_min = re_max = 0.
                pr_avg = pr_min = pr_max = 0.
                vel_avg = vel_min = vel_max = 0.
            tmt_max_v = kpis.get('tmt_max_C', 0.)
            hi_out_v  = kpis.get('hi_out', 0.)
            ht = [
                ('Heat duty / coil',         'Q̇_c',      Q_kW / max(coils_n, 1), 'kW',    'Per-coil process-side heat'),
                ('Heat duty — network',      'Q̇_net',    Q_kW,                   'kW',    'Total furnace heat duty'),
                ('Heat duty — network',      'Q̇_net',    Q_kW / 1e3,             'MW',    'Same in MW'),
                ('Avg internal flux',        'q_i,avg',  q_avg_int,              'kW/m²', 'Q̇/A_inner per coil'),
                ('Inner tube area / coil',   'A_i',      A_in,                   'm²',    'π·D_i·L'),
                ('Outer tube area / coil',   'A_o',      A_out,                  'm²',    'π·D_o·L'),
                ('Total inner area',         'A_i,net',  A_in * coils_n,         'm²',    'All coils'),
                ('Total outer area',         'A_o,net',  A_out * coils_n,        'm²',    'All coils'),
                ('h_i at outlet',            'h_i,out',  hi_out_v,               'W/m²K', 'Gnielinski outlet coefficient', hi_out_v < 400, False),
                ('h_i axial average',        'h_i,avg',  hi_avg,                 'W/m²K', 'Mean of tp[h_i] array'),
                ('h_i axial minimum',        'h_i,min',  hi_min,                 'W/m²K', 'Min h_i along coil'),
                ('h_i axial maximum',        'h_i,max',  hi_max,                 'W/m²K', 'Max h_i along coil'),
                ('Max tube metal temp.',     'TMT_max',  tmt_max_v,              '°C',    'Peak outer-skin T (R chain)', tmt_max_v > 950, tmt_max_v > 1050),
                ('TMT coke penalty',         'ΔTMT_ck',  kpis.get('tmt_coke_penalty_K', 0.), 'K', 'Extra ΔT from coke layer'),
                ('Coke thickness max',       'δ_c,max',  kpis.get('coke_thickness_max_mm', 0.), 'mm', 'Peak coke layer'),
                ('Re at outlet',             'Re_out',   kpis.get('Re_out', 0.), '—',    'Outlet Reynolds'),
                ('Re axial average',         'Re_avg',   re_avg,                 '—',    'Mean Reynolds number'),
                ('Re axial minimum',         'Re_min',   re_min,                 '—',    'Min Reynolds (usually inlet)'),
                ('Re axial maximum',         'Re_max',   re_max,                 '—',    'Max Reynolds (usually outlet)'),
                ('Pr at outlet',             'Pr_out',   kpis.get('Pr_out', 0.), '—',    'Outlet Prandtl'),
                ('Pr axial average',         'Pr_avg',   pr_avg,                 '—',    'Mean Prandtl'),
                ('Velocity axial average',   'v_avg',    vel_avg,                'm/s',  'Mean bulk velocity'),
                ('Velocity axial minimum',   'v_min',    vel_min,                'm/s',  'Inlet-side velocity'),
                ('Velocity axial maximum',   'v_max',    vel_max,                'm/s',  'Outlet-side velocity', vel_max > 300, vel_max > 400),
            ]
            for row in ht:
                if len(row) == 7:
                    nm, sy, vl, un, dc, w, a = row; krow(nm, sy, vl, un, dc, warn=w, alert=a)
                else:
                    nm, sy, vl, un, dc = row;       krow3(nm, sy, vl, un, dc)
        except Exception as e:
            _err(tv1, '§3 Heat Transfer', e)

        # §4 Pressure Drop ────────────────────────────────────────────────────
        try:
            _spc(tv1); _hdr(tv1, '── §4. PRESSURE DROP DECOMPOSITION ──')
            dP_atm = kpis.get('dP_atm', 0.)
            dP_kPa = dP_atm * 101.325
            bend_k = float(geom.get('bend_kfactor', 0.5))
            if _have_arrays and ns > 0:
                F_o  = np.maximum(sol.y[:ns, -1], 1e-8)
                T_o  = float(np.clip(sol.y[ns, -1], 600., 1450.))
                P_o  = float(np.clip(sol.y[ns+1, -1], 1e4, 8e5))
                Ft_o = float(F_o.sum())
                mw_o = float(np.dot(F_o, eng._mw) / Ft_o)
                Z_o  = eng._compressibility_Z(T_o, P_o, mw_o)
                rho_o= P_o * (mw_o / 1000.) / (Z_o * R_GAS * T_o)
                vel_o= (Ft_o * mw_o / 1000.) / max(rho_o * eng.Ac, 1e-9)
                G_o  = rho_o * vel_o
                dP_bend_each = bend_k * 0.5 * rho_o * min(vel_o, 300.) ** 2
                dP_bend_tot  = dP_bend_each * max(n_pass - 1, 0)
            else:
                mw_o = Z_o = rho_o = vel_o = G_o = dP_bend_each = dP_bend_tot = 0.
            dp = [
                ('Total ΔP',           'ΔP',    dP_atm,                         'atm',   'Friction + accel + bends'),
                ('Total ΔP',           'ΔP',    dP_kPa,                         'kPa',   'Same in kPa'),
                ('Total ΔP',           'ΔP',    dP_atm * 1000.,                 'mbar',  'Same in mbar'),
                ('ΔP per pass avg',    'ΔP/N_p',dP_kPa / max(n_pass, 1),        'kPa',   'Mean per straight pass'),
                ('ΔP/L (specific)',    'ΔP/L',  dP_atm * 101325. / max(L_total, 1e-9), 'Pa/m', 'Mean axial gradient'),
                ('Bend ΔP each bend',  'ΔP_b',  dP_bend_each,                   'Pa',    'k_b·½ρv² per 180° bend'),
                ('Bend ΔP total',      'ΣΔP_b', dP_bend_tot,                    'Pa',    '(N_pass-1) × bend ΔP'),
                ('Bend k-factor',      'k_b',   bend_k,                         '—',     'Minor-loss coeff per bend'),
                ('Outlet density',     'ρ_o',   rho_o,                          'kg/m³', 'Z-corrected outlet density'),
                ('Outlet velocity',    'v_o',   vel_o,                          'm/s',   'Bulk velocity at outlet'),
                ('Outlet mass flux',   'G_o',   G_o,                            'kg/m²s','ρ·v at outlet'),
                ('Outlet Z-factor',    'Z_o',   Z_o,                            '—',     'Peng-Robinson compressibility'),
                ('Outlet mixture MW',  'MW_o',  mw_o,                           'g/mol', 'Mole-weighted MW at outlet'),
            ]
            for nm, sy, vl, un, dc in dp:
                krow3(nm, sy, vl, un, dc)
        except Exception as e:
            _err(tv1, '§4 Pressure Drop', e)

        # §5 Severity ─────────────────────────────────────────────────────────
        try:
            _spc(tv1); _hdr(tv1, '── §5. SEVERITY METRICS ──')
            ksf = ksi = 0.
            if _have_arrays:
                try:
                    k_T = 4.65e13 * np.exp(-273e3 / (R_GAS * T_all_K))
                    ksf = float(np.trapz(k_T, tau_all))
                    ksi = float(np.trapz(T_all_K - 273.15, tau_all))
                except Exception:
                    pass
            pe  = kpis.get('pe_ratio', 0.)
            h2m = kpis.get('h2ch4', 0.)
            c2e = kpis.get('eth_yield', 0.)
            c3p = max(kpis.get('pro_yield', 0.), 1e-12)
            sv = [
                ('P/E ratio',              'P/E',    pe,         '—',     'Propylene/Ethylene mass ratio', pe > 0.65, False),
                ('H₂/CH₄ molar ratio',     'H2/CH4', h2m,        'mol/mol','Severity gauge (high → severe)', False, False),
                ('C₂=/C₃= mass ratio',     'C2=/C3=',c2e / c3p, '—',     'Olefin split indicator', False, False),
                ('Kinetic Severity (KSF)',  'KSF',    ksf,        's·s⁻¹', '∫ k_eth dτ (Linden proxy)', False, False),
                ('Thermal Severity (KSI)',  'KSI',    ksi,        '°C·s',  '∫ T_gas dτ', False, False),
            ]
            for nm, sy, vl, un, dc, w, a in sv:
                krow(nm, sy, vl, un, dc, warn=w, alert=a)
        except Exception as e:
            _err(tv1, '§5 Severity', e)

        # §6 Product Yields ───────────────────────────────────────────────────
        try:
            _spc(tv1); _hdr(tv1, '── §6. PRODUCT YIELDS  [g / 100 g HC feed] ──')
            def _yld(sp):
                for r in table:
                    if r.get('Species') == sp: return r.get('g_100g_feed', 0.)
                return 0.
            y_H2   = _yld('H2');   y_CH4  = _yld('CH4')
            y_C2H4 = kpis.get('eth_yield', 0.)
            y_C2H6 = _yld('C2H6'); y_C3H6 = kpis.get('pro_yield', 0.)
            y_C3H8 = _yld('C3H8'); y_C4H6 = _yld('C4H6')
            y_C4H8 = _yld('C4H8') + _yld('iC4H8') + _yld('1C4H8') + _yld('2C4H8')
            y_C6H6 = _yld('C6H6'); y_C7H8 = _yld('C7H8'); y_C8H10= _yld('C8H10')
            y_BTX  = y_C6H6 + y_C7H8 + y_C8H10
            y_OL   = y_C2H4 + y_C3H6 + y_C4H6 + y_C4H8
            y_LG   = y_H2 + y_CH4
            y_CK   = kpis.get('coke_yield', 0.)
            yl = [
                ('Hydrogen',          'Y_H2',   y_H2,   'g/100g HC','H2 yield'),
                ('Methane',           'Y_CH4',  y_CH4,  'g/100g HC','CH4 yield'),
                ('Ethylene',          'Y_C2H4', y_C2H4, 'g/100g HC','Primary olefin'),
                ('Ethane (slip)',      'Y_C2H6', y_C2H6, 'g/100g HC','Unreacted C2H6'),
                ('Propylene',         'Y_C3H6', y_C3H6, 'g/100g HC','Primary olefin'),
                ('Propane (slip)',     'Y_C3H8', y_C3H8, 'g/100g HC','Unreacted C3H8'),
                ('1,3-Butadiene',     'Y_C4H6', y_C4H6, 'g/100g HC','High-value byproduct'),
                ('Butenes (total)',    'Y_C4H8', y_C4H8, 'g/100g HC','1-C4H8 + 2-C4H8 + i-C4H8'),
                ('C4 combined',       'Y_C4',   kpis.get('c4_yield', 0.), 'g/100g HC','All C4 species'),
                ('Benzene',           'Y_BZ',   y_C6H6, 'g/100g HC','BTX aromatic'),
                ('Toluene',           'Y_TOL',  y_C7H8, 'g/100g HC','BTX aromatic'),
                ('Xylenes',           'Y_XY',   y_C8H10,'g/100g HC','BTX aromatic'),
                ('BTX combined',      'Y_BTX',  kpis.get('btx_yield', 0.), 'g/100g HC','Benzene+Toluene+Xylenes'),
                ('Total olefins',     'Y_OL',   y_OL,   'g/100g HC','C2=+C3=+C4H6+C4H8'),
                ('Light gases',       'Y_LG',   y_LG,   'g/100g HC','H2 + CH4'),
                ('Coke',              'Y_COKE', y_CK,   'g/100g HC','Solid coke on tube', y_CK > 1., y_CK > 2.5),
                ('Olefins/Aromatics', 'OL/AR',  y_OL / max(y_BTX, 1e-9), '—','Selectivity gauge'),
                ('Σ yield (check)',   'ΣY',     y_OL + y_BTX + y_LG + y_CK, 'g/100g HC','Sanity sum → ~100'),
            ]
            for row in yl:
                if len(row) == 7:
                    nm, sy, vl, un, dc, w, a = row; krow(nm, sy, vl, un, dc, warn=w, alert=a)
                else:
                    nm, sy, vl, un, dc = row; krow3(nm, sy, vl, un, dc)
        except Exception as e:
            _err(tv1, '§6 Yields', e)

        # §7 Selectivities ────────────────────────────────────────────────────
        try:
            _spc(tv1); _hdr(tv1, '── §7. SELECTIVITIES  [g / 100 g HC converted] ──')
            def _sel(sp):
                for r in table:
                    if r.get('Species') == sp: return r.get('g_100g_conv', 0.)
                return 0.
            for nm, sy, sp in [
                ('Ethylene',    'S_C2H4', 'C2H4'),
                ('Propylene',   'S_C3H6', 'C3H6'),
                ('1,3-Butadiene','S_C4H6','C4H6'),
                ('Benzene',     'S_C6H6', 'C6H6'),
                ('Toluene',     'S_C7H8', 'C7H8'),
                ('Methane',     'S_CH4',  'CH4'),
                ('Hydrogen',    'S_H2',   'H2'),
                ('Coke',        'S_COKE', 'COKE'),
            ]:
                krow3(nm, sy, _sel(sp), 'g/100g conv', f'Selectivity to {sp}')
        except Exception as e:
            _err(tv1, '§7 Selectivities', e)

        # §8 Coking & Tube Life ───────────────────────────────────────────────
        try:
            _spc(tv1); _hdr(tv1, '── §8. COKING & TUBE LIFE ──')
            ck_z = R.get('ck_z')
            ck_p = R.get('ck_p')
            if ck_p is not None and len(ck_p) > 0:
                ck_avg = float(np.mean(ck_p))
                ck_max = float(np.max(ck_p))
                ck_min = float(np.min(ck_p))
                try:    ck_day = float(np.trapz(ck_p, ck_z)) * np.pi * tube_id * 24.
                except: ck_day = ck_avg * np.pi * tube_id * L_total * 24.
            else:
                ck_avg = ck_max = ck_min = ck_day = 0.
            run_h  = self.v_run_hours.get()   if hasattr(self, 'v_run_hours')   else 0.
            qlen   = self.v_quench_length.get()if hasattr(self, 'v_quench_length')else 0.
            ck_rows = [
                ('Avg coke rate',     'ṁ_c,avg', ck_avg,  'kg/m²h', 'Mean coke flux (two-stage model)'),
                ('Max coke rate',     'ṁ_c,max', ck_max,  'kg/m²h', 'Peak coke deposition (hotspot)', ck_max > 0.5, ck_max > 1.),
                ('Min coke rate',     'ṁ_c,min', ck_min,  'kg/m²h', 'Lowest coke node (usually inlet)'),
                ('Total coke/coil·d', 'M_c',     ck_day,  'kg/day', 'Coke laydown per coil per 24 h'),
                ('Total coke network','M_c,net',  ck_day * coils_n, 'kg/day','All coils combined'),
                ('Max coke thickness','δ_c,max',  kpis.get('coke_thickness_max_mm', 0.), 'mm', 'End-of-run coke layer'),
                ('Run hours (EOR)',   't_run',   run_h,   'h',     'Campaign hours for coke evolution'),
                ('TLE quench length', 'L_q',     qlen,    'm',     'Transfer-line exchanger length'),
            ]
            for row in ck_rows:
                if len(row) == 7:
                    nm, sy, vl, un, dc, w, a = row; krow(nm, sy, vl, un, dc, warn=w, alert=a)
                else:
                    nm, sy, vl, un, dc = row; krow3(nm, sy, vl, un, dc)
        except Exception as e:
            _err(tv1, '§8 Coking', e)

        # §9 Atom & Mass Balance ──────────────────────────────────────────────
        try:
            _spc(tv1); _hdr(tv1, '── §9. ATOM & MASS BALANCE ──')
            for elem, label in [('C', 'Carbon'), ('H', 'Hydrogen'), ('O', 'Oxygen')]:
                ci  = bal.get(f'{elem}_in',  0.)
                co  = bal.get(f'{elem}_out', 0.)
                cl  = bal.get(f'{elem}_cls', 100.)
                krow(f'{label} closure', elem, cl, '%', f'In {ci:.4g} mol/s → Out {co:.4g} mol/s',
                     warn=abs(cl - 100.) > 0.5, alert=abs(cl - 100.) > 2.)
                krow3(f'{label} atoms in',  f'{elem}_in',  ci, 'mol/s', f'Inlet {label} atom flow rate')
                krow3(f'{label} atoms out', f'{elem}_out', co, 'mol/s', f'Outlet {label} atom flow rate')
            mi  = bal.get('mass_in',  0.)
            mo  = bal.get('mass_out', 0.)
            mc  = bal.get('mass_cls', 100.)
            krow('Mass closure', 'Σm', mc, '%', f'In {mi:.4g} g/s → Out {mo:.4g} g/s',
                 alert=abs(mc - 100.) > 2.)
            krow3('Mass imbalance', 'Δm', mo - mi, 'g/s', 'Absolute error (should be ≈ 0)')
        except Exception as e:
            _err(tv1, '§9 Balance', e)

        # §10 Reaction Network Stats ──────────────────────────────────────────
        try:
            _spc(tv1); _hdr(tv1, '── §10. REACTION NETWORK STATISTICS ──')
            rxn_lst = eng.reactions if eng else rxns
            n_rxn   = len(rxn_lst)
            def _cnt(cat_kw): return sum(1 for r in rxn_lst if cat_kw in r.get('type', ''))
            rs = [
                ('Feed type',          'feed', ft,                             '—', 'Hydrocarbon feed cracked'),
                ('Total reactions',    'N_r',  n_rxn,                          '—', 'All reactions in network'),
                ('Total species',      'N_s',  ns,                             '—', 'Species tracked (incl H2O, COKE)'),
                ('Paraffin cracking',  'N_pc', _cnt('Paraffin_Crack') + _cnt('Iso_Crack') + _cnt('Ring_Opening'), '—', 'Primary C–C scission'),
                ('Olefin cracking',    'N_oc', _cnt('Olefin_Crack'),           '—', 'Secondary olefin cracking'),
                ('Condensation/PAH',   'N_co', _cnt('Condensation') + _cnt('PAH_Growth') + _cnt('Hydrodealkylation'), '—', 'Aromatic growth routes'),
                ('Coking reactions',   'N_ck', _cnt('Coking'),                 '—', 'Coke-forming reactions'),
                ('Radical reactions',  'N_rad',_cnt('Radical') + _cnt('Beta_Scission') + _cnt('Initiation'), '—', 'Free-radical sub-network'),
            ]
            for nm, sy, vl, un, dc in rs:
                val_s = vl if isinstance(vl, str) else _f(vl, '.0f')
                tag = _tag(idx[0])
                _ins(tv1, (nm, sy, val_s, un, dc), tag); idx[0] += 1
        except Exception as e:
            _err(tv1, '§10 Rxn Stats', e)

        # §11 Geometry ────────────────────────────────────────────────────────
        try:
            _spc(tv1); _hdr(tv1, '── §11. TUBE GEOMETRY & DESIGN ──')
            Ac_m2  = np.pi * (tube_id / 2.) ** 2
            t_wall = (tube_od - tube_id) / 2.
            V_coil = Ac_m2 * L_total
            gm = [
                ('Tube ID',            'D_i',   tube_id * 1e3,                  'mm',    'Inner diameter (clean)'),
                ('Tube OD',            'D_o',   tube_od * 1e3,                  'mm',    'Outer diameter'),
                ('Wall thickness',     't_w',   t_wall * 1e3,                   'mm',    '(D_o − D_i) / 2'),
                ('Flow area',          'A_c',   Ac_m2,                          'm²',    'π D_i² / 4'),
                ('Flow area',          'A_c',   Ac_m2 * 1e4,                    'cm²',   'Same in cm²'),
                ('Passes',             'N_p',   n_pass,                         '—',     'Straight passes per coil'),
                ('Pass length',        'L_p',   L_pass,                         'm',     'Length per pass'),
                ('Total coil length',  'L',     L_total,                        'm',     'Developed length'),
                ('L/D ratio',          'L/D',   L_total / max(tube_id, 1e-9),   '—',     'Slenderness ratio'),
                ('Coil inner volume',  'V_c',   V_coil,                         'm³',    'A_c × L (one coil)'),
                ('Coil inner volume',  'V_c',   V_coil * 1e3,                   'L',     'Same in litres'),
                ('Number of bends',    'N_b',   max(n_pass - 1, 0),             '—',     '180° return bends'),
                ('Roughness',          'ε_r',   geom.get('roughness', 4.5e-4) * 1e6, 'μm','Pipe roughness (Churchill)'),
                ('Emissivity',         'ε',     geom.get('emissivity', 0.75),   '—',     'Outer surface emissivity'),
                ('k_tube',             'k_t',   geom.get('k_tube', 25.),        'W/mK',  'Tube metal conductivity'),
                ('k_coke',             'k_c',   geom.get('k_coke', 1.0),        'W/mK',  'Coke layer conductivity'),
                ('Heat flux profile',  'q(z)',  str(geom.get('heat_flux_profile', 'uniform')), '—', 'Flux shape'),
                ('Profile amplitude',  'A_q',   geom.get('profile_amplitude_K', 0.), 'K','Flux profile amplitude'),
                ('k_heat (tuning)',    'k_h',   geom.get('k_heat', 1.0),        '—',     'Heat flux multiplier'),
                ('k_dp (tuning)',      'k_dp',  geom.get('k_dp', 1.0),          '—',     'Pressure drop multiplier'),
            ]
            for nm, sy, vl, un, dc in gm:
                val_s = vl if isinstance(vl, str) else _f(vl)
                tag = _tag(idx[0]); _ins(tv1, (nm, sy, val_s, un, dc), tag); idx[0] += 1
        except Exception as e:
            _err(tv1, '§11 Geometry', e)

        # §12 Solver Settings ─────────────────────────────────────────────────
        try:
            _spc(tv1); _hdr(tv1, '── §12. SOLVER & KINETIC TUNING ──')
            n_nodes = len(sol.t) if sol is not None else 0
            sv_rows = [
                ('ODE method',         'method',str(self.v_solver.get()),       '—',     'scipy.solve_ivp algorithm'),
                ('Rel. tolerance',     'rtol',  self.v_rtol.get(),              '—',     'ODE relative tolerance'),
                ('Abs. tolerance',     'atol',  self.v_atol.get(),              '—',     'ODE absolute tolerance'),
                ('Tuner — paraffin',   'k_p',   self.v_tp.get(),                '—',     'Paraffin/iso/ring A factor'),
                ('Tuner — olefin',     'k_o',   self.v_to.get(),                '—',     'Olefin cracking A factor'),
                ('Tuner — aromatic',   'k_a',   self.v_ta.get(),                '—',     'Condensation/PAH A factor'),
                ('Tuner — coke',       'k_c',   self.v_tc.get(),                '—',     'Coke kinetics A factor'),
                ('Tube alloy',         'metal', str(self.v_metal.get()),        '—',     'Metallurgy selection'),
                ('DMDS additive',      'DMDS',  str(bool(self.v_dmds.get())),   '—',     'Sulfur passivation active'),
                ('Axial ODE nodes',    'N_z',   n_nodes,                        '—',     'Integration points in solution'),
            ]
            for nm, sy, vl, un, dc in sv_rows:
                val_s = vl if isinstance(vl, str) else _f(vl)
                tag = _tag(idx[0]); _ins(tv1, (nm, sy, val_s, un, dc), tag); idx[0] += 1
        except Exception as e:
            _err(tv1, '§12 Solver', e)

        # ════════════════════════════════════════════════════════════════════
        # ②  SPECIES OUTLET TABLE
        # ════════════════════════════════════════════════════════════════════
        try:
            tv2 = self._var_tv_sp
            if _have_arrays and ns > 0:
                F_o_sp = np.maximum(sol.y[:ns, -1], 1e-8)
                T_o_sp = float(np.clip(sol.y[ns, -1], 600., 1450.))
                P_o_sp = float(np.clip(sol.y[ns+1, -1], 1e4, 8e5))
                Ft_o_sp= float(F_o_sp.sum())
                mw_o_sp= float(np.dot(F_o_sp, eng._mw) / Ft_o_sp)
                Z_o_sp = eng._compressibility_Z(T_o_sp, P_o_sp, mw_o_sp)
                C_tot  = P_o_sp / (Z_o_sp * R_GAS * T_o_sp)   # mol/m³
                sp_idx = eng.sp_idx
            else:
                C_tot = 0.; sp_idx = {}

            for j, row in enumerate(table):
                sp_nm = row.get('Species', '')
                si    = sp_idx.get(sp_nm)
                if si is not None and _have_arrays:
                    y_i = float(F_o_sp[si] / max(Ft_o_sp, 1e-30))
                    C_i = y_i * C_tot
                else:
                    C_i = 0.
                # table['mol_s'] / ['mass_gs'] are per-FURNACE (spyro_metrics × coils)
                # Divide by coils_n for the per-coil columns
                mol_s_fce    = row.get('mol_s',   0.)          # per-furnace mol/s
                mass_gs_fce  = row.get('mass_gs', 0.)          # per-furnace g/s
                mol_s_coil   = mol_s_fce  / max(coils_n, 1)   # per-coil mol/s
                mass_gs_coil = mass_gs_fce / max(coils_n, 1)  # per-coil g/s
                net_kgh      = mass_gs_fce * 3.6               # network kg/h (per-furnace already)
                sel_gg       = row.get('g_100g_conv', 0.) / 100.
                tag = 'even' if j % 2 == 0 else 'odd'
                wt_dry = row.get('wt_pct_dry', 0.)
                if wt_dry > 10.:  tag = 'warn'
                if sp_nm in ('C2H4', 'C3H6', 'C4H6', 'C6H6'): tag = 'good'
                _ins(tv2, (
                    sp_nm,
                    f"{row.get('MW', 0.):.3f}",
                    f"{mol_s_coil:.5g}",       # per-coil mol/s  (= total/N_coils)
                    f"{mass_gs_coil:.5g}",     # per-coil g/s
                    f"{net_kgh:.4g}",          # network kg/h  (all coils combined)
                    f"{C_i:.4g}",
                    f"{row.get('g_100g_feed', 0.):.3f}",
                    f"{row.get('g_100g_conv', 0.):.3f}",
                    f"{row.get('mol_pct_dry', 0.):.3f}",
                    f"{wt_dry:.3f}",
                    f"{row.get('mol_pct_wet', 0.):.3f}",
                    f"{row.get('wt_pct_wet', 0.):.3f}",
                    f"{sel_gg:.4f}",
                ), tag)
        except Exception as e:
            _err(self._var_tv_sp, '② Species section', e, ncols=13)

        # ════════════════════════════════════════════════════════════════════
        # ③④⑤  AXIAL PROFILES  — sample up to 50 nodes
        # ════════════════════════════════════════════════════════════════════
        ax_data = []
        try:
            if _have_arrays and eng is not None:
                n_nodes = len(z_all)
                step    = max(1, n_nodes // 50)
                indices = list(range(0, n_nodes, step))
                if indices[-1] != n_nodes - 1:
                    indices.append(n_nodes - 1)

                for j, idx_n in enumerate(indices):
                    z   = float(z_all[idx_n])
                    T_K = float(T_all_K[idx_n])
                    P   = float(P_all_Pa[idx_n])
                    tau = float(tau_all[idx_n])
                    F   = F_all[:, idx_n]
                    Ft  = float(F.sum())
                    y_mol= F / max(Ft, 1e-30)
                    mw_g = float(np.dot(F, eng._mw) / max(Ft, 1e-30))
                    mw_kg= mw_g / 1000.
                    Z    = eng._compressibility_Z(T_K, P, mw_g)
                    rho  = P * mw_kg / (Z * R_GAS * T_K)
                    vel  = (Ft * mw_kg) / max(rho * eng.Ac, 1e-9)
                    G    = rho * vel
                    mu   = eng._viscosity(y_mol, T_K)
                    k_th = eng._conductivity(y_mol, T_K)
                    Cp_i = np.maximum(eng._cpA + eng._cpB*T_K + eng._cpC*T_K**2 + eng._cpD*T_K**3, 10.)
                    Cp_mol = float(np.dot(y_mol, Cp_i))
                    Cp_mass= Cp_mol / mw_kg
                    Re   = float(re_all[idx_n]) if idx_n < len(re_all) else (rho*vel*eng.tube_id/max(mu, 1e-12))
                    Pr   = float(pr_all[idx_n]) if idx_n < len(pr_all) else (mu*Cp_mass/max(k_th, 1e-10))
                    eps_D= eng.roughness / eng.tube_id
                    f_D  = eng._churchill_f(Re, eps_D)
                    Nu   = max((f_D/8.)*(max(Re,3000.)-1000.)*Pr / (1.+12.7*np.sqrt(f_D/8.)*(Pr**(2./3.)-1.)), 3.66)
                    hi   = float(hi_all[idx_n]) if idx_n < len(hi_all) else Nu * k_th / eng.tube_id
                    # Local conversion
                    hc_local = sum(F[eng.sp_idx[sp]] * get_mw(sp) for sp in fc if sp in eng.sp_idx) if fc else 0.
                    hc_in_1c = sum(feed.get(sp, 0.) * get_mw(sp) for sp in fc) / max(coils_n, 1) if fc else 1.
                    X_loc = max(0., (hc_in_1c - hc_local) / max(hc_in_1c, 1e-9) * 100.)
                    # q_ext + TMT (lightweight: avoid Newton loop, use T+40 estimate)
                    T_sk  = T_K + 40.
                    q_ext_Wm2 = eng._q_outer(z, T_sk)
                    q_lin_W   = q_ext_Wm2 * np.pi * eng.tube_od * eng.k_heat
                    _, T_skin_K, _ = eng._tmt_resistance_chain(q_lin_W, T_K, hi, z)
                    tmt_C = T_skin_K - 273.15
                    q_lin_kW = q_lin_W / 1e3
                    dPdz  = -(f_D * G**2) / (2. * rho * eng.tube_id)
                    ax_data.append({
                        'z': z, 'T_C': T_K - 273.15, 'P_bar': P/1e5,
                        'tau_ms': tau*1e3, 'Re': Re, 'Pr': Pr, 'hi': hi,
                        'vel': vel, 'mu_uPas': mu*1e6, 'Z': Z,
                        'q_ext_kWm2': q_ext_Wm2/1e3, 'TMT_C': tmt_C,
                        'rho': rho, 'mw_g': mw_g, 'Cp_mol': Cp_mol,
                        'Cp_mass': Cp_mass, 'k_th': k_th, 'G': G,
                        'f_D': f_D, 'Nu': Nu, 'X_loc': X_loc, 'Ft': Ft,
                        'q_lin_kW': q_lin_kW, 'T_skin_C': tmt_C, 'dPdz': dPdz,
                        'y_mol': y_mol,
                    })
        except Exception as e:
            _err(self._var_tv_ax, '③ Axial pre-compute', e, ncols=12)

        # ③ Transport ─────────────────────────────────────────────────────────
        try:
            for j, d in enumerate(ax_data):
                tag = 'even' if j % 2 == 0 else 'odd'
                if d['TMT_C'] > 950:  tag = 'warn'
                if d['TMT_C'] > 1050: tag = 'alert'
                _ins(self._var_tv_ax, (
                    f"{d['z']:.3f}",      f"{d['T_C']:.1f}",
                    f"{d['P_bar']:.4f}",  f"{d['tau_ms']:.2f}",
                    f"{d['Re']:.0f}",     f"{d['Pr']:.4f}",
                    f"{d['hi']:.0f}",     f"{d['vel']:.2f}",
                    f"{d['mu_uPas']:.3f}",f"{d['Z']:.5f}",
                    f"{d['q_ext_kWm2']:.3f}", f"{d['TMT_C']:.1f}",
                ), tag)
        except Exception as e:
            _err(self._var_tv_ax, '③ Transport fill', e, ncols=12)

        # ④ Thermodynamics ────────────────────────────────────────────────────
        try:
            for j, d in enumerate(ax_data):
                tag = 'even' if j % 2 == 0 else 'odd'
                _ins(self._var_tv_ax2, (
                    f"{d['z']:.3f}",      f"{d['rho']:.4f}",
                    f"{d['mw_g']:.3f}",   f"{d['Cp_mol']:.2f}",
                    f"{d['Cp_mass']:.1f}",f"{d['k_th']:.4f}",
                    f"{d['G']:.2f}",      f"{d['f_D']:.5f}",
                    f"{d['Nu']:.1f}",     f"{d['X_loc']:.2f}",
                    f"{d['Ft']:.5g}",     f"{d['q_lin_kW']:.3f}",
                    f"{d['T_skin_C']:.1f}",f"{d['dPdz']:.1f}",
                ), tag)
        except Exception as e:
            _err(self._var_tv_ax2, '④ Thermo fill', e, ncols=14)

        # ⑤ Species mole fractions ────────────────────────────────────────────
        try:
            if ax_data and eng is not None:
                # Pick top-10 species by outlet mole fraction
                y_last = ax_data[-1]['y_mol']
                sp_ranked = sorted(
                    [(i, eng.species_list[i], y_last[i])
                     for i in range(ns) if eng.species_list[i] != 'COKE'],
                    key=lambda t: -t[2])[:10]
                top_idx  = [t[0] for t in sp_ranked]
                top_nms  = [t[1] for t in sp_ranked]
                # Re-label columns
                new_cols = ('z [m]', 'T [°C]') + tuple(f'{nm}\n[mol%]' for nm in top_nms)
                while len(new_cols) < 12:
                    new_cols += (f'sp{len(new_cols)-1}\n[mol%]',)
                for col_id, col_name in zip(self._var_tv_ax3['columns'], new_cols):
                    self._var_tv_ax3.heading(col_id, text=col_name)
                for j, d in enumerate(ax_data):
                    y = d['y_mol']
                    vals = [f"{d['z']:.3f}", f"{d['T_C']:.1f}"]
                    for k in range(10):
                        vals.append(f"{y[top_idx[k]]*100.:.3f}" if k < len(top_idx) else '—')
                    _ins(self._var_tv_ax3, tuple(vals), 'even' if j % 2 == 0 else 'odd')
        except Exception as e:
            _err(self._var_tv_ax3, '⑤ Species fractions', e, ncols=12)

        # ════════════════════════════════════════════════════════════════════
        # ⑥  REACTION NETWORK STATISTICS
        # ════════════════════════════════════════════════════════════════════
        try:
            tv6 = self._var_tv_rxn
            rxn_lst = eng.reactions if eng else rxns
            type_map = {}
            for r in rxn_lst:
                t = r.get('type', 'Other')
                type_map.setdefault(t, []).append(r)
            type_desc = {
                'Paraffin_Crack':    'C–C scission of n-paraffin chains',
                'Iso_Crack':         'C–C scission of iso-paraffins (β-scission)',
                'Ring_Opening':      'Naphthene ring-opening to olefin',
                'Olefin_Crack':      'Secondary cracking of olefins',
                'Condensation':      'Olefin/diene condensation to aromatics',
                'PAH_Growth':        'HACA / polycyclic aromatic growth',
                'Hydrodealkylation': 'Aromatic side-chain cracking',
                'Coking (Catalytic)':'Fe/Ni surface-site coking (low-T)',
                'Coking (Pyrolytic)':'Gas-phase radical coking (high-T)',
                'Coking':            'Generic coke laydown',
                'Radical':           'Free-radical (Rice-Herzfeld) step',
                'Beta_Scission':     'β-scission of alkyl radical',
                'Initiation':        'Pressure-dependent initiation',
                'H_Abstraction':     'H-atom abstraction by radical',
                'Termination':       'Radical chain termination',
                'Isomerization':     'Structural isomerization',
                'Recombination':     'Radical-radical recombination',
            }
            for ti, (tname, rxs) in enumerate(
                    sorted(type_map.items(), key=lambda x: -len(x[1]))):
                As  = [r.get('A', 0) for r in rxs if r.get('A', 0) > 0]
                Eas = [r.get('Ea', 0) for r in rxs]
                lA_mn = f"{np.log10(min(As)):.2f}"  if As  else '—'
                lA_mx = f"{np.log10(max(As)):.2f}"  if As  else '—'
                Ea_mn = f"{min(Eas)/1000.:.1f}"      if Eas else '—'
                Ea_mx = f"{max(Eas)/1000.:.1f}"      if Eas else '—'
                desc  = type_desc.get(tname, '—')
                _ins(tv6, (tname, len(rxs), lA_mn, lA_mx, Ea_mn, Ea_mx, desc),
                     'even' if ti % 2 == 0 else 'odd')
            _ins(tv6, ('TOTAL', len(rxn_lst), '—', '—', '—', '—',
                       f'{ft} — {ns} species'), 'header')
        except Exception as e:
            _err(self._var_tv_rxn, '⑥ Rxn Network', e, ncols=7)

        # ── Update stats label & apply filter ────────────────────────────────
        try:
            n_total = sum(len(tv.get_children()) for tv in self._var_trees)
            self._var_stats_lbl.config(
                text=f'{n_total} variables across 6 sections')
        except Exception:
            pass
        self._vars_apply_filter()

    def _vars_apply_filter(self):
        """Show/hide rows in all three trees based on the search string."""
        if not hasattr(self, '_var_trees'):
            return
        term = self._var_search.get().lower().strip()
        for tv, rid, values in self._var_all_rows:
            try:
                if not term or any(term in str(v).lower() for v in values):
                    tv.reattach(rid, '', 'end')
                else:
                    tv.detach(rid)
            except Exception:
                pass

    def _vars_copy_tsv(self):
        """Copy all visible rows from all three trees to the clipboard as TSV."""
        if not hasattr(self, '_var_trees'):
            return
        lines = []
        for tv in self._var_trees:
            cols = tv['columns']
            lines.append('\t'.join(str(c) for c in cols))
            for rid in tv.get_children():
                vals = tv.item(rid, 'values')
                lines.append('\t'.join(str(v) for v in vals))
            lines.append('')
        tsv = '\n'.join(lines)
        self.root.clipboard_clear()
        self.root.clipboard_append(tsv)

    def _vars_export_csv(self):
        """Export all visible rows from all 6 variable trees to a CSV file."""
        if not hasattr(self, '_var_trees'):
            return
        from tkinter import filedialog
        import csv
        fp = filedialog.asksaveasfilename(
            title='Export all variables to CSV',
            defaultextension='.csv',
            filetypes=[('CSV files', '*.csv'), ('All files', '*.*')])
        if not fp:
            return
        try:
            section_names = [
                '①  Process & Thermodynamic KPIs',
                '②  Species Outlet Flows & Yields',
                '③  Axial Profile — Transport',
                '④  Axial Profile — Thermodynamics',
                '⑤  Axial Profile — Species Mole Fractions',
                '⑥  Reaction Network Statistics',
            ]
            with open(fp, 'w', newline='', encoding='utf-8-sig') as f:
                w = csv.writer(f)
                for sec, tv in zip(section_names, self._var_trees):
                    w.writerow([f'## SECTION {sec} ##'])
                    w.writerow(tv['columns'])
                    for rid in tv.get_children():
                        w.writerow(tv.item(rid, 'values'))
                    w.writerow([])
            try:
                self.v_status.set(f'✓ Variables exported → {fp}')
            except Exception:
                pass
        except Exception as e:
            try:
                from tkinter import messagebox
                messagebox.showerror('Export failed', str(e))
            except Exception:
                pass

    def _update_kpis(self, k):
        def put(key, val, warn_fn=None):
            if key not in self.kpi_labels: return
            lbl = self.kpi_labels[key]
            lbl.config(text=val)
            # Simple traffic-light colouring on key metrics
            if warn_fn:
                try:
                    fg = lbl.cget('fg') if isinstance(lbl, tk.Label) else None
                except Exception: pass
        put('COT',     f"{k['COT_C']:.1f}")
        # Combined COT from multi-coil mode (or same as COT in single mode)
        mc_mode = getattr(self, 'v_mc_enabled', None) and self.v_mc_enabled.get()
        if mc_mode:
            comb = self._mc_combined_cot_var.get()
            put('combined_cot', comb if comb else f"{k['COT_C']:.1f}")
        else:
            put('combined_cot', f"{k['COT_C']:.1f}")
        put('conv',    f"{k['actual_conv']*100:.2f}")
        put('firebox', f"{k['Firebox_C']:.1f}")
        put('dP',      f"{k['dP_atm']:.3f}")
        put('heat',    f"{k['heat_duty_kW']:.1f}")
        put('tau',     f"{k['tau_ms']:.1f}")
        put('Re',      f"{k['Re_out']:.0f}")
        put('Pr',      f"{k['Pr_out']:.3f}")
        put('hi',      f"{k['hi_out']:.0f}")
        put('tmt',     f"{k['tmt_max_C']:.1f}")
        put('PE',      f"{k['pe_ratio']:.3f}")
        put('H2CH4',   f"{k['h2ch4']:.3f}")
        put('C2H4',    f"{k['eth_yield']:.2f}")
        put('C3H6',    f"{k['pro_yield']:.2f}")
        put('BTX',     f"{k['btx_yield']:.2f}")
        put('C4s',     f"{k['c4_yield']:.2f}")
        put('coke_y',  f"{k['coke_yield']:.3f}")
        put('CPR',     f"{k.get('coil_pressure_ratio', k.get('CPR', 0.0)):.4f}")
        put('coke_a',  f"{k['avg_coke_kg']:.4f}")
        put('coke_m',  f"{k['max_coke_kg']:.4f}")
        # Traffic-light TMT
        if 'tmt' in self.kpi_labels:
            tmt_val = k['tmt_max_C']
            clr = '#DC2626' if tmt_val > 1000 else ('#D97706' if tmt_val > 950 else '#15803D')
            self.kpi_labels['tmt'].config(fg=clr)
        # Traffic-light COT
        if 'COT' in self.kpi_labels:
            cot_val = k['COT_C']
            clr = '#DC2626' if cot_val > 920 else ('#D97706' if cot_val > 890 else '#1D4ED8')
            self.kpi_labels['COT'].config(fg=clr)
        # Traffic-light Combined COT
        if 'combined_cot' in self.kpi_labels:
            try:
                cc_val = float(self._mc_combined_cot_var.get())
                clr = '#DC2626' if cc_val > 920 else ('#D97706' if cc_val > 890 else '#7C3AED')
                self.kpi_labels['combined_cot'].config(fg=clr)
            except Exception:
                pass


    # ─── Profile tube selector helpers ───────────────────────────────────────

    def _update_profile_tube_selector(self, coil_results):
        """Populate the tube/coil combobox after a simulation run."""
        if not coil_results:
            # Single-coil mode — reset selector
            self._all_coil_results = []
            self._profile_tube_cb['values'] = ['Coil 1 (Primary)']
            self._profile_tube_var.set('Coil 1 (Primary)')
            return
        self._all_coil_results = coil_results
        options = []
        for cr in coil_results:
            if not cr.get('active'):
                continue
            if cr.get('error'):
                options.append(f'Coil {cr["coil"]} ({cr.get("ft","?")}) ⚠ error')
            else:
                options.append(f'Coil {cr["coil"]} ({cr.get("ft","?")})')
        if not options:
            options = ['Coil 1 (Primary)']
        self._profile_tube_cb['values'] = options
        # Default to first valid coil
        self._profile_tube_var.set(options[0])

    def _on_profile_tube_select(self):
        """Re-draw plots for the selected coil when user clicks Show."""
        sel = self._profile_tube_var.get()
        # Parse coil index from selection string e.g. 'Coil 3 (LPG)'
        try:
            coil_idx = int(sel.split()[1]) - 1  # 0-based
        except Exception:
            coil_idx = 0

        if not self._all_coil_results:
            # Single-coil mode — just redraw current data
            if self._last_result is not None:
                self._update_plots(self._last_result)
            return

        # Find matching coil result
        target = None
        active_valid = [cr for cr in self._all_coil_results
                        if cr.get('active') and not cr.get('error') and 'sol' in cr]
        if 0 <= coil_idx < len(self._all_coil_results):
            cr = self._all_coil_results[coil_idx]
            if cr.get('active') and not cr.get('error') and 'sol' in cr:
                target = cr
        if target is None and active_valid:
            target = active_valid[0]
        if target is None:
            return

        # Build a result dict compatible with _update_plots
        if 'tp' not in target:
            target['tp'] = target['eng'].transport_profiles(target['sol'])
        if 'ck_z' not in target:
            target['ck_z'], target['ck_p'] = target['eng'].coking_profile(target['sol'])
        if 'kpis' not in target:
            return
        if 'rxns' not in target:
            target['rxns'] = []
        if 'ft' not in target:
            target['ft'] = '?'
        self._update_plots(target)

    def _update_plots(self, R):
        sol=R['sol']; eng=R['eng']; tp=R['tp']
        ck_z=R['ck_z']; ck_p=R['ck_p']; geom=R['geom']
        z=sol.t; T=sol.y[eng.num_species]-273.15
        P=sol.y[eng.num_species+1]/101325.
        tau_ms=sol.y[eng.num_species+2]*1000.
        coils=geom['coils']; Lp=geom['length_per_pass']; passes=geom['passes']
        def fy(sp): return sol.y[eng.sp_idx[sp]]*coils if sp in eng.sp_idx else np.zeros_like(z)

        ax=self._axes; atw=self._ax_twin
        for a in ax: a.cla(); a.set_facecolor('#FFFFFF')
        for a in atw:
            if a is not None: a.cla()

        CE='#2563EB'; CP='#F97316'; CG='#16A34A'; CV='#7C3AED'
        CB='#92400E'; CD='#DB2777'; CT='#DC2626'; CPR='#1D4ED8'
        CK='#7C2D12'; CTU='#0D9488'; CRE='#1E3A5F'; CHI='#B45309'

        def _vlines(a):
            for p in range(1,passes):
                a.axvline(p*Lp,color='#CBD5E0',ls='--',lw=0.9,alpha=0.5,zorder=0)

        # ── Plot 1: Key Product Yields ────────────────────────────────────────
        a0=ax[0]
        _sp=[('C2H4',CE,'C₂H₄',2.6),('C3H6',CP,'C₃H₆',2.3),('C6H6',CG,'C₆H₆',1.8),
             ('H2',CV,'H₂',1.8),('CH4',CB,'CH₄',1.8),('C4H6',CD,'C₄H₆',1.6)]
        for sp,clr,lbl,lw in _sp:
            if sp in eng.sp_idx: a0.plot(z,fy(sp),lw=lw,color=clr,label=lbl)
        if 'C2H4' in eng.sp_idx: a0.fill_between(z,fy('C2H4'),alpha=0.07,color=CE)
        a0.set_ylabel('Flow (mol/s)')
        a0.set_title(f"{R['ft']} Steam Cracker — Key Product Yields Along Tube")
        a0.legend(ncol=3,loc='upper left',framealpha=0.93,edgecolor='#E2E8F0')
        a0.text(0.98,0.97,f"Conversion = {R['kpis']['actual_conv']*100:.1f}%",
                transform=a0.transAxes,ha='right',va='top',fontsize=8.5,
                color='#1D4ED8',bbox=dict(boxstyle='round,pad=0.4',fc='#EFF6FF',ec='#93C5FD',lw=0.9))
        _vlines(a0)

        # ── Plot 2: Temperature & Pressure ────────────────────────────────────
        a1=ax[1]; a1b=atw[1]
        a1.plot(z,T,color=CT,lw=2.6,label='Gas Temp T')
        a1.fill_between(z,T,T.min(),alpha=0.08,color=CT)
        a1b.plot(z,P,color=CPR,lw=1.9,ls='--',alpha=0.9,label='Pressure P')
        cot=T[-1]
        a1.annotate(f'COT = {cot:.1f}°C',xy=(z[-1],cot),xytext=(-55,14),
                    textcoords='offset points',fontsize=8.5,color=CT,fontweight='bold',
                    arrowprops=dict(arrowstyle='->',color=CT,lw=1.2),
                    bbox=dict(boxstyle='round,pad=0.3',fc='#FEF2F2',ec=CT,lw=0.8))
        a1.set_ylabel('Temperature (°C)',color=CT)
        a1b.set_ylabel('Pressure (atm)',color=CPR)
        a1.tick_params(axis='y',labelcolor=CT)
        a1b.tick_params(axis='y',labelcolor=CPR)
        a1.set_title('Temperature & Pressure Profile')
        _vlines(a1); _vlines(a1b)
        h1,l1=a1.get_legend_handles_labels(); h2,l2=a1b.get_legend_handles_labels()
        a1.legend(h1+h2,l1+l2,loc='upper left',framealpha=0.93)

        # ── Plot 3: Coking & Residence Time ───────────────────────────────────
        a2=ax[2]; a2b=atw[2]
        a2.fill_between(ck_z,ck_p,alpha=0.22,color=CK)
        a2.plot(ck_z,ck_p,color=CK,lw=2.2,label='Coking rate')
        if len(ck_p):
            idx_max=int(np.argmax(ck_p))
            a2.scatter([ck_z[idx_max]],[ck_p[idx_max]],color=CK,s=55,zorder=5)
            a2.annotate(f'max {ck_p[idx_max]:.4f}',xy=(ck_z[idx_max],ck_p[idx_max]),
                        xytext=(8,6),textcoords='offset points',fontsize=7.5,color=CK,
                        bbox=dict(boxstyle='round,pad=0.3',fc='#FFF7ED',ec=CK,lw=0.8))
        a2b.plot(z,tau_ms,color=CTU,lw=1.9,ls='--',alpha=0.9,label='τ residence')
        a2b.fill_between(z,tau_ms,alpha=0.06,color=CTU)
        a2.set_ylabel('Coking  [kg/(m²·h)]',color=CK)
        a2b.set_ylabel('Residence time τ (ms)',color=CTU)
        a2.tick_params(axis='y',labelcolor=CK)
        a2b.tick_params(axis='y',labelcolor=CTU)
        a2.set_title('Coking Rate & Residence Time')
        _vlines(a2)
        h1,l1=a2.get_legend_handles_labels(); h2,l2=a2b.get_legend_handles_labels()
        a2.legend(h1+h2,l1+l2,loc='upper left',framealpha=0.93)

        # ── Plot 4: Re & h_i ──────────────────────────────────────────────────
        a3=ax[3]; a3b=atw[3]
        Rek=tp['Re']/1000.
        a3.plot(z,Rek,color=CRE,lw=2.4,label='Re (×10³)')
        a3.fill_between(z,Rek,alpha=0.07,color=CRE)
        a3b.plot(z,tp['h_i'],color=CHI,lw=1.9,ls='--',alpha=0.9,label='h_i [W/m²K]')
        Pr_out=float(tp['Pr'][-1]) if 'Pr' in tp else float('nan')
        a3.annotate(f"Re_out={tp['Re'][-1]:.0f}\nPr={Pr_out:.2f}",
                    xy=(z[-1],Rek[-1]),xytext=(-80,-28),textcoords='offset points',
                    fontsize=7.5,color=CRE,
                    arrowprops=dict(arrowstyle='->',color='#93C5FD',lw=1.0),
                    bbox=dict(boxstyle='round,pad=0.4',fc='#EFF6FF',ec='#93C5FD',lw=0.9))
        a3.set_ylabel('Re (×10³)',color=CRE)
        a3b.set_ylabel('h_i  [W/(m²·K)]',color=CHI)
        a3.tick_params(axis='y',labelcolor=CRE)
        a3b.tick_params(axis='y',labelcolor=CHI)
        a3.set_xlabel('Tube Length  z (m)')
        a3.set_title('Reynolds Number & Heat-Transfer Coefficient (Gnielinski)')
        _vlines(a3)
        h1,l1=a3.get_legend_handles_labels(); h2,l2=a3b.get_legend_handles_labels()
        a3.legend(h1+h2,l1+l2,loc='lower right',framealpha=0.93)

        self._canvas.draw_idle()


    def _refresh_products(self):
        if self._last_result is None: return
        table = self._last_result['table']
        is_dry = (self.v_basis.get() == 'dry')
        key = 'wt_pct_dry' if is_dry else 'wt_pct_wet'

        for iid in self.prod_tree.get_children():
            self.prod_tree.delete(iid)

        for d in sorted(table, key=lambda x: -x[key]):
            if d['g_100g_feed'] < 0.001 and not d['is_steam']: continue
            if is_dry:
                row = (d['Species'], f"{d['MW']:.2f}", f"{d['mol_s']:.5f}",
                       f"{d['g_100g_feed']:.3f}", f"{d['g_100g_conv']:.3f}",
                       f"{d['mol_pct_dry']:.3f}", f"{d['wt_pct_dry']:.3f}")
            else:
                row = (d['Species'], f"{d['MW']:.2f}", f"{d['mol_s']:.5f}",
                       f"{d['g_100g_feed']:.3f}", '',
                       f"{d['mol_pct_wet']:.3f}", f"{d['wt_pct_wet']:.3f}")
            self.prod_tree.insert('', tk.END, values=row)

    def _update_balance(self, bal):
        for iid in self.bal_tree.get_children():
            self.bal_tree.delete(iid)
        def ok(v): return f"{'✅' if 99.<=v<=101. else '⚠️'} {v:.4f}%"
        for q, ki, ko, cls in [
            ('Carbon   (mol C/s)', f"{bal['C_in']:.6f}", f"{bal['C_out']:.6f}", ok(bal['C_cls'])),
            ('Hydrogen (mol H/s)', f"{bal['H_in']:.6f}", f"{bal['H_out']:.6f}", ok(bal['H_cls'])),
            ('Oxygen   (mol O/s)', f"{bal['O_in']:.6f}", f"{bal['O_out']:.6f}", ok(bal['O_cls'])),
            ('Total mass   (g/s)', f"{bal['mass_in']:.4f}", f"{bal['mass_out']:.4f}", ok(bal['mass_cls'])),
        ]:
            self.bal_tree.insert('', tk.END, values=(q, ki, ko, cls))
        worst = min(bal['C_cls'], bal['H_cls'], bal['O_cls'], bal['mass_cls'])
        if worst >= 99.:
            self.bal_health.config(
                text=f'✅  All balances within 1% — good ODE convergence (worst: {worst:.4f}%).',
                foreground='darkgreen')
        else:
            self.bal_health.config(
                text=f'⚠  Worst closure {worst:.2f}% — tighten rtol/atol in ⑤ Solver.',
                foreground='darkorange')

    def _update_reactions(self, rxns, ft):
        for iid in self.rxn_tree.get_children():
            self.rxn_tree.delete(iid)
        for i, rxn in enumerate(rxns, 1):
            cat = rxn.get('type', '')
            tag = ('Coking' if 'Coking' in cat else
                   'Steam'  if any(x in cat for x in ['Steam', 'Gasif', 'Shift', 'Reforming']) else
                   cat)
            order = sum(rxn['reactants'].values())
            self.rxn_tree.insert('', tk.END, values=(
                i, cat, _fmt_rxn(rxn),
                f"{rxn['A']:.3e}", f"{rxn['Ea']/1000:.1f}",
                f"{order:.1f}"
            ), tags=(tag,))
        self.rxn_header.config(text=(
            f'{ft} feed  │  {len(rxns)} reactions loaded  │  '
            f'Metallurgy: {self.v_metal.get()}  │  '
            f'DMDS: {"ON" if self.v_dmds.get() else "OFF"}  │  '
            f'Tuning: k_p={self.v_tp.get():.2f}, k_o={self.v_to.get():.2f}, '
            f'k_a={self.v_ta.get():.2f}, k_coke={self.v_tc.get():.2f}'
        ))

    def _update_validation(self, ft, table):
        """
        Called after every normal simulation to auto-populate the validation tab
        with the first (primary) dataset for the current feed type.
        The user can switch datasets and re-run via the ▶ Run Validation button.
        """
        feed = ft.lower()
        ds_dict = VALIDATION.get(feed, {})
        if not ds_dict:
            return
        # Select first dataset as the auto-shown reference
        first_id = list(ds_dict.keys())[0]
        # Update the feed/dataset selectors silently
        if hasattr(self, '_val_feed_var'):
            self._val_feed_var.set(feed)
            all_ids = list(ds_dict.keys())
            if hasattr(self, '_val_ds_cb'):
                self._val_ds_cb['values'] = all_ids
            if hasattr(self, '_val_ds_var'):
                self._val_ds_var.set(first_id)

        ds  = ds_dict[first_id]
        ref = ds.get('ref', {})
        model = {d['Species']: d['wt_pct_dry'] for d in table if not d['is_steam']}

        # Quick yield RMSE for the primary dataset
        errs = [(model.get(sp, 0.) - rv)**2 for sp, rv in ref.items()]
        rmse = (sum(errs)/max(len(errs),1))**0.5

        # Populate yield treeview (same tree, legacy path)
        for iid in self.val_tree.get_children():
            self.val_tree.delete(iid)

        self.val_tree.insert('', 'end',
            values=(f'Auto-ref: {first_id}','','','','',''),
            tags=('sep',))
        tol = ds.get('tol_pp', 5.0)
        n_pass = n_total = 0
        for sp in sorted(ref, key=lambda s: -ref[s]):
            rv = ref[sp]; mv = model.get(sp, 0.)
            dp = mv - rv; dpct = dp/max(rv,0.1)*100.
            ok = abs(dp) <= tol; n_total += 1
            if ok: n_pass += 1
            tag = 'pass' if ok else ('warn' if abs(dp) < 2*tol else 'fail')
            self.val_tree.insert('', tk.END,
                values=(sp, f'{rv:.2f}', f'{mv:.2f}',
                        f'{dp:+.2f}', f'{dpct:+.1f}%',
                        '✓' if ok else '✗'),
                tags=(tag,))

        # Update RMSE label
        if hasattr(self, '_val_rmse_var'):
            clr = 'darkgreen' if rmse < 3 else ('darkorange' if rmse < 6 else 'red')
            ico = '✅' if rmse < 3 else ('🟡' if rmse < 6 else '🔴')
            self._val_rmse_var.set(
                f'{ico}  RMSE vs {first_id} = {rmse:.2f} pp  |  '
                f'{n_pass}/{n_total} checks  |  '
                'Use ▶ Run Validation to check any dataset in detail.')
        if hasattr(self, '_val_src_var'):
            self._val_src_var.set(
                f'  Auto-loaded: {first_id} | {ds.get("source","")} | '
                f'Furnace: {ds.get("furnace","—")} ({ds.get("vendor","—")})')

    # ─── Helpers ──────────────────────────────────────────────────────────────
    def _copy_tree(self, tree, headers):
        rows = [tree.item(iid, 'values') for iid in tree.get_children()]
        text = '\t'.join(headers) + '\n' + '\n'.join(
            '\t'.join(str(v) for v in r) for r in rows)
        self.root.clipboard_clear()
        self.root.clipboard_append(text)
        messagebox.showinfo('Copied', f'{len(rows)} rows copied — paste into Excel.')

    def _copy_products(self):
        is_dry = (self.v_basis.get() == 'dry')
        h = (('Species','MW','mol/s','g/100g Feed','g/100g Conv','mol% dry','wt% dry') if is_dry
             else ('Species','MW','mol/s','g/100g Feed','','mol% wet','wt% wet'))
        self._copy_tree(self.prod_tree, h)

    def _copy_reactions(self):
        self._copy_tree(self.rxn_tree, ('#','Type','Reaction','A (eff)','Ea (kJ/mol)','Order'))

    def _export_products(self):
        fp = filedialog.asksaveasfilename(
            defaultextension='.csv',
            filetypes=[('CSV', '*.csv'), ('All files', '*.*')])
        if not fp: return
        rows = [self.prod_tree.item(iid, 'values') for iid in self.prod_tree.get_children()]
        with open(fp, 'w', newline='') as f:
            w = csv.writer(f)
            w.writerow(('Species','MW','mol/s','g/100g Feed','g/100g Conv','mol% dry','wt% dry'))
            w.writerows(rows)
        messagebox.showinfo('Saved', fp)


    # ═════════════════════════════════════════════════════════════════════════
    # ⑦ YIELD OPTIMIZER  v2  — Economic optimisation with 6 algorithms
    # ═════════════════════════════════════════════════════════════════════════
    #
    # Decision variables (all toggleable, all continuous):
    #   conv      : target conversion      [-]
    #   steam     : steam / HC ratio       [kg/kg]
    #   t_in      : tube inlet temperature [°C]
    #   p_in      : tube inlet pressure    [atm]
    #   feed_kghr : HC feed rate           [kg/hr]
    #
    # Objective (maximise):
    #   NR [USD/hr] = Σ_products(flow_kg/hr × price) − feed − steam − fuel costs
    #
    # Constraints enforced hard (penalty in DE/BH/DA/SHGO; explicit in SLSQP):
    #   COT ≤ COT_max,  ΔP ≤ dP_max,  TMT ≤ TMT_max,
    #   τ ∈ [τ_min, τ_max],  C-bal ≥ min,  H-bal ≥ min
    #
    # Algorithms available (scipy.optimize):
    #   Basin-Hopping (BH)        — fastest meaningful global, ~25–75 evals
    #   Differential Evolution    — robust global, ~popsize×maxiter evals
    #   Dual Annealing            — SA + local, good balance
    #   SHGO                      — deterministic global, low-dim
    #   SLSQP (local)             — fastest local, gradient-based, explicit cons
    #   Nelder-Mead (local)       — derivative-free, good polish
    #   + optional SLSQP polish after any global method
    # ─────────────────────────────────────────────────────────────────────────

    _YO_DEFAULT_PRICES = {
        'C2H4':1.05,'C3H6':0.92,'C4H6':1.30,'C4H8':0.58,
        'C4H10':0.48,'iC4H8':0.65,'iC4H10':0.40,'C6H6':0.80,
        'C7H8':0.72,'C8H10':0.62,'C2H6':0.35,'CH4':0.28,
        'H2':2.50,'C2H2':1.80,'C3H8':0.45,'C10H8':0.30,'COKE':0.05,
    }

    def _build_yield_optimizer_tab(self, nb):
        """
        💰 Per-Coil Yield Optimizer — v16
        ──────────────────────────────────
        Layout fix: left controls panel is an independent ScrollableFrame inside a
        PanedWindow, so all controls (DVs, constraints, algorithm, prices, buttons)
        are always reachable regardless of window height.
        """
        # ── Outer tab frame (plain Frame — no scroll at tab level) ──────────
        outer = ttk.Frame(nb)
        nb.add(outer, text='💰 Yield Optimizer')

        self._yo_running   = False
        self._yo_stop_flag = False
        self._yo_obj_hist  = []
        self._yo_best      = None

        # ── Top bar (header + scope + coil selector) — always visible ───────
        top_bar = ttk.Frame(outer)
        top_bar.pack(fill='x', padx=6, pady=(4,2))

        hdr = ttk.Frame(top_bar); hdr.pack(fill='x', pady=(0,2))
        ttk.Label(hdr,
            text='💰  YIELD OPTIMIZER — Maximise Net Revenue subject to Process Constraints',
            font=('Helvetica',11,'bold'), foreground='#1a5276').pack(side=tk.LEFT)

        scope_f = ttk.LabelFrame(top_bar, text='Optimization Scope', padding=4)
        scope_f.pack(fill='x', pady=(0,2))
        self._yo_scope = tk.StringVar(value='Overall')
        scope_row = ttk.Frame(scope_f); scope_row.pack(fill='x')
        ttk.Radiobutton(scope_row, text='Overall  (single shared DVs across furnace)',
                        variable=self._yo_scope, value='Overall',
                        command=self._yo_update_scope_note).pack(side=tk.LEFT, padx=8)
        ttk.Radiobutton(scope_row, text='MultiCoil  (independent per coil group)',
                        variable=self._yo_scope, value='MultiCoil',
                        command=self._yo_update_scope_note).pack(side=tk.LEFT, padx=8)

        coil_sel_f = ttk.LabelFrame(top_bar, text='Per-Coil Optimizer Selection', padding=4)
        coil_sel_f.pack(fill='x', pady=(0,2))
        coil_sel_row = ttk.Frame(coil_sel_f); coil_sel_row.pack(fill='x')
        ttk.Label(coil_sel_row, text='Active Coil:', font=('Helvetica',9,'bold')).pack(side=tk.LEFT, padx=4)
        self._yo_coil_num   = tk.IntVar(value=1)
        self._yo_coil_label = tk.StringVar(value='Coil 1')
        self._yo_coil_cb    = ttk.Combobox(coil_sel_row, textvariable=self._yo_coil_label,
                                            state='readonly', width=22, values=['Coil 1'])
        self._yo_coil_cb.pack(side=tk.LEFT, padx=4)
        ttk.Button(coil_sel_row, text='↺ Refresh Coil List',
                   command=self._yo_refresh_coil_list).pack(side=tk.LEFT, padx=6)
        self._yo_multicoil_toggle = tk.BooleanVar(value=False)
        ttk.Checkbutton(coil_sel_row, text='🔀 Optimize All Coils Sequentially',
                        variable=self._yo_multicoil_toggle,
                        command=self._yo_on_multicoil_toggle).pack(side=tk.LEFT, padx=12)
        self._yo_scope_note_sv = tk.StringVar(value='')
        ttk.Label(coil_sel_f, textvariable=self._yo_scope_note_sv,
                  font=('Helvetica',7,'italic'), foreground='#2c5f8a',
                  wraplength=800, justify='left').pack(anchor='w', padx=6, pady=(1,2))
        self._yo_update_scope_note()

        # ── Main PanedWindow: left controls | right (chart + report) ────────
        pw_main = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
        pw_main.pack(fill='both', expand=True, padx=4, pady=2)

        # LEFT: ScrollableFrame — independently scrollable control panel
        left_scroll = ScrollableFrame(pw_main)
        pw_main.add(left_scroll, weight=0)
        col_l = left_scroll.scrollable_frame   # <── controls go here

        # RIGHT: nested PanedWindow for chart | report
        right_pw = ttk.PanedWindow(pw_main, orient=tk.HORIZONTAL)
        pw_main.add(right_pw, weight=1)
        col_m = ttk.Frame(right_pw); right_pw.add(col_m, weight=3)
        col_r = ttk.Frame(right_pw); right_pw.add(col_r, weight=2)

        # ═══ LEFT COLUMN ═══════════════════════════════════════════════════
        fdv = ttk.LabelFrame(col_l, text='Decision Variables (Manipulated Variables)', padding=6)
        fdv.pack(fill='x', pady=(0,4))
        for ci,(txt,w) in enumerate([('Variable',14),('Lo',7),('Hi',7),('Unit',6)]):
            ttk.Label(fdv,text=txt,width=w,font=('Helvetica',7,'bold'),
                      foreground='#1a3a5c',anchor='center').grid(row=0,column=ci,padx=2,pady=1)

        self._yo_dv_active = []
        dv_cfg = [
            ('Conversion',   '_yo_conv_lo', '_yo_conv_hi',  0.55, 0.97, '—'),
            ('Steam / HC',   '_yo_stm_lo',  '_yo_stm_hi',   0.25, 0.75, 'kg/kg'),
            ('T_inlet',      '_yo_tin_lo',  '_yo_tin_hi',   580., 690., '°C'),
            ('P_inlet',      '_yo_pin_lo',  '_yo_pin_hi',   1.8,  4.0,  'atm'),
            ('HC Feed rate', '_yo_feed_lo', '_yo_feed_hi',  8000.,40000.,'kg/hr'),
        ]
        for r,(lbl,la,ha,ld,hd,unit) in enumerate(dv_cfg,1):
            act=tk.BooleanVar(value=True); self._yo_dv_active.append(act)
            ttk.Checkbutton(fdv,text=lbl,variable=act,width=14).grid(row=r,column=0,sticky='w',padx=2,pady=1)
            lv=tk.DoubleVar(value=ld); hv=tk.DoubleVar(value=hd)
            setattr(self,la,lv); setattr(self,ha,hv)
            ttk.Entry(fdv,textvariable=lv,width=7).grid(row=r,column=1,padx=1,pady=1)
            ttk.Entry(fdv,textvariable=hv,width=7).grid(row=r,column=2,padx=1,pady=1)
            ttk.Label(fdv,text=unit,font=('Helvetica',7),foreground='#666',width=5).grid(row=r,column=3,padx=1)

        # ── Constraints ─────────────────────────────────────────────────────
        fcon = ttk.LabelFrame(col_l, text='Process Constraints (Hard Limits per Coil)', padding=6)
        fcon.pack(fill='x', pady=(0,4))
        con_cfg = [
            ('Max COT',      '_yo_cot_max',  935., '°C', '≤'),
            ('Max ΔP',       '_yo_dp_max',   1.20, 'atm','≤'),
            ('Max TMT',      '_yo_tmt_max',  1050.,'°C', '≤'),
            ('Min τ',        '_yo_tau_min',  80.,  'ms', '≥'),
            ('Max τ',        '_yo_tau_max',  700., 'ms', '≤'),
            ('Min C-balance','_yo_cbal_min', 97.0, '%',  '≥'),
            ('Min H-balance','_yo_hbal_min', 97.0, '%',  '≥'),
        ]
        self._yo_con_sv = {}
        for r,(lbl,attr,dv,unit,dirn) in enumerate(con_cfg):
            v=tk.DoubleVar(value=dv); setattr(self,attr,v)
            ttk.Label(fcon,text=f'{dirn} {lbl}:',font=('Helvetica',8),width=16,
                      anchor='e').grid(row=r,column=0,padx=3,pady=1,sticky='e')
            ttk.Entry(fcon,textvariable=v,width=8).grid(row=r,column=1,padx=2,pady=1)
            ttk.Label(fcon,text=unit,font=('Helvetica',7),foreground='#666').grid(row=r,column=2,padx=1)
            sv=tk.StringVar(value='—')
            lb=ttk.Label(fcon,textvariable=sv,font=('Courier',7),width=14,foreground='#555')
            lb.grid(row=r,column=3,padx=2,sticky='w')
            self._yo_con_sv[lbl]=(sv,lb)

        # ── Algorithm & Solver Parameters (fully exposed) ─────────────────
        falg = ttk.LabelFrame(col_l, text='Objective & Algorithm', padding=6)
        falg.pack(fill='x', pady=(0,4))

        # --- Shared vars ---
        self._yo_method     = tk.StringVar(value='Basin-Hopping')
        self._yo_penalty_wt = tk.DoubleVar(value=800.)
        self._yo_maxiter    = tk.IntVar(value=30)
        self._yo_popsize    = tk.IntVar(value=8)   # Rev-70: was missing → AttributeError
        self._yo_seed       = tk.IntVar(value=42)
        self._yo_polish     = tk.BooleanVar(value=True)
        self._yo_obj_type   = tk.StringVar(value='NetRevenue')
        self._yo_max_time   = tk.DoubleVar(value=300.)   # seconds wall-clock limit
        self._yo_tol        = tk.DoubleVar(value=1e-3)   # convergence tolerance

        # --- Basin-Hopping ---
        self._yo_bh_T        = tk.DoubleVar(value=50.)
        self._yo_bh_stepsize = tk.DoubleVar(value=0.15)
        self._yo_bh_niter_suc= tk.IntVar(value=8)
        self._yo_bh_min_meth = tk.StringVar(value='L-BFGS-B')

        # --- Differential Evolution ---
        self._yo_de_popsize  = tk.IntVar(value=8)
        self._yo_de_mut_lo   = tk.DoubleVar(value=0.5)
        self._yo_de_mut_hi   = tk.DoubleVar(value=1.2)
        self._yo_de_recomb   = tk.DoubleVar(value=0.7)
