        # --- SLSQP/NM ---
        self._yo_local_ftol    = tk.DoubleVar(value=1e-4)
        self._yo_local_eps     = tk.DoubleVar(value=1e-6)
        self._yo_local_maxiter = tk.IntVar(value=300)

        # ── Row 0: Objective ──────────────────────────────────────────────
        def _row(parent, lbl, var, row, col=0, width=7, tip='', span=1):
            ttk.Label(parent,text=lbl,font=('Helvetica',7),anchor='e',width=16
                      ).grid(row=row,column=col,sticky='e',padx=3,pady=1)
