    def _sa_refresh_coils(self):
        """Refresh Sensitivity Analysis coil selector — mirrors _yo_refresh_coil_list."""
        mc_vars = getattr(self, '_mc_coil_vars', [])
        mc_on   = getattr(self, 'v_mc_enabled', None) and self.v_mc_enabled.get()
        if mc_on and mc_vars:
            active = [cv for cv in mc_vars
                      if cv.get('active') and cv['active'].get()]
            nums   = [cv.get('coil_num', i+1) for i,cv in enumerate(active)]
            labels = [f"Coil {cv.get('coil_num',i+1)}: {cv.get('feed_type',tk.StringVar(value='?')).get() if 'feed_type' in cv else '?'}"
                      for i,cv in enumerate(active)]
        else:
            nums   = [1]
            labels = [f"Coil 1: {self.v_feed_type.get()}"]
        if not nums: nums=[1]; labels=[f"Coil 1: {self.v_feed_type.get()}"]
        self._sa_coil_label_map = dict(zip(labels, nums))
        try:
            self._sa_coil_cb['values'] = labels
            cur = self._sa_coil_num.get()
            if cur not in nums:
                self._sa_coil_num.set(nums[0])
                if labels: self._sa_coil_cb.set(labels[0])
        except Exception: pass

    def _sa_stop(self):
        self._sa_stop_flag = True
        self._sa_status_sv.set('Stopped.')

    def _sa_export_csv(self):
        if not self._sa_results:
            messagebox.showinfo('SA Export', 'No results yet — run OAT first.'); return
        fp = filedialog.asksaveasfilename(
            defaultextension='.csv', filetypes=[('CSV','*.csv'),('All','*.*')])
        if not fp: return
        with open(fp,'w',newline='') as f:
            import csv as _csv
            w = _csv.writer(f)
            w.writerow(['Variable','ResponseName','Value','XValue'])
            for var_nm, resp_dict in self._sa_results.items():
                for resp_nm, (xs, ys) in resp_dict.items():
                    for x, y in zip(xs, ys):
                        w.writerow([var_nm, resp_nm, y, x])
        messagebox.showinfo('Exported', fp)

    def _sa_launch_oat(self):
        if self._sa_running:
            messagebox.showinfo('SA','Analysis already running.'); return
        self._sa_running   = True
        self._sa_stop_flag = False
        self._sa_btn_oat.configure(state='disabled')
        self._sa_pbar.set(0.)
        self._sa_status_sv.set('Starting OAT sensitivity…')
        threading.Thread(target=self._sa_oat_worker, daemon=True).start()

    def _sa_oat_worker(self):
        """One-At-a-Time sensitivity: sweep each variable while holding others at base.
        Uses the selected coil's operating conditions as the base point when MC is on."""
        try:
            # Determine which coil to analyze
            lbl_map   = getattr(self, '_sa_coil_label_map', {})
            _sel_lbl  = getattr(self._sa_coil_cb, 'get', lambda: '')()
            sa_coil   = lbl_map.get(_sel_lbl, None)
            cv        = self._yo_get_coil_cv(sa_coil)

            if cv is not None:
                base_conv  = cv.get('target_conv',  self.v_target_conv).get() if 'target_conv' in cv else self.v_target_conv.get()
                base_steam = cv.get('steam',         self.v_steam_ratio).get() if 'steam'       in cv else self.v_steam_ratio.get()
                base_tin   = cv.get('t_in',          self.v_t_in).get()       if 't_in'        in cv else self.v_t_in.get()
                base_pin   = cv.get('p_in',          self.v_p_in).get()       if 'p_in'        in cv else self.v_p_in.get()
                base_feed  = cv.get('feed_rate',     self.v_feed_rate).get()  if 'feed_rate'   in cv else self.v_feed_rate.get()
            else:
                base_conv  = self.v_target_conv.get()
                base_steam = self.v_steam_ratio.get()
                base_tin   = self.v_t_in.get()
                base_pin   = self.v_p_in.get()
                base_feed  = self.v_feed_rate.get()
            bases = [base_conv, base_steam, base_tin, base_pin, base_feed]

            active_vars = [(i,nm,mn_v,mx_v,st_v)
                           for i,(nm,mn_v,mx_v,st_v,ac_v) in enumerate(self._sa_vars)
                           if ac_v.get()]
            active_resp = [nm for nm,av in self._sa_responses if av.get()]

            if not active_vars:
                self.root.after(0, self._sa_status_sv.set, 'No active variables selected.'); return
            if not active_resp:
                self.root.after(0, self._sa_status_sv.set, 'No active responses selected.'); return

            total_evals = sum(st_v.get() for *_,st_v in active_vars)
            done_evals  = [0]
            results = {}  # {var_nm: {resp_nm: (xs, ys)}}

            for vidx, (vi, var_nm, mn_v, mx_v, st_v) in enumerate(active_vars):
                if self._sa_stop_flag: break
                xs = np.linspace(mn_v.get(), mx_v.get(), st_v.get())
                resp_data = {r: [] for r in active_resp}

                for xval in xs:
                    if self._sa_stop_flag: break
                    bv = list(bases)
                    bv[vi] = xval
                    conv, steam, t_in, p_in, feed = bv
                    try:
                        kpis, table, bal = self._yo_run_sim(
                            conv, steam, t_in, p_in, feed, coil_num=sa_coil)
                        NR, *_ = self._yo_net_revenue(kpis, table, feed, steam)
                        sp_map = {row['Species']: row for row in table}

                        def _y(sp): return sp_map[sp]['g_100g_feed'] if sp in sp_map else 0.
                        def _btx(): return _y('C6H6') + _y('C7H8') + _y('C8H10')

                        for rn in active_resp:
                            if   rn == 'Conversion (%)':     v = kpis.get('actual_conv',0)*100
                            elif rn == 'COT (°C)':            v = kpis.get('COT_C', 0)
                            elif rn == 'TMT max (°C)':        v = kpis.get('tmt_max_C', 0)
                            elif rn == 'ΔP (atm)':            v = kpis.get('dP_atm', 0)
                            elif rn == 'τ (ms)':              v = kpis.get('tau_ms', 0)
                            elif rn == 'C₂H₄ yield':         v = _y('C2H4')
                            elif rn == 'C₃H₆ yield':         v = _y('C3H6')
                            elif rn == 'BTX yield':           v = _btx()
                            elif rn == 'C₄H₆ yield':         v = _y('C4H6')
                            elif rn == 'H₂ yield':            v = _y('H2')
                            elif rn == 'Coke yield':          v = _y('COKE')
                            elif rn == 'P/E ratio':           v = kpis.get('pe_ratio', 0)
                            elif rn == 'Heat duty (kW)':      v = kpis.get('heat_duty_kW', 0)
                            elif rn == 'Net Revenue ($/hr)':  v = NR
                            else:                              v = float('nan')
                            resp_data[rn].append(v)
                    except Exception:
                        for rn in active_resp:
                            resp_data[rn].append(float('nan'))

                    done_evals[0] += 1
                    pct = 100. * done_evals[0] / max(total_evals, 1)
                    self.root.after(0, self._sa_pbar.set, pct)
                    self.root.after(0, self._sa_status_sv.set,
                                    f'OAT: {var_nm} step {done_evals[0]}/{total_evals} …')

                results[var_nm] = {rn: (list(xs), resp_data[rn]) for rn in active_resp}
                self.root.after(0, self._sa_draw_oat_partial, results, active_resp)

            self._sa_results = results
            self.root.after(0, self._sa_draw_oat_full, results, active_resp)
            self.root.after(0, self._sa_fill_table, results, active_resp)
            self.root.after(0, self._sa_draw_spider, results, active_resp)
            self.root.after(0, self._sa_status_sv.set, f'OAT complete — {done_evals[0]} simulations.')
        except Exception as e:
            self.root.after(0, self._sa_status_sv.set, f'Error: {e}')
        finally:
            self._sa_running = False
            self.root.after(0, self._sa_btn_oat.configure, {'state': 'normal'})

    def _sa_draw_oat_partial(self, results, active_resp):
        """Draw incremental line charts as OAT completes."""
        self._sa_draw_lines(results, active_resp)

    def _sa_draw_oat_full(self, results, active_resp):
        """Draw full tornado + line charts after OAT completes."""
        self._sa_draw_tornado(results, active_resp)
        self._sa_draw_lines(results, active_resp)

    def _sa_draw_tornado(self, results, active_resp):
        """Draw tornado charts (bar chart of sensitivity range per variable)."""
        fig  = self._sa_fig_tornado
        axes = self._sa_axes_tornado.ravel()
        for ax in axes: ax.cla(); ax.set_visible(False)

        key_resps = [r for r in active_resp if r in
                     ['C₂H₄ yield','C₃H₆ yield','COT (°C)','Net Revenue ($/hr)',
                      'ΔP (atm)','TMT max (°C)']][:len(axes)]
        for ai, resp_nm in enumerate(key_resps):
            ax = axes[ai]; ax.set_visible(True)
            var_names = list(results.keys())
            ranges = []
            for vn in var_names:
                ys = results[vn].get(resp_nm, ([], []))[1]
                clean = [y for y in ys if not (y != y)]
                if clean:
                    ranges.append(max(clean) - min(clean))
                else:
                    ranges.append(0.)
            order = np.argsort(ranges)[::-1]
            vn_ord = [var_names[i] for i in order]
            rn_ord = [ranges[i] for i in order]
            colors = ['#2563EB' if r >= 0 else '#EF4444' for r in rn_ord]
            ax.barh(range(len(vn_ord)), rn_ord, color=colors, edgecolor='white', height=0.55)
            ax.set_yticks(range(len(vn_ord)))
            ax.set_yticklabels(vn_ord, fontsize=6)
            ax.set_xlabel('Δ range', fontsize=7)
            ax.set_title(resp_nm, fontsize=8, fontweight='bold')
            ax.axvline(0, color='black', lw=0.7)
            ax.grid(axis='x', ls='--', alpha=0.3)
            ax.tick_params(labelsize=6)
        fig.suptitle('Tornado Chart — Sensitivity Range per Variable', fontsize=9, fontweight='bold')
        fig.tight_layout(pad=1.4, rect=[0,0,1,0.96])
        self._sa_canvas_tornado.draw_idle()

    def _sa_draw_lines(self, results, active_resp):
        """Draw response curves for each active variable."""
        fig  = self._sa_fig_lines
        axes = self._sa_axes_lines.ravel()
        for ax in axes: ax.cla(); ax.set_visible(False)

        colors_cycle = ['#2563EB','#F97316','#16A34A','#A855F7','#EF4444',
                        '#06B6D4','#F59E0B','#EC4899','#84CC16']
        ai = 0
        for vn, resp_dict in results.items():
            if ai >= len(axes): break
            ax = axes[ai]; ax.set_visible(True)
            xs_ref = None
            for ri, (rn, (xs, ys)) in enumerate(resp_dict.items()):
                if xs_ref is None: xs_ref = xs
                clean_ys = [y if not (y!=y) else None for y in ys]
                ax.plot(xs, clean_ys, color=colors_cycle[ri % len(colors_cycle)],
                        lw=2., label=rn[:18], marker='o', ms=3)
            ax.set_xlabel(vn, fontsize=7)
            ax.set_ylabel('Response (norm.)', fontsize=7)
            ax.set_title(f'{vn}', fontsize=8, fontweight='bold')
            ax.legend(fontsize=5, loc='best')
            ax.grid(ls='--', alpha=0.35); ax.tick_params(labelsize=6)
            ai += 1
        fig.suptitle('Response Curves — Variable vs Key KPIs', fontsize=9, fontweight='bold')
        fig.tight_layout(pad=1.4, rect=[0,0,1,0.96])
        self._sa_canvas_lines.draw_idle()

    def _sa_fill_table(self, results, active_resp):
        """Fill numerical sensitivity table."""
        tree = self._sa_tree
        for item in tree.get_children(): tree.delete(item)
        # For each response, find total normalized sensitivity per variable
        if not active_resp: return
        resp_nm = active_resp[0]  # use first response for ranking
        rows = []
        for vn, resp_dict in results.items():
            xs, ys = resp_dict.get(resp_nm, ([], []))
            clean = [(x,y) for x,y in zip(xs,ys) if not (y!=y)]
            if not clean: continue
            xs_c, ys_c = zip(*clean)
            base_x = xs_c[len(xs_c)//2]
            base_y = ys_c[len(ys_c)//2]
            mn_r = min(ys_c); mx_r = max(ys_c)
            rng  = mx_r - mn_r
            # normalized sensitivity: (dy/y) / (dx/x) at base
            if len(xs_c) > 1 and abs(base_x) > 1e-9 and abs(base_y) > 1e-9:
                dydx = (ys_c[-1] - ys_c[0]) / (xs_c[-1] - xs_c[0])
                sens = abs(dydx) * base_x / base_y
            else:
                sens = 0.
            rows.append((vn, f'{base_x:.4g}', f'{mn_r:.4g}', f'{mx_r:.4g}',
                          f'{rng:.4g}', f'{sens:.4f}'))
        rows.sort(key=lambda r: abs(float(r[5])), reverse=True)
        for rank, row in enumerate(rows, 1):
            tree.insert('', 'end', values=(*row, rank))

    def _sa_draw_spider(self, results, active_resp):
        """Draw spider/radar chart of normalized sensitivity magnitudes."""
        ax = self._sa_ax_spider; ax.cla()
        var_names = list(results.keys())
        N = len(var_names)
        if N < 3: return
        angles = np.linspace(0, 2*np.pi, N, endpoint=False).tolist()
        angles += angles[:1]

        colors_resp = ['#2563EB','#F97316','#16A34A','#A855F7','#EF4444','#06B6D4']
        for ri, resp_nm in enumerate(active_resp[:6]):
            vals = []
            for vn in var_names:
                xs, ys = results[vn].get(resp_nm, ([], []))
                clean = [y for y in ys if not (y!=y)]
                vals.append(max(clean) - min(clean) if clean else 0.)
            mx = max(vals) if max(vals) > 0 else 1.
            vals_norm = [v/mx for v in vals] + [vals[0]/mx]
            ax.plot(angles, vals_norm, color=colors_resp[ri], lw=2.,
                    label=resp_nm[:20], alpha=0.8)
            ax.fill(angles, vals_norm, color=colors_resp[ri], alpha=0.08)

        ax.set_xticks(angles[:-1])
        ax.set_xticklabels([vn.split('(')[0].strip()[:12] for vn in var_names], fontsize=7)
        ax.set_yticks([0.25, 0.5, 0.75, 1.0])
        ax.set_yticklabels(['25%','50%','75%','100%'], fontsize=6)
        ax.set_title('Spider Chart — Normalized Sensitivity per Response', fontsize=9, fontweight='bold', pad=18)
        ax.legend(loc='upper right', bbox_to_anchor=(1.35, 1.15), fontsize=7)
        self._sa_fig_spider.tight_layout()
        self._sa_canvas_spider.draw_idle()

    def _sa_launch_2d(self):
        if self._sa_running:
            messagebox.showinfo('SA','Analysis already running.'); return
        self._sa_running   = True
        self._sa_stop_flag = False
        self._sa_btn_2d.configure(state='disabled')
        self._sa_pbar.set(0.)
        threading.Thread(target=self._sa_2d_worker, daemon=True).start()

    def _sa_2d_worker(self):
        """2D grid sweep for contour map."""
        try:
            var_name_map = {nm: i for i,(nm,*_) in enumerate(self._sa_vars)}
            bases = [self.v_target_conv.get(), self.v_steam_ratio.get(),
                     self.v_t_in.get(), self.v_p_in.get(), self.v_feed_rate.get()]

            xnm = self._sa_x2d.get(); ynm = self._sa_y2d.get()
            znm = self._sa_z2d.get()
            xi  = var_name_map.get(xnm, 0); yi = var_name_map.get(ynm, 1)
            xv  = self._sa_vars[xi]; yv = self._sa_vars[yi]
            N   = self._sa_grid_n.get()
            xs  = np.linspace(xv[1].get(), xv[2].get(), N)
            ys  = np.linspace(yv[1].get(), yv[2].get(), N)
            Z   = np.full((N, N), np.nan)
            NR  = np.full((N, N), np.nan)
            done = [0]; total = N*N

            for ii, xval in enumerate(xs):
                for jj, yval in enumerate(ys):
                    if self._sa_stop_flag: break
                    bv = list(bases); bv[xi] = xval; bv[yi] = yval
                    try:
                        lbl_map2 = getattr(self, '_sa_coil_label_map', {})
                        _sel2    = getattr(self._sa_coil_cb, 'get', lambda: '')()
                        sa_coil2 = lbl_map2.get(_sel2, None)
                        kpis, table, bal = self._yo_run_sim(*bv, coil_num=sa_coil2)
                        nr, *_ = self._yo_net_revenue(kpis, table, bv[4], bv[1])
                        sp_map = {row['Species']: row for row in table}
                        def _y(sp): return sp_map[sp]['g_100g_feed'] if sp in sp_map else 0.
                        def _btx(): return _y('C6H6')+_y('C7H8')+_y('C8H10')
                        rn = znm
                        if   rn=='Conversion (%)':    z = kpis.get('actual_conv',0)*100
                        elif rn=='COT (°C)':           z = kpis.get('COT_C',0)
                        elif rn=='TMT max (°C)':       z = kpis.get('tmt_max_C',0)
                        elif rn=='ΔP (atm)':           z = kpis.get('dP_atm',0)
                        elif rn=='τ (ms)':             z = kpis.get('tau_ms',0)
                        elif rn=='C₂H₄ yield':        z = _y('C2H4')
                        elif rn=='C₃H₆ yield':        z = _y('C3H6')
                        elif rn=='BTX yield':          z = _btx()
                        elif rn=='Net Revenue ($/hr)': z = nr
                        else:                           z = float('nan')
                        Z[jj, ii] = z
                        NR[jj,ii]  = nr
                    except Exception: pass
                    done[0] += 1
                    self.root.after(0, self._sa_pbar.set, 100.*done[0]/total)
                    self.root.after(0, self._sa_status_sv.set,
                                    f'2D: {done[0]}/{total} …')
                if self._sa_stop_flag: break

            self.root.after(0, self._sa_draw_contour, xs, ys, Z, NR, xnm, ynm, znm)
            self.root.after(0, self._sa_status_sv.set,
                            f'2D complete — {done[0]} simulations.')
        except Exception as e:
            self.root.after(0, self._sa_status_sv.set, f'2D Error: {e}')
        finally:
            self._sa_running = False
            self.root.after(0, self._sa_btn_2d.configure, {'state': 'normal'})

    def _sa_draw_contour(self, xs, ys, Z, NR, xnm, ynm, znm):
        for ax in self._sa_ax_contour: ax.cla()
        XX, YY = np.meshgrid(xs, ys)
        ax1, ax2 = self._sa_ax_contour
        # Response contour
        valid = ~np.isnan(Z)
        if valid.any():
            cf1 = ax1.contourf(XX, YY, Z, levels=18, cmap='RdYlGn')
            ax1.contour(XX, YY, Z, levels=12, colors='#333', linewidths=0.5, alpha=0.5)
            self._sa_fig_contour.colorbar(cf1, ax=ax1, shrink=0.85, label=znm)
        ax1.set_xlabel(xnm, fontsize=8); ax1.set_ylabel(ynm, fontsize=8)
        ax1.set_title(f'{znm}\nvs {xnm} & {ynm}', fontsize=8, fontweight='bold')
        ax1.grid(ls='--', alpha=0.25)
        # Net Revenue contour
        if not np.all(np.isnan(NR)):
            cf2 = ax2.contourf(XX, YY, NR, levels=18, cmap='Blues')
            ax2.contour(XX, YY, NR, levels=12, colors='#222', linewidths=0.5, alpha=0.5)
            self._sa_fig_contour.colorbar(cf2, ax=ax2, shrink=0.85, label='Net Revenue ($/hr)')
        ax2.set_xlabel(xnm, fontsize=8); ax2.set_ylabel(ynm, fontsize=8)
        ax2.set_title(f'Net Revenue ($/hr)\nvs {xnm} & {ynm}', fontsize=8, fontweight='bold')

        ax2.grid(ls='--', alpha=0.25)
        self._sa_fig_contour.suptitle('2D Sensitivity Contour Map', fontsize=9, fontweight='bold')
        self._sa_fig_contour.tight_layout()
        self._sa_canvas_contour.draw_idle()

    # ─── Digital Twin Excel Tab ────────────────────────────────────────────────

    def _build_digital_twin_tab(self, nb):
        """
        🔗 Digital Twin — Universal File Processor  (Rev-72)
        ────────────────────────────────────────────────────
        Reads an external file of ANY supported kind, parses the process
        parameters from it, runs the rigorous PFR simulation, and writes the
        results back out in the format the user chooses.

        Supported input formats (auto-detected by extension + content):
            • Excel        .xlsx .xlsm .xls
            • CSV / TSV    .csv .tsv .txt
            • JSON         .json
            • XML          .xml
            • INI / CONF   .ini .cfg .conf
            • YAML-lite    .yaml .yml  (simple key: value)

        Supported output formats:
            • Excel .xlsx   • CSV .csv   • JSON .json   • Text report .txt

        Design goals: highly integrated (reuses the exact same solver as the
        Overall tab via _dt_run_sim_from_params) and error-free (every parse
        and run is wrapped; malformed input degrades gracefully with defaults
        and a clear log message rather than crashing).
        """
        outer = ttk.Frame(nb)
        nb.add(outer, text='🔗 Digital Twin')

        # ── State ────────────────────────────────────────────────────────────
        self._dt_in_path    = tk.StringVar(value='')
        self._dt_out_path   = tk.StringVar(value='')
        self._dt_out_fmt    = tk.StringVar(value='Excel (.xlsx)')
        self._dt_status_sv  = tk.StringVar(value='Ready — import any file to begin.')
        self._dt_pbar       = tk.DoubleVar(value=0.)
        self._dt_detected   = tk.StringVar(value='—')
        self._dt_parsed_params = None   # holds last successfully parsed dict
        # Legacy attributes kept so older helper methods don't crash if reached
        self._dt_excel_path = self._dt_out_path
        self._dt_watch_active = False
        self._dt_watch_thread = None

        # ── Banner ─────────────────────────────────────────────────────────
        hdr = tk.Frame(outer, bg='#064E3B'); hdr.pack(fill='x')
        tk.Label(hdr, text='🔗  DIGITAL TWIN — Excel In / Excel Out',
                 font=('Helvetica',11,'bold'), fg='#D1FAE5', bg='#064E3B',
                 pady=6).pack(side=tk.LEFT, padx=10)
        tk.Label(hdr,
                 text='Enter inputs in Excel  →  Python runs the model  →  results written to Excel',
                 font=('Helvetica',8,'italic'), fg='#6EE7B7', bg='#064E3B').pack(side=tk.LEFT)

        # ── Main layout ──────────────────────────────────────────────────────
        pw = ttk.PanedWindow(outer, orient=tk.HORIZONTAL)
        pw.pack(fill='both', expand=True, padx=4, pady=4)
        left = ScrollableFrame(pw); pw.add(left, weight=0)
        col_l = left.scrollable_frame
        col_r = ttk.Frame(pw); pw.add(col_r, weight=1)

        # ══ STEP 1 — INPUT FILE ════════════════════════════════════════════
        f1 = ttk.LabelFrame(col_l, text='① Input File (Excel / CSV / JSON / XML / INI / YAML)', padding=8)
        f1.pack(fill='x', pady=(0,6))
        ttk.Label(f1, text='File:', font=('Helvetica',8)).grid(row=0,column=0,sticky='w',padx=2,pady=2)
        ttk.Entry(f1, textvariable=self._dt_in_path, width=30).grid(row=0,column=1,padx=2,pady=2)
        ttk.Button(f1, text='📂 Browse', command=self._dt_browse_input
                   ).grid(row=0,column=2,padx=2,pady=2)
        ttk.Label(f1, text='Detected format:', font=('Helvetica',8)
                  ).grid(row=1,column=0,sticky='w',padx=2,pady=2)
        ttk.Label(f1, textvariable=self._dt_detected, font=('Helvetica',8,'bold'),
                  foreground='#047857').grid(row=1,column=1,sticky='w',padx=2,pady=2)
        ttk.Button(f1, text='🔍 Parse / Preview', command=self._dt_parse_preview
                   ).grid(row=2,column=0,columnspan=3,sticky='ew',padx=2,pady=(4,2))

        # ── Template downloads ─────────────────────────────────────────────
        ft = ttk.LabelFrame(col_l, text='② Need a template?', padding=8)
        ft.pack(fill='x', pady=(0,6))
        ttk.Label(ft, text='Generate a sample input file pre-filled with\n'
                           'the current GUI settings, then edit & re-import:',
                  font=('Helvetica',8), justify='left').pack(anchor='w',pady=(0,3))
