    def _dt_import_and_run(self):
        """Manually import inputs from Excel and trigger a run."""
        fp = self._dt_excel_path.get()
        import os
        if not os.path.exists(fp):
            messagebox.showwarning('DT Import', f'File not found: {fp}'); return
        import threading
        threading.Thread(target=self._dt_manual_import_worker, daemon=True).start()

    def _dt_manual_import_worker(self):
        fp = self._dt_excel_path.get()
        try:
            wb     = self._dt_read_wb_with_retry(fp)
            params = self._dt_extract_all_params(wb, gui_snapshot=None)  # reads Tkinter vars directly — acceptable for manual user-triggered import
            self._dt_log_write(f"✅ Manual import: {params['feed_type']} "
                               f"feed={params['feed_rate']:.0f}kg/hr "
                               f"T={params['t_in']:.0f}°C", 'ok')
            def _apply():
                self._suppress = True
                try:
                    self.v_feed_rate.set(params['feed_rate'])
                    self.v_steam_ratio.set(params['steam'])
                    self.v_t_in.set(params['t_in'])
                    self.v_p_in.set(params['p_in'])
                    self.v_target_conv.set(params['conv'])
                    self.v_tp.set(params['kp']); self.v_to.set(params['ko'])
                    self.v_ta.set(params['ka']); self.v_tc.set(params['kc'])
                    self.v_g_c2h6.set(params['g_c2h6']); self.v_g_ch4.set(params['g_ch4'])
                    self.v_g_c3h8.set(params['g_c3h8']); self.v_g_c2h4.set(params['g_c2h4'])
                    self.v_g_c3h6.set(params['g_c3h6']); self.v_g_ic4.set(params['g_ic4'])
                    self.v_g_nc4.set(params['g_nc4'])
                    self.v_p_p.set(params['p_p']); self.v_p_i.set(params['p_i'])
                    self.v_p_n.set(params['p_n']); self.v_p_a.set(params['p_a'])
                    self.v_p_o.set(params['p_o'])
                finally:
                    self._suppress = False
                self.root.after(300, self._force_run)
            self.root.after(0, _apply)
        except Exception as e:
            self._dt_log_write(f'Import error: {e}', 'err')

    def _dt_export(self):
        self._dt_create_and_open()

