    def _build_lm_tab(self, nb):
        tab=ttk.Frame(nb); nb.add(tab,text='🔩 Tube Life (LM)')
        pw=ttk.PanedWindow(tab,orient=tk.HORIZONTAL); pw.pack(fill='both',expand=True)
        left=ttk.Frame(pw,width=310); pw.add(left,weight=0)
        ttk.Label(left,text='🔩  LARSON-MILLER CREEP LIFE',
                  font=('Helvetica',11,'bold'),foreground='#7C2D12').pack(anchor='w',padx=8,pady=(6,2))
        fl=ttk.LabelFrame(left,text='Parameters',padding=8); fl.pack(fill='x',padx=6,pady=4)
        self._lm={}
        alloy_var=tk.StringVar(value='HP40'); self._lm['alloy']=alloy_var
        r=ttk.Frame(fl); r.pack(fill='x',pady=1)
        ttk.Label(r,text='Alloy:',width=20,anchor='e').pack(side=tk.LEFT)
        ttk.Combobox(r,textvariable=alloy_var,values=['HP40','Manaurite36X','HK40','35Cr45Ni'],
                     state='readonly',width=14).pack(side=tk.LEFT,padx=4)
        for lbl,key,dflt in [('Wall thickness (m):','wall',0.011),('P_in (atm):','p_in',2.8),
                               ('Run hours to date:','t_h',2000.),('LM constant C (K):','C',20.)]:
            v=tk.DoubleVar(value=dflt); self._lm[key]=v
            row=ttk.Frame(fl); row.pack(fill='x',pady=1)
            ttk.Label(row,text=lbl,width=20,anchor='e').pack(side=tk.LEFT)
            ttk.Entry(row,textvariable=v,width=10).pack(side=tk.LEFT,padx=4)
        self._lm_sv=tk.StringVar(value='—')
        ttk.Label(left,textvariable=self._lm_sv,font=('Courier',8),foreground='#7C2D12',
                  wraplength=290,justify='left').pack(anchor='w',padx=8,pady=4)
        ttk.Button(left,text='▶  Compute Creep Life',command=self._run_lm).pack(padx=8,pady=4)
        right=ttk.Frame(pw); pw.add(right,weight=1)
        self._lm_fig,self._lm_axes=plt.subplots(2,1,figsize=(7,8),dpi=88)
        self._lm_fig.tight_layout(pad=2.)
        self._lm_canvas=FigureCanvasTkAgg(self._lm_fig,master=right)
        self._lm_canvas.get_tk_widget().pack(fill='both',expand=True)
        NavigationToolbar2Tk(self._lm_canvas,right).update()

    def _run_lm(self):
        try:
            R=self._last_result
            if R is None: self._lm_sv.set('⚠ Run simulation first.'); return
            sol=R['sol']; eng=R['eng']; ns=eng.num_species
            T_K=np.clip(sol.y[ns,:],600.,1450.); z=sol.t
            tp=eng.transport_profiles(sol); hi=tp['h_i']
            R_wall=np.log(eng.tube_od/eng.tube_id)/(2*np.pi*eng.k_tube)
            R_film=1./np.maximum(np.pi*eng.tube_id*hi,1e-6)
            q_arr=np.array([eng._q_outer(z[i],float(T_K[i])+40.) for i in range(len(z))])
            TMT_K=T_K+q_arr*np.pi*eng.tube_od*(R_film+R_wall)
            lm=LarsonMillerLifeModel(alloy=self._lm['alloy'].get(),C_LM=self._lm['C'].get())
            sigma=lm.hoop_stress(self._lm['p_in'].get()*101325.,
                                  Di=eng.tube_id, wall_m=self._lm['wall'].get())
            dmg=lm.cumulative_damage(TMT_K,z,self._lm['t_h'].get(),sigma)
            T_rng=np.linspace(700.,1100.,80)
            t_r_arr=np.array([lm.time_to_rupture(T+273.15,sigma) for T in T_rng])
            for ax in self._lm_axes: ax.cla(); ax.set_facecolor('#fff')
            ax0,ax1=self._lm_axes
            ax0.plot(z,TMT_K-273.15,'darkred',lw=2.2,label='TMT (°C)')
            ax0.axhline(dmg['peak_T_C'],color='red',ls='--',lw=1.2,
                         label=f"Peak {dmg['peak_T_C']:.0f}°C @ z={dmg['peak_z_m']:.1f}m")
            ax0.set_ylabel('TMT (°C)',fontsize=9); ax0.legend(fontsize=7); ax0.grid(ls='--',alpha=0.35)
            ax0.set_title(f'σ={sigma:.1f}MPa  Damage={dmg["damage"]:.4f}  '
                           f't_remain={dmg["t_remaining_h"]:.0f}h',fontsize=9,fontweight='bold')
            ax1.semilogy(T_rng,np.minimum(t_r_arr,1e8),'b-',lw=2.)
            ax1.axvline(dmg['peak_T_C'],color='red',ls='--',lw=1.5,label='Peak TMT')
            if dmg['t_rupture_h']<1e8:
                ax1.axhline(dmg['t_rupture_h'],color='orange',ls=':',lw=1.3,
                             label=f"t_r={dmg['t_rupture_h']:.0f}h")
            ax1.set_xlabel('Temperature (°C)',fontsize=9); ax1.set_ylabel('Time to rupture (h)',fontsize=9)
            ax1.set_title(f'{self._lm["alloy"].get()} — LM rupture curve',fontsize=9,fontweight='bold')
            ax1.legend(fontsize=7); ax1.grid(ls='--',alpha=0.35)
            self._lm_fig.tight_layout(); self._lm_canvas.draw_idle()
            s='✅' if dmg['fraction_used']<0.5 else ('⚠️' if dmg['fraction_used']<0.85 else '🔴')
            self._lm_sv.set(f"{s} σ={sigma:.1f}MPa  Damage={dmg['damage']:.4f} "
                             f"({dmg['fraction_used']*100:.1f}% used)\n"
                             f"   Remaining: {dmg['t_remaining_h']:.0f}h  "
                             f"Peak TMT={dmg['peak_T_C']:.1f}°C")
        except Exception as e: self._lm_sv.set(f'❌ {e}')


    # ═══════════════════════════════════════════════════════════════════════
    # Rev-74  OPC UA HISTORIAN CONNECTOR  + DATA RECONCILIATION
    # ═══════════════════════════════════════════════════════════════════════
    # Connects to ANY plant historian (OSI PI, AspenTech IP21, Honeywell PHD,
    # Yokogawa Exaquantum, Aveva PI, or any OPC UA server) via a user-
    # configurable tag map.  Per cycle it:
    #
    #   1. READS  all mapped tags (process + GC analyser) from the historian
    #   2. RECONCILES kinetics — tunes kp, ko, ka, kc by minimising the
    #      weighted residual between the rigorous model and the measurements
    #      (COT, conversion, ΔP, ethylene/propylene/methane yields, P/E ratio,
    #      C balance).  Works for any feed type because the residual set is
    #      filtered to whatever measurements are available.
    #   3. OPTIMISES the tuned model with bounded ±5 % moves on every MV/CV
    #   4. WRITES OptimizedCOT (and steam) back to the historian
    # ═══════════════════════════════════════════════════════════════════════

    # Default tag map — used as a starting point, but every entry can be
    # changed by the user via the Tag-Map editor so the same code works
    # against any plant historian.  Empty string = "tag not available on
    # this plant" — reconciliation will simply skip that residual.
    _OPC_DEFAULT_TAG_MAP = {
        # logical_name        : OPC UA browse name (under root folder)
        'FeedFlow'            : 'FeedFlow',
        'SteamRatio'          : 'SteamRatio',
        'InletTemp'           : 'InletTemp',
        'InletPressure'       : 'InletPressure',
        'CurrentCOT'          : 'CurrentCOT',
        'MeasuredDP'          : 'MeasuredDP',
        'FuelDuty'            : 'FuelDuty',
        # GC analyser channels (dry mol %)
        'GC_H2_pct'           : 'GC_H2_pct',
        'GC_CH4_pct'          : 'GC_CH4_pct',
        'GC_C2H4_pct'         : 'GC_C2H4_pct',
        'GC_C2H6_pct'         : 'GC_C2H6_pct',
        'GC_C3H6_pct'         : 'GC_C3H6_pct',
        'GC_C3H8_pct'         : 'GC_C3H8_pct',
        'GC_C4_pct'           : 'GC_C4_pct',
        'GC_BTX_pct'          : 'GC_BTX_pct',
        # write-back tags
        'OptimizedCOT'        : 'OptimizedCOT',
        'OptimizedSteam'      : 'OptimizedSteam',
        'LastOptTimestamp'    : 'LastOptTimestamp',
        'OptimizerStatus'     : 'OptimizerStatus',
    }
    _OPC_LOGICAL_KEYS = list(_OPC_DEFAULT_TAG_MAP.keys())

    def _build_opcua_tab(self, nb):
        outer = ttk.Frame(nb)
        nb.add(outer, text='📡 OPC UA / Plant Historian')

        # ── State ───────────────────────────────────────────────────────
        self._opc_endpoint    = tk.StringVar(value='opc.tcp://localhost:4840/cracker/historian')
        self._opc_status      = tk.StringVar(value='⏹ Disconnected')
        self._opc_connected   = False
        self._opc_client      = None
        self._opc_nodes       = {}     # logical_name -> Node
        self._opc_running     = False
        self._opc_cycle_s     = tk.DoubleVar(value=10.0)
        self._opc_mv_pct      = tk.DoubleVar(value=5.0)
        self._opc_cv_pct      = tk.DoubleVar(value=5.0)
        # Reconciliation result (last set of tuned multipliers)
        self._opc_tuned       = {'kp':1.0, 'ko':1.0, 'ka':1.0, 'kc':1.0}
        # Live tag mirror StringVars
        self._opc_live = {k: tk.StringVar(value='—') for k in self._OPC_LOGICAL_KEYS}
        self._opc_cycle_count = tk.IntVar(value=0)
