def corrected_heat_flux_W_m2(q_linear_W_m, tube_od_m):
    import numpy as np
    return q_linear_W_m / max(np.pi * tube_od_m, 1e-12)

def corrected_adiabatic_flame_temperature(fuel_LHV, excess_air):
    base = 2200.0 + 0.005 * fuel_LHV
    correction = 1.0 / (1.0 + 0.15 * excess_air)
    return min(base * correction, 2450.0)

