# ═══════════════════════════════════════════════════════════════════════════════
#  v38 GUI INTEGRATION PATCH
#  Registers new feed types with CrackerApp so the GUI dropdown exposes them.
#  Patches _build_reactions() to route new feed keys through v38 builders.
#  Patches _get_feed_flows() to construct molar flow dicts for new feeds.
# ═══════════════════════════════════════════════════════════════════════════════

def _v38_build_reactions(feed_key: str, tuner=None):
    """
    Route any v38 feed key through the extended kinetics library.
    Falls back to legacy builders for feed keys not in FEED_REGISTRY_V38.
    """
    t = tuner or KineticsTuner()
    if feed_key in FEED_REGISTRY_V38:
        return get_reactions_v38(feed_key, t, include_secondary=True)
    # Legacy mapping for backward compatibility
    _legacy = {
        'ethane':   build_ethane_reactions,
        'propane':  build_propane_reactions,
        'lpg':      build_lpg_reactions,
        'naphtha':  build_naphtha_reactions,
        'kerosene': build_kerosene_reactions,
    }
    if feed_key in _legacy:
        return _legacy[feed_key](t)
    return build_ethane_reactions(t)


# Re-export v38 API with non-colliding names so they coexist with v37 builders
try:
    FEED_REGISTRY_V38 = FEED_REGISTRY
    get_reactions_v38  = get_reactions
except NameError:
    FEED_REGISTRY_V38 = {}
    get_reactions_v38  = None


