# ═══════════════════════════════════════════════════════════════════════════════
# v44 PATCH — Realistic TLE block + dark TLE/plot tabs
# Internet basis: TLE rapidly quenches cracked gas, minimizes residence time and
# pressure drop, generates HP/saturated steam, and must handle fouling/erosion.
# ═══════════════════════════════════════════════════════════════════════════════

_TLE_STEAM_TABLE = np.array([
    [1.013,100.0,2257.0],[5.0,151.8,2108.0],[10.0,179.9,2015.0],[20.0,212.4,1889.0],
    [40.0,250.4,1714.0],[60.0,275.6,1571.0],[80.0,295.0,1441.0],[100.0,311.0,1318.0],
    [120.0,324.7,1203.0],[140.0,336.7,1085.0],[160.0,347.4,952.0],[180.0,357.0,790.0],
    [200.0,365.8,585.0],[220.64,373.95,0.0]
], dtype=float)

def _v44_sat_water_props(P_bar):
    P=float(np.clip(P_bar, _TLE_STEAM_TABLE[0,0], _TLE_STEAM_TABLE[-1,0]))
    Ts=float(np.interp(P,_TLE_STEAM_TABLE[:,0],_TLE_STEAM_TABLE[:,1]))
    hfg=float(np.interp(P,_TLE_STEAM_TABLE[:,0],_TLE_STEAM_TABLE[:,2]))
    return Ts, max(hfg, 250.0)

def _v44_churchill_friction(Re, epsD):
    Re=max(float(Re),1.0); epsD=max(float(epsD),1e-8)
    if Re < 2100: return 64.0/Re
    A=(-2.457*np.log((7.0/Re)**0.9 + 0.27*epsD))**16
    B=(37530.0/Re)**16
    return 8.0*((8.0/Re)**12 + 1.0/(A+B)**1.5)**(1/12)

def _v44_tle_calculate(result, p):
    if not result or result.get('sol') is None or result.get('eng') is None:
        raise RuntimeError('Run the furnace first. TLE inlet is the radiant-coil outlet.')
    sol=result['sol']; eng=result['eng']
    T_in_C=float(sol.y[eng.num_species,-1]-273.15)
    P_in_Pa=max(float(sol.y[eng.num_species+1,-1]),1.0)
    P_in_bar=P_in_Pa/1e5
    F=np.maximum(sol.y[:eng.num_species,-1],0.0)
    coils=max(float(getattr(eng,'coils',1) or 1),1.0)
    m_gas=max(float(np.dot(F,eng._mw)*coils/1000.0),1e-9) # kg/s
    Ft=max(float(np.sum(F)*coils),1e-12)
    MW_mix_kg=max(float(np.dot(F,eng._mw)/max(np.sum(F),1e-12)/1000.0),0.002)
    cp=max(float(p['gas_cp_kj_kgK']),0.8)
    T_target=float(p['target_gas_out_C'])
    Psteam=max(float(p['steam_pressure_bar']),1.013)
    Tsat,hfg=_v44_sat_water_props(Psteam)
    approach=max(float(p['approach_K']),5.0)
    Tmin=Tsat+approach
    T_design_out=max(T_target,Tmin)
    UA_clean=max(float(p['UA_kW_K']),1.0)
    service=max(float(p['availability_pct']),1.0)/100.0
    fouling=max(float(p['fouling_R_factor']),0.0)
    UA=UA_clean*service/(1.0+fouling)
    Cgas=max(m_gas*cp,1e-9) # kW/K
    # Boiling-water side is near constant Tsat; plug-flow exponential cooling.
    T_UA=Tsat+(T_in_C-Tsat)*np.exp(-UA/Cgas)
    T_out=max(T_design_out,T_UA)
    if T_in_C <= T_out: Q=0.0; T_out=T_in_C
    else: Q=Cgas*(T_in_C-T_out)
    dT1=max(T_in_C-Tsat,1.0); dT2=max(T_out-Tsat,1.0)
    lmtd=dT1 if abs(dT1-dT2)<1e-9 else (dT1-dT2)/max(np.log(dT1/dT2),1e-9)
    # Gas hydraulics.
    Nt=max(float(p['n_tubes']),1.0); Di=max(float(p['tube_id_mm']),10.0)/1000.0
    L=max(float(p['tube_length_m']),0.5); rough=max(float(p['roughness_um']),1.0)*1e-6
    K=max(float(p['minor_loss_K']),0.0); coke=max(float(p['coke_dp_factor']),0.1)
    Aflow=Nt*np.pi*(Di/2)**2
    TavgK=(T_in_C+T_out)/2+273.15
    rho=P_in_Pa*MW_mix_kg/(R_GAS*TavgK)
    vel=m_gas/max(rho*Aflow,1e-12)
    mu=max(float(p['gas_mu_uPa_s']),5.0)*1e-6
    Re=rho*vel*Di/max(mu,1e-12)
    f=_v44_churchill_friction(Re,rough/Di)
    dp_f=(f*L/Di+K)*0.5*rho*vel**2*coke
    dp_kPa=dp_f/1000.0
    P_out_bar=max(P_in_bar-dp_kPa/100.0,0.01)
    pr=P_out_bar/max(P_in_bar,1e-12)
    steam_kg_h=Q*3600.0/max(hfg,1e-9)
    bfw_kg_h=steam_kg_h*(1.0+max(float(p['blowdown_pct']),0.0)/100.0)
    hot_ms=max(float(p['hot_residence_ms']),0.0)
    residence_actual_ms=L/max(vel,1e-9)*1000.0
    risk=[]
    if T_out>425: risk.append('hot outlet: secondary reactions / gum risk')
    if residence_actual_ms>100: risk.append('long gas residence')
    if dp_kPa>50: risk.append('high TLE ΔP')
    if vel>180: risk.append('very high gas velocity / erosion risk')
    if Re<3000: risk.append('low turbulence; heat-transfer risk')
    status='OK' if not risk else '; '.join(risk)
    return {'T_gas_in_C':T_in_C,'T_gas_out_C':T_out,'T_target_C':T_target,'Tsat_steam_C':Tsat,'approach_K':approach,
            'Q_recovered_kW':Q,'UA_effective_kW_K':UA,'LMTD_K':lmtd,'HP_steam_kg_h':steam_kg_h,'BFW_kg_h':bfw_kg_h,
            'P_gas_in_bar':P_in_bar,'P_gas_out_bar':P_out_bar,'TLE_pressure_ratio':pr,'dP_kPa':dp_kPa,
            'm_gas_kg_s':m_gas,'MW_mix_kg_kmol':MW_mix_kg*1000,'rho_kg_m3':rho,'velocity_m_s':vel,'Re':Re,'f_D':f,
            'hot_residence_ms_set':hot_ms,'residence_actual_ms':residence_actual_ms,'steam_pressure_bar':Psteam,'hfg_kJ_kg':hfg,'status':status}

def _v44_dark_tree(widget):
    try:
        if isinstance(widget,(tk.Frame,tk.LabelFrame)): widget.configure(bg='#07111F')
        elif isinstance(widget,tk.Label): widget.configure(bg='#07111F',fg='#EAF2FF')
    except Exception: pass
    for ch in widget.winfo_children():
        _v44_dark_tree(ch)

def _v44_darken_figures(self):
    import matplotlib.figure
    for obj in list(getattr(self,'__dict__',{}).values()):
        if isinstance(obj, matplotlib.figure.Figure):
            obj.patch.set_facecolor('#07111F')
            for ax in obj.axes:
                ax.set_facecolor('#0D1829')
                ax.title.set_color('#EAF2FF'); ax.xaxis.label.set_color('#BFD7FF'); ax.yaxis.label.set_color('#BFD7FF')
                ax.tick_params(colors='#BFD7FF')
                for sp in ax.spines.values(): sp.set_color('#334155')
                leg=ax.get_legend()
                if leg:
                    leg.get_frame().set_facecolor('#111C2E'); leg.get_frame().set_edgecolor('#334155')
                    for t in leg.get_texts(): t.set_color('#EAF2FF')
    for name,obj in getattr(self,'__dict__',{}).items():
        if 'canvas' in name.lower():
            try: obj.draw_idle()
            except Exception: pass

def _v44_build_tle_tab(self, nb):
    tab=ttk.Frame(nb, style='DarkVars.TFrame'); nb.add(tab,text='♨ TLE Block')
    try:
        st=ttk.Style(); st.configure('TLE.Treeview',background='#0D1829',fieldbackground='#0D1829',foreground='#EAF2FF',rowheight=24)
        st.configure('TLE.Treeview.Heading',background='#1E2D46',foreground='#38BDF8',font=('Segoe UI Semibold',9))
        st.map('TLE.Treeview',background=[('selected','#2563EB')],foreground=[('selected','#FFFFFF')])
    except Exception: pass
    pw=ttk.PanedWindow(tab,orient=tk.HORIZONTAL); pw.pack(fill='both',expand=True,padx=6,pady=6)
    left=tk.Frame(pw,bg='#07111F'); right=tk.Frame(pw,bg='#07111F'); pw.add(left,weight=0); pw.add(right,weight=1)
    tk.Label(left,text='♨ TRANSFER LINE EXCHANGER — RAPID QUENCH & HP STEAM',bg='#07111F',fg='#38BDF8',font=('Segoe UI Semibold',10)).pack(anchor='w',padx=8,pady=(6,2))
    tk.Label(left,text='Industrial TLE/PQE model: cracked gas quench, boiler steam generation, gas hydraulics, fouling and erosion checks.',bg='#07111F',fg='#BFD7FF',font=('Segoe UI',8),wraplength=360,justify='left').pack(anchor='w',padx=8,pady=(0,6))
    self._tle_vars={}
    specs=[('TLE configuration','tle_type','Linear double-pipe',('Linear double-pipe','Shell-and-tube primary','Tunnel-flow primary')),('Target gas outlet °C','target_gas_out_C',380.0,None),('Clean UA kW/K','UA_kW_K',1200.0,None),('Gas Cp kJ/kg/K','gas_cp_kj_kgK',2.55,None),('Steam drum pressure bar abs','steam_pressure_bar',120.0,None),('Minimum approach K','approach_K',25.0,None),('No. of TLE tubes / coils','n_tubes',8.0,None),('Gas tube ID mm','tube_id_mm',55.0,None),('Effective tube length m','tube_length_m',9.0,None),('Roughness μm','roughness_um',45.0,None),('Minor loss K','minor_loss_K',2.5,None),('Gas viscosity μPa·s','gas_mu_uPa_s',42.0,None),('Fouling R factor','fouling_R_factor',0.15,None),('Coke / erosion ΔP factor','coke_dp_factor',1.0,None),('Availability %','availability_pct',98.0,None),('BFW inlet °C','bfw_in_C',145.0,None),('Blowdown/losses %','blowdown_pct',3.0,None),('Hot transfer target ms','hot_residence_ms',50.0,None)]
    form=tk.Frame(left,bg='#07111F'); form.pack(fill='x',padx=6,pady=2)
    for r,(lbl,key,val,choices) in enumerate(specs):
        tk.Label(form,text=lbl,bg='#07111F',fg='#EAF2FF',font=('Segoe UI',8),anchor='w').grid(row=r,column=0,sticky='w',padx=4,pady=2)
        if choices:
            sv=tk.StringVar(value=val); ttk.Combobox(form,textvariable=sv,values=choices,state='readonly',width=22).grid(row=r,column=1,sticky='ew',padx=4,pady=2); self._tle_vars[key]=sv
        else:
            dv=tk.DoubleVar(value=float(val)); ttk.Entry(form,textvariable=dv,width=14).grid(row=r,column=1,sticky='ew',padx=4,pady=2); self._tle_vars[key]=dv
    btn=tk.Frame(left,bg='#07111F'); btn.pack(fill='x',padx=6,pady=7)
    ttk.Button(btn,text='▶ Calculate TLE',command=self._v44_run_tle).pack(side=tk.LEFT,padx=3)
    ttk.Button(btn,text='↺ Reset TLE',command=self._v44_reset_tle).pack(side=tk.LEFT,padx=3)
    self._tle_status=tk.StringVar(value='Run furnace first, then calculate TLE.')
    tk.Label(left,textvariable=self._tle_status,bg='#07111F',fg='#93C5FD',font=('Consolas',8),wraplength=360,justify='left').pack(fill='x',padx=8,pady=4)
    self._tle_fig=plt.Figure(figsize=(8.8,6.2),dpi=100,facecolor='#07111F')
    self._tle_ax_pfd=self._tle_fig.add_subplot(221); self._tle_ax_t=self._tle_fig.add_subplot(222); self._tle_ax_q=self._tle_fig.add_subplot(223); self._tle_ax_h=self._tle_fig.add_subplot(224)
    self._tle_canvas=FigureCanvasTkAgg(self._tle_fig,master=right); self._tle_canvas.get_tk_widget().pack(fill='both',expand=True,padx=6,pady=6)
    cols=('Parameter','Value','Unit'); self._tle_tree=ttk.Treeview(right,columns=cols,show='headings',style='TLE.Treeview',height=10)
    for c,w in zip(cols,(270,130,95)): self._tle_tree.heading(c,text=c); self._tle_tree.column(c,width=w,anchor='w')
    self._tle_tree.pack(fill='x',padx=6,pady=(0,6))

def _v44_reset_tle(self):
    defaults={'tle_type':'Linear double-pipe','target_gas_out_C':380.0,'UA_kW_K':1200.0,'gas_cp_kj_kgK':2.55,'steam_pressure_bar':120.0,'approach_K':25.0,'n_tubes':8.0,'tube_id_mm':55.0,'tube_length_m':9.0,'roughness_um':45.0,'minor_loss_K':2.5,'gas_mu_uPa_s':42.0,'fouling_R_factor':0.15,'coke_dp_factor':1.0,'availability_pct':98.0,'bfw_in_C':145.0,'blowdown_pct':3.0,'hot_residence_ms':50.0}
    for k,v in defaults.items():
        if k in getattr(self,'_tle_vars',{}): self._tle_vars[k].set(v)
    self._tle_status.set('TLE defaults restored.')

def _v44_run_tle(self):
    try:
        p={k:v.get() for k,v in self._tle_vars.items()}
        r=_v44_tle_calculate(getattr(self,'_last_result',None),p); self._last_tle_result=r
        for item in self._tle_tree.get_children(): self._tle_tree.delete(item)
        rows=[('Gas inlet temperature',r['T_gas_in_C'],'°C'),('Gas outlet temperature',r['T_gas_out_C'],'°C'),('Steam saturation temperature',r['Tsat_steam_C'],'°C'),('Recovered duty',r['Q_recovered_kW'],'kW'),('HP steam generation',r['HP_steam_kg_h'],'kg/h'),('BFW demand incl. blowdown',r['BFW_kg_h'],'kg/h'),('Gas inlet pressure',r['P_gas_in_bar'],'bar abs'),('Gas outlet pressure',r['P_gas_out_bar'],'bar abs'),('TLE pressure ratio',r['TLE_pressure_ratio'],'Pout/Pin'),('Gas ΔP',r['dP_kPa'],'kPa'),('Gas velocity',r['velocity_m_s'],'m/s'),('Gas Reynolds number',r['Re'],'-'),('Actual gas residence',r['residence_actual_ms'],'ms'),('Effective UA',r['UA_effective_kW_K'],'kW/K'),('LMTD',r['LMTD_K'],'K'),('Status',r['status'],'')]
        for a,b,c in rows:
            if isinstance(b,(float,int,np.floating)): b=f'{float(b):,.3f}'
            self._tle_tree.insert('', 'end', values=(a,b,c))
        for ax in [self._tle_ax_pfd,self._tle_ax_t,self._tle_ax_q,self._tle_ax_h]: ax.clear(); ax.set_facecolor('#0D1829')
        # PFD graphic
        ax=self._tle_ax_pfd; ax.axis('off'); ax.set_title('TLE Process Graphic: Furnace Outlet → Quench → HP Steam',color='#EAF2FF',fontsize=9,fontweight='bold')
        boxes=[('Radiant\nCoil',0.05,0.55,'#F97316'),('Transfer\nLine',0.32,0.55,'#64748B'),('TLE / PQE\nRapid Quench',0.58,0.55,'#38BDF8'),('Steam\nDrum',0.58,0.15,'#22C55E')]
        for txtb,x,y,col in boxes:
            ax.add_patch(plt.Rectangle((x,y),0.20,0.22,fc=col,ec='#EAF2FF',lw=1.2,alpha=0.88)); ax.text(x+0.10,y+0.11,txtb,ha='center',va='center',color='white',fontsize=8,fontweight='bold')
        for x1,y1,x2,y2 in [(0.25,0.66,0.32,0.66),(0.52,0.66,0.58,0.66),(0.68,0.55,0.68,0.37)]: ax.annotate('',xy=(x2,y2),xytext=(x1,y1),arrowprops=dict(arrowstyle='->',color='#EAF2FF',lw=1.6))
        ax.text(0.02,0.88,f"In: {r['T_gas_in_C']:.0f}°C, {r['P_gas_in_bar']:.2f} bar",color='#BFD7FF',fontsize=8)
        ax.text(0.58,0.88,f"Out: {r['T_gas_out_C']:.0f}°C, PR={r['TLE_pressure_ratio']:.4f}",color='#BFD7FF',fontsize=8)
        # Temperature profile
        z=np.linspace(0,1,80); Ts=r['Tsat_steam_C']; Tin=r['T_gas_in_C']; Tout=r['T_gas_out_C']
        Tg=Ts+(Tin-Ts)*np.exp(-(-np.log(max((Tout-Ts)/max(Tin-Ts,1e-9),1e-6))*z)) if Tin>Ts else np.ones_like(z)*Tin
        self._tle_ax_t.plot(z,Tg,color='#F97316',lw=2.4,label='Cracked gas'); self._tle_ax_t.axhline(Ts,color='#38BDF8',ls='--',label='Steam/water Tsat'); self._tle_ax_t.axhline(r['T_target_C'],color='#A78BFA',ls=':',label='Target gas out')
        self._tle_ax_t.set_title('TLE Cracked-Gas Rapid Quench Temperature Profile',color='#EAF2FF',fontsize=9,fontweight='bold'); self._tle_ax_t.set_xlabel('Normalized TLE length'); self._tle_ax_t.set_ylabel('Temperature (°C)'); self._tle_ax_t.legend(fontsize=7)
        # Heat recovery
        q=np.maximum(np.gradient(Tg,z),0); q=np.abs(np.gradient(Tg,z)); q=q/max(q.max(),1e-9)*r['Q_recovered_kW']
        self._tle_ax_q.fill_between(z,q,color='#22C55E',alpha=0.25); self._tle_ax_q.plot(z,q,color='#22C55E',lw=2)
        self._tle_ax_q.set_title('Local Heat-Recovery Intensity (Quench Duty Distribution)',color='#EAF2FF',fontsize=9,fontweight='bold'); self._tle_ax_q.set_xlabel('Normalized TLE length'); self._tle_ax_q.set_ylabel('kW index')
        # Hydraulics bar chart
        labels=['ΔP kPa','Vel m/s','Res ms','Steam t/h']; vals=[r['dP_kPa'],r['velocity_m_s'],r['residence_actual_ms'],r['HP_steam_kg_h']/1000.0]
        self._tle_ax_h.bar(labels,vals,color=['#F43F5E','#F59E0B','#38BDF8','#22C55E']); self._tle_ax_h.set_title('TLE Hydraulics & Steam Generation KPIs',color='#EAF2FF',fontsize=9,fontweight='bold'); self._tle_ax_h.tick_params(axis='x',rotation=20)
        for ax in [self._tle_ax_t,self._tle_ax_q,self._tle_ax_h]:
            ax.grid(True,alpha=0.25,color='#334155'); ax.tick_params(colors='#BFD7FF'); ax.xaxis.label.set_color('#BFD7FF'); ax.yaxis.label.set_color('#BFD7FF')
            for sp in ax.spines.values(): sp.set_color('#334155')
            leg=ax.get_legend()
            if leg:
                leg.get_frame().set_facecolor('#111C2E'); leg.get_frame().set_edgecolor('#334155')
                for t in leg.get_texts(): t.set_color('#EAF2FF')
        self._tle_fig.tight_layout(); self._tle_canvas.draw_idle()
        self._tle_status.set(f"TLE calculated: {r['T_gas_in_C']:.0f}→{r['T_gas_out_C']:.0f}°C | Q={r['Q_recovered_kW']:.0f} kW | HP steam={r['HP_steam_kg_h']:.0f} kg/h | ΔP={r['dP_kPa']:.1f} kPa | {r['status']}")
    except Exception as e:
        _log_exception('v44 TLE calculation failed')
        try: self._tle_status.set(f'❌ TLE calculation failed: {e}')
        except Exception: pass

