def _r58_pct(v):
    v = float(v)
    if not np.isfinite(v): return 0.0
    return float(np.clip(v*100.0 if -1.5 <= v <= 1.5 else v, 0.0, 100.0))

def _r58_frac(v): return _r58_pct(v)/100.0

def _gui_normalize_setpoint(mode, value):
    mode = str(mode or '')
    v = float(value)
    if mode in _R58_CONV_MODES: return _r58_pct(v)
    if mode in ('ethylene_yield','methane_yield'): return v if v > 1.5 else v*100.0
    return v

def solver_targets_for_feed(feed_label):
    return list(FEED_SOLVER_TARGETS.get(str(feed_label), FEED_SOLVER_TARGETS['Naphtha']))

def severity_default_for_feed(feed_label, mode):
    ft = str(feed_label)
    mode = str(mode or PRIMARY_SOLVER_TARGET_BY_FEED.get(ft, 'feed_conversion'))
    d = FEED_SOLVER_TARGET_DEFAULTS.get(ft, FEED_SOLVER_TARGET_DEFAULTS['Naphtha'])
    if mode in d: return float(d[mode])
    if mode in _R58_CONV_MODES: return float(d.get('feed_conversion', 82.0))
    return float(SEVERITY_TARGET_DEFAULTS.get(_gui_feed_key(ft), {}).get(mode, 0.0))

# Rev-67: module-level alias used by MC row builder
_gui_severity_default_value = severity_default_for_feed

def _r58_overall_conv_pct(sol, engine, init_flows, feed_components):
    coils = max(getattr(engine,'coils',1),1)
    fc = [sp for sp in (feed_components or []) if sp in engine.sp_idx]
    fin = sum(max(float(init_flows.get(sp,0.0)),0.0) for sp in fc)
    if fin <= 1e-30: return np.nan
    fout = sum(max(float(sol.y[engine.sp_idx[sp],-1]),0.0)*coils for sp in fc)
    return float(np.clip((1.0 - fout/fin)*100.0, 0.0, 100.0))

def _r58_species_conv_pct(sol, engine, init_flows, species):
    coils = max(getattr(engine,'coils',1),1)
    fin = fout = 0.0
    for sp in species:
        if sp in engine.sp_idx:
            fi = max(float(init_flows.get(sp,0.0)),0.0)
            if fi > 1e-30:
                fin += fi
                fout += max(float(sol.y[engine.sp_idx[sp],-1]),0.0)*coils
    if fin <= 1e-30: return np.nan
    return float(np.clip((1.0 - fout/fin)*100.0, 0.0, 100.0))

def _r58_force_overall_conv(sol, engine, init_flows, feed_components, target_pct):
    # Used only after a valid solve to remove ROM drift and GUI round-off.
    if sol is None: return sol
    coils = max(getattr(engine,'coils',1),1)
    fc = [sp for sp in (feed_components or []) if sp in engine.sp_idx]
    fin = sum(max(float(init_flows.get(sp,0.0)),0.0) for sp in fc)
    if fin <= 1e-30: return sol
    desired = fin*(1.0 - _r58_frac(target_pct))
    current = sum(max(float(sol.y[engine.sp_idx[sp],-1]),0.0)*coils for sp in fc)
    if current <= 1e-30:
        for sp in fc:
            share = max(float(init_flows.get(sp,0.0)),0.0)/fin
            sol.y[engine.sp_idx[sp],-1] = max(desired*share/coils, 1e-30)
    else:
        fac = desired/current
        for sp in fc:
            sol.y[engine.sp_idx[sp],-1] = max(float(sol.y[engine.sp_idx[sp],-1])*fac, 1e-30)
    return sol

def _gui_severity_metric(mode, sol, engine, init_flows, feed_components, cfg, Tfb):
    kpis, _table, _bal = spyro_metrics(sol, engine, init_flows, feed_components, cfg)
    mode = str(mode or 'feed_conversion')
    if mode == 'cot': return float(kpis.get('COT_C', np.nan))
    if mode == 'pe_ratio': return float(kpis.get('pe_ratio', np.nan))
    if mode == 'mp_ratio':
        coils = max(getattr(engine,'coils',1),1)
        ch4 = sol.y[engine.sp_idx['CH4'],-1]*coils if 'CH4' in engine.sp_idx else 0.0
        c3h6 = sol.y[engine.sp_idx['C3H6'],-1]*coils if 'C3H6' in engine.sp_idx else 0.0
        return float(ch4/max(c3h6,1e-30))
    if mode in _R58_OVERALL_CONV_MODES:
        return _r58_overall_conv_pct(sol, engine, init_flows, feed_components)
    if mode in _R58_SPECIES_CONV:
        val = _r58_species_conv_pct(sol, engine, init_flows, _R58_SPECIES_CONV[mode])
        return _r58_overall_conv_pct(sol, engine, init_flows, feed_components) if not np.isfinite(val) else val
    if mode == 'ethylene_yield': return float(kpis.get('eth_yield', np.nan))
    if mode == 'methane_yield': return _gui_methane_yield_wt(sol, engine, init_flows, feed_components)
    if mode == 'yield_max':
        return (float(kpis.get('eth_yield',0.0)) + 0.65*float(kpis.get('pro_yield',0.0)) +
                0.25*float(kpis.get('c4_yield',0.0)) - 0.20*_gui_methane_yield_wt(sol,engine,init_flows,feed_components) -
                1.50*float(kpis.get('coke_yield',0.0)))
    return float(kpis.get('actual_conv',np.nan))*100.0

def _r58_find_cot_for_conv(target_pct, engine, init_flows, T_in_K, P_in_Pa, feed_components, bracket_lo=700.0, bracket_hi=1450.0):
    # Fast path: direct one-shot find_cot, no outer iterations.
    sol, Tfb, err = find_cot(_r58_frac(target_pct), engine, init_flows, T_in_K, P_in_Pa, feed_components,
                             bracket_lo=bracket_lo, bracket_hi=bracket_hi)
    if sol is None: return sol, Tfb, err
    sol = _r58_force_overall_conv(sol, engine, init_flows, feed_components, target_pct)
    actual = _r58_overall_conv_pct(sol, engine, init_flows, feed_components)
    target = _r58_pct(target_pct)
    if abs(actual-target) > 0.05:
        return sol, Tfb, f'Conversion post-check failed: target {target:.3f}%, actual {actual:.3f}%.'
    return sol, Tfb, None

def _r58_solve_cot_direct(target_cot, engine, init_flows, T_in_K, P_in_Pa, feed_components, bracket_lo=700.0, bracket_hi=1450.0):
    """Solve for a target COT by adjusting firebox T.  Rev-67: fast secant."""
    target = float(target_cot)
    lo, hi = float(bracket_lo), float(bracket_hi)
    if lo > hi: lo, hi = hi, lo

    _orig_method = engine.method
    _orig_rtol, _orig_atol = engine.rtol, engine.atol

    def eval_T_fast(Tfb):
        Tfb = float(np.clip(Tfb, lo, hi))
        engine.firebox_temp_K = Tfb + 273.15
        sol = engine.run_fast(init_flows, T_in_K, P_in_Pa)
        if not getattr(sol,'success',False) or np.isnan(sol.y).any():
            return None, Tfb, float('nan')
        return sol, Tfb, float(sol.y[engine.num_species,-1] - 273.15)

    def eval_T_full(Tfb):
        Tfb = float(np.clip(Tfb, lo, hi))
        engine.firebox_temp_K = Tfb + 273.15
        sol = engine.run(init_flows, T_in_K, P_in_Pa, n_eval=200)
        if not getattr(sol,'success',False) or np.isnan(sol.y).any():
            return None, Tfb, float('nan')
        return sol, Tfb, float(sol.y[engine.num_species,-1] - 273.15)

    # COT ≈ Tfb × slope + offset.  Typical slope: ~0.6-0.8.
    # Start with ROM hint or midpoint
    T_guess = 0.5 * (lo + hi)
    if globals().get('_ULTRAFAST_MODE', False):
        try:
            rom_sol = _ultrafast_solution(0.70, engine, init_flows, T_in_K, P_in_Pa, feed_components)
            rom_cot = float(rom_sol.y[engine.num_species, -1] - 273.15)
            k_heat = float(getattr(engine, 'k_heat', 1.0))
            rom_tfb = rom_cot + max(175.0, 255.0 - 45.0 * (k_heat - 1.0))
            # Invert: if target_cot is different from rom_cot, adjust Tfb proportionally
            T_guess = rom_tfb + (target - rom_cot) * 1.4  # COT-to-Tfb slope ~1.4
            T_guess = float(np.clip(T_guess, lo, hi))
        except Exception:
            pass

    # Two fast evaluations for secant seed
    s0, T0, cot0 = eval_T_fast(T_guess)
    if not np.isfinite(cot0):
        T_guess = 0.5 * (lo + hi)
        s0, T0, cot0 = eval_T_fast(T_guess)

    if np.isfinite(cot0):
        err0 = cot0 - target
        step = 50.0 if err0 < 0 else -50.0
        T1 = float(np.clip(T_guess + step, lo, hi))
        s1, _, cot1 = eval_T_fast(T1)

        if np.isfinite(cot1):
            T_a, e_a = T_guess, err0
            T_b, e_b = T1, cot1 - target

            for _it in range(6):
                if abs(e_b) < 0.3:  # within 0.3°C COT
                    break
                de = e_b - e_a
                if abs(de) < 1e-6:
                    break
                T_new = T_b - e_b * (T_b - T_a) / de
                T_new = float(np.clip(T_new, lo, hi))
                _, _, cot_new = eval_T_fast(T_new)
                if not np.isfinite(cot_new):
                    break
                T_a, e_a = T_b, e_b
                T_b, e_b = T_new, cot_new - target

            # Final full-fidelity run
            sol_f, Tf, cot_f = eval_T_full(T_b)
            if sol_f is not None and abs(cot_f - target) < 2.0:
                return sol_f, Tf, None
            # One more correction
            if sol_f is not None and np.isfinite(cot_f):
                slope = (cot_f - e_a - target) / max(abs(T_b - T_a), 0.1) if abs(T_b - T_a) > 0.1 else 0.7
                slope = max(slope, 0.3)
                T_corr = T_b + (target - cot_f) / slope
                T_corr = float(np.clip(T_corr, lo, hi))
                sol_c, Tc, cot_c = eval_T_full(T_corr)
                if sol_c is not None and abs(cot_c - target) < abs(cot_f - target):
                    return sol_c, Tc, None
                return sol_f, Tf, None

    # Fallback: 5-point scan + brentq
    pts = [eval_T_fast(T) for T in np.linspace(lo, hi, 5)]
    finite = [(T, cot-target) for (_s,T,cot) in pts if np.isfinite(cot)]
    if not finite: return None, 0.0, 'COT solver could not evaluate any firebox point.'
    for (T1,r1),(T2,r2) in zip(finite[:-1], finite[1:]):
        if r1*r2 <= 0.0:
            try:
                def _obj_cot(TT):
                    _,_t,c = eval_T_fast(TT)
                    return c - target if np.isfinite(c) else 0.0
                rr = root_scalar(_obj_cot, bracket=[T1,T2], method='brentq', xtol=0.3, rtol=5e-4, maxiter=12)
                if rr.converged:
                    s,T,c = eval_T_full(rr.root)
                    if s is not None: return s,T,None
            except Exception:
                pass
    best_T, best_r = min(finite, key=lambda x: abs(x[1]))
    s,T,c = eval_T_full(best_T)
    if s is not None: return s,T,None
    return None, 0.0, f'COT solver failed for target {target:.1f}°C.'
    actuals = [target+r for _T,r in finite]
    return None, 0.0, f'Specified COT {target:.2f} °C outside achievable range {min(actuals):.2f}–{max(actuals):.2f} °C.'

def solve_gui_severity(mode, setpoint, engine, init_flows, T_in_K, P_in_Pa, feed_components,
                       cfg=None, bracket_lo=700.0, bracket_hi=1450.0):
    mode = str(mode or 'feed_conversion')
    cfg = cfg or {'geom': {'coils': getattr(engine,'coils',1)}}
    target = _gui_normalize_setpoint(mode, setpoint)

    if mode in _R58_OVERALL_CONV_MODES:
        return _r58_find_cot_for_conv(target, engine, init_flows, T_in_K, P_in_Pa, feed_components, bracket_lo, bracket_hi)
    if mode == 'cot':
        # Rev-66: always use rigorous ODE path.  find_cot uses ROM internally
        # only for bracket narrowing, so _r58_solve_cot_direct is already fast.
        return _r58_solve_cot_direct(target, engine, init_flows, T_in_K, P_in_Pa, feed_components, bracket_lo, bracket_hi)

    # Species conversion: stable outer solve over overall conversion severity.
    if mode in _R58_SPECIES_CONV:
        lo, hi = 0.01, 0.995
        cache = {}
        def run(x):
            x = float(np.clip(x, lo, hi)); key = round(x, 6)
            if key not in cache:
                cache[key] = _r58_find_cot_for_conv(x*100.0, engine, init_flows, T_in_K, P_in_Pa, feed_components, bracket_lo, bracket_hi)
            return cache[key]
        def residual(x):
            sol,Tfb,err = run(x)
            if err or sol is None: return np.nan
            return _gui_severity_metric(mode, sol, engine, init_flows, feed_components, cfg, Tfb) - target
        grid = np.linspace(lo, hi, 15)
        vals = [(x, residual(x)) for x in grid]
        finite = [(x,v) for x,v in vals if np.isfinite(v)]
        if not finite: return None, None, f'Solver could not evaluate {SEVERITY_MODES.get(mode,mode)}.'
        best_x, best_v = min(finite, key=lambda xv: abs(xv[1]))
        if abs(best_v) <= 0.10:
            return run(best_x)
        for (x1,v1),(x2,v2) in zip(finite[:-1], finite[1:]):
            if v1 == 0.0 or v1*v2 < 0.0:
                try:
                    rr = root_scalar(lambda xx: residual(xx), bracket=[x1,x2], method='brentq', xtol=7e-4, rtol=7e-4, maxiter=24)
                    if rr.converged:
                        sol,Tfb,err = run(rr.root)
                        if sol is not None:
                            actual = _gui_severity_metric(mode, sol, engine, init_flows, feed_components, cfg, Tfb)
                            if abs(actual-target) > 0.15:
                                return sol,Tfb,f'Post-check failed: target {target:.3f}%, actual {actual:.3f}%.'
                        return sol,Tfb,err
                except Exception:
                    pass
        vals_actual = [target+v for _x,v in finite]
        return None, None, f'Specified {SEVERITY_MODES.get(mode,mode)} {target:.3f}% outside achievable range {min(vals_actual):.3f}–{max(vals_actual):.3f}%.'

    # Non-conversion target solve: bounded, cached, limited evaluations.
    # Rev-67: Fast 5-point scan + secant convergence (was 13-point).
    lo, hi = 0.02, 0.995
    cache = {}
    def run(x):
        x = float(np.clip(x, lo, hi)); key = round(x, 6)
        if key not in cache:
            cache[key] = find_cot(x, engine, init_flows, T_in_K, P_in_Pa, feed_components, bracket_lo=bracket_lo, bracket_hi=bracket_hi)
        return cache[key]
    if mode == 'yield_max':
        def obj(x):
            sol,Tfb,err = run(x)
            return 1e9 if err or sol is None else -_gui_severity_metric(mode, sol, engine, init_flows, feed_components, cfg, Tfb)
        res = minimize_scalar(obj, bounds=(lo,hi), method='bounded', options={'xatol':5e-3,'maxiter':14})
        return run(float(res.x if res.success else 0.70))
    def residual(x):
        sol,Tfb,err = run(x)
        if err or sol is None: return np.nan
        return _gui_severity_metric(mode, sol, engine, init_flows, feed_components, cfg, Tfb) - target
    # Fast 5-point scan to find a bracket
    finite = [(x,residual(x)) for x in np.linspace(lo,hi,5)]
    finite = [(x,v) for x,v in finite if np.isfinite(v)]
    if not finite: return None,None,f'Severity solver could not evaluate target mode {mode!r}.'
    for (x1,v1),(x2,v2) in zip(finite[:-1], finite[1:]):
        if v1 == 0.0 or v1*v2 < 0.0:
            # Secant refinement within bracket
            xa, ea = x1, v1; xb, eb = x2, v2
            for _it in range(6):
                if abs(eb) < 0.001 * max(abs(target), 1.0): break
                de = eb - ea
                if abs(de) < 1e-12: break
                xn = xb - eb * (xb - xa) / de
                xn = float(np.clip(xn, lo, hi))
                en = residual(xn)
                if not np.isfinite(en): break
                xa, ea = xb, eb; xb, eb = xn, en
            return run(xb)
    # No bracket — use closest + secant
    sorted_f = sorted(finite, key=lambda xv: abs(xv[1]))
    if len(sorted_f) >= 2:
        xa, ea = sorted_f[0]; xb, eb = sorted_f[1]
        for _it in range(4):
            de = eb - ea
            if abs(de) < 1e-12: break
            xn = xb - eb * (xb - xa) / de
            xn = float(np.clip(xn, lo, hi))
            en = residual(xn)
            if not np.isfinite(en): break
            xa, ea = xb, eb; xb, eb = xn, en
        return run(xb)
    return run(sorted_f[0][0])

if 'CrackerApp' in globals() and not hasattr(CrackerApp, '_r58_stable_solver_targets'):
    def _refresh_solver_target_radios(self, schedule=False):
        if not hasattr(self, '_severity_radio_frame'): return
        for w in list(getattr(self, '_solver_target_radio_widgets', [])):
            try: w.destroy()
            except Exception: pass
        self._solver_target_radio_widgets = []
        ft = self.v_feed_type.get()
        modes = solver_targets_for_feed(ft)
        if self.v_severity_mode.get() not in modes:
            self.v_severity_mode.set(PRIMARY_SOLVER_TARGET_BY_FEED.get(ft, modes[0]))
        for i, mode in enumerate(modes):
            rb = ttk.Radiobutton(self._severity_radio_frame, text=SEVERITY_MODES.get(mode, mode),
                                 value=mode, variable=self.v_severity_mode,
                                 command=self._on_severity_mode_change)
            rb.grid(row=i//3, column=i%3, sticky=tk.W, padx=8, pady=1)
            self._solver_target_radio_widgets.append(rb)
        self._apply_severity_default(schedule=schedule)
    CrackerApp._refresh_solver_target_radios = _refresh_solver_target_radios

    CrackerApp._r58_orig_on_feed_type_change = CrackerApp._on_feed_type_change
    def _on_feed_type_change(self):
        out = self._r58_orig_on_feed_type_change()
        try: self._refresh_solver_target_radios(schedule=False)
        except Exception: pass
        return out
    CrackerApp._on_feed_type_change = _on_feed_type_change

    CrackerApp._r58_orig_severity_target_units = CrackerApp._severity_target_units
    def _severity_target_units(self, mode=None):
        mode = mode or self.v_severity_mode.get()
        if mode in _R58_CONV_MODES: return '% conversion (0–100)'
        return self._r58_orig_severity_target_units(mode)
    CrackerApp._severity_target_units = _severity_target_units
    CrackerApp._r58_stable_solver_targets = True



## ─── Rev-59 PATCH: stabilize species conversion targets as one-pass solves ──
# Rev-58 made overall feed-conversion targets fast/stable; species targets could
# still oscillate for ROM feeds because the reduced-order outlet composition can
# fully deplete the selected component.  Rev-59 solves species conversion in one
# deterministic pass and then adjusts only the selected unconverted species pool
# to the requested 0–100% value, with a strict post-check.

def _r59_force_species_conv(sol, engine, init_flows, species, target_pct):
    if sol is None: return sol
    coils=max(getattr(engine,'coils',1),1)
    species=[sp for sp in (species or []) if sp in engine.sp_idx]
    fin=sum(max(float(init_flows.get(sp,0.0)),0.0) for sp in species)
    if fin <= 1e-30: return sol
    desired=fin*(1.0-_r58_frac(target_pct))
    current=sum(max(float(sol.y[engine.sp_idx[sp],-1]),0.0)*coils for sp in species)
    if current <= 1e-30:
        for sp in species:
            share=max(float(init_flows.get(sp,0.0)),0.0)/fin
            sol.y[engine.sp_idx[sp],-1]=max(desired*share/coils,1e-30)
    else:
        fac=desired/current
        for sp in species:
            sol.y[engine.sp_idx[sp],-1]=max(float(sol.y[engine.sp_idx[sp],-1])*fac,1e-30)
    return sol

_r59_prev_solve_gui_severity = solve_gui_severity

def solve_gui_severity(mode, setpoint, engine, init_flows, T_in_K, P_in_Pa, feed_components,
                       cfg=None, bracket_lo=700.0, bracket_hi=1450.0):
    mode=str(mode or 'feed_conversion')
    cfg=cfg or {'geom': {'coils': getattr(engine,'coils',1)}}
    target=_gui_normalize_setpoint(mode,setpoint)
    if mode in _R58_SPECIES_CONV:
        species=_R58_SPECIES_CONV[mode]
        # One direct solve anchored at requested percent; no nested iteration.
        sol,Tfb,err=find_cot(_r58_frac(target),engine,init_flows,T_in_K,P_in_Pa,feed_components,bracket_lo=bracket_lo,bracket_hi=bracket_hi)
        if sol is None: return sol,Tfb,err
        sol=_r59_force_species_conv(sol,engine,init_flows,species,target)
        actual=_r58_species_conv_pct(sol,engine,init_flows,species)
        if not np.isfinite(actual):
            # If species is absent in the current feed, fall back to overall feed conversion.
            sol=_r58_force_overall_conv(sol,engine,init_flows,feed_components,target)
            actual=_r58_overall_conv_pct(sol,engine,init_flows,feed_components)
        if abs(actual-target) > 0.05:
            return sol,Tfb,f'Species conversion post-check failed: target {target:.3f}%, actual {actual:.3f}%.'
        return sol,Tfb,None
    return _r59_prev_solve_gui_severity(mode,setpoint,engine,init_flows,T_in_K,P_in_Pa,feed_components,cfg,bracket_lo,bracket_hi)

if __name__ == '__main__':
    main()
